_G.BankFrame = CreateFrame("Frame", "BankFrame", UIParent)
_G.BankFrame:SetScript("OnHide", function()
	_G.__bankOnHideRan = _G.__bankOnHideRan + 1
	CloseBankFrame()
end)
_G.BankFrame.selectedTab = 1

