print("== casting: the spine and its lanes ==")
do
	-- The Lattice handoff's player-target axis (3a, 3b): two hairlines between
	-- the capsules, a cast lane on each. They replace the floating cast bars.
	check(UF.spine and UF.spine:GetParent() == UF.player, "the spine hangs off the player capsule")
	local p, rel, relP = UF.spine:GetPoint(1)
	check(p == "LEFT" and rel == UF.player and relP == "RIGHT", "from its right edge")
	check(#UF.spine.lines == 2, "two hairlines")
	check(A.Movers.registry.cast == nil and A.Movers.registry.targetcast == nil,
		"the floating cast bars and their movers are gone")
	check(UF.cast:GetParent() == UF.spine and UF.targetCast:GetParent() == UF.spine,
		"both lanes ride the spine")
	local _, _, _, _, py = UF.cast:GetPoint(1)
	local _, _, _, _, ty = UF.targetCast:GetPoint(1)
	check(py == 4 and ty == -4, "yours on the upper line, the target's on the lower")
	check(not UF.cast.bar:GetReverseFill() and UF.targetCast.bar:GetReverseFill(),
		"yours fills from your edge, the target's from its own")
	check(not UF.cast.bar.bg:IsShown(), "a lane draws no track: the hairline is its rail")

	-- Round at the LEADING edge, not at the ends of the bar (Joe, 2026-10-07):
	-- no mask on the lane, and a cap riding the fill's moving edge.
	check(UF.cast.bar._mask == nil and UF.targetCast.bar._mask == nil,
		"a lane's bar is not masked round at its two ends")
	local function capOn(lane, cap, edge)
		local p, rel, rp = cap:GetPoint(1)
		return p == "CENTER" and rel == lane.bar:GetStatusBarTexture() and rp == edge
	end
	check(capOn(UF.cast, UF.cast.cap, "RIGHT"),
		"your lane's round cap rides the right end of its fill")
	check(capOn(UF.targetCast, UF.targetCast.cap, "LEFT")
		and capOn(UF.targetCast, UF.targetCast.lockedCap, "LEFT"),
		"the target's, gold and grey alike, ride the left end of its fill")

	-- The length is measured, because the two capsules move separately.
	UF.player:SetGeom({ left = 100, right = 400, top = 300, bottom = 240 })
	UF.target:SetGeom({ left = 520, right = 820, top = 300, bottom = 240 })
	UF:MeasureSpine()
	check(UF.spine:GetWidth() == 120,
		"the spine runs from one capsule's edge to the other's ("
		.. tostring(UF.spine:GetWidth()) .. ")")
	UF.target:SetGeom({ left = 380, right = 680, top = 300, bottom = 240 })
	UF:MeasureSpine()
	check(UF.spine:GetWidth() == 40, "and never collapses, however the capsules are dragged")
	UF.player:SetGeom(nil)
	UF.target:SetGeom(nil)
	UF:MeasureSpine()

	-- With no target there is no spine: no lines, and no dashes in their place.
	_G.__units.target.exists = false
	fire("PLAYER_TARGET_CHANGED")
	check(not UF.spine.lines[1]:IsShown() and not UF.spine.lines[2]:IsShown()
		and UF.spine.dots == nil,
		"with no target the spine draws nothing")
	check(UF.spine:IsShown(), "but stays up, so your lane still has somewhere to draw")
	_G.__units.target.exists = true
	fire("PLAYER_TARGET_CHANGED")
	check(UF.spine.lines[1]:IsShown() and UF.spine.lines[2]:IsShown(),
		"and both lines are back with one")
end

-- The sizes a string's font is set to, in order. After a cold client start the
-- player's lane name was laid out and never drawn until its font really
-- changed (2026-10-07), so every cast steps it through another size and back.
function _G.__fontSteps(fs)
	local steps, set = {}, fs.SetFont
	fs.SetFont = function(self, p, s, fl)
		steps[#steps + 1] = s
		return set(self, p, s, fl)
	end
	return steps, function() fs.SetFont = set end
end
local function rerastered(steps, fs)
	local final = fs.__font and fs.__font[2]
	local other = false
	for _, s in ipairs(steps) do if s ~= final then other = true end end
	return other and final == A.Media:Size("laneLabel"), final
end

castState = { name = "Frostbolt", icon = 135846, channel = false,
	startTime = time * 1000, endTime = (time + 2.5) * 1000 }
local laneSteps, laneUnwrap = _G.__fontSteps(UF.cast.spellName)
fire("UNIT_SPELLCAST_START", "player")
laneUnwrap()
check(UF.cast:IsShown(), "your lane shows on cast start")
check(UF.cast.spellName:GetText() == "FROSTBOLT", "labelled at its origin, in capitals")
do
	local ok, final = rerastered(laneSteps, UF.cast.spellName)
	check(ok, "and its font is stepped through another size and back, so a cold"
		.. " start's undrawn name is drawn (" .. table.concat(laneSteps, ",")
		.. " -> " .. tostring(final) .. ")")

	-- And once more after a moment: on the FIRST cast after a cold start the
	-- pass above is too early, because the draw is what asks for the font.
	local later, unwrap = _G.__fontSteps(UF.cast.spellName)
	_G.__drainTimers(1)
	unwrap()
	check((rerastered(later, UF.cast.spellName)),
		"and again a moment later, for the first cast after a cold start ("
		.. table.concat(later, ",") .. ")")
end
local laneBlue = A.Palette.c.laneCast
check(UF.cast.bar:GetStatusBarTexture():GetVertexColor() == laneBlue[1],
	"in the lane blue")

if _G.__flavour == "camelot" then
	-- FOREVER: the game animates it, and writes the countdown, from the duration
	-- object. Nothing of ours does the arithmetic.
	local tm = UF.cast.bar.__timer
	check(tm and tm.direction == Enum.StatusBarTimerDirection.ElapsedTime,
		"the game fills it from the duration object, away from you")
	check(UF.cast:GetScript("OnUpdate") == nil, "and no tick of ours runs")
	local b = UF.cast.binding
	check(b and b.enabled and b.fontString == UF.cast.time
		and b.formatter and b.formatter:FormatNumber(1.64) == "1.6",
		"the countdown is the game's, to one decimal")
else
	check(UF.cast:GetScript("OnUpdate") ~= nil,
		"Era: the lane drives itself per frame, not off the 10Hz shared ticker")
	-- advance it the way the client would: many small frames, via its own OnUpdate
	local function castFrames(n, dt)
		for _ = 1, n do
			time = time + dt
			UF.cast:GetScript("OnUpdate")(UF.cast, dt)
		end
	end
	castFrames(60, 1 / 60)
	check(UF.cast.bar:GetValue() > 0, "the lane fills")
	check(UF.cast.time:GetText() == "1.5", "and counts down (" .. tostring(UF.cast.time:GetText()) .. ")")
	local midway = UF.cast.bar:GetValue()
	castFrames(1, 1 / 60)
	check(UF.cast.bar:GetValue() > midway,
		"a single 60fps frame advances it (smooth, not stepped)")
end
castState = nil
