print("== independent bars ==")
do
	local cfg = A.db.profile.modules.actionbars

	-- Bar 1 plus the two that size themselves. Bars 2-6 are off by default.
	local onCount, onIds = EnabledBars()
	check(onCount == 4, "bar 1, stance, pet and extra on; 2-6 off (" .. onIds .. ")")

	local byId = {}
	for _, b in ipairs(AB.bars) do byId[b.id] = b end
	check(byId["1"] and byId["stance"] and byId["pet"] and byId["extra"],
		"and they are the ones expected")

	-- BAR 1 FOLLOWS THE FORM; NO OTHER BAR PAGES AT ALL.
	check(byId["1"].paged and byId["1"].header:GetAttribute("_onstate-page") ~= nil,
		"bar 1 follows the form")
	for _, b in ipairs(AB.bars) do
		if b.kind == "action" and b.id ~= "1" then
			check(not b.paged and b.buttons[1]:GetAttribute("_childupdate-actionpage") == nil,
				"bar " .. b.id .. " keeps its own source - only bar 1 follows the form")
		end
	end

	-- THE BUTTON'S OWN SNIPPET, run against a stand-in for the restricted
	-- environment: what it writes is what the client would.
	do
		local bar1 = byId["1"]
		local function runChild(button, message)
			local fn = loadstring(AB.CHILD_SNIPPET)
			setfenv(fn, { self = button, message = message, tonumber = tonumber })
			fn()
		end
		runChild(bar1.buttons[1], 7)
		runChild(bar1.buttons[12], 7)
		check(bar1.buttons[1]:GetAttribute("action") == 73
			and bar1.buttons[12]:GetAttribute("action") == 84,
			"in Stealth (bonus bar 7) bar 1 shows actions 73-84 ("
			.. tostring(bar1.buttons[1]:GetAttribute("action")) .. "-"
			.. tostring(bar1.buttons[12]:GetAttribute("action")) .. ")")
		runChild(bar1.buttons[1], 1)
		runChild(bar1.buttons[12], 1)
		check(bar1.buttons[1]:GetAttribute("action") == 1
			and bar1.buttons[12]:GetAttribute("action") == 12,
			"and back to 1-12 out of it")

		-- AND IT CAN BE SWITCHED OFF, giving the bar its own page back.
		local cfg1 = bar1.cfg
		runChild(bar1.buttons[1], 7)
		cfg1.stancePaging = false
		AB.ApplyPaging(bar1)
		check(not bar1.paged and _G.__stateDrivers.page == nil
			and bar1.header:GetAttribute("_onstate-page") == nil
			and bar1.buttons[1]:GetAttribute("_childupdate-actionpage") == nil,
			"switched off, the driver and both snippets are gone")
		check(bar1.buttons[1]:GetAttribute("action") == 1,
			"and bar 1 is back on its own page, whatever form it was showing")
		cfg1.stancePaging = nil
		AB.ApplyPaging(bar1)
		check(bar1.paged and _G.__stateDrivers.page ~= nil,
			"and on again - an old profile with no setting counts as on")
		cfg1.stancePaging = true
	end

	-- each bar owns a fixed block of actions
	check(byId["1"].buttons[1]:GetAttribute("action") == 1
		and byId["1"].buttons[12]:GetAttribute("action") == 12,
		"bar 1 owns actions 1-12")

	-- Enabling from the *options panel* has to build the bar, not just set a
	-- flag. Reconfigure only ever looked at bars that already existed, so ticking
	-- Enabled in the panel left the bar on and nowhere.
	do
		local tree = A.Options:Build()
		local opt = tree.args.actionbars.args.bar2.args.enabled
		local info = { arg = opt.arg, type = "toggle" }
		opt.set(info, true)
		local bar2
		for _, b in ipairs(AB.bars) do if b.id == "2" then bar2 = b end end
		check(bar2 ~= nil and bar2.dock:IsShown(),
			"ticking Enabled in the options panel builds the bar and shows it")
		check(bar2 and bar2.buttons[1]:GetAttribute("action") == 13,
			"and it owns actions 13-24")
		opt.set(info, false)
		check(bar2 and not bar2.dock:IsShown(), "unticking hides it again")
	end

	-- turning on bar 3 gives it actions 25-36, live
	AB:SetBarEnabled("3", true)
	local bar3
	for _, b in ipairs(AB.bars) do if b.id == "3" then bar3 = b end end
	check(bar3 ~= nil, "bar 3 can be switched on without a reload")
	check(bar3.buttons[1]:GetAttribute("action") == 25
		and bar3.buttons[12]:GetAttribute("action") == 36,
		"and owns actions 25-36, because bar N is page N")

	-- rows is the control; columns fall out of it
	SlashCmdList["AETHERUI"]("bar 3 rows 3")
	check(bar3.rows == 3 and bar3.cols == 4,
		"3 rows of 12 buttons lays out 4 wide (got " .. tostring(bar3.rows) .. "x"
		.. tostring(bar3.cols) .. ")")
	SlashCmdList["AETHERUI"]("bar 3 buttons 6")
	check(#bar3.buttons >= 6 and bar3.shown == 6, "buttons can be reduced to 6")
	check(bar3.buttons[7] and not bar3.buttons[7]:IsShown(),
		"the surplus is hidden, not leaked - frames cannot be destroyed")
	SlashCmdList["AETHERUI"]("bar 3 buttons 12")
	check(bar3.shown == 12, "and grown again")

	-- pointing a bar at another page re-addresses it in place
	SlashCmdList["AETHERUI"]("bar 3 page 7")
	check(bar3.buttons[1]:GetAttribute("action") == 73,
		"a bar can point at a bonus page (7-10), which is how a druid sees their"
		.. " form abilities without anything swapping under them")
	-- PAGES 13-15 ARE WOW FOREVER'S MultiBar5-7. Era has 120 slots and no more.
	SlashCmdList["AETHERUI"]("bar 3 page 13")
	if _G.__flavour == "camelot" then
		check(bar3.buttons[1]:GetAttribute("action") == 145,
			"on Forever a bar can point at page 13, actions 145-156 ("
			.. tostring(bar3.buttons[1]:GetAttribute("action")) .. ")")
	else
		check(bar3.buttons[1]:GetAttribute("action") == 73,
			"on Era page 13 is refused - there are only 10 pages ("
			.. tostring(bar3.buttons[1]:GetAttribute("action")) .. ")")
	end
	SlashCmdList["AETHERUI"]("bar 3 page 3")

	-- per-bar scale
	SlashCmdList["AETHERUI"]("bar 3 scale 0.5")
	local other = byId["1"].dock:GetScale()
	check(bar3.dock:GetScale() < other,
		"scale is per bar, so a side bar can shrink without dragging bar 1 with it")

	-- A SWITCHED-OFF BAR GIVES ITS KEYS BACK. Its hidden buttons still click,
	-- so a key left pointing at them cast bar 3's spells unseen until a reload.
	_G.__bindingSet.MULTIACTIONBAR3BUTTON1 = "F3"
	AB:ApplyBindings()
	check(_G.__overrides["F3"] == "AetherUIBar3Button1",
		"bar 3 on: Blizzard's MULTIACTIONBAR3 key presses it")

	AB:SetBarEnabled("3", false)
	check(not bar3.dock:IsShown(), "and off again")
	check(_G.__overrides["F3"] == nil,
		"and switched off, its key no longer reaches its hidden buttons ("
		.. tostring(_G.__overrides["F3"]) .. ")")
	_G.__bindingSet.MULTIACTIONBAR3BUTTON1 = nil
end

-- WOW FOREVER'S THREE EXTRA BARS (2026-10-07). The client has MultiBar5-7 on
-- pages 13-15; Era has neither the pages nor the bars.
print("== Forever's bars 7-9 ==")
do
	local defaults = A.Config.defaults.profile.modules.actionbars.bars
	local ids = {}
	for i, b in ipairs(defaults) do ids[i] = tostring(b.id) end
	local list = table.concat(ids, ",")

	-- APPENDED: AceDB saves a list's differences by position, so the stance,
	-- pet and extra bars must stay where saved profiles expect them.
	check(ids[7] == "stance" and ids[8] == "pet" and ids[9] == "extra",
		"stance, pet and extra keep positions 7-9 in the defaults (" .. list .. ")")

	if _G.__flavour == "camelot" then
		local ok = #defaults == 12
		for n = 1, 3 do
			local b = defaults[9 + n]
			ok = ok and b and b.id == tostring(6 + n) and b.page == 12 + n
				and b.kind == "action" and b.enabled == false
		end
		check(ok, "bars 7-9 come after them, on pages 13-15, off by default (" .. list .. ")")

		-- Blizzard's own keys for those bars reach ours.
		_G.__bindingSet.MULTIACTIONBAR5BUTTON1 = "F7"
		_G.__bindingSet.MULTIACTIONBAR7BUTTON12 = "F9"
		AB:SetBarEnabled("7", true)
		AB:SetBarEnabled("9", true)
		local byId = {}
		for _, b in ipairs(AB.bars) do byId[b.id] = b end
		check(byId["7"] and byId["7"].dock:IsShown()
			and byId["7"].buttons[1]:GetAttribute("action") == 145
			and byId["9"] and byId["9"].buttons[12]:GetAttribute("action") == 180,
			"bar 7 switches on owning actions 145-156, bar 9 ends at 180")
		check(_G.__overrides["F7"] == "AetherUIBar7Button1"
			and _G.__overrides["F9"] == "AetherUIBar9Button12",
			"and Blizzard's MULTIACTIONBAR5 and 7 keys press them ("
			.. tostring(_G.__overrides["F7"]) .. ", " .. tostring(_G.__overrides["F9"]) .. ")")
		check(AB.ParentFor(byId["7"]) == nil,
			"bar 7 stands on the screen, like bars 3-6, until the trunks exist")

		AB:SetBarEnabled("7", false)
		AB:SetBarEnabled("9", false)
		_G.__bindingSet.MULTIACTIONBAR5BUTTON1 = nil
		_G.__bindingSet.MULTIACTIONBAR7BUTTON12 = nil
		AB:ApplyBindings()
		check(not byId["7"].dock:IsShown(), "and off again")
	else
		check(#defaults == 9, "Era has no bars 7-9 (" .. list .. ")")
	end
end

print("== stance and pet bars ==")
do
	local byId = {}
	for _, b in ipairs(AB.bars) do byId[b.id] = b end

	local stance = byId["stance"]
	check(#stance.buttons == 2,
		"the stance bar sizes itself from GetNumShapeshiftForms (got "
		.. #stance.buttons .. ")")
	check(stance.buttons[1]:GetID() == 1 and stance.buttons[2]:GetID() == 2,
		"buttons carry their form id, which is what Blizzard's template clicks on")
	check(stance.buttons[1].icon:GetTexture() == "Icons\\Bear", "form icon painted")
	check(stance.buttons[2].glow:IsShown(), "the active form is lit")

	-- learning a form has to grow the bar
	local twoW, twoH = stance.dock:GetWidth(), stance.dock:GetHeight()
	_G.__forms[3] = { texture = "Icons\\Travel", active = false, castable = true }
	fire("UPDATE_SHAPESHIFT_FORMS")
	check(#stance.buttons == 3, "learning a form grows the bar")
	check(stance.dock:GetWidth() > twoW, "and its pad with it")
	_G.__forms[3] = nil
	fire("UPDATE_SHAPESHIFT_FORMS")
	check(stance.shown == 2, "and unlearning shrinks it back")
	-- THE PAD TOO. The third button is kept, hidden - frames cannot be
	-- destroyed - and LayoutBar counted it, so the pad stayed three wide with
	-- a blank where the unlearned form had been.
	check(math.abs(stance.dock:GetWidth() - twoW) < 0.5 and math.abs(stance.dock:GetHeight() - twoH) < 0.5,
		"and its pad is two buttons wide again, not three with a blank (" ..
		("%.0f against %.0f"):format(stance.dock:GetWidth(), twoW) .. ")")
	local scols, srows = A.Layout.BarShape("stance")
	check(scols * srows == 2,
		"and a layout string writes its shape over the two showing (" .. scols .. "x" .. srows .. ")")

	-- AND AN ACTION BAR ASKED FOR FEWER BUTTONS, the same way: the surplus
	-- is hidden, and the pad is the buttons showing.
	do
		local one = byId["1"]
		local cfg1 = one.cfg
		local wasButtons, wasRows, wasCols = cfg1.buttons, cfg1.rows, cfg1.cols
		cfg1.cols, cfg1.rows = nil, 1
		A:GetModule("actionbars"):OnConfigChanged()
		local fullW = one.dock:GetWidth()
		cfg1.buttons = 8
		A:GetModule("actionbars"):OnConfigChanged()
		local ab = A.Config:Module("actionbars")
		local size, gap = one.cfg.size or ab.size, ab.spacing
		check(math.abs((fullW - one.dock:GetWidth()) - 4 * (size + gap)) < 0.5,
			"a bar asked for 8 of its 12 buttons is 4 buttons narrower, not 12 wide"
			.. " with four blanks (" .. ("%.0f, then %.0f"):format(fullW, one.dock:GetWidth()) .. ")")
		cfg1.buttons, cfg1.rows, cfg1.cols = wasButtons, wasRows, wasCols
		A:GetModule("actionbars"):OnConfigChanged()
	end

	local pet = byId["pet"]
	check(#pet.buttons == 10, "the pet bar always has its ten slots")
	check(pet.buttons[1].icon:GetTexture() == "Icons\\PetAttack", "pet icon painted")
	check(pet.buttons[3].icon:GetTexture() == "Icons\\PetGrowl",
		"a token action resolves through the global it names, rather than being"
		.. " used as a texture path")
	check(pet.buttons[5]:GetAlpha() < 1, "an empty pet slot dims")

	-- THE TOOLTIP IS OURS TO SET. These come from PetActionButtonTemplate so
	-- they already carry the client's own OnEnter - but it reads
	-- `self.tooltipName` and RETURNS if it is not there, and the only thing that
	-- sets it is PetActionBarMixin:Update walking Blizzard's own buttons, which
	-- ours replaced. So every pet button had a working tooltip handler quietly
	-- doing nothing, which is exactly what it looked like in game.
	check(pet.buttons[1].tooltipName == "Attack",
		"a pet button carries the name its tooltip is drawn from ("
		.. tostring(pet.buttons[1].tooltipName) .. ")")

	-- AND A TOKEN ACTION'S NAME IS THE NAME OF A GLOBAL, exactly as its texture
	-- is. Read straight through, a hunter's Growl is captioned with the token.
	check(pet.buttons[3].tooltipName == "Growl",
		"a token action is resolved through the global, not printed raw ("
		.. tostring(pet.buttons[3].tooltipName) .. ")")

	-- An empty slot names nothing, or the tooltip is last pet's answer.
	check(pet.buttons[5].tooltipName == nil,
		"and an empty slot names nothing (" .. tostring(pet.buttons[5].tooltipName) .. ")")

	-- the pet bar's visibility is secure, because a pet can be dismissed in combat
	check(_G.__stateDrivers.visibility and _G.__stateDrivers.visibility:find("%[pet%]"),
		"pet bar visibility is a secure driver - a pet comes and goes mid-fight")

	-- THE DRIVER OWNS IT, and nothing else may show it (Joe, 2026-10-07: "when
	-- enabling bars on a character which doesn't have pet, the pet bar flashes
	-- on for a second"). Checked straight after the change, before any driver
	-- pass could cover for it.
	local savedPet = _G.__units.pet.exists
	_G.__units.pet.exists = false
	tick(0.2)
	check(not pet.dock:IsShown(), "no pet out: the pet bar is down")
	AB:SetBarEnabled("3", true)
	check(not pet.dock:IsShown(),
		"and switching another bar on does not flash it up")
	AB:SetBarEnabled("3", false)
	-- Nor does the module coming up, which is every login and every reload.
	AB:OnDisable()
	AB:OnEnable()
	check(not pet.dock:IsShown(), "and the module enabling does not flash it up either")

	-- SWITCHED OFF IS OFF, pet or no pet. Hiding the dock alone left the
	-- driver to put it back on the next pass.
	_G.__units.pet.exists = true
	AB:SetBarEnabled("pet", false)
	tick(0.2)
	check(not pet.dock:IsShown(),
		"the pet bar switched off stays down with a pet out, through a driver pass")
	AB:SetBarEnabled("pet", true)
	check(pet.dock:IsShown() and pet.visibilityDriven == true,
		"and switched back on it is up with the pet, driver restored")
	_G.__units.pet.exists = savedPet
	tick(0.2)
end

print("== adopted buttons ==")
do
	local extra
	for _, b in ipairs(AB.bars) do if b.kind == "extra" then extra = b end end
	check(extra ~= nil, "the extra bar exists")
	check(#extra.buttons == 1 and extra.buttons[1] == _G.MainMenuBarVehicleLeaveButton,
		"and has adopted Blizzard's own taxi button rather than building one")
	check(extra.buttons[1]:GetParent() == extra.header, "it is reparented onto our dock")
	check(extra.buttons[1].__aetherAdopted, "and marked, so layout leaves it alone in combat")

	-- Visibility comes from the game, not from the frame. Blizzard's button is
	-- :Show()n from the start and only invisible because its bar is hidden, so
	-- trusting IsShown() put an empty square on screen permanently.
	check(_G.__taxiButton:IsShown() == false,
		"adoption puts the button down rather than leaving it wherever it was")
	tick(0.1)
	check(not extra.dock:IsShown(),
		"and the dock stays down while you are not on a flight path, however the"
		.. " button itself feels about it")

	_G.__onTaxi = true
	tick(0.1)
	check(extra.dock:IsShown() and _G.__taxiButton:IsShown(),
		"boarding a taxi brings both up")

	_G.__onTaxi = false
	tick(0.1)
	check(not extra.dock:IsShown() and not _G.__taxiButton:IsShown(),
		"and landing puts them away again")

	-- a shown-but-irrelevant button must not drag the dock up with it
	_G.__taxiButton:Show()
	tick(0.1)
	check(not extra.dock:IsShown(),
		"a button that shows itself for its own reasons does not open the dock")

	-- it has to be placeable, which means visible while you are placing it
	check(A.Movers.registry.barextra ~= nil, "the extra bar has a mover like any other")
	check(extra.dock:GetWidth() > 1,
		"and a body to grab even with nothing in it (" .. extra.dock:GetWidth() .. ")")

	SlashCmdList["AETHERUI"]("unlock")
	check(extra.dock:IsShown(),
		"unlocking holds it up - you cannot drag a frame you can never see")
	tick(0.1)
	check(extra.dock:IsShown(), "and the ticker leaves it alone while you place it")
	SlashCmdList["AETHERUI"]("lock")
	tick(0.1)
	check(not extra.dock:IsShown(), "locking hands it back to the game")

	-- the pet bar has the same problem for a class with no pet out
	local pet
	for _, b in ipairs(AB.bars) do if b.kind == "pet" then pet = b end end
	SlashCmdList["AETHERUI"]("unlock")
	check(pet.visibilityDriven == false,
		"previewing the pet bar takes its secure visibility driver off rather than"
		.. " arguing with it")
	SlashCmdList["AETHERUI"]("lock")
	check(pet.visibilityDriven == true, "and puts it back on lock")

	-- and it parks beside bar 1 rather than in the middle of the screen
	local d = AB.DefaultAnchor(extra)
	check(d.point == "BOTTOM" and d.x > 0,
		"its default position is to the right of bar 1, computed from bar 1's"
		.. " actual width (x " .. math.floor(d.x) .. ")")
	extra.cfg.side = "left"
	check(AB.DefaultAnchor(extra).x < 0, "and to the left when asked")
	extra.cfg.side = "right"
end

print("== cooldowns ==")
-- Anchor the mock cooldowns to *now*: the session has been running for a while
-- by this point and anything set at load time has long since expired.
do
	local cd3, cd5 = bar.buttons[3].cooldown, bar.buttons[5].cooldown
	_G.__actions[3].cd = { time, 30 }
	_G.__actions[5].cd = { time, 1.5 }
	fire("SPELL_UPDATE_COOLDOWN")
	tick(0.1)
	check(cd3:IsShown() and cd3.__cd and cd3.__cd[2] == 30,
		"a real cooldown draws its swipe, from the duration object")
	check(cd5:IsShown() and cd5.__cd and cd5.__cd[2] == 1.5, "and so does a global")

	-- THE NUMBERS ARE THE COOLDOWN'S OWN, because ours would have to read the
	-- time left. The old "no number for a 1.5s global" rule is the client's to
	-- apply now, against the total duration, so nothing of ours compares.
	check(cd3:GetHideCountdownNumbers() == false,
		"the cooldown draws its own countdown numbers")
	check(cd3:GetMinimumCountdownDuration() == 2000,
		"but none for a cooldown of two seconds or less - a global gets no number")
	check((cd3:GetCountdownFontString():GetFont()) == A.Media.font.bold,
		"and they are in Outfit, the stack role's face, not the game font ("
		.. tostring((cd3:GetCountdownFontString():GetFont())) .. ")")
	check(bar.buttons[3].cdText == nil,
		"an action button carries no countdown text of its own any more")

	-- RESTRICTED. Two reports from the game, both a secret read by us: first
	-- `duration > 0` in UpdateCooldown, then SetCooldown refusing the numbers
	-- outright; and on 2026-09-23, in the open world, `count > 1` at
	-- ActionBars.lua:161. The stand-ins throw on any comparison, as the client
	-- does, so this runs the repaint directly to see the error rather than have
	-- the event pump swallow it.
	if _G.__flavour == "camelot" then
		_G.__cooldownsRestricted = true
		_G.__actions[3].cd = { time, 30 }
		-- Wiped first, so a swipe left over from the check above cannot pass
		-- for one this repaint drew.
		cd3:Clear()
		cd3:Hide()
		local ok, err = pcall(AB.RefreshAll, AB)
		check(ok, "a restricted cooldown and count repaint without throwing"
			.. (ok and "" or (" -- " .. tostring(err))))
		check(cd3:IsShown() and cd3.__cd and cd3.__cd[2] == 30,
			"AND THE SWIPE STILL DRAWS - the duration object carries it, where"
			.. " SetCooldown refused the numbers")
		check(bar.buttons[8].count:GetText() == "20",
			"and the stack count still shows, handed to SetText unread")
		_G.__cooldownsRestricted = false
	end

	_G.__actions[3].cd = nil
	fire("SPELL_UPDATE_COOLDOWN")
	tick(0.1)
	check(not cd3:IsShown() and cd3.__cd == nil, "the swipe clears when the cooldown ends")
	_G.__actions[5].cd = nil
	fire("SPELL_UPDATE_COOLDOWN")
end

print("== drag and drop ==")
local b = bar.buttons[4]
b:GetScript("OnDragStart")(b)
check(_G.__picked == 4, "dragging picks up the right action")
b:GetScript("OnReceiveDrag")(b)
check(_G.__placed == 4, "dropping places into the right action")


print("== the target's lane is not your lane ==")
do
	-- The lanes are told apart by WHERE they are - yours on the upper line from
	-- your edge, theirs on the lower from theirs - and by colour that answers
	-- the handoff's question, "can I interrupt it", not the target's reaction.
	local UFm = A:GetModule("unitframes")
	_G.__units.target.exists = true
	_G.__units.target.reaction = 2          -- hostile

	time = time + 1
	_G.__ccCasts.target = { name = "Lightning Bolt", icon = 1, channel = false,
		start = time * 1000, finish = (time + 3) * 1000 }
	_G.__ccFire("UNIT_SPELLCAST_START", "target")
	local theirs = UFm.targetCast.bar._colors
	check(theirs == A.Palette.c.laneTarget, "a hostile caster's lane is gold, not red")
	_G.__units.target.reaction = 5
	_G.__ccFire("UNIT_SPELLCAST_START", "target")
	check(UFm.targetCast.bar._colors == A.Palette.c.laneTarget, "and so is a friendly one's")

	castState = { name = "Fireball", icon = 135812, channel = false,
		startTime = time * 1000, endTime = (time + 2.5) * 1000 }
	fire("UNIT_SPELLCAST_START", "player")
	check(UFm.cast.bar._colors == A.Palette.c.laneCast, "and yours is the lane blue")

	-- the glow follows the lane rather than staying blue round a gold one
	local gr, gg, gb = UFm.targetCast.glow:GetVertexColor()
	check(math.abs(gr - theirs[1]) < 0.01 and math.abs(gg - theirs[2]) < 0.01
		and math.abs(gb - theirs[3]) < 0.01,
		"the glow takes its own lane's colour")

	-- your own frame is never a reaction
	check(A.Palette:ReactionEdge("player") == A.Palette.c.glassEdge,
		"and the player's own rim never picks up friendly green off"
		.. " UnitReaction('player', 'player')")

	_G.__ccCasts.target = nil
	_G.__ccFire("UNIT_SPELLCAST_STOP", "target")
	castState = nil
	fire("UNIT_SPELLCAST_STOP", "player")
	_G.__units.target.reaction = 2
	_G.__units.target.exists = false
	fire("PLAYER_TARGET_CHANGED")
end

print("== auras: four trays of icon tiles ==")
-- the idle-fader section above dropped the target; put it back
_G.__units.target.exists = true
fire("PLAYER_TARGET_CHANGED")

local AU = A:GetModule("auras")
check(AU and AU.enabled, "auras module enabled"
	.. (AU and AU.lastError and ("  -- " .. AU.lastError) or ""))

-- THE TILES ARE CLASSIC ERA'S. WoW Forever's trays are the game's own aura
-- containers, tested in their own section; the tile checks from here to the
-- right-click block run only where tiles exist.
local TILES = (_G.__flavour ~= "camelot")
check(AU.ContainersAvailable() == not TILES and (AU.trays ~= nil) == TILES,
	TILES and "Era has no aura containers, so it builds tiles"
		or "Forever uses the game's aura containers and builds no tiles")

local PB, PD = AU.playerBuffs, AU.playerDebuffs
local TB, TD = AU.targetBuffs, AU.targetDebuffs

if TILES then
check(#AU.trays == 4, "four trays: buffs and debuffs, player and target")
check(PB.active == 4, "four player buffs (got " .. PB.active .. ")")
check(PD.active == 2, "two player debuffs (got " .. PD.active .. ")")
check(TB.active == 2, "target buffs are shown at all now (got " .. TB.active .. ")")
check(TD.active == 3,
	"and only the player's own target debuffs (got " .. TD.active .. ")")
end

if TILES then  -- the ring says WHAT KIND of thing is on you
	-- The name is gone from a tile, so the school colour is the only thing
	-- left carrying it - and it has to be the client's own, or a curse reads
	-- as one thing here and another on Blizzard's own frames. Nothing checked
	-- this at all until the table moved into the palette.
	local school = A.Palette.c.debuffSchool
	local missing = {}
	for _, kind in ipairs({ "Magic", "Curse", "Disease", "Poison" }) do
		local c = school[kind]
		if type(c) ~= "table" or type(c[3]) ~= "number" then
			missing[#missing + 1] = kind
		end
	end
	check(#missing == 0,
		"all four schools are named (" .. table.concat(missing, ", ") .. ")")

	-- The player's second debuff is a Curse, the target's first is Magic.
	local curse = PD.tiles[2]
	local cr, cg, cb = curse.art.ring:GetVertexColor()
	check(math.abs(cr - school.Curse[1]) < 0.001
		and math.abs(cg - school.Curse[2]) < 0.001
		and math.abs(cb - school.Curse[3]) < 0.001,
		"a curse wears the curse purple (" ..
		string.format("%.2f %.2f %.2f", cr, cg, cb) .. ")")

	local magic = TD.tiles[1]
	local mr, mg, mb = magic.art.ring:GetVertexColor()
	check(math.abs(mr - school.Magic[1]) < 0.001
		and math.abs(mg - school.Magic[2]) < 0.001
		and math.abs(mb - school.Magic[3]) < 0.001,
		"and a magic debuff the magic blue, which is a DIFFERENT colour - one"
		.. " lookup returning the same tint for both would pass either alone")

	-- An untyped debuff has no school to show, and falls back to danger
	-- rather than to the last colour the ring happened to be wearing.
	local plain = PD.tiles[1]
	local pr = plain.art.ring:GetVertexColor()
	check(math.abs(pr - A.Palette.c.danger[1]) < 0.001,
		"an untyped debuff falls back to danger (" ..
		string.format("%.2f", pr) .. ")")
end

if TILES then  -- a tile is an icon and a timer, and nothing else
	local t = PB.tiles[1]
	check(t.name == nil, "no name field on a tile - the name is on the tooltip")
	check(t.art.icon:GetTexture() == 135843, "the icon is painted")
	check(t.time:GetText() == "30m", "the timer reads in minutes at this range")
	-- A mount, a Well Fed, most things a player walks around with. The field is
	-- fixed width either way, so an empty one read as a pill that had failed to
	-- load rather than one with nothing to say.
	check(PB.tiles[4].time:GetText() == "n/a",
		"a permanent aura says so rather than leaving the timer field blank")
	do
		-- On login the server has not finished sending aura data and everything
		-- comes back with a zero duration, which is indistinguishable from a
		-- permanent aura - so every buff was marked timeless, and a timeless tile
		-- is one the ticker never looks at again.
		local saved = _G.__auras.player.HELPFUL
		_G.__auras.player.HELPFUL = {
			{ "Frost Armor", 135843, 0, nil, 0, nil, "player", true },
		}
		fire("PLAYER_ENTERING_WORLD")
		check(PB.tiles[1].time:GetText() == "n/a", "a zero duration reads as timeless")
		_G.__auras.player.HELPFUL = saved
		_G.__tick()                       -- the settle pass the load kicked off
		check(PB.tiles[1].time:GetText() ~= "n/a",
			"and the settle pass picks up the real numbers when they arrive,"
			.. " without needing a UNIT_AURA to happen along")
	end
	check(PB.tiles[4]:GetWidth() == PB.tiles[1]:GetWidth(),
		"and keeps the same width as a timed one")
	check(PB.tiles[3].count:GetText() == 3, "a stack shows its count")
	check(PB.tiles[1].count:GetText() == "", "and a single application does not")

	local spec = AU.spec
	check(t:GetWidth() > spec.size * 2,
		"the pill is wide enough for the icon and a timer beside it")
	check(t:GetHeight() == spec.size + 8,
		"and only a little taller than the icon it wraps, the way the deck draws it")
	check(t.time:GetWidth() == 30,
		"the timer field is fixed width, so a ticking timer cannot resize the pill")
	check(PB.tiles[1]:GetWidth() == PB.tiles[4]:GetWidth(),
		"a permanent aura's pill is the same width as a timed one - the grid has"
		.. " to stay a grid")
end

print("== no tray exceeds the frame it belongs to ==")
if TILES then
	local cfg = A.db.profile.modules.auras
	local ufcfg = A.db.profile.modules.unitframes

	for _, t in ipairs(AU.trays) do
		local d = t.display
		local rowW = d.opts.perRow * (AU:TileWidth() + cfg.spacing) - cfg.spacing
		check(rowW <= UF.player:GetWidth(),
			("%s: a full row is %d wide, the capsule is %d")
				:format(t.key, rowW, UF.player:GetWidth()))
	end

	-- Columns are derived, not configured: widen the capsule and every tray gets
	-- wider on its own.
	local before = PB.opts.perRow
	local savedW, savedBar = ufcfg.width, ufcfg.barWidth
	ufcfg.width, ufcfg.barWidth = 500, 340
	A:Reconfigure()
	check(PB.opts.perRow > before,
		("a wider capsule gets more columns without touching the config (%d -> %d)")
			:format(before, PB.opts.perRow))
	ufcfg.width, ufcfg.barWidth = savedW, savedBar
	A:Reconfigure()
	check(PB.opts.perRow == before, "and loses them again when it narrows")

	-- perRow is a cap, not the source
	cfg.perRow = 3
	AU:OnConfigChanged()
	check(PB.opts.perRow == 3, "setting a column cap uses it")
	cfg.perRow = 0
	AU:OnConfigChanged()
	check(PB.opts.perRow == before, "and 0 goes back to whatever fits")
end

if _G.__flavour == "camelot" then
section("secret values are drawn, never read", function()
	-- THE BUG THIS EXISTS FOR: 260 errors off one tooltip, all
	-- "attempt to compare local 'max' (a secret number value)". On WoW Forever
	-- a unit's max health can come back wrapped so it may be passed to a bar but
	-- never compared, divided or cached.
	check(A.IsSecret(1) == false, "an ordinary number is not secret")
	check(A.IsSecret(_G.__MakeSecret(4242)) == true, "a marked one is")
	check(A.IsSecret(1, 2, _G.__MakeSecret(4243)) == true,
		"and any one of several arguments is enough")
	check(A.IsSecret() == false, "no arguments is not secret")
	check(A.IsSecret(nil) == false, "and neither is nil")

	local f = UF.player
	local saved, savedMax = units.player.hp, units.player.hpMax

	-- The bar still gets both values - that is the whole point of the rule, and
	-- a frame that simply stopped drawing would be a worse answer than one that
	-- drops the readout.
	units.player.hp, units.player.hpMax =
		_G.__MakeSecret(4244), _G.__MakeSecret(4245)
	UF.UpdateAll(f)
	check(f.hpText:GetText() == "",
		"a secret health drops the readout rather than throwing")
	check(f._lastHealth == nil,
		"and is NEVER cached - a stored secret poisons the next comparison too,"
		.. " which is how this fails a second time somewhere else")
	check(f._healthSecret == true, "the frame remembers only that it was secret")

	-- Reconcile runs at 10Hz, so an unguarded comparison here is not one error,
	-- it is a wall of them.
	local ok = pcall(UF.Reconcile)
	check(ok, "the 10Hz reconcile pass survives a secret instead of erroring"
		.. " ten times a second")

	units.player.hp, units.player.hpMax = saved, savedMax
	UF.UpdateAll(f)
	check(f._healthSecret == nil and f.hpText:GetText() ~= "",
		"and an ordinary value afterwards reads out again, so the secret branch"
		.. " does not latch")

	-- A VALUE TURNING SECRET MID-GLIDE. The glide ran on, read the secret back
	-- out of the bar and subtracted - or landed on top of it with the stale
	-- target it had been heading for (Lattice Prune Audit, Forever item 8).
	do
		local bar = f.health
		units.player.hp, units.player.hpMax = 1000, 1000
		UF.UpdateAll(f)
		bar:SetValueNow(1000)
		units.player.hp = 400
		UF.UpdateAll(f)
		check(bar._animating == true, "a plain change glides")

		local secret = _G.__MakeSecret(4290)
		units.player.hp = secret
		UF.UpdateAll(f)
		check(not bar._animating and bar:GetValue() == secret,
			"turning secret mid-glide ends the glide and keeps the secret")
		local ok, err = pcall(bar._Step, bar, 0.1)
		check(ok and bar:GetValue() == secret,
			"and a stray step leaves it alone rather than throwing: " .. tostring(err))

		-- ...and back: the first plain value lands at once, with nothing read
		-- from the secret still held in the bar.
		units.player.hp = 800
		UF.UpdateAll(f)
		ok, err = pcall(bar._Step, bar, 0.1)
		check(ok and bar:GetValue() == 800 and not bar._animating,
			"the first plain value after a secret one snaps into place: " .. tostring(err))

		units.player.hp, units.player.hpMax = saved, savedMax
		UF.UpdateAll(f)
	end

	-- A SECRET CAST IS DRAWN BY THE GAME. Reported from the game, before the
	-- lanes, as "UNIT_SPELLCAST_START: attempt to perform numeric conversion on
	-- a secret number value" - the old tick divided one secret by another.
	if UF.targetCast then
		local lane = UF.targetCast
		_G.__nativeCasts.target = { name = "Secret Bolt", icon = 135846, channel = false,
			startTime = time * 1000, endTime = (time + 2) * 1000, restricted = true }
		local ok, err = pcall(UF.CastStart, lane, false)
		check(ok, "a secret cast does not throw: " .. tostring(err))
		check(lane:GetScript("OnUpdate") == nil,
			"no tick of ours runs - it is the thing that would do the arithmetic")
		check(lane.bar:IsShown() and lane.bar.__timer ~= nil,
			"the lane still fills: the game animates it from the duration object")
		check(lane.locked.__alphaFlag ~= nil and issecretvalue(lane.locked.__alphaFlag),
			"and gold-or-grey is the secret flag handed straight to the game")

		-- No duration object and secret times: nothing honest to draw.
		_G.__nativeCasts.target.noDuration = true
		UF.CastStart(lane, false)
		check(not lane.bar:IsShown() and lane.time:GetText() == ""
			and lane.spellName:GetText() == "SECRET BOLT",
			"with no duration object the lane goes and the label stays")
		_G.__nativeCasts.target = nil
		UF.CastStop(lane)
	end
end)

section("a restricted aura read is refused, not merely secret", function()
	-- A DIFFERENT FAILURE FROM A SECRET NUMBER. A secret value comes back and
	-- can be handed to a setter; a restricted aura read THROWS. Reported from
	-- the game as "GetAuraDataByIndex(): Auras cannot be accessed when secret
	-- while tainted by 'AetherUI'", repeatedly, off both a ticker and UNIT_AURA.
	local Aur = A:GetModule("auras")

	check(Aur.AurasRestricted() == false, "auras read normally to begin with")
	check(Aur.GetAura("player", 1, "HELPFUL") ~= nil, "and an aura comes back")

	_G.__aurasRestricted = true
	check(Aur.AurasRestricted() == true,
		"the client's own ShouldAurasBeSecret is asked first, and answers")

	local ok, err = pcall(Aur.GetAura, "player", 1, "HELPFUL")
	check(ok, "the read does not throw once restricted"
		.. (ok and "" or (" -- " .. tostring(err))))
	check(ok and err == nil,
		"it answers 'no aura here', so every caller's existing end-of-list"
		.. " handling does the rest rather than learning a third state")

	-- The whole point of a hard-error API: if the guard is missed, the client
	-- errors rather than returning nil. Prove the mock really does that.
	local threw = not pcall(C_UnitAuras.GetAuraDataByIndex, "player", 1, "HELPFUL")
	check(threw, "and the underlying API really does throw, so this is a guard"
		.. " rather than a nil check dressed up as one")

	-- AND THE GUARD'S REAL JOB: not calling it at all. The pcall inside GetAura
	-- already stops a throw reaching the log, so "does it error" passes with the
	-- guard deleted. What would be left is a throwing C call made several times
	-- a second, per aura, per unit, for as long as the restriction lasts.
	_G.__auraReads = 0
	for i = 1, 20 do Aur.GetAura("player", i, "HELPFUL") end
	check(_G.__auraReads == 0,
		"twenty scans while restricted make ZERO calls to the API - the pcall is"
		.. " the net, this is the thing that stops us needing it ("
		.. tostring(_G.__auraReads) .. ")")

	_G.__aurasRestricted = false
	check(Aur.AurasRestricted() == false and Aur.GetAura("player", 1, "HELPFUL") ~= nil,
		"lifting the restriction restores the scan - it must not latch, or a"
		.. " zone edge would empty the tray for the rest of the session")
	-- The tile tooltip guard (the PTR feedback race, 2026-09-23) is gone from
	-- here with the tiles: on Forever the game's own buttons show the tooltip.
end)

section("WoW Forever: aura trays the game fills", function()
	-- THE BUG: target debuffs blank on Forever, reported 2026-10-06. The read
	-- above is refused in every fight, so trays built on it show nothing when
	-- it matters. The game's aura containers fill the trays instead.
	local Aur = A:GetModule("auras")
	local F = Aur.forever
	check(F ~= nil and Aur.trays == nil,
		"the trays are the game's containers, and no tiles are built")
	if not F then return end
	local cfg = A.db.profile.modules.auras
	local P = A.Palette.c

	check(#F.trays == 4 and F.initError == nil,
		"four trays, and no square's setup failed (" .. tostring(F.initError) .. ")")
	for _, t in ipairs(F.trays) do
		check(t.container and #t.failed == 0,
			t.key .. " has its container and every group (" .. table.concat(t.failed, "; ") .. ")")
	end
	local PBt, PDt, TBt, TDt = F.playerBuffs, F.playerDebuffs, F.targetBuffs, F.targetDebuffs

	-- where they hang (the handoff: buffs above, debuffs below, rows from the
	-- bars' outer end toward the other capsule)
	local inset, pad = UF:BarsInset(), 12
	local p, rel, relP, x = PBt.host:GetPoint(1)
	check(p == "BOTTOMLEFT" and rel == UF.player and relP == "TOPLEFT" and x == inset - pad,
		"player buffs sit above the player capsule, starting where the bars start (got "
		.. tostring(p) .. " -> " .. tostring(relP) .. " at " .. tostring(x) .. ")")
	p, rel, relP, x = TDt.host:GetPoint(1)
	check(p == "TOPRIGHT" and rel == UF.target and relP == "BOTTOMRIGHT" and x == -(inset - pad),
		"target debuffs sit below the target, measured back from its right end")
	check(PBt.host:GetParent() == UF.player, "a tray is a child of its capsule, so it fades with it")

	local c, tc = PBt.container, TDt.container
	check(c:GetParent() == PBt.host and PBt.host:DoesClipChildren(),
		"each container sits in a clipping host of ours")
	check(c.__flow.anchor == "BOTTOMLEFT" and c.__flow.h == 1 and c.__flow.v == 1,
		"player buffs grow right and up")
	check(tc.__flow.anchor == "TOPRIGHT" and tc.__flow.h == -1 and tc.__flow.v == -1,
		"target debuffs grow left, toward the player, and down")

	-- groups: style is per group, so mine and theirs are two
	local tg, pg = tc.__groupOrder, PDt.container.__groupOrder
	check(tg[1].key == "mine" and tg[1].filter == "HARMFUL|PLAYER"
		and tg[1].opts.layout.layoutIndex == 1,
		"your debuffs on the target are their own group, laid out first - nearest the portrait")
	check(tg[2].filter == "HARMFUL|!PLAYER", "everyone else's come after")
	check(pg[1].filter == "HARMFUL|RAID" and pg[2].filter == "HARMFUL|!RAID",
		"on you, debuffs you can dispel are their own group, first")
	for _, t in ipairs(F.trays) do
		check(t.container.__unit == t.unit and not t.container.__unitBeforeGroups,
			t.key .. ": the unit is set after the groups, which is what registers UNIT_AURA for them")
	end

	-- the squares, built once each by the game through our initializer
	local function plate(b)
		for _, r in ipairs(b.__regions) do
			if r.__layer == "BACKGROUND" and r.__tex == A.Media.texture.slotMask then return r end
		end
	end
	local function near(tex, col, a)
		local r, g, b, al = tex:GetVertexColor()
		return math.abs(r - col[1]) < 0.001 and math.abs(g - col[2]) < 0.001
			and math.abs(b - col[3]) < 0.001 and math.abs(al - (a or col[4] or 1)) < 0.001
	end
	local mine, theirs = tg[1].buttons[1], tg[2].buttons[1]
	local dispel, buff = pg[1].buttons[1], PBt.container.__groupOrder[1].buttons[1]
	check(#tg[1].buttons == 10, "the game builds ten squares a group, up front")
	check(mine:GetWidth() == 24 and mine:GetHeight() == 24, "a square is 24 across")
	check(mine.__icon and mine.__icon:GetNumMaskTextures() == 1,
		"its icon is registered with the game and cut to the rounded square")
	check(plate(mine) and near(plate(mine), P.accent),
		"your debuffs are edged in the accent")
	check(plate(theirs) and near(plate(theirs), P.auraEdgeOther) and theirs:GetAlpha() == 0.5,
		"everyone else's are a faint edge at half strength")
	check(plate(dispel) and near(plate(dispel), P.auraDispel),
		"a debuff you can dispel off yourself is edged red")
	check(plate(buff) and near(plate(buff), P.auraEdge), "a buff has the plain hairline")
	check(TBt.container:GetAlpha() == 0.6, "the target's buffs are drawn at 60%")

	-- the tags: the game writes them, our formatter decides what they say
	local opts = mine.__timerOpts
	local fmt = opts and ((opts.binding and opts.binding.formatter) or opts.textFormatter)
	check(fmt and fmt:FormatNumber(12) == " 12 " and fmt:FormatNumber(45) == "",
		"the timer shows under thirty seconds and says nothing above it")
	check(fmt and fmt:FormatNumber(0.4) == " 1 ", "and rounds up, so it never reads 0 with time left")
	check(opts and opts.binding and opts.binding.zeroText == "" and opts.binding.expiredText == "",
		"a permanent aura says nothing either")
	local sfmt = mine.__stackOpts and mine.__stackOpts.formatter
	check(sfmt and sfmt:FormatNumber(1) == "" and sfmt:FormatNumber(3) == " 3 ",
		"a stack of one says nothing, more shows the count")
	local _, chipTo = (function()
		for _, r in ipairs(mine.__timer:GetParent().__regions) do
			if r.__tex == "SOLID" then return r, select(2, r:GetPoint(1)) end
		end
	end)()
	check(chipTo == mine.__timer,
		"the chip behind the timer hangs off the text itself, so no text means no chip")

	check(buff.__cancel == "RightButtonUp", "right-click cancels your own buffs")
	check(mine.__cancel == nil and mine.__clicksOn == false,
		"other squares take no clicks, so they never swallow one meant for the world")
	check(buff.__tipAnchor == "ANCHOR_TOP" and mine.__tipAnchor == "ANCHOR_BOTTOM",
		"tooltips open away from the capsule")

	-- rest and combat: a shorter line in the same host; nothing of ours moves
	local function cap(t) return t.container.__flow.lineSize end
	local hostW = PBt.host:GetWidth()
	check(cap(PBt) == 3 * 28 - 4 and tg[1].max == 3, "three to a row at rest")
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	check(cap(PBt) == 8 * 28 - 4 and tg[1].max == 8, "up to eight in a fight")
	check(PBt.host:GetWidth() == hostW, "and the host did not resize to do it")

	-- the skin changes mid-fight while auras are secret: wait, do not fight it
	_G.__aurasRestricted = true
	A.db.profile.skin = OTHER A:Restyle()
	check(F.restylePending == true, "a restyle while auras are secret waits")
	_G.__aurasRestricted = false
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not F.restylePending and near(plate(mine), A.Palette.c.accent),
		"and lands when the fight ends, in the new skin's accent")
	check(cap(PBt) == 3 * 28 - 4, "and the rows go back to three")
	A.db.profile.skin = "midnight" A:Restyle()

	-- a new target is not an aura event, so the trays are told
	local before, mineBefore = tc.__refreshes, c.__refreshes
	fire("PLAYER_TARGET_CHANGED")
	check(tc.__refreshes > before and c.__refreshes == mineBefore,
		"a new target refreshes the target's trays and only those")

	-- the settings that still mean something here
	cfg.debuffs.onlyMine = true
	Aur:OnConfigChanged()
	check(tg[2].enabled == false and tg[1].enabled == true,
		"only mine switches everyone else's group off")
	cfg.debuffs.onlyMine = false
	Aur:OnConfigChanged()
	check(tg[2].enabled == true, "and back on")
	cfg.buffs.target = false
	Aur:OnConfigChanged()
	check(not TBt.host:IsShown() and TDt.host:IsShown(), "a tray turned off is hidden, alone")
	cfg.buffs.target = true
	Aur:OnConfigChanged()
	cfg.showTime = false
	Aur:OnConfigChanged()
	check(not mine.__timer:GetParent():IsShown(), "timers off hides the timer tags")
	cfg.showTime = true
	Aur:OnConfigChanged()
	check(mine.__timer:GetParent():IsShown(), "and back")

	-- the diagnostic has something to say here too
	local ok, err = pcall(function() SlashCmdList["AETHERUI"]("auras") end)
	check(ok, "the aura diagnostic runs on Forever: " .. tostring(err))

	-- THE STAND-IN HAS TEETH. Each of these is a rule our code could break and
	-- still look fine in a kinder mock.
	check(not pcall(c.AddAuraGroup, c, "bad", "HARMFUL|NOT_A_FILTER", {}),
		"an unknown filter is refused")
	check(not pcall(c.SetAuraGroupEnabled, c, "nope", true), "so is an unknown group")
	_G.__aurasRestricted = true
	check(not pcall(mine.SetAlpha, mine, 1), "a square refuses writes while auras are secret")
	check(not pcall(plate(mine).SetVertexColor, plate(mine), 1, 1, 1, 1),
		"and so does the art on it")
	_G.__aurasRestricted = false
	local probe = CreateFrame("Frame", nil, UIParent)
	check(not pcall(probe.SetPoint, probe, "TOP", c, "BOTTOM"), "nothing may anchor to a container")
	local bare = mine:CreateFontString(nil, "OVERLAY")
	check(not pcall(mine.SetDurationText, mine, bare, {}),
		"a string with no font cannot be handed over")
end)

end

if _G.__flavour ~= "camelot" then
section("Classic Era has no aura containers", function()
	check(not pcall(CreateFrame, "AuraContainer", nil, UIParent, "CustomAuraContainerTemplate"),
		"the frame type does not exist on Era, so the stand-in cannot hand Era a"
		.. " container it would never get")
end)
end

print("== Blizzard's own unit frames are taken off screen ==")
do
	-- NEVER RUN BEFORE 2026-09-22. The mock had none of these frames, so
	-- A:Banish took its `if not frame then return false end` exit six times and
	-- the suite went green having tested nothing at all. That is the omission
	-- version of the same bug the fabricated dropdowns were.
	for _, n in ipairs({ "PlayerFrame", "TargetFrame", "ComboFrame", "PetFrame",
		"TargetFrameToT" }) do
		local f = _G[n]
		check(f and not f:IsShown(), n .. " is hidden")
		check(f and f:GetParent() ~= UIParent,
			"and reparented off UIParent, so another addon calling Show() on it"
			.. " cannot put " .. n .. " back")
	end

	-- THE CAST BAR IS NAMED DIFFERENTLY PER CLIENT, and the module banishes both
	-- names for that reason. Whichever one this client has must be gone;
	-- whichever it has not must not have been conjured up to be banished.
	local castName = _G.__flavour == "camelot" and "PlayerCastingBarFrame"
		or "CastingBarFrame"
	local absentName = _G.__flavour == "camelot" and "CastingBarFrame"
		or "PlayerCastingBarFrame"
	check(_G[castName] and not _G[castName]:IsShown(),
		castName .. " is hidden - it is the one this client declares")
	check(_G[absentName] == nil,
		absentName .. " does not exist here, and banishing a name the client has"
		.. " not got has to be a no-op rather than a mock frame to aim at")

	-- THE ALT POWER BARS: SILENCED, NOT MOVED.
	--
	-- I checked these once and cleared them on the grounds that they are
	-- PlayerFrame descendants, so reparenting carries them along and they cannot
	-- draw. That was the wrong question. They self-register, their handlers keep
	-- running while invisible, and on camelot those handlers reach the aura API
	-- and hard-error. EllesmereUI had already written this down.
	for _, n in ipairs({ "AlternatePowerBar", "MonkStaggerBar",
		"EvokerEbonMightBar", "DemonHunterSoulFragmentsBar" }) do
		local f = _G[n]
		check(f and not f:IsEventRegistered("UNIT_POWER_UPDATE"),
			n .. " has had its OWN events unregistered - hiding its parent does"
			.. " not stop it running")
		check(f and f:GetParent() == _G.PlayerFrame,
			"and it is NOT reparented: it is Edit Mode managed, the same class"
			.. " of mistake as moving MainStatusTrackingBarContainer")
	end
end

print("== the capsules never resize ==")
do
	local cfg = A.db.profile.modules.unitframes

	check(UF.player.tray == nil and UF.target.tray == nil,
		"there is no in-capsule tray any more")
	check(UF.player.glass:GetHeight() == cfg.height
		and UF.target.glass:GetHeight() == cfg.height,
		"both capsules sit at their designed height")
	local gp, _, grelP = UF.player.glass:GetPoint(1)
	check(gp == "TOPLEFT" and grelP == "TOPLEFT"
		and UF.player.glass:GetNumPoints() == 2,
		"the glass fills the core exactly rather than being pinned to its top edge")

	-- The complaint that started this: one unit with a debuff and one without
	-- used to be two frames of different heights side by side.
	if TILES then
		local savedP = _G.__auras.player.HARMFUL
		_G.__auras.player.HARMFUL = {}
		fire("UNIT_AURA", "player")
		check(PD.active == 0 and TD.active > 0, "player clean, target debuffed")
		check(UF.player.glass:GetHeight() == UF.target.glass:GetHeight(),
			"the two capsules are still exactly the same height - which is the whole"
			.. " point of taking the auras out of them")
		_G.__auras.player.HARMFUL = savedP
		fire("UNIT_AURA", "player")
	end
end

print("== tray placement ==")
if TILES then
	local cfg = A.db.profile.modules.auras

	local bp, brel, brelP = PB.frame:GetPoint(1)
	check(bp == "BOTTOMLEFT" and brel == UF.player and brelP == "TOPLEFT",
		"player buffs hang off the top of the player capsule (got "
		.. tostring(bp) .. " -> " .. tostring(brelP) .. ")")
	local dp, drel, drelP = PD.frame:GetPoint(1)
	check(dp == "TOPLEFT" and drel == UF.player and drelP == "BOTTOMLEFT",
		"player debuffs off the bottom")
	check(select(2, TB.frame:GetPoint(1)) == UF.target
		and select(2, TD.frame:GetPoint(1)) == UF.target,
		"and the target's two hang off the target, the same way round")

	check(PB.opts.growUp and not PD.opts.growUp,
		"rows grow away from the capsule, so the row nearest the frame stays put")
	check(PB.frame:GetParent() == UF.player,
		"a tray is a child of its capsule, so it inherits the fade and the scale")
	check(PB.frame:GetScale() == 1,
		"and takes no scale of its own - the capsule is already scaled")

	-- Centred, because a row of pills almost never divides evenly into a capsule
	-- and the slack pushed onto one side reads as a pill that failed to load.
	check(PB.opts.align == "CENTER" and TD.opts.align == "CENTER",
		"rows are centred on their frame by default")
	do
		local n, tw, gap = PB.active, AU:TileWidth(), cfg.spacing
		local rowW = n * tw + (n - 1) * gap
		local p, rel, relP, x = PB.tiles[1]:GetPoint(1)
		check(p == "BOTTOM" and relP == "BOTTOM" and rel == PB.frame,
			"a centred tile is anchored on the frame's centre line")
		check(math.abs(x - (-rowW / 2 + tw / 2)) < 0.01,
			("the first pill sits half a row left of centre (%.1f)"):format(x))
		-- and the row is symmetric about it
		local _, _, _, xn = PB.tiles[n]:GetPoint(1)
		check(math.abs(x + xn) < 0.01,
			("the last pill mirrors it (%.1f vs %.1f)"):format(x, xn))
	end

	-- ...and mirrored is still there for anyone who wants it
	cfg.align = "MIRROR"
	AU:OnConfigChanged()
	check(PB.opts.align == "LEFT" and TD.opts.align == "RIGHT",
		"mirrored follows the unit's own name and readout - left on the player,"
		.. " right on the target")
	check(select(1, TD.tiles[1]:GetPoint(1)) == "TOPRIGHT",
		"so a half-full target row is measured back from the right edge")
	cfg.align = "CENTER"
	AU:OnConfigChanged()

	-- second row
	local savedB = _G.__auras.player.HELPFUL
	local many = {}
	for i = 1, PB.opts.perRow + 2 do
		many[i] = { "Buff " .. i, 130000 + i, 0, nil, 60, nil, "player", true }
	end
	_G.__auras.player.HELPFUL = many
	fire("UNIT_AURA", "player")
	check(PB.active == PB.opts.perRow + 2, "a full row plus two")
	local _, _, _, _, y1 = PB.tiles[1]:GetPoint(1)
	local _, _, _, _, y2 = PB.tiles[PB.opts.perRow + 1]:GetPoint(1)
	check(y2 > y1, "the second row stacks upward, away from the capsule")
	_G.__auras.player.HELPFUL = savedB
	fire("UNIT_AURA", "player")
end

print("== timers ==")
if TILES then
	local before = PB.tiles[1]:GetWidth()
	time = time + 120
	PB:Tick()
	check(PB.tiles[1].time:GetText() == "28m", "the timer ticks down")
	check(PB.tiles[1]:GetWidth() == before,
		"and cannot reflow anything - every tile is the same size whatever its"
		.. " timer says")

	-- an aura about to fall off says so
	local saved = _G.__auras.player.HELPFUL
	_G.__auras.player.HELPFUL = {
		{ "Ice Barrier", 135988, 0, nil, 30, nil, "player", true },
	}
	fire("UNIT_AURA", "player")
	PB:Tick()
	check(PB.tiles[1]._urgent == false, "a healthy timer is not urgent")
	time = time + 27
	PB:Tick()
	check(PB.tiles[1]._urgent == true, "under five seconds it turns urgent")
	_G.__auras.player.HELPFUL = saved
	fire("UNIT_AURA", "player")
	PB:Tick()
	check(PB.tiles[1]._urgent ~= true, "and back again when it is replaced")
end


print("== auras: a timer that has not arrived yet is never a blank field ==")
if TILES then
	local saved = _G.__auras.player.HELPFUL

	-- Case one, as the client actually reports it for the first few seconds
	-- after a login: a real duration with an expiry of zero. This used to come
	-- out of W.AuraTime as an empty string, get written to a fixed-width field,
	-- and stay empty for the rest of the session because the tile was not
	-- flagged timeless and the ticker just kept writing the same nothing.
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", 135932, 0, nil, 1800, nil, "player", true, 0 },
	}
	fire("UNIT_AURA", "player")
	local t = PB.tiles[1]
	check(t.time:GetText() == "n/a",
		"a duration with no expiry reads n/a rather than going blank (got '"
		.. tostring(t.time:GetText()) .. "')")
	check(t._stale == true and t._timeless == false,
		"and is marked stale, not permanent - the difference is whether we ever"
		.. " ask again")

	-- the server catches up. No UNIT_AURA fires, because nothing changed as far
	-- as the client is concerned - the re-poll is the only thing that can notice.
	_G.__auras.player.HELPFUL[1][9] = nil
	for i = 1, 15 do tick(0.1) end
	check(t.time:GetText() == "30m",
		"and the tile picks the real timer up on its own, with no UNIT_AURA to"
		.. " prompt it (got '" .. tostring(t.time:GetText()) .. "')")
	check(t._stale == false, "and stops asking")

	-- Case two: duration zero, which is what a permanent aura and an aura the
	-- server has not described yet both look like.
	_G.__auras.player.HELPFUL = {
		{ "Frost Armor", 135843, 0, nil, 0, nil, "player", true },
	}
	fire("UNIT_AURA", "player")
	t = PB.tiles[1]
	check(t.time:GetText() == "n/a" and t._timeless == true,
		"duration zero reads n/a and is believed permanent")

	_G.__auras.player.HELPFUL[1][5] = 1800
	for i = 1, 15 do tick(0.1) end
	check(t.time:GetText() == "30m",
		"but the belief is re-tested, so a buff that turns out to have a timer"
		.. " gets one (got '" .. tostring(t.time:GetText()) .. "')")

	-- and a re-poll must not read a neighbour's clock when indices shift
	_G.__auras.player.HELPFUL = {
		{ "Well Fed", 133905, 0, nil, 0, nil, nil, false },
	}
	fire("UNIT_AURA", "player")
	t = PB.tiles[1]
	check(t._timeless == true and t._name == "Well Fed", "a genuinely permanent aura")
	_G.__auras.player.HELPFUL = {
		{ "Ice Barrier", 135988, 0, nil, 60, nil, "player", true },
	}
	for i = 1, 15 do tick(0.1) end   -- no UNIT_AURA: the tile still thinks it is Well Fed
	check(t.time:GetText() == "n/a",
		"whose tile refuses to take a duration from whatever now sits at its"
		.. " index, because the name no longer matches")

	-- The sequence actually seen in game. The buff is a real thirty-minute one
	-- with time left on it, but at login the client hands out an expiry that is
	-- only a few seconds away. The tile counts that down, reaches zero, and -
	-- before this - printed an empty string into a fixed-width field and kept
	-- printing it, because a tile only ever re-formats the numbers it cached at
	-- the last Update and UNIT_AURA never fires again if nothing changes.
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", 135932, 0, nil, 1800, nil, "player", true,
		  GetTime() + 3 },
	}
	fire("UNIT_AURA", "player")
	t = PB.tiles[1]
	check(t.time:GetText() == "3s", "a bad expiry from the server counts down")
	for i = 1, 40 do tick(0.1) end
	check(t.time:GetText() ~= "",
		"and when it runs out the field never goes blank (got '"
		.. tostring(t.time:GetText()) .. "')")

	_G.__auras.player.HELPFUL[1][9] = nil   -- the client finally has it right
	for i = 1, 15 do tick(0.1) end
	check(t.time:GetText() == "30m",
		"the tile re-reads and picks up the real remaining time, with no"
		.. " UNIT_AURA and long after Resettle has given up (got '"
		.. tostring(t.time:GetText()) .. "')")

	-- the diagnostic has to survive whatever state the trays are in, because the
	-- one time anybody runs it is when something is wrong
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", 135932, 0, nil, 1800, nil, "player", true, 0 },
		{ "Well Fed", 133905, 0, nil, 0, nil, nil, false },
	}
	fire("UNIT_AURA", "player")
	local printed = 0
	local realAdd = DEFAULT_CHAT_FRAME.AddMessage
	DEFAULT_CHAT_FRAME.AddMessage = function(self, msg)
		printed = printed + 1
		realAdd(self, msg)
	end
	local ok, err = pcall(function() SlashCmdList["AETHERUI"]("auras") end)
    DEFAULT_CHAT_FRAME.AddMessage = realAdd
	check(ok, "the aura diagnostic runs: " .. tostring(err))
	check(printed > 8,
		"and prints what the API says next to what the tile believes, which is the"
		.. " only way any of these has ever actually been found (" .. printed
		.. " lines)")

	_G.__auras.player.HELPFUL = saved
	fire("UNIT_AURA", "player")
end

print("== an empty tray takes up no room ==")
if TILES then
	local tall = PB.frame:GetHeight()
	local saved = _G.__auras.player.HELPFUL
	_G.__auras.player.HELPFUL = {}
	fire("UNIT_AURA", "player")
	check(PB.frame:GetHeight() < tall and PB.active == 0,
		"an empty tray collapses instead of holding its last size")
	check(PB.tiles[1]:GetAlpha() == 0,
		"and its tiles are parked rather than hidden - hiding one would be"
		.. " refused in combat, since they carry secure cancel buttons")
	_G.__auras.player.HELPFUL = saved
	fire("UNIT_AURA", "player")

	_G.__units.target.exists = false
	fire("PLAYER_TARGET_CHANGED")
	check(TB.active == 0 and TD.active == 0, "both target trays clear with no target")
	_G.__units.target.exists = true
	fire("PLAYER_TARGET_CHANGED")
	check(TD.active == 1 or TD.active == 3, "and come back with one")
end

print("== turning a tray off ==")
if TILES then
	local cfg = A.db.profile.modules.auras
	cfg.buffs.target = false
	AU:OnConfigChanged()
	check(not AU.trays[3].enabled and TB.active == 0,
		"target buffs off empties that tray and only that tray")
	check(TD.active > 0, "the target's debuffs are untouched")
	cfg.buffs.target = true
	AU:OnConfigChanged()
	check(TB.active > 0, "and back on again")
end

print("== right-click to cancel ==")
if TILES then
	local cfg = A.db.profile.modules.auras.buffs

	check(AU.playerBuffs.tiles[PB.opts.max] ~= nil,
		"every buff tile is built up front, not lazily (" .. PB.opts.max .. " of them)")

	local bad = nil
	for i = 1, PB.opts.max do
		local c = PB.tiles[i] and PB.tiles[i].click
		if not c or c:GetAttribute("type2") ~= "macro" then bad = i break end
	end
	check(bad == nil, "every tile carries a secure macro button"
		.. (bad and (" (tile " .. bad .. " does not)") or ""))

	-- "cancelaura" as a secure action type does not dispatch on Classic Era -
	-- right-click did nothing. /cancelaura via a macro does.
	local m = {}
	for i = 1, PB.active do m[i] = PB.tiles[i].click:GetAttribute("macrotext2") end
	check(m[1] == "/cancelaura Frost Armor" and m[3] == "/cancelaura Ice Barrier",
		"the macro cancels by name (got " .. tostring(m[3]) .. ")")

	check(PB.tiles[1].click:GetNumPoints() == 2,
		"the cancel button tracks the tile with SetAllPoints, so resizing the tile"
		.. " in combat never touches the secure frame")
	check(PB.tiles[1].click:GetScript("PreClick") == nil,
		"nothing insecure sits *before* the secure dispatch - a PreClick hook taints"
		.. " it and the cancel gets refused in combat")
	check(PB.tiles[1].click:GetScript("PostClick") ~= nil,
		"but PostClick does the out-of-combat cancel, after the dispatch")

	check(PD.tiles[1] and PD.tiles[1].click == nil and PD.tiles[1]._auraName == nil,
		"debuff tiles get no cancel wiring at all - debuffs cannot be cancelled")
	check(TB.tiles[1] and TB.tiles[1].click == nil,
		"and neither do the target's buffs - they are not yours to drop")

	-- the actual cancel, both routes
	do
		_G.__cancelled = nil
		PB.tiles[2].click:GetScript("PostClick")(PB.tiles[2].click, "RightButton")
		check(_G.__cancelled ~= nil and _G.__cancelled.index == 2,
			"right-click out of combat cancels the buff that tile is showing")

		_G.__cancelled = nil
		PB.tiles[2].click:GetScript("PostClick")(PB.tiles[2].click, "LeftButton")
		check(_G.__cancelled == nil, "left-click does not")

		_G.__inCombat = true
		_G.__cancelled = nil
		PB.tiles[2].click:GetScript("PostClick")(PB.tiles[2].click, "RightButton")
		check(_G.__cancelled == nil,
			"and in combat the insecure route stands down - only the macro can act")
		_G.__inCombat = false

		-- the tile underneath covers the case where the secure button never built
		_G.__cancelled = nil
		local orphan = PB.tiles[3]
		orphan:GetScript("OnMouseUp")(orphan, "RightButton")
		check(_G.__cancelled ~= nil and _G.__cancelled.index == 3,
			"the tile's own OnMouseUp is the same handler, for when there is no"
			.. " secure button on top of it")
	end

	-- raising the cap mid-fight has to defer, then land
	-- The cap is min(configured max, columns x rows), so raising it means
	-- raising the row count, not the number - which is itself worth asserting.
	local cols, wasMax, wasRows = PB.opts.perRow, PB.opts.max, cfg.maxRows
	-- Tiles are never destroyed, only parked, and an earlier section ran with the
	-- unit frames off - where a tray has no capsule to size itself against and
	-- takes the configured max instead. Start this one from an empty display so
	-- "was it built during the fight" means what it says.
	for i = #PB.tiles, 1, -1 do PB.tiles[i] = nil end
	PB.active = 0
	_G.__inCombat = true
	cfg.maxRows = wasRows + 2
	AU:OnConfigChanged()
	local want = math.min(cfg.max, cols * cfg.maxRows)
	check(PB.opts.max == want and want > wasMax,
		("the cap is columns x rows, capped by the configured max (%d)"):format(want))
	check(PB._primePending, "raising the buff cap in combat defers the wiring")
	check(PB.tiles[want] == nil or PB.tiles[want].click == nil,
		"and writes no secure attribute while locked")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(PB.tiles[want] and PB.tiles[want].click
		and PB.tiles[want].click:GetAttribute("type2") == "macro",
		"the deferred wiring lands when the fight ends")
	check(not PB._primePending, "and the pending flag clears")
	cfg.maxRows = wasRows
	AU:OnConfigChanged()

	-- The one this whole section was missing. The tray's tiles carry secure
	-- buttons, so the tray *and every tile in it* is off limits for geometry in
	-- combat - the restriction reaches ancestors, not just the protected frame.
	-- Buffs coming and going mid-fight is the most ordinary thing there is, and
	-- it produced fourteen blocked-action reports per fight.
	local savedBuffs = _G.__auras.player.HELPFUL
	_G.__inCombat = true
	A.lastFailure = nil

	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", "T1", 0, nil, 1800, GetTime() + 1500, true },
		{ "Ice Armor",        "T2", 0, nil, 1800, GetTime() + 900,  true },
		{ "Evocation",        "T3", 3, nil,    8, GetTime() + 6,    true },
	}
	fire("UNIT_AURA", "player")
	_G.__auras.player.HELPFUL = {
		{ "Arcane Intellect", "T1", 0, nil, 1800, GetTime() + 1500, true },
	}
	fire("UNIT_AURA", "player")

	check(A.lastFailure == nil,
		"buffs coming and going mid-fight ask the client for nothing it will"
		.. " refuse (" .. tostring(A.lastFailure) .. ")")
	check(PB.active == 1, "and the tray still tracks what is actually up")
	check(PB.tiles[1]:GetAlpha() == 1 and PB.tiles[2]:GetAlpha() == 0,
		"the ones that dropped go to alpha rather than being moved or hidden")
	check(PB._layoutPending, "with the layout owed until the fight ends")

	-- A tile that has never been on screen still has a home, or a buff gained
	-- mid-fight would land nowhere: a frame with no points does not draw.
	check(PB.tiles[PB.opts.max] and PB.tiles[PB.opts.max]:GetPoint(1) ~= nil,
		"every slot was placed up front, so a new buff mid-fight has somewhere"
		.. " to appear")

	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not PB._layoutPending, "and the layout is settled when it does")

	_G.__auras.player.HELPFUL = savedBuffs
	fire("UNIT_AURA", "player")
end

-- ---------------------------------------------------------------------------
-- class resources (round 17, ported from archive/mop 2026-10-07)
--
-- A tray under the player capsule and nowhere else. Almost everything that can
-- go wrong here is silent on screen: a resource read through the wrong power
-- number draws as permanently empty, so most of what follows is about WHAT WAS
-- READ rather than about what was placed. Ported for a rogue who reported the
-- combo points missing on both clients.
-- ---------------------------------------------------------------------------

-- WRAPPED IN A BLOCK: the main chunk sits at LuaJIT's ceiling of 200 locals.
do

local RSm = A:GetModule("resources")
local PT = Enum.PowerType
local camelot = _G.__flavour == "camelot"

--- Give the player a class and whatever powers go with it, then rebuild.
local function beResource(class, secondary, fine, form)
	_G.__units.player.classToken = class
	_G.__units.player.secondary = secondary
	_G.__units.player.secondaryFine = fine
	_G.__shapeshiftForm = form
	RSm:Refresh()
	RSm:Reserve()
end

local function rowKeys()
	local out = {}
	for _, r in ipairs(RSm:Rows()) do out[#out + 1] = r.key end
	return table.concat(out, ",")
end

local function litPips()
	local n = 0
	for _, pip in ipairs(RSm.tray and RSm.tray.pips or {}) do
		if pip:IsShown() and pip.orb:IsShown() then n = n + 1 end
	end
	return n
end

local function shownPips()
	local n = 0
	for _, pip in ipairs(RSm.tray and RSm.tray.pips or {}) do
		if pip:IsShown() then n = n + 1 end
	end
	return n
end

print("== class resources: which row is live ==")
do
	check(RSm and RSm.enabled, "the resources module is enabled")
	check(RSm.tray ~= nil, "and a tray was built")

	-- NOBODY GETS A TRAY BY DEFAULT. An empty tray is permanent furniture that
	-- says nothing.
	beResource("WARRIOR", nil, nil)
	check(rowKeys() == "", "a class with no secondary resource has no rows")
	check(not RSm.tray:IsShown(), "and no tray at all, rather than an empty one")

	-- THE MAXIMUM IS WHAT SAYS YOU HAVE IT, and the count is the client's.
	beResource("PALADIN", { [PT.HolyPower] = { cur = 2, max = 3 } })
	check(rowKeys() == "holy", "a paladin's row is holy power (" .. rowKeys() .. ")")
	check(shownPips() == 3 and litPips() == 2,
		"three sockets and two lit - the EMPTY ones are drawn too ("
		.. shownPips() .. " / " .. litPips() .. ")")
	_G.__units.player.secondary[PT.HolyPower].max = 5
	RSm:Refresh()
	check(shownPips() == 5,
		"raising the client's maximum adds sockets without touching the table ("
		.. shownPips() .. ")")
end

print("== class resources: combo points, where each client keeps them ==")
do
	local wasTarget = _G.__units.target.exists
	_G.__units.target.exists = true

	if camelot then
		-- WOW FOREVER: the player's own power, as on the modern client. The
		-- mock's GetComboPoints answers zero here, so a tray still reading the
		-- target would light nothing.
		beResource("ROGUE", { [PT.ComboPoints] = { cur = 3, max = 5 } })
		check(rowKeys() == "combo", "a rogue's row is combo points")
		check(shownPips() == 5 and litPips() == 3,
			"five sockets and three lit, read from the player's own power ("
			.. litPips() .. ")")

		-- A SECRET READING draws empty sockets rather than erroring.
		_G.__units.player.secondary[PT.ComboPoints].cur = _G.__SecretStandIn()
		A.lastFailure = nil
		local ok = pcall(RSm.Refresh, RSm)
		check(ok and litPips() == 0 and shownPips() == 5,
			"a hidden (secret) count draws the sockets empty and does not throw")
		_G.__units.player.secondary[PT.ComboPoints].cur = 0
	else
		-- CLASSIC ERA: the TARGET'S, gone with it.
		beResource("ROGUE", { [PT.ComboPoints] = { cur = 0, max = 5 } })
		check(rowKeys() == "combo", "a rogue's row is combo points")
		_G.__comboPoints = 3
		RSm:Refresh()
		check(shownPips() == 5 and litPips() == 3,
			"five sockets and three lit, read from GetComboPoints - the target's ("
			.. litPips() .. ")")
		_G.__units.target.exists = false
		RSm:Refresh()
		check(shownPips() == 5 and litPips() == 0,
			"losing the target empties the row and KEEPS the sockets - the points"
			.. " are gone rather than stale (" .. litPips() .. ")")
		_G.__comboPoints = 0
	end

	-- A DRUID'S ARE A CAT FORM THING, asked of the form.
	beResource("DRUID", { [PT.ComboPoints] = { cur = 0, max = 5 } }, nil, nil)
	check(rowKeys() == "", "a druid out of Cat Form has no combo row (" .. rowKeys() .. ")")
	beResource("DRUID", { [PT.ComboPoints] = { cur = 0, max = 5 } }, nil, 1)
	check(rowKeys() == "combo", "and has one in Cat Form (" .. rowKeys() .. ")")

	_G.__units.target.exists = wasTarget
end

print("== class resources: the spec gate, where a client has specs ==")
do
	-- NEITHER CLIENT DEFINES THE MISTS SPEC CONSTANTS. With no spec the warlock
	-- rows drop; with one, the maximum decides, as it does for everybody else.
	local lock = { [PT.BurningEmbers] = { cur = 2, max = 4 } }
	local fine = { [PT.BurningEmbers] = { cur = 25, max = 40 } }
	_G.__spec = nil
	beResource("WARLOCK", lock, fine)
	check(rowKeys() == "", "with no spec, the spec-named rows drop (" .. rowKeys() .. ")")

	_G.__spec = 3
	beResource("WARLOCK", lock, fine)
	check(rowKeys() == "embers", "with one, the maximum decides (" .. rowKeys() .. ")")

	-- THE UNMODIFIED FLAG: 25 tenths is two embers and half of a third.
	check(shownPips() == 4 and litPips() == 2, "four ember sockets, two full")
	local third = RSm.tray.pips[3]
	check(third and third.fill:IsShown() and not third.orb:IsShown(),
		"and the third part filled and NOT lit - only readable through"
		.. " UnitPower's unmodified flag")
	check(third and math.abs(third.fill:GetHeight() - 13 * 0.5) < 0.51,
		"filled to half its height (" .. tostring(third and third.fill:GetHeight()) .. " of 13)")
	_G.__spec = nil
end

print("== class resources: the death knight, the one stacked case ==")
do
	beResource("DEATHKNIGHT", { [PT.RunicPower] = { cur = 45, max = 100 } })
	check(rowKeys() == "runes,runicPower", "two rows, pips above the bar (" .. rowKeys() .. ")")
	check(shownPips() == 6, "six runes (" .. shownPips() .. ")")

	-- HUED BY TYPE, per socket, read off the gradient a lit pip is drawn with.
	local blood = A.Palette.c.resource.runeBlood
	local frost = A.Palette.c.resource.runeFrost
	local _, p1top = RSm.tray.pips[1].orb:GetGradient()
	local _, p3top = RSm.tray.pips[3].orb:GetGradient()
	check(p1top and math.abs(p1top[1] - blood[1][1]) < 0.01, "the first rune is blood-hued")
	check(p3top and math.abs(p3top[1] - frost[1][1]) < 0.01,
		"and the third is frost - the hue is the socket's, not the row's")

	-- RECHARGING IS A LIQUID LEVEL AND NOT A SWEEP.
	_G.__runes[2] = { type = 1, start = GetTime() - 5, duration = 10, ready = false }
	RSm:Refresh()
	local r2 = RSm.tray.pips[2]
	check(not r2.orb:IsShown() and r2.fill:IsShown(),
		"a spent rune is a filling socket rather than a lit orb")
	_G.__runes[2] = { type = 1, start = 0, duration = 0, ready = true }
	RSm:Refresh()
	check(RSm.tray.pips[2].orb:IsShown(), "and a rune that was never spent is simply ready")

	local flow = RSm.tray.flows[1]
	check(flow and flow:IsShown() and flow.readout:GetText() == "45",
		"and the runic power bar is drawn with its value")
	check(flow.tick:IsShown(), "and a threshold tick")
end

print("== class resources: only the player, flush under the capsule ==")
do
	beResource("ROGUE", { [PT.ComboPoints] = { cur = 0, max = 5 } })
	local UFm = A:GetModule("unitframes")
	check(RSm.tray:GetParent() == UFm.player, "the tray hangs off the player capsule")
	check(RSm.tray:GetWidth() <= UFm.player:GetWidth() + 0.01,
		"and never exceeds it (" .. RSm.tray:GetWidth() .. " of " .. UFm.player:GetWidth() .. ")")

	-- CLIPPED, NEVER TUCKED BEHIND: a translucent capsule hides nothing.
	check(RSm.tray:GetClipsChildren() == true, "the tray clips its children")
	local pt, _, rel, _, yoff = RSm.tray:GetPoint(1)
	local px = A:PxIn(RSm.tray)
	check(pt == "TOP" and rel == "BOTTOM" and (yoff or 0) >= 0 and (yoff or 0) <= px + 0.001,
		"its top edge is the capsule's foot, overlapping by one physical pixel and no more")
	local _, _, _, _, gy = RSm.tray.glass:GetPoint(1)
	check((gy or 0) > 0, "the glass reaches above that line so its top corners are cut square")
	check(RSm.tray:GetFrameLevel() > UFm.player:GetFrameLevel(),
		"and it draws above the capsule, clear of the shadow that edge casts")
	local highest
	for _, pip in ipairs(RSm.tray.pips) do
		if pip:IsShown() then
			local _, _, _, _, py = pip:GetPoint(1)
			local top = -(py or 0) - 13 / 2
			if not highest or top < highest then highest = top end
		end
	end
	check(highest ~= nil and highest >= 0,
		"every pip sits below the capsule's lower edge (" .. tostring(highest) .. ")")
end

print("== class resources: the player's debuffs make room ==")
-- The debuff row hangs from the same lower edge, so a character who can have
-- a tray has its debuffs hung one tray lower - ALWAYS, because the tray comes
-- and goes in a fight and the debuff row cannot be moved in one.
do
	local Aur = A:GetModule("auras")
	local function debuffY()
		local f
		if Aur.forever then
			for _, t in ipairs(Aur.forever.trays) do
				if t.key == "playerDebuffs" then f = t.host end
			end
		else
			for _, t in ipairs(Aur.trays or {}) do
				if t.key == "playerDebuffs" then f = t.display.frame end
			end
		end
		return f and select(5, f:GetPoint(1))
	end

	beResource("WARRIOR", nil, nil)
	check(RSm:ReserveHeight() == 0, "a warrior leaves no room - there is never a tray")
	local yNone = debuffY()

	beResource("ROGUE", { [PT.ComboPoints] = { cur = 0, max = 5 } })
	local room = RSm:ReserveHeight()
	check(room == 7 * 2 + 13, "a rogue's room is one row of pips and its padding (" .. room .. ")")
	local yRogue = debuffY()
	check(yNone and yRogue and math.abs((yNone - yRogue) - room) < 0.01,
		"and the player's debuffs hang exactly that much lower ("
		.. tostring(yNone) .. " -> " .. tostring(yRogue) .. ")")

	-- WHETHER THE TRAY IS UP OR NOT.
	RSm.tray:Hide()
	Aur:Reanchor()
	check(debuffY() == yRogue, "and stay there with the tray hidden - they do not follow it")

	-- A DRUID KEEPS THE ROOM IN EVERY FORM: shifting to Cat in a fight cannot
	-- move the debuffs.
	beResource("DRUID", { [PT.ComboPoints] = { cur = 0, max = 5 } }, nil, nil)
	check(rowKeys() == "" and RSm:ReserveHeight() == room,
		"a druid in caster form has no row but keeps the room for one")

	-- AND NEVER SHOWN MEANS NO ROOM.
	local was = A.db.profile.modules.resources.display
	A.db.profile.modules.resources.display = "off"
	RSm:Reserve()
	check(RSm:ReserveHeight() == 0 and debuffY() == yNone,
		"set never to show, the room goes back to the debuffs")
	A.db.profile.modules.resources.display = was
	beResource("WARRIOR", nil, nil)
	check(debuffY() == yNone, "and a class with no tray puts them back under the capsule")
end

print("== class resources: when it is on screen ==")
do
	beResource("PALADIN", { [PT.HolyPower] = { cur = 1, max = 3 } })
	local was = A.db.profile.modules.resources.display
	local wasTarget = _G.__units.target.exists

	_G.__units.target.exists = false
	_G.__inCombat = true
	RSm:UpdateVisibility()
	check(RSm.tray:IsShown() and RSm.tray:GetAlpha() == 1, "in combat it is up, at full strength")

	_G.__inCombat = false
	_G.__units.target.exists = true
	RSm:UpdateVisibility()
	check(RSm.tray:IsShown(), "a target keeps it up out of combat")

	_G.__units.target.exists = false
	RSm._changed = GetTime() - 1
	RSm:UpdateVisibility()
	check(RSm.tray:IsShown(), "and a change keeps it up for three seconds")

	-- The tray EASES out: run its fade to the end before asking.
	local function settle()
		local up = RSm.tray:GetScript("OnUpdate")
		if up then up(RSm.tray, 1) end
	end

	RSm._changed = GetTime() - 10
	RSm:UpdateVisibility()
	check(RSm.tray:IsShown() and RSm.tray.__fading,
		"past that, with nothing happening, it starts to fade rather than blinking out")
	local up = RSm.tray:GetScript("OnUpdate")
	if up then up(RSm.tray, 0.15) end
	check(RSm.tray:IsShown() and RSm.tray:GetAlpha() > 0 and RSm.tray:GetAlpha() < 1,
		"half way through it is half there (" .. RSm.tray:GetAlpha() .. ")")
	settle()
	check(not RSm.tray:IsShown() and RSm.tray:GetAlpha() == 1,
		"and then it goes, ready to come back at full strength")

	_G.__units.player.secondary[PT.HolyPower].cur = 3
	RSm:Refresh()
	RSm._changed = GetTime() - 10
	RSm:UpdateVisibility()
	check(RSm.tray:IsShown() and RSm.tray:GetAlpha() < 1,
		"but a FULL one fades to a dim rather than going")

	A.db.profile.modules.resources.display = "combat"
	RSm._changed = GetTime()
	RSm:UpdateVisibility()
	settle()
	check(not RSm.tray:IsShown(), "combat only means combat only")
	_G.__inCombat = true
	RSm:UpdateVisibility()
	check(RSm.tray:IsShown(), "and a fight brings it straight back")
	_G.__inCombat = false

	A.db.profile.modules.resources.display = "off"
	RSm:UpdateVisibility()
	check(not RSm.tray:IsShown(), "off is off, in combat or out")

	A.db.profile.modules.resources.display = was
	_G.__units.target.exists = wasTarget
end

print("== class resources: only its own resource holds it up ==")
-- Seen on WoW Forever (2026-10-07): an empty rogue's tray, no target, out of
-- combat, staying up. Energy ticking restarted the grace period on every tick,
-- and nothing looked again once the grace period ran out.
do
	local wasTarget = _G.__units.target.exists
	_G.__units.target.exists = false
	_G.__inCombat = false
	_G.__pending, _G.__pendingDelay, _G.__pendingDue = {}, {}, {}
	beResource("ROGUE", { [PT.ComboPoints] = { cur = 0, max = 5 } })
	RSm._changed = GetTime() - 10
	RSm._graceMark = nil
	RSm:UpdateVisibility()
	local up = RSm.tray:GetScript("OnUpdate")
	if up then up(RSm.tray, 1) end
	check(not RSm.tray:IsShown(), "an empty rogue with no target, out of combat, has no tray")

	-- ENERGY IS NOT OURS.
	fire("UNIT_POWER_FREQUENT", "player", "ENERGY")
	check(not RSm.tray:IsShown(),
		"energy ticking does not bring it back - it is not this tray's resource")

	-- A COMBO POINT IS, and holds it up for the grace period...
	check(RSm:Owns("COMBO_POINTS") and not RSm:Owns("ENERGY"),
		"the tray knows combo points as its own and energy as not")
	fire("UNIT_POWER_FREQUENT", "player", "COMBO_POINTS")
	check(RSm.tray:IsShown() and RSm.tray:GetAlpha() == 1,
		"a combo point changing brings it up")

	-- ...and only for that. The look-again is what was missing.
	time = time + 3.1
	_G.__drainTimers(1)
	check(RSm.tray.__fading == true,
		"when the grace period runs out it looks again on its own, and starts to"
		.. " go - rather than waiting for an event that may never come")
	up = RSm.tray:GetScript("OnUpdate")
	if up then up(RSm.tray, 1) end
	check(not RSm.tray:IsShown(), "and is gone")

	-- A fade interrupted by something worth showing is cancelled, not finished.
	fire("UNIT_POWER_FREQUENT", "player", "COMBO_POINTS")
	RSm._changed = GetTime() - 10
	RSm:UpdateVisibility()
	check(RSm.tray.__fading == true, "fading again")
	_G.__units.target.exists = true
	RSm:UpdateVisibility()
	check(RSm.tray:IsShown() and RSm.tray:GetAlpha() == 1 and not RSm.tray.__fading
		and RSm.tray:GetScript("OnUpdate") == nil,
		"and a target arriving mid-fade puts it straight back, fade cancelled")

	_G.__units.target.exists = wasTarget
	beResource("WARRIOR", nil, nil)
end

