print("== quest tracker ==")

local QT = A:GetModule("questtracker")
check(QT and QT.enabled, "questtracker module enabled"
	.. (QT and QT.lastError and ("  -- " .. QT.lastError) or ""))

--- The text beside the i-th quest node on the World trunk, while it holds a
--  quest: what a row of the old floating panel was, and carrying the same
--  fields - questTitle, index, questID, lines, the mouse script. Globals: the
--  file is at the local cap.
function _G.TRow(i)
	local n = QT.nodes and QT.nodes[i]
	return n and n.quest and n.holder or nil
end
--- Whether the i-th quest node wears the active look: an accent outline lit.
function _G.TActive(i)
	local n = QT.nodes and QT.nodes[i]
	if not (n and n.quest and n.quest.active and n.button:IsShown() and n.button.glow:IsShown()) then
		return false
	end
	local r, g, b = n.button.rim:GetVertexColor()
	local a = A.Palette.c.accent
	return math.abs(r - a[1]) < 0.001 and math.abs(g - a[2]) < 0.001 and math.abs(b - a[3]) < 0.001
end
--- The reference screen (1920 x 1080, the minimap at its default) on, and
--  the screen that was there put back off. How many quests the trunk can hold
--  depends on both.
function _G.__refScreen(on)
	if on then
		_G.__refSaved = { w = UIParent:GetWidth(), h = UIParent:GetHeight(), geom = UIParent.__geom,
			anchors = A.db.profile.anchors }
		UIParent:SetSize(1920, 1080)
		UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
		A.db.profile.anchors = {}
	elseif _G.__refSaved then
		local s = _G.__refSaved
		UIParent:SetSize(s.w, s.h)
		UIParent.__geom = s.geom
		A.db.profile.anchors = s.anchors
		_G.__refSaved = nil
	end
	A:Reconfigure()
end
--- How many quest nodes are on the trunk now.
function _G.TShown()
	local k = 0
	for _, n in ipairs(QT.nodes or {}) do
		if n.quest and n.button:IsShown() then k = k + 1 end
	end
	return k
end
check(QT.nodes and QT.nodes[1] and QT.nodes[1].button and A.Trunk:Get("world").frame:IsShown(),
	"the tracked quests are nodes on the World trunk")

-- THE REFERENCE SCREEN for every tracker section: the quests are nodes on the
-- World trunk, and how many fit depends on where the minimap sits and how tall
-- the screen is. Put back after the last tracker section.
_G.__trackerScreen = { w = UIParent:GetWidth(), h = UIParent:GetHeight(), anchors = A.db.profile.anchors,
	geom = UIParent.__geom }
UIParent:SetSize(1920, 1080)
-- A rect as well as a size: the mock answers UIParent's top as a flat 400 without one.
UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
A.db.profile.anchors = {}
A:Reconfigure()

do
	-- The fader section above entered combat and never left it, so the tracker
	-- is legitimately folded by the time we get here. Start from a known state.
	_G.__inCombat = false
	QT._preCombat = nil
	QT:SetCollapsed(false)
	A.db.char.tracked, A.db.char.untracked = {}, {}
	QT:Refresh()

	-- auto mode is the default: everything in the log, nothing to opt in to
	check(#QT.quests == 4,
		"auto-track shows every quest in the log with no gesture at all (got "
		.. #QT.quests .. ")")
	check(GetNumQuestWatches() == 0 and #_G.__watches == 0,
		"and never touches Blizzard's watch list to do it")
	check(TShown() == 4, "each one a node on the trunk (" .. TShown() .. ", room "
		.. tostring(A.Trunk:Get("world"):Room()) .. ", screen " .. UIParent:GetWidth() .. "x"
		.. UIParent:GetHeight() .. ", pill bottom "
		.. tostring(select(2, A.Movers.PointAt(A:GetModule("minimap").pill, "BOTTOM"))) .. ")")
	-- 6a's geometry: under the Quest Log node, 32 apart (compact), each
	-- quest's text ending 8 short of its node, its title level with it. Both
	-- tightened in game (Joe): the first quest 36 under the Quest Log node,
	-- not a branch node's 72.
	local n1, n2 = QT.nodes[1], QT.nodes[2]
	local ql = A.Trunk:Get("world"):Node("questlog")
	check(n1.y < ql.y and math.abs(n1.y - n2.y - 32) < 0.5,
		"quest nodes hang under the Quest Log node, 32 apart (" .. (n1.y - n2.y) .. ")")
	check(math.abs(ql.y - n1.y - 36) < 0.5,
		"the first one 36 under the Quest Log node (" .. (ql.y - n1.y) .. ")")
	local cx, cy = A.Movers.PointAt(n1.button, "CENTER")
	local tr = A.Movers.PointAt(n1.holder.title, "RIGHT")
	local ty = select(2, A.Movers.PointAt(n1.holder.title, "CENTER"))
	check(math.abs(cx - tr - 17) < 0.5 and math.abs(ty - cy) < 0.5,
		"its text ends 8 short of the node, level with it (" .. (cx - tr) .. ", " .. (ty - cy) .. ")")

	-- dismissing one is a blacklist entry, and it has to stick across a refresh
	QT.SetTracked(1069, false)
	QT:Refresh()
	check(#QT.quests == 3 and A.db.char.untracked[1069],
		"dismissing a quest blacklists it rather than rebuilding a whitelist")
	local stillThere = false
	for _, q in ipairs(QT.quests) do
		if q.questID == 1069 then stillThere = true end
	end
	check(not stillThere, "and it stays gone across a refresh")

	-- a newly accepted quest appears on its own
	table.insert(_G.__questLog, { id = 7777, title = "A Fresh Errand", level = 20,
		objectives = { { "Errand run: 0/1", "event", false } } })
	QT:Refresh()
	check(#QT.quests == 4, "a newly accepted quest shows up without being tracked")
	table.remove(_G.__questLog)

	QT.SetTracked(1069, true)
	QT:Refresh()
	check(#QT.quests == 4 and A.db.char.untracked[1069] == nil, "and can be brought back")
end

do  -- both sets are pruned against the live log, the way Questie prunes its two
	A.db.char.untracked[999999] = true
	A.db.char.tracked[888888] = true
	QT:Refresh()
	check(A.db.char.untracked[999999] == nil and A.db.char.tracked[888888] == nil,
		"IDs that are not in the log are dropped from both sets - neither can grow"
		.. " without bound")
end

print("== quest tracker: manual mode ==")
do
	A.db.profile.modules.questtracker.autoTrack = false
	A.db.char.tracked, A.db.char.untracked = {}, {}
	QT:Refresh()
	check(#QT.quests == 0 and TShown() == 0, "manual mode starts empty - it is a whitelist")
	local bare = A.Trunk:Get("world").frame:GetHeight()

	-- shift-clicking in Blizzard's quest log puts an index in ITS watch list;
	-- we adopt it and hand the slot straight back, which is the only way that
	-- gesture keeps working past Blizzard's five-quest cap
	AddQuestWatch(2)
	AddQuestWatch(3)
	QT:Refresh()
	check(GetNumQuestWatches() == 0,
		"Blizzard's watch list is emptied again, so its five-slot cap never bites")
	check(A.db.char.tracked[861] and A.db.char.tracked[1069],
		"and both quests landed in our own set, keyed by questID")
	check(#QT.quests == 2 and TShown() == 2, "two quest nodes now (got " .. #QT.quests .. ")")
	check(A.Trunk:Get("world").frame:GetHeight() > bare, "the trunk grew to hold them")
end

do
	local row = TRow(1)
	check(row.questTitle == "Chen's Empty Keg", "node 1 is the first tracked quest in log order")
	check(row.title:GetText() == "Chen's Empty Keg", "its title beside it")
	-- COMPACT (Joe): not the active quest, so its objectives are not under it -
	-- they pop out with the cursor on it.
	check(not (row.lines[1] and row.lines[1]:IsShown()), "no objective lines under a quest that is not active")
	row:GetScript("OnEnter")(row)
	check(GameTooltip:IsShown() and GameTooltip.__lines[1] == "Chen's Empty Keg"
		and GameTooltip.__lines[2] == "Empty Keg: 0/1",
		"hovered, its objectives pop out beside it (" .. tostring(GameTooltip.__lines[2]) .. ")")
	row:GetScript("OnLeave")(row)
	check(not GameTooltip:IsShown(), "and go when the cursor leaves")
	check(math.abs(QT.quests[1].pct - 0) < 0.01,
		"progress comes from the numbers in the objective text")
	check(QT.quests[2].complete and math.abs(QT.quests[2].pct - 1) < 0.01,
		"a finished quest reads as complete")
end

do  -- indices shift when the log changes; the tracker must not hold one
	table.insert(_G.__questLog, 2, { id = 99, title = "A New Quest", level = 12, objectives = {} })
	QT:Refresh()
	local row = TRow(1)
	check(row.questTitle == "Chen's Empty Keg" and row.index == 3,
		"the same quest is still row 1, now at log index " .. tostring(row.index)
		.. " - tracking is by questID, not by index")
	table.remove(_G.__questLog, 2)
	QT:Refresh()
end

do  -- partial progress across two objectives: 3/8 and 1/4 is 4/12
	AddQuestWatch(5)
	QT:Refresh()
	local q
	for _, entry in ipairs(QT.quests) do
		if entry.questID == 4901 then q = entry end
	end
	check(q and math.abs(q.pct - (4 / 12)) < 0.001,
		"progress sums the counters across every objective (got "
		.. string.format("%.3f", q and q.pct or -1) .. ")")
	check(q and #q.lines >= 2, "both objective lines read")
end

do  -- a quest with no objectives falls back to isComplete rather than showing 0%
	AddQuestWatch(6)
	QT:Refresh()
	local q
	for _, entry in ipairs(QT.quests) do
		if entry.questID == 5041 then q = entry end
	end
	check(q and #q.lines == 0 and q.pct == nil,
		"an objective-less quest gets no bar at all, rather than one pinned at zero")
end

print("== quest tracker: the room on the trunk ==")
do
	-- Ten at most (the design's number), and fewer where the screen is too
	-- short: 6a's own spacing ran ten quests off a 1080 screen. What does not
	-- fit is one "+n" node, never silently dropped.
	local cfg = A.db.profile.modules.questtracker
	local saved = cfg.max
	cfg.max = 1
	QT:Refresh()
	local more = QT.more
	check(QT.hidden > 0 and TShown() == 1, "a max of one shows one quest node (" .. QT.hidden .. " hidden)")
	check(more and more.button:IsShown() and more.holder.title:GetText() == "+" .. QT.hidden,
		"and the rest are one +n node rather than silently dropped (got "
		.. tostring(more and more.holder.title:GetText()) .. ")")

	-- AND IT OPENS THE LOG, at the FIRST of the hidden ones - not the first
	-- tracked one, which is already on the trunk. Those are the same quest
	-- whenever nothing is hidden, so the difference only shows here.
	do
		local want = more.moreQuest
		local firstShown = TRow(1) and TRow(1).questID
		check(want and firstShown ~= nil and want.questID ~= firstShown,
			"it stands for one of the HIDDEN quests (" .. tostring(want and want.questID)
			.. " vs " .. tostring(firstShown) .. ")")
		local QLg = A:GetModule("questlog")
		QLg:Hide()
		more.button:GetScript("OnClick")(more.button, "LeftButton")
		check(QLg.win and QLg.win:IsShown(), "clicking it opens our log")
		check(want and QLg.selectedID == (want.questID or ("i" .. tostring(want.index))),
			"at the first quest it was standing in for (got " .. tostring(QLg.selectedID) .. ")")
		QLg:Hide()
	end
	cfg.max = saved
	QT:Refresh()
	check(not more.button:IsShown() and QT.hidden == 0, "the max restored, every quest is back and the +n goes")

	-- The screen's own height: a short screen holds fewer. 700, near the
	-- shortest UIParent the client gives (768 at the largest UI scale is about
	-- 668): at 480 the minimap at 6a's place and the four world tools under
	-- the quests leave no room for even the +n node.
	local w, h = UIParent:GetWidth(), UIParent:GetHeight()
	UIParent:SetSize(w, 700)
	UIParent:SetGeom({ cx = w / 2, cy = 350, left = 0, right = w, bottom = 0, top = 700 })
	A:Reconfigure()
	check(QT.hidden > 0 and more.button:IsShown(),
		"on a short screen the quests that do not fit fold into +n (" .. QT.hidden .. " hidden)")
	local lastY = select(2, A.Movers.PointAt(more.button, "BOTTOM"))
	for _, n in ipairs(QT.nodes) do
		if n.quest and n.button:IsShown() then
			lastY = math.min(lastY, select(2, A.Movers.PointAt(n.button, "BOTTOM")))
		end
	end
	check(lastY and lastY > 24, "and nothing on the trunk runs off its bottom (lowest at "
		.. tostring(lastY) .. ", " .. TShown() .. " quests shown)")
	-- The Quest Log node over the quests takes 36 of the room, as it does on
	-- the strand, not a branch node's 72 and not nothing.
	local withLog = A.Trunk:Get("world"):Room()
	A:SetModuleEnabled("questlog", false)
	local noLog = A.Trunk:Get("world"):Room()
	A:SetModuleEnabled("questlog", true)
	check(withLog and noLog and math.abs(noLog - withLog - 36) < 0.5,
		"the Quest Log node above the quests counts 36 of the room (" .. tostring(noLog and withLog and noLog - withLog) .. ")")
	UIParent:SetSize(w, h)
	UIParent:SetGeom({ cx = w / 2, cy = h / 2, left = 0, right = w, bottom = 0, top = h })
	A:Reconfigure()
end

print("== quest focus: WoW Forever's super-tracking ==")
do
	local QL = A:GetModule("questlog")
	local function menuItem(text)
		for _, it in ipairs(A.Widgets.MenuFrame().items) do
			if it:IsShown() and it.text:GetText() == text then return it end
		end
	end

	if _G.__flavour == "camelot" then
		-- THE FOCUSED QUEST IS THE ACTIVE ONE (Lattice 6a), and compact shows
		-- objectives under the active quest only (Joe).
		C_SuperTrack.__id = 0
		QT:Refresh()
		local row = TRow(1)
		check(not TActive(1) and not (row.lines[1] and row.lines[1]:IsShown()),
			"nothing focused: no active quest, no objective lines on the trunk")

		row:GetScript("OnMouseUp")(row, "RightButton")
		local focus = menuItem("Focus this quest")
		check(focus ~= nil, "the menu offers to focus it")
		if focus then focus:GetScript("OnClick")(focus) end
		row = TRow(1)
		check(C_SuperTrack.__id == row.questID and TActive(1),
			"focused, it is the active node - a lit accent outline (" .. tostring(C_SuperTrack.__id) .. ")")
		local line = row.lines[1]
		check(line and line:IsShown() and line:GetText() == "Empty Keg: 0/1",
			"with its objectives under its title (" .. tostring(line and line:GetText()) .. ")")

		-- An objective line keeps its quest focused; it does not open the log.
		QL:Hide()
		line.__mouseOver = true
		row:GetScript("OnMouseUp")(row, "LeftButton")
		line.__mouseOver = false
		check(C_SuperTrack.__id == row.questID and not (QL.win and QL.win:IsShown()),
			"clicking an objective line keeps it focused and does not open the log")

		-- The menu offers to stop, and stopping clears it everywhere.
		row:GetScript("OnMouseUp")(row, "RightButton")
		local stop = menuItem("Stop focusing")
		check(stop ~= nil, "the menu offers Stop focusing on the focused quest")
		if stop then stop:GetScript("OnClick")(stop) end
		check(C_SuperTrack.__id == 0 and not TActive(1) and not TRow(1).lines[1]:IsShown(),
			"and it stops: the node goes back to plain, its lines with it")

		-- Focus set from elsewhere (Blizzard's map) is followed through the event.
		C_SuperTrack.SetSuperTrackedQuestID(TRow(1).questID)
		check(TActive(1), "focus set from anywhere else is shown too - SUPER_TRACKING_CHANGED")

		-- The log's Focus button: present, worded by state, and it toggles.
		-- Opening the log selects its first QUEST by itself (EnsureSelection);
		-- entry 1 is a zone heading, which shows nothing.
		QL:Show()
		local foot = QL.win.detail.foot
		check(foot.focus:IsShown(), "the quest log has a Focus button")
		local shownID = QL.shown and QL.shown.questID
		check(shownID ~= nil, "with a quest showing to focus")
		C_SuperTrack.SetSuperTrackedQuestID(0)
		QL:ToggleFocus()
		check(C_SuperTrack.__id == shownID, "Focus focuses the shown quest")
		check(foot.focus.label:GetText() == "Unfocus", "and the button then offers Unfocus")
		QL:ToggleFocus()
		check(C_SuperTrack.__id == 0, "and Unfocus stops")
		QL:Hide()
	else
		-- Classic Era: no super-tracking, so nothing anywhere offers it, and with
		-- no TomTom route nothing is active: titles only, objectives on hover.
		check(not A.Quest.CanFocus(), "Classic Era cannot focus")
		check(not TActive(1) and not (TRow(1).lines[1] and TRow(1).lines[1]:IsShown()),
			"and with no route, no quest is active and none shows its lines")
		local QLog = A:GetModule("questlog")
		QLog:Hide()
		local row = TRow(1)
		row:GetScript("OnMouseUp")(row, "LeftButton")
		check(QLog.win and QLog.win:IsShown(), "a click on a quest opens the log")
		QLog:Hide()

		local r = TRow(1)
		r:GetScript("OnMouseUp")(r, "RightButton")
		local offered = false
		for _, it in ipairs(A.Widgets.MenuFrame().items) do
			local t = it.text:GetText()
			if t == "Focus this quest" or t == "Stop focusing" then offered = true end
		end
		check(not offered, "and the menu offers no focus")
		QLog:Show()
		check(not QLog.win.detail.foot.focus:IsShown(), "and the log shows no Focus button")
		QLog:Hide()
	end
end

--- The tracker menu's shown item with this text. By NAME, not by position:
--  WoW Forever adds Focus near the top, so "item 3 is Share" was true on one
--  client only.
local function TrackerMenuItem(text)
	for _, it in ipairs(A.Widgets.MenuFrame().items) do
		if it:IsShown() and it.text:GetText() == text then return it end
	end
end
-- Open / (Focus) / Stop tracking / Share / Abandon, before any Navigate item.
local TRACKER_MENU_BASE = A.Quest.CanFocus() and 5 or 4

print("== quest tracker: clicks ==")
do
	local row = TRow(1)

	-- This check used to read `__questLogOpenedTo == row.index`, which asserted
	-- that Blizzard's QuestLog_OpenToQuest had been called - and that WAS the
	-- bug. A test can only ever pin down the behaviour somebody wrote into it;
	-- this one pinned down opening the very window the addon replaces, and went
	-- green for as long as it kept happening.
	local QL = A:GetModule("questlog")
	QL:Hide()
	_G.__questLogOpenedTo = nil
	row:GetScript("OnMouseUp")(row, "LeftButton")
	check(QL.win and QL.win:IsShown() and QL.selectedID == row.questID,
		"left-click opens OUR log at that quest")
	check(_G.__questLogOpenedTo == nil,
		"and leaves Blizzard's frame alone (it is the one we replaced)")
	QL:Hide()

	-- shift-click untracks
	_G.__shift = true
	local before = #QT.quests
	row:GetScript("OnMouseUp")(row, "LeftButton")
	check(#QT.quests == before - 1, "shift-click stops tracking it")
	check(A.db.char.tracked[861] == nil, "and it leaves our set")
	_G.__shift = false
	AddQuestWatch(2)
	QT:Refresh()

	-- right-click menu
	local r = TRow(1)
	r:GetScript("OnMouseUp")(r, "RightButton")
	check(A.Widgets.MenuFrame() and A.Widgets.MenuFrame():IsShown(), "right-click opens the menu")
	check(#A.Widgets.MenuFrame().items >= 4, "menu has open / untrack / share / abandon")
	check(A.Widgets.MenuFrame().items[1].text:GetText() == "Open quest log", "first item opens the log")

	-- ...and it had better be OURS. Every route this used to take reached for
	-- Blizzard's QuestLogFrame - the frame Modules/QuestLog.lua exists to replace
	-- - so clicking a row opened the window the addon spends a module hiding, and
	-- threw on the way there: QuestLog_OnShow calls QuestLog_SetSelection BEFORE
	-- QuestLog_Update, and the selection path reads titleButton.r, which only
	-- Update ever writes. On a frame nobody has drawn that is SetVertexColor(nil).
	do
		local QL = A:GetModule("questlog")
		QL:Hide()
		_G.__questLogOpenedTo = nil

		local row = TRow(1)
		row:GetScript("OnMouseUp")(row, "LeftButton")

		check(QL.win and QL.win:IsShown(),
			"clicking a row opens OUR quest log, not the one this addon replaced")
		check(_G.__questLogOpenedTo == nil,
			"and never calls Blizzard's QuestLog_OpenToQuest, which shows their"
			.. " frame and takes the SetVertexColor(nil) crash with it")
		QL:Hide()

		-- Opened AT the clicked quest - and this has to be checked against a row
		-- the log would NOT have landed on by itself. Asserting it on row 1 is
		-- vacuous: EnsureSelection picks the first quest on show, so removing the
		-- Select call entirely leaves the check green. (Confirmed by mutation:
		-- deleting the select passed until this block used a different row.)
		local default_ = nil
		QL:Show()
		default_ = QL.selectedID
		QL:Hide()

		local other
		for i = 1, #QT.nodes do
			local r2 = TRow(i)
			if r2 and r2:IsShown() and r2.questID and r2.questID ~= default_ then other = r2 break end
		end
		check(other ~= nil,
			"there is a tracked row the log would not select on its own, or the"
			.. " check below proves nothing (default " .. tostring(default_) .. ")")
		if other then
			other:GetScript("OnMouseUp")(other, "LeftButton")
			check(QL.selectedID == other.questID,
				"opened AT the quest that was clicked rather than at whatever the"
				.. " log picks for itself (got " .. tostring(QL.selectedID)
				.. ", want " .. tostring(other.questID) .. ", default "
				.. tostring(default_) .. ")")
		end
		QL:Hide()
	end

	-- The menu opens ON TOP of the tracker's own panel, so it is a surface you
	-- read through two layers of glass unless it stops being glass. It takes the
	-- modal fill for exactly the reason the palette gives that token.
	check(A.Widgets.MenuFrame()._fillColor == A.Palette.c.dialogFill,
		"the menu is not glass - it takes the same fill as the abandon dialog")
	check((A.Widgets.MenuFrame()._fillColor[4] or 1) > (A.Palette.c.glassStrong[4] or 1),
		"which is more opaque than the panel underneath it (" .. (A.Widgets.MenuFrame()._fillColor[4] or 1)
		.. " vs " .. (A.Palette.c.glassStrong[4] or 1) .. ")")
	check(A.Widgets.MenuFrame()._edgeColor == A.Palette.c.glassEdgeHi,
		"with the brighter rim, or an opaque fill in a dim rim reads as a hole")

	-- And it follows a skin change, which goes through ApplySkin rather than
	-- through the constructor - the one place the two can disagree.
	local wasSkin = A.db.profile.skin
	A.db.profile.skin = OTHER
	A:Restyle()
	check(A.Widgets.MenuFrame()._fillColor == A.Palette.c.dialogFill
		and A.Widgets.MenuFrame()._edgeColor == A.Palette.c.glassEdgeHi,
		"and it is still the dialog surface after a skin change, not glass again")
	A.db.profile.skin = wasSkin
	A:Restyle()

	_G.__questShared = nil
	local share = TrackerMenuItem("Share quest")
	share:GetScript("OnClick")(share)
	check(_G.__questShared == r.index, "share quest routes through SelectQuestLogEntry")
	check(not A.Widgets.MenuFrame():IsShown(), "and the menu closes behind it")

	_G.__abandonPopup = nil
	r:GetScript("OnMouseUp")(r, "RightButton")
	local abandon = TrackerMenuItem("Abandon quest")
	abandon:GetScript("OnClick")(abandon)
	check(_G.__abandonPopup == "ABANDON_QUEST",
		"abandon goes through Blizzard's confirmation, never straight to AbandonQuest")
end

-- ---------------------------------------------------------------------------
-- Questie and TomTom mocks
--
-- Modelled on the contracts read out of the installed copies - Questie 11.33.2
-- and TomTom v4.3.8-release - rather than on how they are usually described,
-- because every detail below is a way this integration can be wrong while
-- looking perfectly right on screen:
--
--   * QuestieLoader:ImportModule returns an EMPTY STUB for a name it does not
--     know. Never nil, never an error. A module renamed out from under us is
--     therefore a table whose functions are all nil, and the only way to notice
--     is to type-check each one.
--   * Questie's spawn tables are keyed by AREA id, not uiMapID, and hold {x, y}
--     in 0-100. TomTom wants a uiMapID and 0-1. Two conversions, either of
--     which silently produces a waypoint somewhere else entirely.
--   * GetNearestSpawnForQuest returns the FINISHER when quest:IsComplete() == 1.
--   * ZoneDB:GetUiMapIdByAreaId is a COLON call - DistanceUtils' are not - and
--     returns nil for an area it has no mapping for.
--   * TomTom:AddWaypoint returns a uid TABLE, and deduplicates on map/x/y/title
--     without re-pointing its arrow, so a repeat call is a silent no-op.
-- ---------------------------------------------------------------------------

local questieNPCs = {
	-- npcId = { name, spawns keyed by areaId with 0-100 coords, dist = Questie's
	-- own ordering number, which is NOT yards and whose "nothing" is 999999999 }
	[3271] = { name = "Savannah Prowler", dist = 100, spawns = { [17] = { { 45.0, 62.0 } } } },
	[3441] = { name = "Mankrik",          dist = 100, spawns = { [17] = { { 52.5, 31.0 } } } },
	[3272] = { name = "Distant Prowler",  dist = 900, spawns = { [17] = { { 80.0, 20.0 } } } },
	[3273] = { name = "Near Prowler",     dist =  10, spawns = { [17] = { { 30.0, 40.0 } } } },
	[9999] = { name = "Somewhere Odd",    dist = 100, spawns = { [4242] = { { 10.0, 10.0 } } } },
	[8888] = { name = "In A Dungeon",     dist = 100, spawns = { [17] = { { -1, -1 } } } },
	[7777] = { name = "Off The Map",      dist = 100, spawns = { [17] = { { 150.0, 20.0 } } } },
	[6666] = { name = "Malformed",        dist = 100, spawns = "not a table" },
}

local questieObjects = {
	[1617] = { name = "Silverleaf", dist = 100, spawns = { [17] = { { 22.0, 74.0 } } } },
}

local questieItems = {
	-- What GetItem returns: an item has no location of its own, only sources.
	[4632] = { Sources = { { Id = 3273, Type = "monster" }, { Id = 1617, Type = "object" } } },
}

-- Counters for the things we should never hand another addon: a spawn table
-- that is not a table, or a nil area id. Both are guarded in Nav, and without
-- these the guards look redundant - the pcall around them would swallow the
-- error and the result would be nil either way, which is what the caller wanted
-- anyway. The property being tested is not "we survive it", it is "we do not do
-- it": an error raised inside Questie shows up in the player's chat as Questie's
-- bug, with our name nowhere near it.
local questieCalls = { getQuest = 0, badSpawns = 0, nilArea = 0 }

local function questieQuest(id, opts)
	opts = opts or {}
	local q = {
		Id = id,
		Objectives = opts.objectives or {},
		SpecialObjectives = {},
		ObjectiveData = opts.objectiveData or {},
		-- ALWAYS a table, exactly as QuestieDB.GetQuest builds it - it assigns
		-- Finisher unconditionally for every quest it knows. Modelling this as
		-- optional is what let an ordering bug through review: a `if not spawn
		-- and quest.Finisher` test placed too early is true for every quest
		-- alive, and it silently swallowed the database fallback underneath it.
		Finisher = opts.finisher or { NPC = { 3441 } },
		_complete = opts.complete and 1 or 0,
	}
	function q:IsComplete() return self._complete end
	return q
end

local questieQuests = {}

local function InstallQuestie()
	local modules = {}
	_G.QuestieLoader = {
		-- The real one hands back a stub rather than failing. That is the whole
		-- reason Nav type-checks every function it uses.
		ImportModule = function(_, name)
			modules[name] = modules[name] or { private = {} }
			return modules[name]
		end,
	}

	local db = _G.QuestieLoader:ImportModule("QuestieDB")
	local dist = _G.QuestieLoader:ImportModule("DistanceUtils")
	local zone = _G.QuestieLoader:ImportModule("ZoneDB")

	-- GetQuest is a DOT call; GetNPC / GetObject / GetItem are COLON calls. A
	-- mock that ignored the difference would hide the one class of mistake this
	-- integration is most likely to make.
	db.GetQuest = function(questId)
		questieCalls.getQuest = questieCalls.getQuest + 1
		return questieQuests[questId]
	end
	db.GetNPC = function(_, npcId) return questieNPCs[npcId] end
	db.GetObject = function(_, objectId) return questieObjects[objectId] end
	db.GetItem = function(_, itemId) return questieItems[itemId] end

	dist.GetNearestSpawn = function(spawns)
		if type(spawns) ~= "table" then
			-- The real one walks it with pairs() and no guard at all.
			questieCalls.badSpawns = questieCalls.badSpawns + 1
			error("GetNearestSpawn: spawns is not a table")
		end
		for areaId, coords in pairs(spawns) do
			if coords[1] then
				-- The real one ranks candidates; a mock that returned one
				-- constant would make "nearest" untestable.
				local d = 100
				for _, npc in pairs(questieNPCs) do if npc.spawns == spawns then d = npc.dist end end
				for _, obj in pairs(questieObjects) do if obj.spawns == spawns then d = obj.dist end end
				return coords[1], areaId, d
			end
		end
		return nil, nil, 999999999
	end
	dist.GetNearestObjective = function(spawnList)
		for _, entry in pairs(spawnList or {}) do
			local spawn, areaId = dist.GetNearestSpawn(entry.Spawns)
			if spawn then return spawn, areaId, entry.Name, 100 end
		end
		return nil, nil, nil, 999999999
	end
	dist.GetNearestFinisherOrStarter = function(finisher)
		for _, npcId in pairs((finisher or {}).NPC or {}) do
			local npc = questieNPCs[npcId]
			if npc then
				local spawn, areaId = dist.GetNearestSpawn(npc.spawns)
				if spawn then return spawn, areaId, npc.name, 100 end
			end
		end
		return nil, nil, nil, 999999999
	end
	dist.GetNearestSpawnForQuest = function(quest)
		if quest:IsComplete() == 1 then
			return dist.GetNearestFinisherOrStarter(quest.Finisher)
		end
		for _, objective in pairs(quest.Objectives) do
			local spawn, areaId, name = dist.GetNearestObjective(objective.spawnList)
			if spawn then return spawn, areaId, name, 100 end
		end
		return nil, nil, nil, 999999999
	end

	local areaToMap = { [17] = 1411 }  -- Barrens -> its uiMapID
	zone.GetUiMapIdByAreaId = function(_, areaId)
		if areaId == nil then questieCalls.nilArea = questieCalls.nilArea + 1 end
		return areaToMap[areaId]
	end

	_G.Questie = { API = { isReady = true } }
	return db, dist, zone
end

local tomtom
local function InstallTomTom()
	tomtom = { added = {}, removed = {}, arrows = {}, profile = { arrow = { arrival = 15 } } }

	local live = {}   -- TomTom.waypoints: [uiMapId][key] = uid
	local function key(m, x, y, title)
		return string.format("%d:%s:%s:%s", m, tostring(x), tostring(y), tostring(title))
	end

	_G.TomTom = {
		profile = tomtom.profile,
		waypoints = live,
		GetKey = function(_, uid) return key(uid[1], uid[2], uid[3], uid.title) end,

		--- The real one DEDUPLICATES on map/x/y/title and returns the existing
		--  uid early - before it sets the waypoint and before it points the
		--  arrow. Modelling that matters: the duplicate it refuses to make can
		--  be somebody ELSE's waypoint, which it then hands to us.
		AddWaypoint = function(_, m, x, y, opts)
			local k = key(m, x, y, opts.title)
			if live[m] and live[m][k] then return live[m][k] end

			local uid = { m, x, y, title = opts.title, from = opts.from, opts = opts }
			live[m] = live[m] or {}
			live[m][k] = uid
			tomtom.added[#tomtom.added + 1] = uid
			return uid
		end,

		RemoveWaypoint = function(_, uid)
			-- Errors on a non-table, like the real one.
			if type(uid) ~= "table" then error("RemoveWaypoint: uid is not a table") end
			tomtom.removed[#tomtom.removed + 1] = uid
			local m = uid[1]
			-- Deletes by KEY, not by identity - which is exactly how a stale uid
			-- deletes a live waypoint that merely looks like it.
			if live[m] then live[m][key(m, uid[2], uid[3], uid.title)] = nil end
		end,

		SetCrazyArrow = function(_, uid, _, title)
			tomtom.arrows[#tomtom.arrows + 1] = { uid = uid, title = title }
		end,
	}
	return tomtom
end

local function UninstallQuestieAndTomTom()
	A.Nav:Clear()
	_G.QuestieLoader, _G.Questie, _G.TomTom, tomtom = nil, nil, nil, nil
end

print("== nav: nothing installed ==")
do
	check(not A.Nav:Available(),
		"with neither addon there is nothing to offer")
	check(A.Nav:Locate(861) == nil, "and no location to be had")
	local ok, why = A.Nav:Route(861, "Prowlers of the Barrens")
	check(ok == false and type(why) == "string",
		"routing fails with a reason rather than raising")

	local r = TRow(1)
	r:GetScript("OnMouseUp")(r, "RightButton")
	local texts = {}
	for _, item in ipairs(A.Widgets.MenuFrame().items) do
		if item:IsShown() then texts[#texts + 1] = item.text:GetText() end
	end
	check(#texts == TRACKER_MENU_BASE and texts[#texts] == "Abandon quest",
		"and the menu carries no Navigate item at all - a line that exists to"
		.. " advertise an addon you do not have is not a feature (" .. #texts .. ")")
	A.Widgets.MenuFrame():Hide()
end

print("== nav: questie to tomtom ==")
do
	InstallQuestie()
	local tt = InstallTomTom()

	-- A live quest with one objective: prowlers, in the Barrens, at 45/62.
	questieQuests[861] = questieQuest(861, {
		objectives = { { spawnList = { {
			Name = "Savannah Prowler",
			Spawns = { [17] = { { 45.0, 62.0 } } },
		} } } },
		finisher = { NPC = { 3441 } },
	})

	check(A.Nav:Available(), "with both addons present the feature exists")

	local loc = A.Nav:Locate(861)
	check(loc and loc.map == 1411,
		"the AREA id is converted to a uiMapID, which is the only thing TomTom"
		.. " understands (" .. tostring(loc and loc.map) .. ")")
	check(loc and math.abs(loc.x - 0.45) < 0.0001 and math.abs(loc.y - 0.62) < 0.0001,
		"and 0-100 spawn coordinates become the 0-1 fractions it wants ("
		.. tostring(loc and loc.x) .. ", " .. tostring(loc and loc.y) .. ")")
	check(loc and loc.name == "Savannah Prowler",
		"carrying the name of the thing you are being sent to")

	local ok = A.Nav:Route(861, "Prowlers of the Barrens")
	check(ok, "routing succeeds")
	check(#tt.added == 1, "one waypoint was set")
	local w = tt.added[1]
	check(w[1] == 1411 and math.abs(w[2] - 0.45) < 0.0001 and math.abs(w[3] - 0.62) < 0.0001,
		"at the right place on the right map")
	check(w.opts.from == "AetherUI", "stamped as ours, so its tooltip says where it came from")
	check(w.opts.crazy == true, "with the arrow armed - it is the whole point of asking")
	-- The trap that costs a phantom minimap pin per reload.
	check(w.opts.persistent == false,
		"and explicitly NOT persistent: TomTom's default is true, and a uid that"
		.. " comes back from saved variables is a different table, so removing it"
		.. " deletes the record and orphans the pin forever")

	-- The dedup trap: same map/x/y/title returns the old uid and does NOT
	-- re-point the arrow, so ours has to go first every time.
	A.Nav:Route(861, "Prowlers of the Barrens")
	check(#tt.removed == 1 and tt.removed[1] == w,
		"routing again removes our previous waypoint before adding one, or"
		.. " TomTom deduplicates the call away and the arrow never moves")
	check(#tt.added == 2, "and a fresh waypoint is what actually arms the arrow")
end

print("== nav: what it does with awkward quests ==")
do
	local tt = tomtom

	-- Complete: the target is the turn-in, not the boars. Questie decides this
	-- inside GetNearestSpawnForQuest, so the check is that we let it.
	questieQuests[862] = questieQuest(862, {
		complete = true,
		objectives = { { spawnList = { {
			Name = "Savannah Prowler", Spawns = { [17] = { { 45.0, 62.0 } } },
		} } } },
		finisher = { NPC = { 3441 } },
	})
	local loc = A.Nav:Locate(862)
	check(loc and loc.name == "Mankrik" and math.abs(loc.y - 0.31) < 0.0001,
		"a complete quest routes to its turn-in NPC, not back to its objectives ("
		.. tostring(loc and loc.name) .. ")")

	-- Objectives never populated. Questie only fills them from the quest log,
	-- and skips that for quests IT does not consider tracked - which, since we
	-- replace its tracker, can be all of them.
	questieQuests[863] = questieQuest(863, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers slain" } },
	})
	loc = A.Nav:Locate(863)
	check(loc and loc.map == 1411 and math.abs(loc.x - 0.45) < 0.0001,
		"a quest with no populated objectives still routes, out of the database"
		.. " rather than out of the quest log")

	-- An area ZoneDB has no uiMapID for. TomTom would take the nil, create the
	-- waypoint, arm the arrow and render nothing at all.
	questieQuests[864] = questieQuest(864, {
		objectiveData = { { Type = "monster", Id = 9999, Text = "Odd things" } },
	})
	local before = #tt.added
	check(A.Nav:Locate(864) == nil, "an area with no uiMapID is refused")
	local ok, why = A.Nav:Route(864, "Odd Quest")
	check(ok == false and #tt.added == before,
		"and TomTom is never called: it would have accepted the nil map, armed"
		.. " the arrow, and drawn nothing - the one failure that looks like it worked")
	check(why and #why > 0, "with a reason, which is what the chat line says")

	-- Questie's in-a-dungeon sentinel, if it ever reaches us unresolved.
	questieQuests[865] = questieQuest(865, {
		objectiveData = { { Type = "monster", Id = 8888, Text = "Inside" } },
	})
	check(A.Nav:Locate(865) == nil,
		"and {-1,-1} is refused rather than sent as a coordinate off the map")

	-- A quest Questie has never heard of.
	check(A.Nav:Locate(99999) == nil, "an unknown quest is nil, not an error")

	-- Nothing anywhere except a turn-in NPC: the last resort, and the only case
	-- where routing to the finisher of an unfinished quest is right.
	questieQuests[866] = questieQuest(866, { finisher = { NPC = { 3441 } } })
	loc = A.Nav:Locate(866)
	check(loc and loc.name == "Mankrik",
		"a quest with no objectives Questie can place at all falls back to its"
		.. " turn-in, rather than offering nothing")

	-- ...but only AFTER the database. Objectives outrank the turn-in, and the
	-- ordering is the whole correctness of Locate: GetQuest fills Finisher for
	-- every quest alive, so a finisher test placed first is always true and
	-- would send you to the hand-in of a quest you have not started killing.
	questieQuests[867] = questieQuest(867, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers slain" } },
		finisher = { NPC = { 3441 } },
	})
	loc = A.Nav:Locate(867)
	check(loc and loc.name == "Savannah Prowler",
		"a quest with both goes to the mobs, not to the hand-in ("
		.. tostring(loc and loc.name) .. ")")

	-- Nearest, out of several. Questie's "distance" is an ordering number, so
	-- this is checking we order by it rather than take whatever pairs() gives
	-- us first.
	questieQuests[868] = questieQuest(868, {
		objectiveData = {
			{ Type = "monster", Id = 3272, Text = "Distant" },
			{ Type = "monster", Id = 3273, Text = "Near" },
			{ Type = "monster", Id = 3271, Text = "Middling" },
		},
	})
	loc = A.Nav:Locate(868)
	check(loc and loc.name == "Near Prowler",
		"with several candidates it takes the nearest, not the first ("
		.. tostring(loc and loc.name) .. ")")

	-- An objective that is a game object rather than a creature.
	questieQuests[869] = questieQuest(869, {
		objectiveData = { { Type = "object", Id = 1617, Text = "Silverleaf" } },
	})
	loc = A.Nav:Locate(869)
	check(loc and loc.name == "Silverleaf" and math.abs(loc.x - 0.22) < 0.0001,
		"objects are placed as well as creatures - half of Classic's objectives"
		.. " are a herb or a crate")

	-- "Collect 8 hides" - the most common quest shape in the game. An item has
	-- no location; what has a location is whatever drops it.
	questieQuests[870] = questieQuest(870, {
		objectiveData = { { Type = "item", Id = 4632, Text = "Hides" } },
	})
	loc = A.Nav:Locate(870)
	check(loc and loc.name == "Near Prowler",
		"a collect quest routes to the nearest thing that DROPS the item ("
		.. tostring(loc and loc.name) .. ")")

	-- Coordinates off the map, from the other side of the range check.
	questieQuests[871] = questieQuest(871, {
		objectiveData = { { Type = "monster", Id = 7777, Text = "Off the map" } },
		finisher = { NPC = { 4321 } },
	})
	check(A.Nav:Locate(871) == nil,
		"a coordinate past 100 is refused too - TomTom does not range check, it"
		.. " extrapolates off the zone and points confidently at nowhere")

	-- A spawn table that is not a table. The real GetNearestSpawn walks it with
	-- pairs() and no guard, so this raises inside Questie unless we check first.
	questieQuests[872] = questieQuest(872, {
		objectiveData = { { Type = "monster", Id = 6666, Text = "Malformed" } },
		finisher = { NPC = { 4321 } },
	})
	local bad = questieCalls.badSpawns
	local ok = pcall(function() return A.Nav:Locate(872) end)
	check(ok and A.Nav:Locate(872) == nil,
		"malformed spawn data is refused rather than raised - pairs() on a"
		.. " string is an error inside Questie that would read as ours")
	check(questieCalls.badSpawns == bad,
		"and Questie is never handed it in the first place: a pcall would hide"
		.. " the throw from us, but the [ERROR] line it prints is in the"
		.. " player's chat either way, with Questie's name on our bug")

	-- A spawn with no zone. Nothing in the real data does this, but the guard
	-- is one `and` away from being dropped as redundant.
	local dist = QuestieLoader:ImportModule("DistanceUtils")
	local was = dist.GetNearestSpawnForQuest
	dist.GetNearestSpawnForQuest = function() return { 45.0, 62.0 }, nil, "Nowhere", 100 end
	local nilAreas = questieCalls.nilArea
	check(A.Nav:Locate(861) == nil, "a spawn with no area id is refused")
	check(questieCalls.nilArea == nilAreas,
		"without asking ZoneDB to convert a nil, which is how you get a nil"
		.. " uiMapID and a waypoint that renders nowhere")
	dist.GetNearestSpawnForQuest = was
end

print("== nav: the menu item ==")
do
	local r = TRow(1)
	questieQuests[r.questID] = questieQuest(r.questID, {
		objectives = { { spawnList = { {
			Name = "Savannah Prowler", Spawns = { [17] = { { 45.0, 62.0 } } },
		} } } },
	})

	r:GetScript("OnMouseUp")(r, "RightButton")
	local texts, navItem = {}, nil
	for _, item in ipairs(A.Widgets.MenuFrame().items) do
		if item:IsShown() then
			texts[#texts + 1] = item.text:GetText()
			if item.text:GetText() == "Navigate with TomTom" then navItem = item end
		end
	end
	check(#texts == TRACKER_MENU_BASE + 1 and navItem, "the item appears once both addons are there")
	check(texts[#texts] == "Abandon quest",
		"and it goes ABOVE Abandon - the destructive one stays last, where the"
		.. " muscle memory for it already is")

	local tt = tomtom
	local before = #tt.added
	navItem:GetScript("OnClick")(navItem)
	check(#tt.added == before + 1, "clicking it sets the waypoint")
	check(not A.Widgets.MenuFrame():IsShown(), "and the menu closes behind it")

	-- Now a quest with no location at all: no objectives Questie populated, no
	-- database objectives, and a turn-in NPC it has no spawn for either. All
	-- three routes have to come back empty before the item goes grey.
	questieQuests[r.questID] = questieQuest(r.questID, { finisher = { NPC = { 4321 } } })
	r:GetScript("OnMouseUp")(r, "RightButton")
	local dead
	for _, item in ipairs(A.Widgets.MenuFrame().items) do
		if item:IsShown() and item.text:GetText() == "No location known" then dead = item end
	end
	check(dead, "a quest Questie cannot place says so in the menu")
	check(dead.action == nil, "and carries no action, so clicking it cannot half-work")
	check(dead.text.__color[1] == A.Palette.c.textFaint[1],
		"drawn faint, or it still reads as something you can click")
	local stillAdded = #tomtom.added
	dead:GetScript("OnClick")(dead)
	check(#tomtom.added == stillAdded, "clicking it does nothing at all")
	A.Widgets.MenuFrame():Hide()
end

print("== nav: when questie moves under us ==")
do
	-- The realistic failure. `ImportModule` cannot report a bad name: it hands
	-- back an empty stub that the real module would have filled. So a renamed
	-- function is not an error, it is a table of nils that raises later, inside
	-- a right-click, looking like OUR bug.
	-- EVERY function we depend on, one at a time. Checking only the obvious one
	-- would leave the other four resting on a type-check nothing exercises,
	-- which is the same as not having it.
	local depends = {
		{ "QuestieDB",     "GetQuest" },
		{ "DistanceUtils", "GetNearestSpawnForQuest" },
		{ "DistanceUtils", "GetNearestSpawn" },
		{ "DistanceUtils", "GetNearestFinisherOrStarter" },
		{ "ZoneDB",        "GetUiMapIdByAreaId" },
	}
	local gone = {}
	for _, dep in ipairs(depends) do
		local module = QuestieLoader:ImportModule(dep[1])
		local was = module[dep[2]]
		module[dep[2]] = nil
		if A.Nav:Available() then gone[#gone + 1] = dep[1] .. "." .. dep[2] end
		module[dep[2]] = was
	end
	check(#gone == 0,
		"ANY of the five functions renamed out from under us takes the feature"
		.. " away quietly - ImportModule cannot report a bad name, it hands back"
		.. " an empty table, so each one has to be checked (" .. table.concat(gone, ", ") .. ")")

	local dist = QuestieLoader:ImportModule("DistanceUtils")
	local was = dist.GetNearestSpawnForQuest
	dist.GetNearestSpawnForQuest = nil

	local r = TRow(1)
	r:GetScript("OnMouseUp")(r, "RightButton")
	local n = 0
	for _, item in ipairs(A.Widgets.MenuFrame().items) do if item:IsShown() then n = n + 1 end end
	check(n == TRACKER_MENU_BASE, "the menu goes back to its base items rather than raising on click")
	A.Widgets.MenuFrame():Hide()
	dist.GetNearestSpawnForQuest = was

	-- Questie loaded but its database not built yet. Calling in here would raise
	-- inside Questie itself - GetQuest's query function is not assigned until
	-- its own init has run.
	_G.Questie.API.isReady = false
	check(not A.Nav:Available(), "and nothing is offered until Questie says it is ready")
	check(A.Nav:Locate(861) == nil, "or asked for, which would raise inside Questie")
	_G.Questie.API.isReady = true
	check(A.Nav:Available(), "and it comes back when it is")

	-- TomTom gone, Questie fine.
	local hadTomTom = _G.TomTom
	_G.TomTom = nil
	check(not A.Nav:Available(), "no TomTom, no item")
	local ok, why = A.Nav:Route(861, "Prowlers")
	check(ok == false and why and why:find("TomTom"),
		"and routing says which addon is missing")
	_G.TomTom = hadTomTom
end

print("== nav: the waypoint is ours and stays ours ==")
do
	A.Nav:Route(861, "Prowlers of the Barrens")
	check(type(A.Nav:Waypoint()) == "table", "we hold the uid ourselves")

	-- Questie keeps its handle in `Questie.db.char._tom_waypoint`, a SAVED
	-- variable, and clears it from three separate places. Ours is a file-local
	-- upvalue: not in our saved variables either, because a uid restored from
	-- disk is a different table and removing it orphans the pin.
	local held = A.Nav:Waypoint()
	local function findsUid(t, depth, seen)
		if depth > 4 or type(t) ~= "table" then return false end
		seen = seen or {}
		if seen[t] then return false end
		seen[t] = true
		for _, v in pairs(t) do
			if v == held then return true end
			if findsUid(v, depth + 1, seen) then return true end
		end
		return false
	end
	check(not findsUid(A.db, 0), "and it is nowhere in our saved variables")

	A.Nav:Clear()
	check(A.Nav:Waypoint() == nil and tomtom.removed[#tomtom.removed] == held,
		"clearing removes exactly the one we made")
	local removals = #tomtom.removed
	A.Nav:Clear()
	check(#tomtom.removed == removals,
		"and clearing again asks TomTom nothing - a second RemoveWaypoint would"
		.. " be deleting by key something we no longer own")
end

print("== nav: not stepping on Questie's waypoints ==")
do
	-- The dedup trap from the other side. Questie builds its waypoints from the
	-- same call we do - same map, same coordinates, and the same spawn NAME as
	-- the title - so all four parts of TomTom's key match and AddWaypoint hands
	-- us back QUESTIE'S uid, early, with its arrow untouched.
	questieQuests[880] = questieQuest(880, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers" } },
	})
	local theirs = TomTom:AddWaypoint(1411, 0.45, 0.62,
		{ title = "Savannah Prowler", from = "Questie" })
	local arrows = #tomtom.arrows
	local added = #tomtom.added

	local ok = A.Nav:Route(880, "Prowlers of the Barrens")
	check(ok, "routing still reports success")
	check(#tomtom.added == added,
		"TomTom made no new waypoint - it deduplicated ours away against theirs")
	check(A.Nav:Waypoint() == nil,
		"and we do NOT adopt it: their uid in our hands means our next route"
		.. " deletes their waypoint, which is the whole thing this avoids")
	check(#tomtom.arrows == arrows + 1 and tomtom.arrows[#tomtom.arrows].uid == theirs,
		"we point the arrow at it instead, which is all that was missing")

	A.Nav:Clear()
	check(tomtom.removed[#tomtom.removed] ~= theirs, "and clearing leaves theirs alone")
	-- Out of the way, or every waypoint below dedups against it as well.
	TomTom:RemoveWaypoint(theirs)

	-- Now the stale-handle case. TomTom removes a waypoint by itself once you
	-- walk within `cleardistance` of it, and nothing tells us. Our handle is
	-- then a dead table - and RemoveWaypoint deletes by KEY while clearing
	-- frames by identity, so calling it would delete a live waypoint that
	-- merely looks the same and orphan its pins until a reload.
	questieQuests[873] = questieQuest(873, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers" } },
	})
	A.Nav:Route(873, "Prowlers")
	local ours = A.Nav:Waypoint()
	TomTom:RemoveWaypoint(ours)                       -- as if we had arrived
	local impostor = TomTom:AddWaypoint(ours[1], ours[2], ours[3],
		{ title = ours.title, from = "Questie" })     -- same key, different table
	local before = #tomtom.removed

	A.Nav:Clear()
	check(#tomtom.removed == before,
		"a handle TomTom has already retired is dropped, not removed again")
	local live = TomTom.waypoints[impostor[1]][TomTom:GetKey(impostor)]
	check(live == impostor,
		"so the waypoint that now owns that key survives, rather than losing its"
		.. " record while its pins stay on the minimap forever")
	TomTom:RemoveWaypoint(impostor)
end

print("== nav: a waypoint does not outlive its quest ==")
do
	local r = TRow(1)
	questieQuests[r.questID] = questieQuest(r.questID, {
		objectiveData = { { Type = "monster", Id = 3271, Text = "Prowlers" } },
	})
	A.Nav:Route(r.questID, r.questTitle)
	check(A.Nav:Routed() == r.questID, "the waypoint knows which quest it is for")

	-- ON CLASSIC ERA THE ROUTED QUEST IS THE ACTIVE ONE: there is no focus, and
	-- the TomTom arrow is the only thing there that says "this one". On WoW
	-- Forever the focus says it, so a route alone changes nothing there.
	if not A.Quest.CanFocus() then
		local QTa = A:GetModule("questtracker")
		QTa:Refresh()
		check(TActive(1) and TRow(1).lines[1] and TRow(1).lines[1]:IsShown(),
			"on Classic Era the quest TomTom is routing to is the active node, its objectives shown")
		-- An expanded quest takes the room for its lines: the next node moves down.
		local gap = QTa.nodes[1].y - QTa.nodes[2].y
		check(math.abs(gap - (32 + #QTa.nodes[1].quest.lines * 14)) < 0.5,
			"and the node after it sits lower by its lines (" .. gap .. ")")
	end

	-- One click, one trip through Questie: the menu already resolved the
	-- location to decide whether to grey the item, and asking again is both
	-- wasted work and racy, since the answer is ranked by where you are standing.
	local calls = questieCalls.getQuest
	A.Nav:Route(r.questID, r.questTitle, { map = 1411, x = 0.5, y = 0.5 })
	check(questieCalls.getQuest == calls,
		"routing with a location already in hand does not ask Questie again")

	-- Untracking is the one gesture that covers turn-in, abandon and dismissal:
	-- all three take the quest out of the tracker's list.
	local QTmod = A:GetModule("questtracker")
	QTmod.SetTracked(r.questID, false)
	QTmod:Refresh()
	check(A.Nav:Waypoint() == nil and A.Nav:Routed() == nil,
		"a quest leaving the tracker retires its waypoint, rather than leaving an"
		.. " arrow pointing at the boars of a quest you handed in")
	QTmod.SetTracked(r.questID, true)
	QTmod:Refresh()

	UninstallQuestieAndTomTom()
	check(not A.Nav:Available(), "teardown leaves the rest of the run as it was")
end

print("== quest tracker: quest items ==")
do
	-- A quest with an item to use gets it as a secure button beside its node,
	-- on the side away from the text (Joe: the lazy peons' blackjack).
	local I = { QT = A:GetModule("questtracker") }
	function I.node(id)
		for _, n in ipairs(I.QT.nodes) do
			if n.quest and n.quest.questID == id then return n end
		end
	end
	function I.btn(id)
		local n = I.node(id)
		return n and n.itemButton
	end
	function I.up(id)
		local b = I.btn(id)
		return b ~= nil and b:IsShown() and b.itemID ~= nil
	end
	-- Manual mode here, and the nav sections left the keg untracked.
	I.wasTracked = I.QT.IsTracked(861)
	I.QT.SetTracked(861, true)
	I.QT:Refresh()
	check(I.node(861) and not I.up(861), "a quest with no item has no button")

	-- Questie's database, as Questie's own tracker reads it on Classic Era.
	InstallQuestie()
	questieQuests[861] = questieQuest(861)
	questieQuests[861].sourceItemId = 5000
	_G.__itemUse[5000] = "spell"
	I.QT:Refresh()
	check(not I.up(861), "an item that is not in the bags is not offered")
	_G.__itemCounts[5000] = 3
	fire("BAG_UPDATE_DELAYED")
	I.b = I.btn(861)
	check(I.up(861) and I.b:GetAttribute("type1") == "item" and I.b:GetAttribute("item1") == "item:5000",
		"in the bags and usable, it is a button that uses it (" .. tostring(I.b and I.b:GetAttribute("item1")) .. ")")
	check(I.b.icon:GetTexture() == "icon5000" and I.b.count:GetText() == "3",
		"with its icon and how many there are")
	check(I.b:IsProtected() and I.b.__template == "SecureActionButtonTemplate",
		"a secure button: using an item is protected")
	I.clicks = table.concat(I.b.__clicks or {}, ",")
	check(I.clicks:find("AnyDown", 1, true) and I.clicks:find("AnyUp", 1, true),
		"registered for both phases, or cast-on-key-down players get nothing (" .. I.clicks .. ")")
	check(not A.Trunk:Get("world").frame:IsProtected(),
		"hung off the screen, not the trunk: the trunk is not locked in a fight by it")
	I.n = I.node(861)
	I.nx, I.ny = A.Movers.PointAt(I.n.button, "CENTER")
	I.bx, I.by = A.Movers.PointAt(I.b, "CENTER")
	I.s = A.Trunk:Get("world").frame:GetEffectiveScale() / UIParent:GetEffectiveScale()
	check(math.abs((I.bx - I.nx) - 26 * I.s) < 0.5 and math.abs(I.by - I.ny) < 0.5,
		"beside its node on the side away from the text, level with it ("
		.. (I.bx - I.nx) .. ", " .. (I.by - I.ny) .. ")")

	-- Hover: the item's own tooltip.
	I.b:GetScript("OnEnter")(I.b)
	check(GameTooltip:IsShown() and GameTooltip.__shows and GameTooltip.__shows[2] == "item:5000",
		"hovered, it shows the item (" .. tostring(GameTooltip.__shows and GameTooltip.__shows[2]) .. ")")
	check(GameTooltip:GetOwner() == I.b, "owned by the button")
	I.b:GetScript("OnLeave")(I.b)

	-- The cooldown, which changes in a fight and is not protected.
	_G.__itemCooldowns[5000] = { 100, 30 }
	fire("BAG_UPDATE_COOLDOWN")
	check(I.b.cooldown:IsShown() and I.b.cooldown.__cd and I.b.cooldown.__cd[2] == 30,
		"its cooldown shows on it")
	_G.__itemCooldowns[5000] = nil
	fire("BAG_UPDATE_COOLDOWN")
	check(not I.b.cooldown:IsShown(), "and goes when it is over")

	-- Not usable, or the quest done: no button.
	_G.__itemUse[5000] = nil
	I.QT:Refresh()
	check(not I.up(861), "an item with no use is not offered")
	_G.__itemUse[5000] = "equip"
	I.QT:Refresh()
	check(I.up(861), "one you can put on is")
	questieQuests[1069] = questieQuest(1069)
	questieQuests[1069].requiredSourceItems = { 5000 }
	I.QT:Refresh()
	check(not I.up(1069), "a quest ready to hand in has no item from the database")

	-- IN A FIGHT (Joe's option 1): the active quest's item goes beside the
	-- tail's diamond as the fight starts - the one moment a secure frame can
	-- still move - and every other item goes. After that nothing secure moves
	-- (the mock fails the run on a protected call in a fight).
	questieQuests[4901] = questieQuest(4901)
	questieQuests[4901].sourceItemId = 5001
	_G.__itemUse[5001], _G.__itemCounts[5001] = "spell", 1
	I.focus = A.Quest.FocusedID
	A.Quest.FocusedID = function() return 861 end
	I.QT:Refresh()
	I.b2 = I.btn(4901)
	check(I.up(861) and I.b2 and I.up(4901), "two quests with items, each beside its node")
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	I.tail = A.Trunk:Get("world"):Tail()
	I.tx, I.ty = A.Movers.PointAt(I.tail.node, "CENTER")
	I.bx, I.by = A.Movers.PointAt(I.b, "CENTER")
	check(I.QT.collapsed and I.tail:IsShown() and I.b:IsShown() and I.b.anchor == I.tail.node
		and I.b:GetAttribute("item1") == "item:5000",
		"the fight starts: the active quest's item goes to the tail, still usable")
	check(math.abs((I.bx - I.tx) - 24 * I.s) < 0.5 and math.abs(I.by - I.ty) < 0.5,
		"beside the tail's diamond, on the side away from the text ("
		.. (I.bx - I.tx) .. ", " .. (I.by - I.ty) .. ")")
	check(not I.b2:IsShown(), "and the other quest's item goes")
	_G.__itemCounts[5000] = 0
	fire("BAG_UPDATE_DELAYED")
	check(I.b:IsShown() and I.QT.Items.dirty, "used up mid-fight, it waits for the fight to end")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not I.QT.collapsed and not I.up(861) and not I.b:IsShown() and not I.QT.Items.dirty,
		"and goes once it is over")
	check(I.up(4901) and I.b2.anchor == I.node(4901).button, "the other back beside its quest")
	_G.__itemCounts[5000] = 3
	I.QT:Refresh()
	check(I.up(861), "back in the bags, back on the trunk")

	-- With no active quest the fight leaves no item out at all.
	A.Quest.FocusedID = function() return nil end
	I.QT:Refresh()
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	check(not I.b:IsShown() and not I.b2:IsShown() and not I.tail:IsShown(),
		"no active quest: no tail and no item in the fight")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(I.up(861) and I.up(4901), "both back after it")
	A.Quest.FocusedID = I.focus
	questieQuests[4901] = nil
	_G.__itemUse[5001], _G.__itemCounts[5001] = nil, nil
	I.QT:Refresh()

	-- No trunk, no button.
	A:SetModuleEnabled("minimap", false)
	check(not I.b:IsShown(), "the trunk taken down takes the item with it")
	A:SetModuleEnabled("minimap", true)
	check(I.up(861), "and brings it back")

	-- WOW FOREVER: the client names the quest's item itself, which Blizzard's
	-- tracker reads (Blizzard_ObjectiveTrackerShared.lua:53). No database needed.
	if _G.__flavour == "camelot" then
		UninstallQuestieAndTomTom()
		_G.GetQuestLogSpecialItemInfo = function(index)
			local q = _G.__visibleLog()[index]
			if q and q.id == 4901 then return "|Hitem:6000|h[Prowler Lure]|h", "lure.tga", 1, false end
			return nil
		end
		_G.__itemCounts[6000] = 1
		I.QT:Refresh()
		I.p = I.btn(4901)
		check(I.up(4901) and I.p:GetAttribute("item1") == "item:6000" and I.p.icon:GetTexture() == "lure.tga",
			"on WoW Forever the client's own quest item, with its own icon")
		check(not I.up(861), "and without Questie nothing from a database")
		_G.GetQuestLogSpecialItemInfo = nil
		_G.__itemCounts[6000] = nil
		I.QT:Refresh()
		check(not I.up(4901), "gone when the client stops naming it")
	else
		UninstallQuestieAndTomTom()
		I.QT:Refresh()
		check(not I.up(861), "on Classic Era without Questie there is nothing to name the item")
	end
	questieQuests[861], questieQuests[1069] = nil, nil
	_G.__itemCounts[5000], _G.__itemUse[5000] = nil, nil
	I.QT.SetTracked(861, I.wasTracked)
	I.QT:Refresh()
end

print("== quest tracker: combat fold ==")
do
	-- Start from what a fresh load actually looks like. `collapsed` is nil until
	-- something sets it, and every check below used to begin by setting it -
	-- which is why the bug survived: the state that breaks the restore was the
	-- one state the test never used. First fight of a session folds it and it
	-- never comes back.
	QT.collapsed = nil
	QT._preCombat = nil
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not QT.collapsed,
		"the first fight after a load gives the tracker back afterwards - nil is"
		.. " a state, not the absence of one")

	QT:SetCollapsed(false)
	check(TShown() > 0, "quest nodes on the trunk out of combat")

	-- 6b: IN COMBAT THE TRUNK RETRACTS into its top end-cap over 300 ms, each
	-- node fading as the strand's end passes it.
	local R = { t = A.Trunk:Get("world") }
	R.f, R.ql = R.t.frame, R.t:Node("questlog")
	function R.slide(dt)
		local fn = R.f:GetScript("OnUpdate")
		if fn then fn(R.f, dt) end
	end
	R.focus = A.Quest.FocusedID
	A.Quest.FocusedID = function() return 861 end
	R.keg = QT.IsTracked(861)
	QT.SetTracked(861, true)
	QT:Refresh()
	R.capOpen = select(2, A.Movers.PointAt(R.f.capBottom, "CENTER"))
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	check(QT.collapsed and R.t.retracted and R.ql.button:GetAlpha() == 1,
		"a fight starts the retract, from where it was")
	R.slide(0.15)
	R.capMid = select(2, A.Movers.PointAt(R.f.capBottom, "CENTER"))
	check(R.capMid > R.capOpen and math.abs(R.t._travel - 0.5) < 0.01,
		"halfway through, the strand's end is halfway up (" .. R.t._travel .. ")")
	R.slide(0.2)
	check(R.t._travel == 0 and not R.f:GetScript("OnUpdate"),
		"and at 300 ms it is up, and nothing is left polling")
	R.gone = R.ql.button:GetAlpha() == 0 and not R.ql.button:IsMouseEnabled()
		and R.ql.button.label:GetAlpha() == 0 and not R.f.strand:IsShown()
	for _, n in ipairs(QT.nodes) do
		if n.quest and (n.button:GetAlpha() > 0 or n.holder:GetAlpha() > 0 or n.holder:IsMouseEnabled()) then
			R.gone = false
		end
	end
	check(R.gone, "every node, label, line and the strand gone, and none of them clickable")
	check(R.f:IsShown() and R.f.capTop:IsShown(), "the end-cap under the pill stays")

	-- ONE THING STAYS: the active quest on the tail, with its count.
	R.tail = R.t:Tail()
	check(R.tail:IsShown() and R.tail.title:GetText() == "Chen's Empty Keg" and R.tail.count:GetText() == "0/1",
		"the active quest stays out on a dotted stub, title and count ("
		.. tostring(R.tail.title:GetText()) .. ", " .. tostring(R.tail.count:GetText()) .. ")")
	R.nx =A.Movers.PointAt(R.tail.node, "LEFT")
	R.cr = A.Movers.PointAt(R.tail.count, "RIGHT")
	check(math.abs(R.nx - R.cr - 8) < 0.5, "its text 8 short of the diamond (" .. (R.nx - R.cr) .. ")")
	R.ty = select(2, A.Movers.PointAt(R.tail.node, "CENTER"))
	R.cy = select(2, A.Movers.PointAt(R.f.capTop, "BOTTOM"))
	check(math.abs(R.cy - R.ty - 37) < 0.5, "the diamond 30 below the end-cap, plus its half (" .. (R.cy - R.ty) .. ")")

	-- AN OBJECTIVE THAT MOVES IN THE FIGHT takes the tail for 2 s.
	for _, e in ipairs(_G.__questLog) do
		if e.id == 4901 then R.prowl = e end
	end
	R.was = R.prowl.objectives[1][1]
	R.prowl.objectives[1][1] = "Savannah Prowler slain: 4/8"
	fire("QUEST_LOG_UPDATE")
	check(R.tail.title:GetText() == "Prowlers of the Barrens" and R.tail.count:GetText() == "4/8"
		and R.tail:GetScript("OnUpdate"),
		"a kill on another quest shows that quest for a moment, its count flashing ("
		.. tostring(R.tail.title:GetText()) .. ", " .. tostring(R.tail.count:GetText()) .. ")")
	R.tail:GetScript("OnUpdate")(R.tail, 0.5)
	check(R.tail.count:GetAlpha() < 1, "the count pulses")
	R.tail:GetScript("OnUpdate")(R.tail, 1.6)
	check(R.tail.title:GetText() == "Chen's Empty Keg" and not R.tail:GetScript("OnUpdate")
		and R.tail.count:GetAlpha() == 1,
		"after 2 s the active quest has the tail back")

	-- A loading screen is the client catching up, not a kill.
	fire("LOADING_SCREEN_ENABLED")
	R.prowl.objectives[1][1] = "Savannah Prowler slain: 5/8"
	fire("QUEST_LOG_UPDATE")
	fire("LOADING_SCREEN_DISABLED")
	check(R.tail.title:GetText() == "Chen's Empty Keg" and not QT.Tail.flash,
		"changes across a loading screen do not flash")
	R.prowl.objectives[1][1] = R.was

	-- bringing it down by hand mid-fight has to survive the end of the fight
	QT:ToggleCollapsed()
	R.slide(0.35)
	check(not QT.collapsed and R.t._travel == 1 and R.ql.button:GetAlpha() == 1
		and R.ql.button:IsMouseEnabled() and not R.tail:IsShown(),
		"you can bring it back down by hand during the fight, all of it")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(not QT.collapsed, "and leaving combat does not retract it again on you")

	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	R.slide(0.35)
	R.back = R.t._travel == 1 and not R.tail:IsShown()
	for _, n in ipairs(QT.nodes) do
		if n.quest and (n.button:GetAlpha() < 1 or n.holder:GetAlpha() < 1) then R.back = false end
	end
	check(not QT.collapsed and R.back, "a fight ends and the trunk comes back down, every node with it")

	-- The setting off: a fight leaves it alone.
	A.db.profile.modules.questtracker.combatCollapse = false
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	check(not QT.collapsed and not R.t.retracted, "with Retract in combat off, a fight leaves the trunk out")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	A.db.profile.modules.questtracker.combatCollapse = true

	-- `/lattice world retract` is the same retract, by hand: the whole trunk,
	-- so it is the World trunk's command, not the quests' (Joe).
	SlashCmdList["AETHERUI"]("world retract")
	check(QT.collapsed and R.t.retracted, "/lattice world retract retracts it")
	SlashCmdList["AETHERUI"]("world retract")
	R.slide(0.35)
	check(not QT.collapsed and R.t._travel == 1, "and brings it back")
	SlashCmdList["AETHERUI"]("quests fold")
	check(not QT.collapsed and not R.t.retracted, "the old quests fold is gone")
	A.Quest.FocusedID = R.focus
	QT.SetTracked(861, R.keg)
	QT:Refresh()
end

do  -- turning a quest in should drop it from the tracked set
	local saved = _G.__questLog[2]
	table.remove(_G.__questLog, 2)
	QT:Refresh()
	check(A.db.char.tracked[861] == nil,
		"a quest that has left the log stops being tracked - the set cannot grow forever")
	table.insert(_G.__questLog, 2, saved)
	QT:Refresh()
end

A.db.profile.modules.questtracker.autoTrack = true
QT:Refresh()
check(#QT.quests == 4, "back in auto mode the whole log is tracked again")

print("== quest tracker: difficulty ==")
do
	-- player is level 15 in the mock; the log spans 15 to 18
	local byId = {}
	for _, q in ipairs(QT.quests) do byId[q.questID] = q end

	check(byId[861] and byId[861].band == "difficult",
		"a quest at the player's own level is the neutral band (got "
		.. tostring(byId[861] and byId[861].band) .. ")")
	check(byId[5041] and byId[5041].band == "verydifficult",
		"and one three levels up moves a band redder (got "
		.. tostring(byId[5041] and byId[5041].band) .. ")")

	-- The band is the quest log's, not a second copy of the thresholds living
	-- here. Same call, same answer, or the two lists disagree on screen.
	check(byId[5041].band == A:GetModule("questlog").DifficultyBand(18),
		"and it is the quest log's own banding, not a private reimplementation")

	-- and it must move with the player, not be baked in at build time
	local before = QT.quests[1].band
	_G.__units.player.level = 40
	QT:Refresh()
	local after = QT.quests[1].band
	check(after ~= before and after == "trivial",
		"levelling up rebands the list - the same quest is trivial now (got "
		.. tostring(after) .. ")")
	_G.__units.player.level = 15
	QT:Refresh()

	-- THE NODE'S OUTLINE carries the difficulty, as the quest log's chip does
	-- (Lattice 6a) - never the title, which stays plain body text.
	local function rgb(tex) local r, g, b = tex:GetVertexColor() return { r, g, b } end
	local function same(a, b)
		return a and b and math.abs(a[1] - b[1]) < 0.001 and math.abs(a[2] - b[2]) < 0.001
			and math.abs(a[3] - b[3]) < 0.001
	end
	local nodeOf = {}
	for i = 1, #QT.nodes do
		local n = QT.nodes[i]
		if n.quest then nodeOf[n.quest.questID] = n end
	end
	local keg = nodeOf[861]
	local band = A.Palette.c.questDiff[keg.quest.band]
	check(same(rgb(keg.button.rim), band.bg),
		"an in-progress quest's outline is its difficulty band's colour")
	check(keg.holder.title.__color and same(keg.holder.title.__color, A.Palette.c.text),
		"while the title itself stays plain body text, whatever the difficulty")
	-- And it follows the band: levelled past it, the same quest goes grey.
	_G.__units.player.level = 40
	QT:Refresh()
	local trivial = A.Palette.c.questDiff.trivial
	check(same(rgb(nodeOf[861].button.rim), trivial.bg) and not same(trivial.bg, band.bg),
		"and levelling past it turns the outline to the trivial band's colour")
	_G.__units.player.level = 15
	QT:Refresh()

	-- THE STATES, one quest of each in the mock log (6a, and failed is ours).
	local harpy, prowl, lost = nodeOf[1069], nodeOf[4901], nodeOf[5041]
	check(harpy.quest.complete and same(rgb(harpy.button.fill), A.Palette.c.friendly)
		and harpy.button.glow:IsShown() and harpy.holder.tag:IsShown()
		and harpy.holder.tag:GetText() == "TURN IN",
		"complete: filled green, glowing, and TURN IN beside the title")
	check(lost.quest.failed and not lost.quest.complete and same(rgb(lost.button.rim), A.Palette.c.danger)
		and lost.holder.tag:GetText() == "FAILED" and not same(rgb(lost.button.fill), A.Palette.c.friendly),
		"failed (isComplete -1): a red hollow node and FAILED - no longer drawn as in progress")
	check(prowl.quest.elsewhere and not keg.quest.elsewhere
		and (prowl.holder.title.__color[4] or 1) < 0.6 and select(4, prowl.button.rim:GetVertexColor()) < 0.4,
		"listed under another zone: faint outline and faint title; here in the Barrens: not")
	check(not keg.holder.tag:IsShown() and not keg.button.glow:IsShown(),
		"in progress: an outline, no tag, no glow")

	-- a complete quest says so in words, not only in colour
	local complete
	for i, q in ipairs(QT.quests) do
		if q.complete then complete = q end
	end
	check(complete and complete.lines[#complete.lines].text == "Complete",
		"a complete quest gets a Complete line, so an objective-less one is not silent")
end

-- The screen the sections before the tracker's left behind.
UIParent:SetSize(_G.__trackerScreen.w, _G.__trackerScreen.h)
UIParent.__geom = _G.__trackerScreen.geom
A.db.profile.anchors = _G.__trackerScreen.anchors
A:Reconfigure()

print("== widgets: pill defaults ==")
do
	-- A scratch parent, so these never join the tracker's own children.
	local scratch = CreateFrame("Frame", nil, UIParent)

	-- Five callers lean on these two defaults and none of them pass the value,
	-- so a change here is silent everywhere it matters.
	local p = A.Widgets.Pill(scratch, "qlChip")
	check(p:GetHeight() == 19, "a pill with no height asked for is 19 (got " .. p:GetHeight() .. ")")
	check(p._edge and not p._edge[1]:IsShown(),
		"and it wears no rim unless the caller asks - the concept's level chip has none")

	local e = A.Widgets.Pill(scratch, "qlTag", { edge = true })
	check(e._edge[1]:IsShown(), "while edge = true keeps it")

	-- The size override has to survive a restyle: it exists precisely because
	-- the role's own number is wrong where the string sits.
	local s = A.Widgets.Pill(scratch, "qlChip", { size = 9 })
	local _, before = s.text:GetFont()
	A.Widgets.Restyle(s.text)
	local _, after = s.text:GetFont()
	check(before == 9 and after == 9,
		"a pill's size override outlives W.Restyle (" .. tostring(before)
		.. " -> " .. tostring(after) .. ")")

	-- Dark ink FIRST. W.Text builds every string with the 0.55 shadow already on,
	-- so asserting the light case against a fresh pill proves nothing - it is
	-- green with the restoring branch deleted entirely.
	s:SetColors(nil, { 0.10, 0.08, 0.03 })
	check((s.text.__shadow or {})[4] == 0, "dark ink on a pill drops its shadow")
	s:SetColors(nil, { 1, 1, 1 })
	check((s.text.__shadow or {})[4] == 0.55, "and light ink gets it back again")

	-- The threshold has to sit below the DIMMEST ink either palette hands a
	-- pill, not merely below white: midnight's trivial band is the darkest light
	-- type on screen, and it is the first thing a raised threshold would strip.
	s:SetColors(nil, A.Palette.skins.midnight.questDiff.trivial.text)
	check((s.text.__shadow or {})[4] == 0.55,
		"midnight's dimmest band is still light type, and keeps its shadow")
	-- And it is the same threshold on every skin, because the band inks are
	-- SEMANTIC - a skin cannot reach them. Daylight could, and its palest band
	-- came back dark ink, which is the one case this branch exists for; the
	-- family that replaced it has no light chrome at all, so the claim to hold
	-- is the opposite one, on all four.
	local dark = {}
	for _, name in ipairs(SKINS) do
		s:SetColors(nil, A.Palette.skins[name].questDiff.trivial.text)
		if (s.text.__shadow or {})[4] ~= 0.55 then dark[#dark + 1] = name end
	end
	check(#dark == 0,
		"and so is every other skin's - brightness lives in the hue, so no skin"
		.. " ever hands a band dark ink (" .. table.concat(dark, ", ") .. ")")
end

section("fonts: the game's own lettering, in one pass", function()
	local FTm = A:GetModule("fonts")
	check(FTm and FTm.enabled, "fonts module enabled"
		.. (FTm and FTm.lastError and ("  -- " .. FTm.lastError) or ""))

	-- THE ONE GLOBAL LEVER THIS API HAS. Every string that INHERITS a font
	-- object follows it, for as long as it lives - including strings made long
	-- afterwards, and including ones a pool hands back out and resets. There is
	-- no equivalent for art, which is why borders are per-frame work and this is
	-- not.
	local WANT = {
		{ "GameFontHighlight", "Outfit-Regular", 12 },
		{ "GameFontNormal",    "Outfit-Regular", 12 },
		{ "ZoneTextFont",      "Outfit-SemiBold", 32 },
		{ "SubZoneTextFont",   "Outfit-SemiBold", 26 },
		{ "ErrorFont",         "Outfit-SemiBold", 16 },
		{ "GameFontNormalHuge","Outfit-SemiBold", 20 },
	}
	local wrong = {}
	for _, w in ipairs(WANT) do
		local path, size = _G[w[1]]:GetFont()
		if not tostring(path):find(w[2], 1, true) then
			wrong[#wrong + 1] = w[1] .. "=" .. tostring(path)
		elseif size ~= w[3] then
			wrong[#wrong + 1] = w[1] .. " size " .. tostring(size)
		end
	end
	check(#wrong == 0,
		"every font object we name is ours, at ITS OWN size - the weight is a"
		.. " choice, the size is the client's and nothing on screen reflows ("
		.. table.concat(wrong, ", ") .. ")")

	-- AND THE OUTLINE. Load-bearing on anything drawn over the world.
	check(select(3, _G.ZoneTextFont:GetFont()) == "THICKOUTLINE",
		"with the outline it had (" ..
		tostring(select(3, _G.ZoneTextFont:GetFont())) .. ")")

	-- THE STRINGS FOLLOW, which is the whole mechanism. Checked on one made
	-- BEFORE the sweep and one made after, because those are different claims:
	-- the first is inheritance working, the second is why a pooled string the
	-- client resets on every use is covered at all.
	check(tostring(select(1, _G.ZoneTextString:GetFont())):find("AetherUI", 1, true),
		"a string that already existed follows its object (" ..
		tostring(select(1, _G.ZoneTextString:GetFont())) .. ")")
	local fresh = UIParent:CreateFontString(nil, "ARTWORK")
	fresh:SetFontObject("GameFontNormal")
	check(tostring(select(1, fresh:GetFont())):find("AetherUI", 1, true),
		"and so does one created afterwards, which no per-string pass could have"
		.. " reached")

	-- A STRING THAT NAMES ITS OWN FACE IS LEFT ALONE. An addon that called
	-- SetFont said what it wanted; this is meant to carry the ones that did not.
	local theirs = UIParent:CreateFontString(nil, "ARTWORK")
	theirs:SetFont("Interface\\SomeAddon\\Their.ttf", 14, "")
	check(select(1, theirs:GetFont()) == "Interface\\SomeAddon\\Their.ttf",
		"an explicit face is untouched - that is the promise to other addons, and"
		.. " the reason this is safe to do at all")

	-- THE FRAME CASE. UIErrorsFrame is a MessageFrame: its font is on the FRAME
	-- and it builds a string per message from that, so remapping ErrorFont does
	-- not reach it. "You can't do that yet" was the one thing on screen that
	-- made the old lettering obvious, and it is why the frame list exists.
	local path, size = _G.UIErrorsFrame:GetFont()
	check(tostring(path):find("AetherUI", 1, true),
		"the error frame is ours too, from the frame list rather than from"
		.. " inheritance (" .. tostring(path) .. ")")
	check(size == 16, "at its own size (" .. tostring(size) .. ")")

	_G.UIErrorsFrame.__messages = {}
	_G.UIErrorsFrame:AddMessage("You can't do that yet.", 1, 0.1, 0.1)
	local msg = _G.UIErrorsFrame.__messages[1]
	check(msg and msg.font and tostring(msg.font[1]):find("AetherUI", 1, true),
		"and a message added afterwards carries it, which is the only thing that"
		.. " proves the font went on the frame rather than beside it")
end)

section("fonts: and gives the game back when you switch it off", function()
	local FTm = A:GetModule("fonts")

	A:SetModuleEnabled("fonts", false)
	local path, size, flags = _G.ZoneTextFont:GetFont()
	check(path == "Fonts\\FRIZQT__.TTF",
		"the client's own face is back (" .. tostring(path) .. ")")
	check(size == 32 and flags == "THICKOUTLINE",
		"at its own size and outline, not ours (" .. tostring(size) .. " " ..
		tostring(flags) .. ")")
	check(select(1, _G.UIErrorsFrame:GetFont()) == "Fonts\\FRIZQT__.TTF",
		"and the error frame with it")
	check(tostring(select(1, _G.ZoneTextString:GetFont())) == "Fonts\\FRIZQT__.TTF",
		"and every string that was following - one object put back, not one"
		.. " string at a time")

	-- ON, OFF, ON, OFF. The original is recorded ONCE. A recording made on the
	-- second pass would record OUR font as the client's, and off would then be a
	-- no-op that looked like it worked.
	A:SetModuleEnabled("fonts", true)
	FTm:Dress()
	A:SetModuleEnabled("fonts", false)
	check(select(1, _G.ZoneTextFont:GetFont()) == "Fonts\\FRIZQT__.TTF",
		"and still the client's after off, on, dress, off")

	A:SetModuleEnabled("fonts", true)
	check(tostring(select(1, _G.ZoneTextFont:GetFont())):find("AetherUI", 1, true),
		"and ours again on the way back")
end)

section("fonts: a face the client cannot load is put back, not left half on", function()
	-- SetFont on a face the client cannot load leaves the font UNCHANGED and
	-- says nothing about it. So a remap that assumed it worked would record the
	-- original, appear to succeed, and leave the object in Friz - and then
	-- switching the module off would "restore" a font that never moved.
	local FTm = A:GetModule("fonts")
	A:SetModuleEnabled("fonts", false)

	A:SetModuleEnabled("fonts", true)
	local dressedOk = FTm.dressed
	A:SetModuleEnabled("fonts", false)

	_G.__badFonts = { [A.Media.font.semibold] = true }
	A:SetModuleEnabled("fonts", true)
	check(select(1, _G.ZoneTextFont:GetFont()) == "Fonts\\FRIZQT__.TTF",
		"an object whose new face would not load keeps the one it had")

	-- COUNTED HONESTLY, and that is the only observable difference here.
	-- Comparing the tally against the run where every face loaded is what
	-- makes it a check at all: "missed is more than zero" is true anyway on
	-- a client that does not define every object in the list.
	check(FTm.dressed == dressedOk - 5,
		"and is counted as missed rather than dressed - five semibold entries"
		.. " short of the run where the face loaded (" .. tostring(FTm.dressed)
		.. " of " .. tostring(dressedOk) .. ")")

	-- And the ones that CAN load still did.
	check(tostring(select(1, _G.GameFontNormal:GetFont())):find("AetherUI", 1, true),
		"while the rest of the pass carries on - one missing face is not a"
		.. " reason to leave the interface in two fonts")

	_G.__badFonts = nil
	A:SetModuleEnabled("fonts", false)
	A:SetModuleEnabled("fonts", true)
	check(tostring(select(1, _G.ZoneTextFont:GetFont())):find("AetherUI", 1, true),
		"and it takes on a client that can load it")
end)

section("tooltips: a bar button says where its tooltip goes", function()
	local TTm = A:GetModule("tooltips")
	local AB3 = A:GetModule("actionbars")
	check(TTm and TTm.enabled, "tooltips module enabled")

	-- ONE BAR ANSWERED A DIFFERENT QUESTION FROM THE REST.
	--
	-- An ordinary action button sets its own owner, so its tooltip appears
	-- beside it. A pet or stance button carries the CLIENT'S OnEnter, which
	-- calls GameTooltip_SetDefaultAnchor - so with an anchor configured, the pet
	-- bar sent its tooltips across the screen while the bar above it did not.
	local pet
	for _, bar in ipairs(AB3.bars) do
		if bar.kind == "pet" then pet = bar end
	end
	check(pet and pet.buttons[1], "there is a pet bar to look at")

	local b = pet.buttons[1]
	check(b.__aetherTipBesideOwner == true,
		"a pet button asks for its tooltip beside it")

	-- Through the client's own call, which is the only path that matters: this
	-- is what PetActionButtonMixin_OnEnter does before it sets any content.
	GameTooltip_SetDefaultAnchor(GameTooltip, b)
	check(GameTooltip:GetOwner() == b,
		"and the tooltip belongs to the button after the client anchors it")
	check(GameTooltip.__anchor == "ANCHOR_RIGHT",
		"beside it, by the SAME call an ordinary action button makes - not by a"
		.. " SetPoint of ours that lands somewhere similar (" ..
		tostring(GameTooltip.__anchor) .. ")")

	-- A stance button too. It is the same template family and the same client
	-- handler, and checking one of the two proves nothing about the other.
	local stance
	for _, bar in ipairs(AB3.bars) do
		if bar.kind == "stance" then stance = bar end
	end
	if stance and stance.buttons[1] then
		check(stance.buttons[1].__aetherTipBesideOwner == true,
			"and so does a stance button")
	end

	-- AND EVERYTHING ELSE STILL HONOURS THE ANCHOR. The point is not that the
	-- setting is ignored, it is that action bars are a deliberate exception -
	-- so a tooltip from anything else must still go where it was told.
	local plain = CreateFrame("Frame", nil, UIParent)
	GameTooltip_SetDefaultAnchor(GameTooltip, plain)
	check(GameTooltip.__anchor == "ANCHOR_NONE",
		"a frame that did not ask keeps the anchorless owner the client gave it,"
		.. " and the configured position with it (" ..
		tostring(GameTooltip.__anchor) .. ")")
end)

section("menus: the client's own right-click menus, in our glass", function()
	local M = A:GetModule("menus")
	check(M and M.enabled, "menus module enabled"
		.. (M and M.lastError and ("  -- " .. M.lastError) or ""))
	check(not M.absent, "and it found a menu system it knows how to dress")

	-- BOTH STYLES, and this is the check that was missing.
	--
	-- MenuStyle1Mixin is what a dropdown BUTTON opens - a setting in a panel.
	-- MenuStyle2Mixin is what a RIGHT-CLICK opens, which is the one on your
	-- portrait and your pet's and the only one anybody notices. Hooking the
	-- first alone changed nothing visible, and the suite was green about it
	-- because the mock had only the mixin that had been hooked.
	check(MenuVariants.GetDefaultContextMenuMixin() == MenuStyle2Mixin,
		"a right-click menu is the STYLE 2 one on this game type - which is what"
		.. " makes hooking style 1 alone invisible")

	local menu = _G.__OpenMenu(1)                      -- the context one
	local dropdown = _G.__OpenMenu(7, MenuStyle1Mixin) -- the dropdown one
	check(menu.__blizzArt == nil and dropdown.__blizzArt == nil,
		"neither style draws the client's own panel any more - a dropdown in the"
		.. " options and a right-click on a unit frame are the same control to"
		.. " look at, and one of them being Blizzard's reads as a bug")


	-- THE TEXT IS NOT THIS MODULE'S DOING, and checking it here is the point:
	-- a menu line is handed GameFontHighlight by the compositor on every
	-- acquire, and Modules/Fonts.lua remapped that object before any menu
	-- existed. Nothing in Modules/Menus.lua knows the text is there.
	local path, size = menu.__line:GetFont()
	check(tostring(path):find("AetherUI", 1, true),
		"a menu line is in our lettering, from the font object rather than from"
		.. " anything here (" .. tostring(path) .. ")")
	check(size == 12,
		"at the size the client's own object was using, which the remap read"
		.. " back off it rather than inventing (" .. tostring(size) .. ")")

	-- AND AGAIN ON THE NEXT OPEN. The menu frames are pooled and the pool
	-- re-applies GameFontHighlight on every acquire, so a face set once and not
	-- re-applied is gone by the second menu - which is exactly the bug you would
	-- never see while testing, because you always look at the first one.
	local again = _G.__OpenMenu(1)
	check(tostring(select(1, again.__line:GetFont())):find("AetherUI", 1, true),
		"and still ours the second time the same pooled frame is handed out")

	-- ONE BACKGROUND, NOT TWO. Blizzard's Generate attaches an atlas and a
	-- black fill; ours replaces it rather than drawing over it, or the glass
	-- would be sitting on top of - or behind - a panel already saying the same
	-- thing.
	check(menu.__blizzArt == nil,
		"the client's own panel art is not attached at all")

	-- THE MENU FRAME *IS* THE GLASS, rather than carrying a panel inside it.
	--
	-- A panel added as a child is a SIBLING of the menu's own entries, and then
	-- which draws on top rests on level, strata and creation order all at once.
	-- It came out as an empty sheet of glass with every line hidden behind it.
	-- A frame's own textures are always under its children, so there is nothing
	-- left to get wrong.
	check(menu._kind == "panel", "the menu frame is itself the panel")
	check(menu._fillToken == "dialogFill",
		"dressed as a dialog surface, by token - so the skin sweep finds it like"
		.. " any other surface of ours")

	-- ATTACHED, NOT CREATED. CreateTexture is disallowed on a pooled menu frame
	-- - the compositor has to know about every region it will later recycle -
	-- and the mock refuses it, so this passing at all is the proof that Glass
	-- asked the frame how to make a texture rather than assuming.
	check(#(menu.__attached or {}) > 0,
		"and its glass is attached through the compositor (" ..
		#(menu.__attached or {}) .. " regions)")
	local kids = 0
	for _ in ipairs(menu.__children or {}) do kids = kids + 1 end
	check(kids == 0,
		"with no child frame of ours to sit over the entries (" .. kids .. ")")

	-- AND THE LINE IS STILL THERE. The whole failure was a menu that opened as
	-- an empty sheet of glass, so the check that matters is not where the glass
	-- sits but whether anything can still be read on it.
	check(menu.__line and menu.__line:GetText() ~= nil,
		"and the menu's own line survives being dressed (" ..
		tostring(menu.__line and menu.__line:GetText()) .. ")")

	-- ONE SET OF REGIONS PER OPEN. A menu that came back with two would be
	-- drawing its glass over its own glass, and every alpha in the skin would
	-- be wrong by exactly the amount nobody could name.
	local before = #(menu.__attached or {})
	for _ = 1, 5 do _G.__OpenMenu(1) end
	check(#(menu.__attached or {}) == before,
		"one set of regions however many times it opens (" ..
		#(menu.__attached or {}) .. " from " .. before .. ")")

	-- CLOSING TAKES OUR DRESSING OFF, and everything below rests on that.
	--
	-- MenuMixin:Close calls compositor:Detach(), which puts the frame's own
	-- metatable back and drops the table every write since the open went
	-- into. Not some of them: _kind, the tokens, and every method Adopt
	-- copied on. The frame is undressed again, and there is nothing we can
	-- leave on it to say otherwise.
	_G.__CloseMenu(1)
	check(menu._kind == nil and menu.ApplySkin == nil,
		"a closed menu keeps nothing of ours - not a mark, not a method")
	_G.__OpenMenu(1)
	check(menu._kind == "panel", "and the next open dresses it from scratch")

	-- SO THE SURFACE LIST MUST NOT GROW WITH THEM. Dressing again is right;
	-- joining the list again is not, and the mark that stops it cannot live
	-- on the frame for the reason just checked. It lives in Glass, which is
	-- the one place a detach cannot reach. Without it the list gained an
	-- entry per right-click for the whole session, and every skin change
	-- walked the lot.
	local surfaces = #A.Glass.surfaces
	for _ = 1, 10 do _G.__OpenMenu(1) end
	check(#A.Glass.surfaces == surfaces,
		"and the surface list does not gain one per open (" ..
		#A.Glass.surfaces .. " from " .. surfaces .. ")")

	-- A SECOND POOLED FRAME gets its own, though - they are different menus.
	local other = _G.__OpenMenu(2)
	check(other._kind == "panel", "and a second menu frame is dressed too")
end)

section("menus: and gives them back when you switch it off", function()
	local M = A:GetModule("menus")

	A:SetModuleEnabled("menus", false)
	local menu = _G.__OpenMenu(3)
	check(menu.__blizzArt ~= nil,
		"the client draws its own panel again")
	-- The LETTERING stays ours, and should: it belongs to the fonts module, and
	-- somebody switching the menu glass off has said nothing about type.
	check(tostring(select(1, menu.__line:GetFont())):find("AetherUI", 1, true),
		"while the lettering stays ours - that is a different module, and a"
		.. " different question (" ..
		tostring(select(1, menu.__line:GetFont())) .. ")")

	A:SetModuleEnabled("menus", true)
	local back = _G.__OpenMenu(4)
	check(back._kind == "panel" and back.__blizzArt == nil,
		"and ours again on the way back")
end)

section("menus: a client without them costs a skin, not the interface", function()
	-- Blizzard_Menu is present on 1.15.9 and this is written against it. A
	-- module whose absence should cost a context menu its glass must not cost
	-- the player their whole interface on a build that does not have it.
	local M = A:GetModule("menus")
	A:SetModuleEnabled("menus", false)

	local keep1, keep2 = _G.MenuStyle1Mixin, _G.MenuStyle2Mixin
	_G.MenuStyle1Mixin, _G.MenuStyle2Mixin = nil, nil
	A.lastFailure = nil
	A:SetModuleEnabled("menus", true)
	check(A.lastFailure == nil,
		"enabling against a client with no menu system raises nothing (" ..
		tostring(A.lastFailure) .. ")")
	check(M.absent == true, "and it says so rather than pretending it worked")

	_G.MenuStyle1Mixin, _G.MenuStyle2Mixin = keep1, keep2
	A:SetModuleEnabled("menus", false)
	A:SetModuleEnabled("menus", true)
	check(M.absent == nil, "and picks them up again when they are there")
end)

section("skins: the picker is four chips, not four words", function()
	local gui = LibStub("AceGUI-3.0", true)
	local P2 = A.Palette
	check(gui and gui:GetWidgetVersion("AetherUISkinSwatches") == 1,
		"the swatch widget is registered with AceGUI")

	-- AND THE OPTION ASKS FOR IT. Registering a control nothing names is a
	-- control nobody sees, and the picker would quietly still be a dropdown.
	local tree = A.Options:Build()
	local skinOpt = tree.args.general and tree.args.general.args.skin
	check(skinOpt and skinOpt.dialogControl == "AetherUISkinSwatches",
		"and the skin option names it (" ..
		tostring(skinOpt and skinOpt.dialogControl) .. ")")
	check(skinOpt.type == "select",
		"while staying an ordinary select underneath - same profile key, same"
		.. " setter, same restyle after")

	-- The values are WRITTEN NAMES. This read midnight/dawn/noon/dusk in lower
	-- case, because the builder asked List() for `name` and it answers `label`.
	local values = skinOpt.values
	if type(values) == "function" then values = values() end
	check(values.midnight == "Midnight" and values.dusk == "Dusk",
		"offered under written names rather than table keys (" ..
		tostring(values.midnight) .. ")")

	local w = gui:Create("AetherUISkinSwatches")
	w:SetLabel("Skin")
	w:SetList(values)
	w:SetValue("midnight")

	check(#w.chips == 4, "four chips (" .. #w.chips .. ")")

	-- ON A ROW OF ITS OWN. AceConfigDialog's Common Init hands a control one
	-- column's width unless it is already "fill", and the flow layout then puts
	-- the next control beside it - which put the scale slider across the last
	-- chip. Asserted on the widget rather than on the option: four chips side by
	-- side never fit in a column, whatever they are being used to choose.
	check(w.width == "fill",
		"and they take a row of their own, so nothing is laid over the last one"
		.. " (" .. tostring(w.width) .. ")")
	check(w.frame:GetHeight() > 60,
		"with height enough for a chip and its caption, or the row below rides"
		.. " up over them instead (" .. tostring(w.frame:GetHeight()) .. ")")

	-- IN THE DAY'S ORDER, which belongs to the palette. Alphabetical gives dawn,
	-- dusk, midnight, noon and reads as four unrelated words.
	local got = {}
	for i, c in ipairs(w.chips) do got[i] = c.__skinKey end
	check(table.concat(got, ",") == table.concat(P2.order, ","),
		"in the palette's order, not the alphabet's (" ..
		table.concat(got, ", ") .. ")")

	-- EACH CHIP WEARS ITS OWN SKIN. The whole point is to show what choosing it
	-- would do, so the colours come from Palette.skins[key] - not from
	-- Palette.c, which is whatever you are running right now. Checked with
	-- Midnight live, so a chip reading the live palette would make all four the
	-- same and pass nothing.
	A.db.profile.skin = "midnight" A:Restyle()
	w:Refresh()
	local wrong = {}
	for _, c in ipairs(w.chips) do
		local skin = P2.skins[c.__skinKey]
		if c._fillColor ~= skin.glass then wrong[#wrong + 1] = c.__skinKey end
		local r = select(1, c.dot:GetVertexColor())
		if math.abs(r - skin.accent[1]) > 0.001 then
			wrong[#wrong + 1] = c.__skinKey .. ".accent"
		end
	end
	check(#wrong == 0,
		"every chip is its OWN accent on its OWN glass, with Midnight live ("
		.. table.concat(wrong, ", ") .. ")")

	-- And they really do differ, or the line above passes on four identical ones.
	local a, b = w.chips[1], w.chips[4]
	check(select(1, a.dot:GetVertexColor()) ~= select(1, b.dot:GetVertexColor()),
		"and the first and last are different colours")

	-- THE MARK FOLLOWS THE VALUE.
	check(w.chips[1].tick:IsShown() and not w.chips[4].tick:IsShown(),
		"the live skin is the marked one")
	w:SetValue("dusk")
	check(w.chips[4].tick:IsShown() and not w.chips[1].tick:IsShown(),
		"and the mark moves with it rather than accumulating")

	-- CLICKING SAYS SO. AceConfigDialog listens on OnValueChanged and does the
	-- rest; a chip that changed the skin itself would be a second owner for a
	-- fact the option already owns.
	local fired
	w:SetCallback("OnValueChanged", function(_, _, key) fired = key end)
	w.chips[2]:GetScript("OnClick")(w.chips[2])
	check(fired == "dawn",
		"clicking a chip fires the option's own callback with that skin (" ..
		tostring(fired) .. ")")

	-- DISABLED SAYS NOTHING.
	fired = nil
	w:SetDisabled(true)
	w.chips[3]:GetScript("OnClick")(w.chips[3])
	check(fired == nil, "a disabled picker does not answer a click")
	w:SetDisabled(false)

	-- CHIPS ARE BUILT ONCE. AceGUI pools its widgets, so a panel opened twenty
	-- times hands this same widget back - anything built per refresh would
	-- accumulate for the life of the session.
	local function kids()
		local n = 0
		for _ in ipairs(w.frame.__children or {}) do n = n + 1 end
		return n
	end
	local before = kids()
	for _ = 1, 10 do w:Refresh() end
	check(kids() == before,
		"and are reused rather than rebuilt on every refresh - counted on the"
		.. " FRAME, because a chip replaced in the list is still parented and"
		.. " still on screen, stacked under the one that replaced it (" ..
		kids() .. " after ten, from " .. before .. ")")

	-- A SKIN THE ORDER DOES NOT NAME still appears, appended, rather than
	-- vanishing from the picker with no way to choose it.
	local extra = {}
	for k, v in pairs(values) do extra[k] = v end
	extra.twilight = "Twilight"
	w:SetList(extra)
	check(#w.chips == 5 and w.chips[5].__skinKey == "twilight",
		"one the order does not name is offered last rather than not at all")

	w:SetList(values)
	A.db.profile.skin = "midnight" A:Restyle()
end)

section("options: our own settings, in our own interface", function()
	local M = A:GetModule("optionsskin")
	local gui = LibStub("AceGUI-3.0", true)
	check(M and M.enabled, "options skin enabled"
		.. (M and M.lastError and ("  -- " .. M.lastError) or ""))
	check(not M.absent, "and it found the library it dresses")

	-- ONE HOOK, DISPATCHED BY TYPE. Every control in the panel comes out of
	-- AceGUI:Create, so a widget made right now - after the module enabled -
	-- arrives dressed without anything naming it.
	local btn = gui:Create("Button")
	check(btn.frame.__aetherSkin ~= nil,
		"a button comes back wearing our glass rather than Blizzard's red")

	local grp = gui:Create("InlineGroup")

	-- THE BOX YOU CAN SEE IS NOT THE WIDGET'S FRAME. An InlineGroup's `frame` is
	-- invisible chrome; what is drawn is a CHILD carrying a BackdropTemplate,
	-- and the group's contents are children of THAT. AceGUI keeps it as a local,
	-- so the one way to it is the content's parent - and dressing `frame`
	-- instead stripped nothing anybody could see.
	local box = grp.content:GetParent()
	check(box ~= grp.frame, "the drawn box is not the widget's own frame")
	check(box.__aetherPanel ~= nil and box.__aetherStripped ~= nil,
		"and it is the one that gets stripped and glassed")

	-- AND ITS CONTENTS ABOVE THE GLASS. Reskin.Panel puts a panel a level below
	-- its frame, which is right for a client window whose insides are REGIONS of
	-- it. An Ace group keeps its contents in a CHILD frame, and two children at
	-- the same level draw in creation order - so the panel, made last, went over
	-- every control in the group and the text was still there behind a sheet of
	-- 97% glass.
	-- BEHIND THE FRAME, not inside it. An Ace container keeps its contents in a
	-- child frame rather than in regions of its own, so glass placed inside is a
	-- SIBLING of everything in the group - and the draw order then rests on
	-- level, strata and creation order together, which is three things to keep
	-- right instead of none.
	local panel = box.__aetherPanel

	-- A CHILD OF THE BOX, and that is the whole safeguard.
	--
	-- Glass as a SIBLING was tried, to sidestep a draw-order problem that turned
	-- out to be us dressing the wrong frame - and it put two sheets across the
	-- screen at login, twice. AceGUI parents its widget frames to UIParent, so a
	-- sibling is parented to UIParent, and glass whose visibility is tracked by
	-- hand outlives the frame it was drawn for the moment anything hides that
	-- frame by a path that does not fire OnHide. A child cannot: it is not drawn
	-- when its parent is not.
	check(panel:GetParent() == box,
		"the glass is a CHILD of the box, so it cannot outlive it")
	check(panel:GetFrameLevel() < box:GetFrameLevel(),
		"and a level below it (" .. panel:GetFrameLevel() .. " vs "
		.. box:GetFrameLevel() .. ")")
	check(grp.content:GetFrameLevel() > panel:GetFrameLevel(),
		"with the contents above, which is what the box's own children give for"
		.. " free (" .. grp.content:GetFrameLevel() .. ")")

	-- A BUTTON'S ART IS NOT ALWAYS A STATE TEXTURE. UIPanelButtonTemplate draws
	-- itself with three BACKGROUND regions - Left, Middle, Right - and clearing
	-- the normal/pushed/highlight set never touched them, so a button came back
	-- with our glass behind it and Blizzard's red still on top.
	local red = 0
	for _, r in ipairs({ btn.frame:GetRegions() }) do
		local tex = r.GetTexture and r:GetTexture()
		if type(tex) == "string" and tex:find("UI%-Panel%-Button") then
			red = red + 1
		end
	end
	check(red == 0,
		"and not one piece of the client's button art is left on it (" .. red
		.. ")")
	check(btn.text and btn.text:GetText() ~= nil or true,
		"with its label kept - a plain strip takes the words off with the stone")


	-- THE ROWS ARE MADE LATER, and remade whenever the tree is filtered or a
	-- branch opens - so dressing whatever exists at Create time would cover the
	-- first page and nothing after it. RefreshTree is what builds and repaints
	-- them, and it is wrapped.
	--
	-- Driven the way the client does: the tree bails out and defers to an
	-- OnUpdate while its frame is parented to UIParent, so the fixture gives it
	-- a real parent and a real height first.
	local tree = gui:Create("TreeGroup")
	tree.frame:SetParent(CreateFrame("Frame", nil, UIParent))
	tree.frame:SetSize(400, 300)
	tree.treeframe:SetSize(160, 300)
	tree:SetTree({ { value = "a", text = "Alpha" }, { value = "b", text = "Beta" } })
	tree:SelectByValue("a")

	check(#tree.buttons > 0, "the tree builds rows (" .. #tree.buttons .. ")")

	local chosen, other
	for _, row in ipairs(tree.buttons) do
		if row.selected then chosen = chosen or row else other = other or row end
	end
	check(chosen ~= nil, "and one of them is the selected one")

	-- A row is an OptionsListButtonTemplate and the selection is Blizzard's blue
	-- gradient, drawn by LockHighlight on the button's own highlight texture. So
	-- the art comes off and the selection is drawn by us - which means reading
	-- `selected` rather than a texture we have just taken away.
	if chosen then
		-- The client's own selection is a blue gradient on the row's HIGHLIGHT
		-- texture, drawn permanently by LockHighlight. It has to come off, or
		-- ours is simply painted underneath it.
		local hl = chosen.GetHighlightTexture and chosen:GetHighlightTexture()
		check(hl == nil or hl:GetTexture() == 0,
			"the client's blue gradient is off the row (" ..
			tostring(hl and hl:GetTexture()) .. ")")

		check(chosen.__aetherSel ~= nil and chosen.__aetherSel:IsShown(),
			"the chosen row wears our selection")
		local r = select(1, chosen.__aetherSel:GetVertexColor())
		check(math.abs(r - A.Palette.c.rowSel[1]) < 0.001,
			"in the palette's row colour rather than the client's blue (" ..
			string.format("%.2f", r) .. ")")
	end
	if other then
		check(other.__aetherSel ~= nil and not other.__aetherSel:IsShown(),
			"and an unchosen row wears none - one drawn on every row is a list with"
			.. " nothing chosen at all")
	end

	-- AND THE ROWS BUILT ON THE NEXT REFRESH TOO. This is the whole reason the
	-- method is wrapped rather than the rows dressed once.
	tree:SetTree({ { value = "a", text = "Alpha" }, { value = "b", text = "Beta" },
		{ value = "c", text = "Gamma" } })
	local undressed = 0
	for _, row in ipairs(tree.buttons) do
		if not row.__aetherSel then undressed = undressed + 1 end
	end
	check(undressed == 0,
		"a row built by a later refresh is dressed with the rest (" .. undressed
		.. " bare of " .. #tree.buttons .. ")")

	check(tree.border and tree.border.__aetherPanel ~= nil,
		"the category list gets glass")
	check(tree.treeframe and tree.treeframe.__aetherPanel ~= nil,
		"and so does the list beside it - two frames, and dressing one of them"
		.. " leaves a stone edge down the middle")

	-- A SLIDER IS THREE PIECES OF ART. The groove, the thumb and the number box
	-- under it, and leaving any one alone is what makes a control look half done.
	local sl = gui:Create("Slider")
	check(sl.slider.__aetherTrack ~= nil, "a slider gets a hairline groove")
	local thumb = sl.slider:GetThumbTexture()
	check(tostring(thumb.__tex):find("AetherUI", 1, true),
		"and our thumb on it (" .. tostring(thumb.__tex) .. ")")
	check(sl.editbox.__aetherPill ~= nil,
		"with the number box under it in glass too")

	-- SOMETHING SAYING WHERE YOU ARE IN A FIELD. Reported from the game as a
	-- box you can type into with no cursor in it - and nothing this addon does
	-- can hide the engine's own: it is not a region, so no sweep reaches it. So
	-- the caret is ours instead, where it can be seen, coloured and checked.
	do
		local box = sl.editbox
		local caret = box.__aetherCaret
		check(caret ~= nil, "a dressed field carries a caret of ours")
		caret = caret or { GetPoint = function() end, GetHeight = function() end,
			GetWidth = function() end, GetAlpha = function() end,
			IsShown = function() end }
		check(not caret:IsShown(),
			"which is down until the field is the one being typed in")

		local focus = box:GetScript("OnEditFocusGained")
		if focus then focus(box) end
		check(caret:IsShown(), "and comes up when the field takes focus")

		-- WHERE THE CLIENT SAYS IT IS. OnCursorChanged hands over x, y and HEIGHT
		-- in the box's own coordinates, y negative downward - the sign SetPoint
		-- already wants.
		local moved = box:GetScript("OnCursorChanged")
		if moved then moved(box, 37, -4, 1, 15) end
		local at, rel, relP, cx, cy = caret:GetPoint(1)
		check(at == "TOPLEFT" and rel == box and relP == "TOPLEFT"
			and cx == 37 and cy == -4,
			"and it goes where the client says the cursor is (" .. tostring(cx)
			.. ", " .. tostring(cy) .. ")")
		check(caret:GetHeight() == 15,
			"at the height the client says, rather than a guess at the font (" ..
			tostring(caret:GetHeight()) .. ")")
		check(caret:GetWidth() == 1,
			"and a hairline wide, because a text cursor is a hairline")

		local tick = box:GetScript("OnUpdate")
		local lit = caret:GetAlpha()
		if tick then tick(box, 1.0) end
		check(caret:GetAlpha() ~= lit,
			"it blinks rather than sitting there being mistaken for a letter (" ..
			tostring(lit) .. " to " .. tostring(caret:GetAlpha()) .. ")")

		local lost = box:GetScript("OnEditFocusLost")
		if lost then lost(box) end
		check(not caret:IsShown(),
			"and goes away with the focus, so only the field you are in has one")
	end

	-- The check box keeps its TICK and loses its box. A tick taken off with the
	-- rest never looks checked, whatever the state says.
	local cb = gui:Create("CheckBox")
	local r = select(1, cb.check:GetVertexColor())
	check(math.abs(r - A.Palette.c.accent[1]) < 0.001,
		"a check box keeps its tick, in the accent (" ..
		string.format("%.2f", r) .. ")")

	-- The colour swatch becomes our disc and keeps the colour it holds.
	A.lastFailure = nil
	local cp = gui:Create("ColorPicker")
	cp:SetColor(0.1, 0.2, 0.3, 1)
	check(A.lastFailure == nil and cp.colorSwatch:GetTexture() == A.Media.texture.chipDisc,
		"a colour picker's swatch is our disc (" .. tostring(A.lastFailure) .. ")")
	local sr, sg, sb = cp.colorSwatch:GetVertexColor()
	check(sr == 0.1 and sg == 0.2 and sb == 0.3, "and still shows the colour it holds")
	check(not cp.colorSwatch.checkers:IsShown(), "with Blizzard's checkerboard gone from behind it")

	-- THE STANDALONE WINDOW has three parts a plain container does not, and all
	-- three are anchored to art we have just taken off.
	local win = gui:Create("Frame")
	A.lastFailure = nil
	M.Dress(win)
	check(A.lastFailure == nil,
		"dressing the window raises nothing (" .. tostring(A.lastFailure) .. ")")
	check(win.frame.__aetherPanel ~= nil,
		"and it gets its glass - the LAST thing the dresser does, so this is"
		.. " what says the whole of it ran rather than the first half")

	-- The title hung off a header texture anchored ABOVE the frame, so with the
	-- art gone the words landed on the top border with nothing over them. The
	-- HEADER is re-anchored rather than the words, because the invisible frame
	-- you drag the window by is SetAllPoints on it and is not exposed at all.
	local p, rel, relP, _, y = win.titlebg:GetPoint(1)
	check(rel == win.frame,
		"the title bar hangs off the window itself (" .. tostring(rel and "frame")
		.. ")")
	check(p == "TOP" and relP == "TOP" and y < 0,
		"and sits INSIDE its top edge rather than over it (" .. tostring(p) ..
		" " .. tostring(y) .. ")")
	check(select(2, win.titletext:GetPoint(1)) == win.titlebg,
		"with the words on the bar, so the two cannot drift apart")

	-- The status line is a Button with its own backdrop, so stripping the
	-- window's regions never reached it - it is the wide dark box along the
	-- bottom.
	-- Reached through the status TEXT, because AceGUI keeps the bar itself as a
	-- local and never puts it on the widget. The first pass read widget.statusbg,
	-- found nil, and did nothing at all - silently, since skipping a part that
	-- is not there raises nothing.
	local statusbg = win.statustext:GetParent()
	check(statusbg:GetBackdrop() == nil,
		"the status line has lost its backdrop")
	check(statusbg.__aetherPill ~= nil, "and wears glass instead")

	-- The Close button is the other thing AceGUI keeps to itself, and it was
	-- the last red thing on the window.
	local closed
	for _, child in ipairs({ win.frame:GetChildren() }) do
		if child ~= statusbg and child.__aetherSkin then closed = child end
	end
	check(closed ~= nil, "and the Close button is ours rather than Blizzard's red")

	-- The size grip is three textures out of the tooltip border atlas, children
	-- of the sizer rather than regions of the window, so they survive the strip
	-- and read as a scrap of somebody else's art in the corner.
	local tinted, total = 0, 0
	for _, r in ipairs({ win.sizer_se:GetRegions() }) do
		total = total + 1
		if r._aetherTint then tinted = tinted + 1 end
	end
	check(total > 0 and tinted == total,
		"and every piece of the size grip is re-tinted (" .. tinted .. " of "
		.. total .. ")")

	-- AND THE SCROLL BAR, which only appears once the window is dragged small
	-- enough to need one - which is exactly when nobody is looking for it, and
	-- is where Blizzard's arrows came back.
	local sf = gui:Create("ScrollFrame")
	check(sf.scrollbar and sf.scrollbar.__aetherScroll,
		"a scroll frame's bar is ours before it is ever shown")
	check(sf.scrollbar.__aetherTrack ~= nil,
		"with a rail, so a list you can scroll says so even at rest")

	-- A DROPDOWN IS NOT AN EDIT BOX. Handing the whole UIDropDownMenuTemplate
	-- frame to the edit box dresser wrapped a pill round the ART rather than
	-- round the control, which is why they came out half again too tall.
	local dd = gui:Create("Dropdown")
	check(dd.dropdown.__aetherStripped ~= nil,
		"a dropdown loses the template's own art")
	check(dd.dropdown.__aetherPill ~= nil, "and wears a pill instead")
	check(dd.dropdown.__aetherPill:GetHeight() < 30,
		"sized to the text row rather than to the frame around it (" ..
		tostring(dd.dropdown.__aetherPill:GetHeight()) .. ")")
	check(dd.button and dd.button.__aetherGlyph ~= nil,
		"and the arrow is our chevron rather than a gold plate")

	local hd = gui:Create("Heading")
	check(tostring(hd.left.__tex):find("AetherUI", 1, true),
		"a heading rule is ours (" .. tostring(hd.left.__tex) .. ")")

	-- STRIPPED ONCE. AceGUI pools its widgets, so this same frame comes back for
	-- the next panel that needs one - and stripping again would record our own
	-- emptied regions as the originals, which makes switching the module off a
	-- no-op that looks like it worked.
	local store = box.__aetherStripped
	local n = 0
	for _ in pairs(store) do n = n + 1 end
	M.Dress(grp)
	M.Dress(grp)
	local after = 0
	for _ in pairs(box.__aetherStripped) do after = after + 1 end
	check(box.__aetherStripped == store and after == n,
		"dressing again keeps the first recording rather than re-taking it (" ..
		after .. " of " .. n .. ")")

	-- A TYPE WE DO NOT DRESS IS LEFT ALONE, not guessed at.
	A.lastFailure = nil
	local ok = pcall(M.Dress, { type = "SomethingElse", frame = CreateFrame("Frame") })
	check(ok and A.lastFailure == nil,
		"a widget type this does not know is passed over in silence")

	-- AND A DRESSER THAT ERRORS DOES NOT TAKE THE PANEL WITH IT. These are
	-- somebody else's frames, built by a library that changes shape between
	-- versions, and a settings panel that errors is worse than one that looks
	-- like Blizzard's.
	A.lastFailure = nil
	ok = pcall(M.Dress, { type = "Slider" })   -- no slider, no editbox, no frame
	check(ok, "a dresser handed a widget with nothing on it raises nothing")
end)

section("options: and hands Blizzard's panel back", function()
	local M = A:GetModule("optionsskin")
	local gui = LibStub("AceGUI-3.0", true)

	local grp = gui:Create("InlineGroup")
	local box = grp.content:GetParent()
	check(box.__aetherStripped ~= nil, "dressed to begin with")

	A:SetModuleEnabled("optionsskin", false)
	check(box.__aetherStripped == nil,
		"switching off puts the client's own regions back")

	-- And the hook comes off with it: a widget built while the module is off is
	-- Blizzard's, or "off" only means "off for the ones already made".
	local after = gui:Create("InlineGroup")
	local abox = after.content:GetParent()
	check(abox.__aetherStripped == nil and abox.__aetherPanel == nil,
		"and one built afterwards is untouched")

	A:SetModuleEnabled("optionsskin", true)
	local back = gui:Create("InlineGroup")
	check(back.content:GetParent().__aetherPanel ~= nil,
		"and ours again on the way back")
end)

section("conveniences: instant quest text is the client's own setting", function()
	local CVm = A:GetModule("conveniences")
	local c = A.Config:Module("conveniences")
	check(CVm and CVm.enabled, "conveniences module enabled")

	-- OFF TO BEGIN WITH, and that is a decision rather than an oversight: this
	-- overrides a setting the client already has, under Interface, which the
	-- player may have chosen on purpose.
	check(c.instantQuestText == false,
		"off by default - it overrides a setting the player may have chosen")
	check(GetCVar("instantQuestText") == "0",
		"and the game is left as it was until asked")

	-- NOTHING IS HOOKED. QuestFrame reads this CVar itself every time it opens a
	-- page, so writing it IS the feature - hooking the fade or forcing an alpha
	-- would be a second owner for something the client already decides.
	c.instantQuestText = true
	CVm:ApplyQuestText()
	check(GetCVar("instantQuestText") == "1",
		"turning it on sets the client's own variable (" ..
		tostring(GetCVar("instantQuestText")) .. ")")

	-- AND IT IS IDEMPOTENT. Every write to a CVar is a write the client logs,
	-- and a config change runs this again.
	local writes = _G.__cvarWrites
	CVm:ApplyQuestText()
	CVm:ApplyQuestText()
	check(_G.__cvarWrites == writes,
		"and setting it again writes nothing - it is already what we want")

	-- BACK THE WAY IT WAS. Not to "0" - to whatever it was before we touched
	-- it, which is the difference between restoring and guessing.
	c.instantQuestText = false
	CVm:ApplyQuestText()
	check(GetCVar("instantQuestText") == "0",
		"turning it off puts the player's own setting back")

	do
		-- A player who had it on ALREADY gets it back on, which is the case a
		-- restore-to-zero would quietly break.
		SetCVar("instantQuestText", "1")
		c.instantQuestText = true
		CVm:ApplyQuestText()
		c.instantQuestText = false
		CVm:ApplyQuestText()
		check(GetCVar("instantQuestText") == "1",
			"and somebody who already had it on keeps it on afterwards")
		SetCVar("instantQuestText", "0")
	end
end)

section("conveniences: repairing spends money, so it says so", function()
	local CVm = A:GetModule("conveniences")
	local c = A.Config:Module("conveniences")
	local R = _G.__repair

	check(c.autoRepair == false,
		"off by default, because it spends your money")

	-- NOTHING TO DO IS NOT AN ERROR. GetRepairAllCost answers TWO values - the
	-- cost and whether anything needs doing - and reading only the first is how
	-- an addon repairs for nothing every time a merchant opens.
	c.autoRepair = true
	R.cost, R.repairs, R.refused = 0, 0, 0
	_G.__money = 100000
	check(CVm:Repair() == nil, "a merchant with nothing to repair costs nothing")
	check(R.repairs == 0, "and no repair is attempted")

	-- The ordinary case.
	R.cost = 5000
	local before = _G.__money
	check(CVm:Repair() == "repaired", "an armour bill is paid")
	check(_G.__money == before - 5000,
		"and the money goes (" .. tostring(before - _G.__money) .. ")")

	-- CANNOT AFFORD IT. RepairAllItems on too little money does NOTHING in the
	-- client - no error, no partial repair - so an addon that fired blind would
	-- look like it had repaired and leave you in a fight with a broken weapon.
	R.cost, R.repairs, R.refused = 9999999, 0, 0
	_G.__money = 10
	check(CVm:Repair() == "broke", "too little money is reported, not ignored")
	check(R.repairs == 0 and R.refused == 0,
		"and the client is never asked - it would have said nothing either way")
	check(_G.__money == 10, "with the money untouched")

	-- A MERCHANT WHO CANNOT REPAIR is left alone.
	R.canMerchant, R.cost, R.repairs = false, 5000, 0
	_G.__money = 100000
	check(CVm:Repair() == nil, "a merchant who cannot repair is not asked to")
	check(R.repairs == 0, "and nothing is spent at one")
	R.canMerchant = true

	-- AND THE SWITCH IS THE SWITCH.
	c.autoRepair = false
	R.cost, R.repairs = 5000, 0
	check(CVm:Repair() == nil and R.repairs == 0,
		"switched off, a merchant opening costs nothing")

	-- Through the EVENT, which is what actually drives it: MERCHANT_SHOW rather
	-- than a frame appearing, because the event is the game saying a merchant is
	-- open whether or not anything has drawn a window yet.
	c.autoRepair = true
	R.cost, R.repairs = 3000, 0
	_G.__money = 100000
	fire("MERCHANT_SHOW")
	check(R.repairs == 1,
		"and opening a merchant repairs, from the event rather than a frame")

	c.autoRepair = false
	R.cost = 0
end)

section("options: every page has a place of its own", function()
	-- TWO PAGES ON THE SAME NUMBER is not an error and does not look like one:
	-- AceConfig sorts by order and breaks the tie however it likes, so a page
	-- inserted in the middle silently swaps places with its neighbour on some
	-- runs and not others. Which is precisely what inserting one just did.
	local tree = A.Options:Build()
	local seen, clash = {}, nil
	for key, node in pairs(tree.args or {}) do
		local o = node and node.order
		if type(o) == "number" then
			if seen[o] then clash = clash or (key .. " and " .. seen[o] .. " are both " .. o) end
			seen[o] = key
		end
	end
	check(not clash, "no two pages share an order (" .. tostring(clash) .. ")")

	-- AND EVERY MODULE IS REACHABLE FROM SOMEWHERE IN IT. A module with a
	-- config table and no control anywhere is one a player cannot switch on,
	-- and it ships looking exactly like a module that does not work. This one
	-- nearly went out that way.
	--
	-- Reachability, not a page each: five modules share the "The game's own"
	-- page and are perfectly reachable there. So the tree is walked for the
	-- config paths its controls actually write to, which is the same question
	-- asked without assuming the shape of the answer.
	local reached = {}
	local function walk(node)
		if type(node) ~= "table" then return end
		local path = node.arg and node.arg.path
		if type(path) == "table" and path[1] == "modules" and path[2] then
			reached[path[2]] = true
		end
		for _, child in pairs(node.args or {}) do walk(child) end
	end
	walk(tree)

	local unreachable = {}
	for name in pairs(A.Config.defaults.profile.modules or {}) do
		if not reached[name] then unreachable[#unreachable + 1] = name end
	end
	table.sort(unreachable)
	check(#unreachable == 0,
		"every module with settings can be reached from the panel (" ..
		(#unreachable > 0 and table.concat(unreachable, ", ") or "all of them")
		.. ")")
end)

print("== options tree ==")
do
	local tree = A.Options:Build()
	check(type(tree) == "table" and tree.type == "group", "the tree builds")

	-- Walking it and checking every path is the whole reason Build() is pure.
	-- A typo in a path is otherwise a control that silently does nothing, and
	-- you find it a month later.
	local leaves, bad, kinds = 0, {}, {}
	local function walk(node, trail)
		for key, opt in pairs(node.args or {}) do
			local where = trail .. "." .. key
			if opt.type == "group" then
				walk(opt, where)
			elseif opt.arg and opt.arg.path then
				leaves = leaves + 1
				kinds[opt.type] = (kinds[opt.type] or 0) + 1
				local t, k = A.Options.Resolve(opt.arg.path)
				if not t then
					bad[#bad + 1] = where .. " (no table at " .. table.concat(opt.arg.path, ".") .. ")"
				elseif t[k] == nil then
					bad[#bad + 1] = where .. " -> " .. table.concat(opt.arg.path, ".") .. " is nil"
				end
			end
		end
	end
	walk(tree, "root")

	check(leaves > 50, "it has a real number of controls in it (" .. leaves .. ")")
	check(#bad == 0, "every control's path resolves to something that exists"
		.. (#bad > 0 and ("  -- " .. table.concat(bad, "; ")) or ""))
	check((kinds.toggle or 0) > 0 and (kinds.range or 0) > 0 and (kinds.select or 0) > 0,
		"toggles, ranges and selects all present")

	-- A button that leaves a MODE running has to name what it will do next.
	--
	-- Both of these close the panel and leave something switched on, so the
	-- next time anybody opens this page the mode is already running - and a
	-- button still offering to start it is a button lying about the state of
	-- the screen. Ace resolves a function `name` when the page is built, which
	-- is exactly the moment that matters here.
	do
		local function Find(node, key)
			for k, opt in pairs(node.args or {}) do
				if k == key then return opt end
				if opt.type == "group" then
					local hit = Find(opt, key)
					if hit then return hit end
				end
			end
		end

		local unlock = Find(tree, "unlock")
		check(unlock and type(unlock.name) == "function",
			"the unlock button names itself dynamically rather than carrying a"
			.. " fixed string")

		A.Movers:Lock()
		check(unlock.name() == "Unlock frames", "locked, it offers to unlock")
		A.Movers:Unlock()
		check(unlock.name() == "Lock frames",
			"and once they ARE unlocked it offers to lock - the panel is shut"
			.. " for the whole time the mode is on, so this is read on the next"
			.. " open (got " .. tostring(unlock.name()) .. ")")
		A.Movers:Lock()

		local bind = Find(tree, "bind")
		check(bind and type(bind.name) == "function",
			"and keybind mode does the same - it has the identical shape and"
			.. " would have the identical bug")
		local AB = A:GetModule("actionbars")
		if AB and AB.enabled then
			AB:SetBindMode(false)
			check(bind.name() == "Keybind mode", "off, it offers to enter")
			AB:SetBindMode(true)
			check(bind.name() == "Leave keybind mode", "on, it offers to leave")
			AB:SetBindMode(false)
		end
	end

	-- and the accessors round-trip through the real db
	local widthOpt = tree.args.unitframes.args.width
	local before = widthOpt.get({ arg = widthOpt.arg, type = "range" })
	check(before == A.db.profile.modules.unitframes.width, "get reads the live value")
	widthOpt.set({ arg = widthOpt.arg, type = "range" }, 360)
	check(A.db.profile.modules.unitframes.width == 360, "set writes it back")
	widthOpt.set({ arg = widthOpt.arg, type = "range" }, before)

	-- a nil-means-true toggle has to report true, or the checkbox lies
	local hb = tree.args.auras.args.hideBlizzard
	A.db.profile.modules.auras.hideBlizzard = nil
	check(hb.get({ arg = hb.arg, type = "toggle" }) == true,
		"a toggle that defaults to nil-means-true reports true, not nil")
	A.db.profile.modules.auras.hideBlizzard = true

	-- bar pages are generated from the config, so a bar added later gets controls
	local bars = tree.args.actionbars.args
	local pages = 0
	for k in pairs(bars) do if k:find("^bar") then pages = pages + 1 end end
	check(pages == #A.db.profile.modules.actionbars.bars,
		"one page per configured bar, generated rather than hard-coded (got "
		.. pages .. " for " .. #A.db.profile.modules.actionbars.bars .. " bars)")
	check(bars.barstance.args.page == nil,
		"a stance bar gets no page control - its buttons come from the game")
	check(bars.bar1.args.page ~= nil, "an action bar does")

	-- profiles go last, and that has to be a decision rather than a guess: the
	-- running order counter lands in the hundreds by the end of the tree
	local tops = {}
	for key, opt in pairs(tree.args) do
		if opt.type == "group" and opt.order then tops[key] = opt.order end
	end
	local first, firstOrder = nil, math.huge
	for key, n in pairs(tops) do
		if n < firstOrder then first, firstOrder = key, n end
	end
	check(first == "home", "Home is the first page (" .. tostring(first) .. ")")
	check(tops.general and tops.general < (tops.unitframes or 0),
		"and General comes straight after it")
	local maxOther = 0
	for key, n in pairs(tops) do
		if key ~= "profiles" then maxOther = math.max(maxOther, n) end
	end
	check(A.Options.PAGE_ORDER.profiles > maxOther,
		"and profiles sorts after every other page (" .. A.Options.PAGE_ORDER.profiles
		.. " > " .. maxOther .. ")")

	-- registration degrades rather than erroring when Ace3 is absent
	check(A.Options:Register() == false,
		"Register reports false without the Ace libraries instead of throwing")

	-- THE GAME'S OWN OPTIONS LIST CARRIES A DOOR, NOT THE SETTINGS. One page
	-- under AddOns, registered at login whether or not Ace loaded, holding a
	-- button that opens our window.
	do
		local mine = {}
		for _, cat in ipairs(_G.__settingsPages) do
			if cat.name == "Lattice" then mine[#mine + 1] = cat end
		end
		check(#mine == 1,
			"one Lattice page in the game's AddOns list (" .. #mine .. ")")
		check(mine[1] and mine[1].frame == A.Options.stub,
			"and it is the stub, not the settings tree")

		-- THE CLIENT'S WINDOW SHUTS FIRST and ours opens a frame later, as
		-- EllesmereUI does - so ours is not opened from inside the client's own
		-- click.
		local sp = _G.SettingsPanel
		sp:Show()
		local opened = 0
		local realOpen = A.Options.Open
		A.Options.Open = function() opened = opened + 1 return true end
		A.Options.stubButton:GetScript("OnClick")(A.Options.stubButton)
		check(not sp:IsShown(), "pressing it closes the game's Options window")
		check(opened == 0, "and does not open ours inside the same click")
		_G.__drainTimers(1)
		check(opened == 1, "but on the next frame (" .. opened .. ")")
		A.Options.Open = realOpen

		-- AND IT SAYS WHOSE IT IS: the mark above the line, cropped to its ink.
		local marked = false
		for _, r in ipairs({ A.Options.stub:GetRegions() }) do
			if r.GetTexture and r:GetTexture() == A.Media.texture.logo then marked = true end
		end
		check(marked, "the stub wears the logo above its button")
	end

	-- HOME: the brand and the four things a player reaches for first.
	do
		local home = tree.args.home and tree.args.home.args
		check(home ~= nil, "there is a Home page")
		check(home and home.logo and home.logo.image == A.Media.texture.lockup
			and home.logo.imageCoords == A.Media.lockupCoord,
			"it opens with the full lockup - tagline and all - cropped to its ink")
		check(home and home.logo and math.abs(home.logo.imageWidth / home.logo.imageHeight
			- A.Media.lockupAspect) < 0.05,
			"at the lockup's own aspect, so it is not squashed")
		check(home and home.logo and home.logo.order > home.top.order
			and home.afterLogo and home.afterLogo.order > home.logo.order,
			"with air above and below it - Ace stacks controls flush otherwise")
		local current = A:Notes()
		check(home and home.newsBody and current and current.lines[1]
			and home.newsBody.name:find(current.lines[1], 1, true),
			"and what this version changed, from the changelog rather than written twice")
		check(home and home.tour and home.news and home.unlock and home.bind,
			"with the tour, what's new, unlock and keybind mode on it")
		check(home and home.support and home.support.name:find("discord.gg/drveoj", 1, true),
			"and where to get help")

		-- The window opens there every time, unless a page was asked for. No
		-- Ace in the suite, so a stand-in dialog records what it was told.
		local O = A.Options
		local was = { O.registered, O.dialog, O.Register }
		local picked
		O.registered = true
		O.Register = function() return true end
		O.dialog = { SelectGroup = function(_, _, g) picked = g end, Open = function() end }
		O:Open()
		check(picked == "home", "the window opens on Home (" .. tostring(picked) .. ")")
		O:Open("changelog")
		check(picked == "changelog", "unless a page was asked for, as the Notes link does")
		home.news.func()
		check(picked == "changelog", "and What's new on Home goes to the changelog page")
		O.registered, O.dialog, O.Register = was[1], was[2], was[3]
	end
	SlashCmdList["AETHERUI"]("")
	check(true, "and bare /aether falls back to the command list")
end

print("== minimap ==")

local MMm = A:GetModule("minimap")
check(MMm and MMm.enabled, "minimap module enabled"
	.. (MMm and MMm.lastError and ("  -- " .. MMm.lastError) or ""))
check(MMm.frame and MMm.pill, "map holder and zone pill built")
check(MMm.drawer == nil,
	"and NO drawer - addon launchers live on the Toolbox rail now. Defaulting"
	.. " it off was not enough: the drawer showed its contents ON HOVER, so"
	.. " any button the rail had not claimed sat in a frame at alpha 0 and"
	.. " simply vanished until somebody hovered the zone pill")

do  -- Blizzard's Minimap is reshaped, not replaced: it cannot be recreated
	local cfg = A.db.profile.modules.minimap
	check(Minimap:GetParent() == MMm.frame,
		"the real Minimap is reparented into our holder rather than rebuilt")
	check(Minimap.__mask ~= nil, "and masked round")
	check(Minimap:GetWidth() == cfg.size, "sized from the config")
	-- Layering: an earlier version hung a soft ring off the holder as a plain
	-- BACKGROUND region meaning to put it behind the map, and a region draws at
	-- its own frame's strata - so it landed on top instead.
	check(MMm.frame.border ~= nil and MMm.frame.vignette == nil and MMm.frame.rim == nil,
		"the whole edge is one texture - a rim plus a separately-gated vignette"
		.. " was two draw orders and two switches, and the bug was in the seam"
		.. " between them every single time")
	check(MMm.frame.border:GetAlpha() == 1,
		"drawn at full alpha rather than behind a config value that could be 0")
	do
		-- Same hue as every pill's rim. The band survives the multiply because
		-- it is baked dark, which is why the tones are luminance and not colour.
		local r = select(1, MMm.frame.border:GetVertexColor())
		check(math.abs(r - A.Palette.c.glassEdge[1]) < 0.001,
			"and tinted with glassEdge, so the map's border and the zone pill"
			.. " under it are the same colour")
	end
	check(MMm.frame.top:GetFrameStrata() == "MEDIUM"
		and Minimap:GetFrameStrata() == "LOW",
		"and on a whole strata above the map, not merely a higher level - the"
		.. " Minimap is a widget the client renders into, and it does not"
		.. " composite against a sibling at its own strata")
	do
		local _, rel, _, x = MMm.frame.border:GetPoint(1)
		check(rel == MMm.frame and x < 0,
			"and drawn proud of the map, not flush with it - a mask edge is the"
			.. " client's to anti-alias and it stair-steps, so the border has to"
			.. " lap over it rather than stop short")
	end
	check(A.db.profile.modules.minimap.shadow == nil,
		"the old shadow key is migrated away - a profile carrying 0 from the"
		.. " version where it was off by default would hide the border")
	check(Minimap:GetFrameStrata() == "LOW",
		"with the map itself left in Blizzard's own band, where other addons"
		.. " expect to find it")
	check(MinimapCluster.__mouse == false,
		"the cluster's mouse is off - it is a rectangle much bigger than the map"
		.. " and it swallows clicks meant for what is behind it")
end

if _G.__flavour == "camelot" then do  -- the furniture, camelot
	-- THE NAMED LIST BUYS ALMOST NOTHING HERE. Nine of the twelve names in
	-- MM.blizzardFrames do not exist on this client, and the three that do
	-- (GameTimeFrame, MinimapCompassTexture, MinimapBackdrop) are not where the
	-- furniture went. Everything else moved onto the cluster as an ANONYMOUS
	-- parentKey, which is the part that breaks the sweep: SweepCluster sorts
	-- children with issecurevariable(name), and a frame whose GetName() is nil
	-- cannot be sorted that way at all - it is simply skipped.
	--
	-- So the sweep has to learn the parentKey shape. These check the end state,
	-- not the route: whatever way the module gets there, none of this furniture
	-- may be left drawing over the glass.
	local r = MMm.hideReport
	check(not MinimapCluster.Tracking:IsShown(),
		"the tracking button is banished, though nothing globally names it")
	check(not MinimapCluster.IndicatorFrame.MailFrame:IsShown(),
		"and the mail indicator, which is two parentKeys deep")
	check(not MinimapCluster.BorderTop:IsShown(), "and the cluster's border bar")
	check(not MinimapCluster.ZoneTextButton:IsShown(), "and the zone text button")
	check(not MinimapCluster.InstanceDifficulty:IsShown(),
		"and the instance difficulty badge")
	check(not Minimap.ZoomIn:IsShown() and not Minimap.ZoomOut:IsShown(),
		"the zoom buttons go too - they are children of Minimap here, not globals")

	-- Both reported from the game on 2026-09-22, and both reachable ONLY by
	-- parentKey: one is built at runtime by a file that exists on no other
	-- client, the other is a frame Blizzard did not used to draw at all.
	check(not MinimapCluster.DielFrame:IsShown(),
		"WoW Forever's day/night dial is banished - the sun off the map's corner")
	check(not MinimapCluster.MinimapContainer.PlayerCoords:IsShown(),
		"and Blizzard's own coordinates, which sat under the map behind our pill"
		.. " and read as ours printed twice - a SIBLING of Minimap, not a child,"
		.. " which is what the first fix got wrong")

	-- The three names that DO survive the move still have to work by name.
	check(r.GameTimeFrame == "hidden", "the day/night dial is still banished by name")
	check(r.MinimapBackdrop == "swept",
		"and the backdrop is still recursed into, not carried off")

	-- NOT A FRAME THE CLIENT HAS NOT GOT. A report claiming to have hidden
	-- MinimapBorder on camelot is the mock being kind in a new way.
	check(r.MinimapBorder == "absent" or r.MinimapBorder == nil,
		"a name this client does not have is reported absent, never hidden")
	check(r.MiniMapTracking == "absent" or r.MiniMapTracking == nil,
		"and so is Era's tracking frame")

	check(not _G.__clusterArt:IsShown() and _G.__clusterArt:GetAlpha() == 0,
		"an unnamed region of the cluster is swept, the same as on Era")
	check(_G.SomeAddonOnTheCluster:IsShown(),
		"but an addon's own frame on the cluster is still left where it is")
	-- No pin-alpha check here. Zen's blocks run thousands of checks earlier and
	-- drive __minimapPin's alpha on purpose, so anything asserted about it down
	-- here is asserting the leftovers of an unrelated test. It is covered where
	-- it belongs, in the two zen blocks.

	-- The wheel, with no Minimap_ZoomInClick to fall back on: the module has to
	-- drive SetZoom itself here.
	Minimap:GetScript("OnMouseWheel")(Minimap, 1)
	check(Minimap:GetZoom() == 1, "the wheel zooms in without Minimap_ZoomInClick")
	Minimap:GetScript("OnMouseWheel")(Minimap, -1)
	check(Minimap:GetZoom() == 0, "and out")

	-- AND THERE IS A REAL MENU HERE, unlike Era. Tracking is a dropdown on the
	-- cluster, so the right-click opens it rather than cancelling a buff -
	-- CancelTrackingBuff does not exist on this client.
	_G.__trackingMenu = nil
	Minimap:GetScript("OnMouseUp")(Minimap, "RightButton")
	check(_G.__trackingMenu ~= nil,
		"right-click opens the tracking menu off MinimapCluster.Tracking.Button")
	check(_G.CancelTrackingBuff == nil,
		"and never reaches for CancelTrackingBuff, which this client has not got")
end else do  -- the furniture
	local r = MMm.hideReport
	check(r.MinimapBorder == "hidden" and r.MinimapZoomIn == "hidden"
		and r.MiniMapTracking == "hidden" and r.GameTimeFrame == "hidden",
		"the border, zoom, tracking and day/night dial are all banished")
	check(_G.MinimapZoomIn:GetParent() ~= MinimapCluster,
		"banished frames are reparented off the cluster, so another addon calling"
		.. " Show() on one cannot put it back")
	check(r.MiniMapWorldMapButton == nil,
		"MiniMapWorldMapButton is never touched - it is Wrath+ only and does not"
		.. " exist on this client")

	-- The named list is not the whole job: some of the art up there is an
	-- anonymous region with no global to put in a list, which is what left a
	-- border bar and a toggle tab sitting above the map first time round.
	check(not _G.__clusterArt:IsShown() and _G.__clusterArt:GetAlpha() == 0,
		"an unnamed region of the cluster is swept too")
	check(not _G.MinimapZoneTextButton:IsShown(),
		"and a named Blizzard child is banished whether it was listed or not")
	check(_G.SomeAddonOnTheCluster:IsShown(),
		"but an addon's own frame on the cluster is left exactly where it is -"
		.. " issecurevariable tells the two apart")
	check(r.MinimapBackdrop == "swept",
		"the backdrop is recursed into rather than carried off, so a third-party"
		.. " button parented there does not go with it")

	-- the two that were doing real work survive without any chrome
	_G.__minimapPinged, _G.__trackingMenu = nil, nil
	Minimap:GetScript("OnMouseWheel")(Minimap, 1)
	check(Minimap:GetZoom() == 1, "the wheel zooms in")
	Minimap:GetScript("OnMouseWheel")(Minimap, -1)
	check(Minimap:GetZoom() == 0, "and out")
	-- THERE IS NO MENU ON THIS CLIENT, and this has now been checked twice
	-- against a frame the client had not got.
	--
	-- First MiniMapTrackingDropDown, invented by the mock because the module
	-- asked for it; then MiniMapTrackingButton, built by the mock when the toc
	-- gives it only to clients past vanilla. Both times the suite was green
	-- while right-clicking the map did nothing in the game.
	--
	-- Era's tracking is a BUFF YOU CAST, so there is no list to choose from and
	-- nothing to open. The right-click does what the frame we hid did, which is
	-- cancel it.
	_G.__trackingCancelled = nil
	Minimap:GetScript("OnMouseUp")(Minimap, "RightButton")
	check(_G.__trackingCancelled == true,
		"right-click cancels the tracking buff - this client has no menu, and"
		.. " that is the whole of what the frame we hid did")
	Minimap:GetScript("OnMouseUp")(Minimap, "LeftButton")
	check(_G.__minimapPinged, "and left-click still pings")
end end

print("== the zone pill ==")
do
	local cfg = A.db.profile.modules.minimap
	MMm:UpdateZone()
	check(MMm.pill.zone:GetText() == "The Barrens", "zone named")
	check(MMm.pill.coords:GetText() == "45 · 58",
		"coordinates read out of C_Map (got " .. tostring(MMm.pill.coords:GetText()) .. ")")
	check(MMm.pill.clock:GetText() ~= "", "and the clock is in there too")

	-- Coordinates walk a digit at a time as you move and the clock ticks over
	-- every minute. Measured to their content, either one nudges the whole block
	-- sideways while you are standing still looking at it.
	do
		local before = MMm.pill:GetWidth()
		_G.__playerPos = { 0.07, 0.09 }        -- "7 . 9" - much narrower
		MMm:UpdateZone()
		check(MMm.pill:GetWidth() == before,
			"the block does not move when the coordinates change width")
		check(MMm.pill.coordW and MMm.pill.coordW > 0
			and MMm.pill.coordW < MMm.pill:GetWidth(),
			"and the fixed field is *measured* from the font rather than guessed"
			.. " - the guess was half again too wide and pushed the block off the"
			.. " side of the screen (" .. tostring(MMm.pill.coordW) .. ")")
		_G.__playerPos = { 0.45, 0.58 }
		MMm:UpdateZone()
	end
	check(not MMm.pill.dot:IsShown(), "no combat dot out of combat")

	-- tinted by zone type, the same colours the rest of the game uses
	_G.__pvpType = "contested"
	MMm:UpdateZone()
	local r = select(1, MMm.pill.zone:GetTextColor())
	check(math.abs(r - 1.0) < 0.01, "a contested zone is tinted")
	_G.__pvpType = nil

	-- an instance has a map but no position on it, which is a different nil
	-- from having no map at all - both have to mean "no coordinates"
	_G.__playerPos = nil
	MMm:UpdateZone()
	check(MMm.pill.coords:GetText() == "",
		"an instance drops the coordinates rather than showing nils")
	_G.__playerPos = { 0.45, 0.58 }
	_G.__uiMap = nil
	MMm:UpdateZone()
	check(MMm.pill.coords:GetText() == "", "and so does having no map at all")
	_G.__uiMap = 1413

	-- in combat the pill says so
	_G.__inCombat = true
	MMm:UpdateZone()
	check(MMm.pill.dot:IsShown() and MMm.pill.zone:GetText() == "In combat",
		"in a fight the pill swaps for a dot and 'In combat'")
	check(select(2, MMm.pill.zone:GetPoint(1)) == MMm.pill.dot,
		"and the label moves out of the dot's way - both were anchored 14 in from"
		.. " the same edge, so the dot was drawn on top of the first word")
	check(MMm.pill.clock:GetText() ~= "", "the clock stays either way")
	check(MMm.pill.coords:GetWidth() == 0,
		"and the empty coordinate field collapses - a fixed-width field with"
		.. " nothing in it still takes up its width in the anchor chain, which"
		.. " pushed the clock out past the end of the pill")
	_G.__inCombat = false
	MMm:UpdateZone()
	check(MMm.pill.zone:GetText() == "The Barrens", "and comes back afterwards")
end

print("== toolbox: a widget nobody has poked is still right ==")
do
	local TBm = A:GetModule("toolbox")
	TBm:SetDock("LEFT")

	-- THE GOLD WIDGET SAID "0s" while the bag window on the same screen said
	-- 3g 38s 13c.
	--
	-- GetMoney answers 0 at login, before the client has been told otherwise.
	-- Gold carried only PLAYER_MONEY, which fires when your money CHANGES - so
	-- the single read at enable wrote a zero and nothing looked again until you
	-- earned or spent something. Bag space and durability were right on that
	-- same screen because they carry PLAYER_ENTERING_WORLD and Gold did not.
	do
		local gold
		for _, p in ipairs(TBm.PROVIDERS) do if p.key == "Gold" then gold = p end end
		local hasLogin = false
		for _, e in ipairs(gold.events or {}) do
			if e == "PLAYER_ENTERING_WORLD" then hasLogin = true end
		end
		check(hasLogin,
			"Gold is swept at login like every other event-driven widget - an"
			.. " event that only fires on CHANGE cannot establish a first value")

		-- Every event-driven provider, not just the one that was reported. A
		-- widget whose only event is a change event has the same bug waiting.
		local missing = {}
		for _, p in ipairs(TBm.PROVIDERS) do
			if p.events then
				local ok = false
				for _, e in ipairs(p.events) do
					if e == "PLAYER_ENTERING_WORLD" then ok = true end
				end
				if not ok then missing[#missing + 1] = p.key end
			end
		end
		check(#missing == 0,
			"and so is every other one (" ..
			(#missing > 0 and table.concat(missing, ", ") or "all of them") .. ")")
	end

	-- ...and the general version: opening the Widgets branch re-reads the lot,
	-- so a value that was not available at login is right by the time it is
	-- seen.
	do
		TBm:SetOpen(false)
		_G.__money = 0
		TBm:RefreshProviders("Gold")
		local zero = TBm._published.Gold.value

		-- The client finally knows, and says nothing about it.
		_G.__money = 33813
		check(TBm._published.Gold.value == zero,
			"a value that changed with no event still reads stale while shut")

		TBm:SetOpen(true, nil, "widgets")
		check(TBm._published.Gold.value ~= zero,
			"and opening the Widgets branch re-reads it (was " .. tostring(zero)
			.. ", now " .. tostring(TBm._published.Gold.value) .. ")")
	end

	-- The two that cannot be event-driven answer on the FIRST tick after the
	-- branch opens rather than a second later, and stop when it shuts.
	do
		TBm:SetOpen(false)
		check(not TBm._polling, "nothing is polled with the Widgets branch shut")
		TBm:SetOpen(true, nil, "widgets")
		check(TBm._polling and TBm._pollAccum ~= nil and TBm._pollAccum >= 1.0,
			"the poll is due immediately on opening rather than after a full"
			.. " period (got " .. tostring(TBm._pollAccum) .. ")")
	end

	-- ESCAPE CLOSES A BRANCH: every branch panel is in UISpecialFrames, and
	-- the client hides what it finds shown there.
	do
		local p = TBm.panels.widgets
		local listed = false
		for _, n in ipairs(_G.UISpecialFrames or {}) do
			if p and n == p:GetName() then listed = true end
		end
		check(listed, "the branch is in UISpecialFrames, which is what Escape reads")
		p:Hide()
		check(not TBm:IsOpen() and not TBm._polling,
			"and hiding it - which is Escape - shuts it and stops the poll")
	end
end

print("== the copy box ==")
do
	A.db.profile.anchors = A.db.profile.anchors or {}
	A.db.profile.anchors.player = { point = "CENTER", relPoint = "CENTER",
		x = -180, y = -120 }

	-- CHAT CANNOT BE COPIED FROM IN THIS CLIENT. That is the whole reason the
	-- copy box exists, so a capture that only reaches chat has not reached
	-- anybody.
	local said = {}
	local chat = _G.DEFAULT_CHAT_FRAME
	local realAdd = chat.AddMessage
	chat.AddMessage = function(self, msg)
		said[#said + 1] = tostring(msg)
		return realAdd(self, msg)
	end
	SlashCmdList["AETHERUI"]("preset capture centre")
	chat.AddMessage = realAdd

	local box = _G.AetherUIErrorBox
	check(box ~= nil, "the copy box was opened")
	local text = box and box:GetText() or ""
	check(text:match("^LAT%d+;") ~= nil and text:find("player=", 1, true) ~= nil,
		"the layout string is in the box, which is the only thing in this client "
		.. "whose text can be selected (" .. text:sub(1, 24) .. ")")
	-- THE BARE STRING, NOTHING AROUND IT. Joe captured, copied the box and
	-- pasted it into /lattice layout - and it was the `centre = { ... }` table
	-- this used to print, which the layout box refused.
	check(text:find("{", 1, true) == nil and text:find("\"", 1, true) == nil
		and text:find("\n", 1, true) == nil,
		"and nothing wrapped round it: no table, no quotes, one line")
	check(A.Layout:Decode(text) ~= nil,
		"so what capture puts in the box pastes straight into the layout box")
	local named = false
	for _, line in ipairs(said) do
		if line:find("screen", 1, true) and line:find("/lattice layout", 1, true) then
			named = true
		end
	end
	check(named,
		"and chat says what size screen it was made on, and where it pastes")

	-- AND OUT TO THE DISK, WHICH IS THE ONLY ROUTE THAT WORKS.
	--
	-- Ctrl+A, Ctrl+C takes what the EditBox LAID OUT rather than the string it
	-- was handed: a capture that read correctly in the box, and counted
	-- correctly in chat at 1683 characters and 25 lines, arrived in Windows as
	-- thousands of lines. CopyToClipboard would have stepped over the box and
	-- is forbidden to addons - see the mock. What is left is the saved
	-- variables file, which is a text file that holds what it is given.
	local out = A.db.global.export and A.db.global.export.preset_centre
	check(out == text,
		"a capture is written to the saved variables byte for byte, which is the "
		.. "one way text leaves this client intact")

	-- NOTHING TRAILING. The symptom was the report followed by a screenful of
	-- empty lines, so what matters is that the last character of the export is
	-- the last character of the report.
	local pad = tostring(out or ""):match("%s*$") or ""
	check(pad:find("\n") == nil,
		"and not one blank line after it (" .. #pad .. " characters of trailing "
		.. "space)")

	-- THE BUTTON DOES THE SAME, for a panel dump or an error log that was not
	-- put there by a command.
	local dlg = box and box:GetParent() and box:GetParent():GetParent()
	check(dlg and dlg.copy ~= nil, "the copy box has an Export button")
	if dlg and dlg.copy then
		A.Errors:ShowText("one\ntwo\nthree")
		dlg.copy:GetScript("OnClick")(dlg.copy)
		check(A.db.global.export.last == "one\ntwo\nthree",
			"and its Export button writes whatever is on screen (" ..
			tostring(A.db.global.export.last) .. ")")
	end

	-- AND NOTHING GOES NEAR THE CLIPBOARD. CopyToClipboard is in this client -
	-- Blizzard's own console and Edit Mode both call it - and forbidden to
	-- addons, so an attempt is an error report in the player's face whether or
	-- not it is pcall'd. It shipped once and came straight back.
	local tried = false
	local realCopy = _G.CopyToClipboard
	_G.CopyToClipboard = function() tried = true end
	if dlg and dlg.copy then
		pcall(dlg.copy:GetScript("OnClick"), dlg.copy)
	end
	pcall(SlashCmdList["AETHERUI"], "preset capture centre")
	_G.CopyToClipboard = realCopy
	check(not tried,
		"and nothing on this path calls the forbidden clipboard function")

	-- AND IT SAYS HOW MUCH IT WAS GIVEN. A box showing one line of an
	-- eight-line report looks exactly like a report that had one line in it,
	-- and telling those apart from the outside took two builds.
	local counted = false
	for _, line in ipairs(said) do
		if line:find("copy box:", 1, true) then counted = true end
	end
	check(counted,
		"and it says how many characters and lines it was handed, so a short "
		.. "box can be told from a short report")

	A.db.profile.anchors.player = nil
end
-- Where the chat's GLASS sits, in HUD units from the screen's bottom left:
-- what a layout's chat record places (the panel and the edit box hang off
-- ChatFrame1, and the frame's own position is not what a player sees). Also
-- its left, right, top and bottom edges in UIParent units, for the board.
--
-- ChatFrame1 widened by Chat:Insets(), because the panel itself is pinned
-- between two DIFFERENT frames - the tab dock and ChatFrame1 - which this mock
-- does not resolve (see fromAnchors). That Insets() is what the panel really
-- does is checked against the panel's own anchors, in the chat block below.
function _G.__chatGlass()
	local CM = A:GetModule("chat")
	local f = _G.ChatFrame1
	if not (CM.Insets and f and f:GetLeft()) then return nil end
	local l, b, r, t = CM:Insets()
	local s = f:GetEffectiveScale() / UIParent:GetEffectiveScale()
	local edges = { l = (f:GetLeft() - l) * s, r = (f:GetRight() + r) * s,
		b = (f:GetBottom() - b) * s, t = (f:GetTop() + t) * s }
	local hud = A.db.profile.scale or 1
	return (edges.l - UIParent:GetLeft()) / hud, (edges.b - UIParent:GetBottom()) / hud, edges
end

print("== presets: the shipped arrangements of the HUD ==")
do
	-- WHAT NO ARRANGEMENT NAMES, AND WHY.
	--
	-- Apply wipes the anchors and writes the preset's, so a mover that no
	-- preset names falls back on its coded default every time somebody tries
	-- an arrangement on. That is harmless for a default that is right
	-- anywhere and a bug for one that is not: the stance bar's used to be
	-- BOTTOMLEFT 24, 220, which is on top of the chat window in all three of
	-- them. Reported from the game against 0.31.0.
	--
	-- A NEW NAME ON THIS LIST IS A DECISION rather than an oversight, which is
	-- the whole point of writing them down. Anything else appearing here fails
	-- this and somebody has to say which of the two it is.
	do
		-- The reference layout (rows) places what the Lattice board places. The
		-- rest it leaves on their own defaults, on purpose (Joe, 2026-10-08):
		local UNNAMED = {
			-- The floating tracker is gone (the World trunk took it); the name
			-- stays known so old strings load, and places nothing.
			quests = true,
			-- Not on the board. Its own default is the bottom right corner.
			tooltip = true,
			-- The music deck: not on the board either.
			ifec = true,
		}

		local named = {}
		for _, key in ipairs(A.Presets.order) do
			for name in pairs(A.Presets.list[key].decoded.records) do
				named[name] = true
			end
		end

		local surprises = {}
		for name in pairs(A.Movers.registry) do
			if not named[name] and not UNNAMED[name] then
				surprises[#surprises + 1] = name
			end
		end
		table.sort(surprises)
		check(#surprises == 0,
			"every mover is either named by an arrangement or written down as one "
			.. "that is not (" .. (#surprises > 0 and
			table.concat(surprises, ", ") or "no surprises") .. ")")

		-- AND THE STANCE BAR'S OWN DEFAULT IS THE COMPUTED ONE. The reference
		-- layout places it, but a pasted string that does not name it puts it
		-- back on this default - which was once on top of the chat window.
		local stance
		for _, bar in ipairs(A:GetModule("actionbars").bars or {}) do
			if bar.id == "stance" then stance = bar end
		end
		local entry = A.Movers.registry.barstance
		check(stance ~= nil and stance.cfg.beside == "1"
			and entry and entry.default and entry.default.point == "BOTTOM",
			"the stance bar parks beside bar 1 rather than in the chat's corner ("
			.. tostring(entry and entry.default and entry.default.point) .. ")")
	end

	local P = A.Presets
	check(P ~= nil, "the presets loaded")

	-- PUT BACK AFTERWARDS. Applying an arrangement writes the profile scale
	-- and every anchor in it, and the checks after this one are laid out
	-- against the scale the suite started at.
	local wasScale = A.db.profile.scale
	-- THE DESIGN'S WAY (Joe, 2026-10-08): the reference layout, which is the
	-- Rows seed, and none of 1.x's three. Block and Split join it as seeds, in
	-- the brief's order (9c).
	check(#P.order == 3 and P.order[1] == "rows" and P.order[2] == "block"
		and P.order[3] == "split" and P.list.rows ~= nil and P.list.block ~= nil
		and P.list.split ~= nil,
		"the reference layout comes first, then the Block and Split seeds (" ..
		table.concat(P.order, ", ") .. ")")
	check(P.list.corner == nil and P.list.centre == nil and P.list.bottom == nil,
		"and 1.x's corner, centre and bottom are gone")

	-- AND EVERY ONE OF THEM HAS COORDINATES IN IT.
	--
	-- These three shipped as empty tables for two builds while the layouts were
	-- being made by eye in the game, and an empty preset APPLIES CLEANLY: it
	-- wipes the anchors, moves nothing, and reads back as the arrangement you
	-- just chose. A first-run tour offering three cards that all do nothing is
	-- the worst possible version of this feature and it looks like it works.
	local anchors = A.db.profile.anchors
	for _, key in ipairs(P.order) do
		local preset = P.list[key]
		local named = 0
		for _ in pairs(preset and preset.decoded and preset.decoded.records or {}) do
			named = named + 1
		end
		check(named > 6,
			"\"" .. key .. "\" is a real arrangement rather than an empty table ("
			.. named .. " frames)")
		-- AND NO SCALE. The HUD scale is the player's - the monitor's
		-- arithmetic or their own slider (54d8cab) - and the first strings
		-- carried 0.71 and set it on everyone, which on a 1690-tall screen drew
		-- the whole HUD half as big again (Joe, 2026-10-08).
		check(preset.layout:find("s=", 1, true) == nil and preset.scale == nil,
			"and no scale in it, because the scale is the player's")
	end

	-- NO NAME IN THEM THAT IS NOT A FRAME. These tables are pasted in by hand
	-- from a capture, and a mistyped key is not an error - it is an entry that
	-- silently moves nothing. Bars past the first are exempt: they register
	-- only when they are switched on, and this profile has one.
	for _, key in ipairs(P.order) do
		local bad = {}
		for name in pairs(P.list[key].decoded.records) do
			if not A.Movers.registry[name] and not tostring(name):find("^bar%d$") then
				bad[#bad + 1] = name
			end
		end
		table.sort(bad)
		check(#bad == 0,
			"every frame \"" .. key .. "\" names is one this addon can move (" ..
			(#bad > 0 and table.concat(bad, ", ") or "all of them") .. ")")
	end

	-- AND NO TWO OF THEM ARE THE SAME LAYOUT. Three cards on the tour that
	-- differ only in their wording is a choice that is not one.
	for i = 1, #P.order do
		for j = i + 1, #P.order do
			local a, b = P.order[i], P.order[j]
			check(P.list[a].layout ~= P.list[b].layout,
				"\"" .. a .. "\" and \"" .. b .. "\" are different arrangements")
		end
	end

	-- A probe arrangement, as a string, through the same decode the shipped
	-- ones take.
	local function probe(key, text)
		local decoded, err = A.Layout:Decode(text)
		check(decoded ~= nil, "the probe \"" .. key .. "\" decodes (" .. tostring(err) .. ")")
		P.order[#P.order + 1] = key
		P.list[key] = { label = key, blurb = "", layout = text, decoded = decoded,
			scale = decoded and decoded.scale }
	end

	-- NOTHING CHOSEN YET reads as nothing chosen. Every shipped arrangement now
	-- has coordinates, so an untouched profile is none of them - and a tour
	-- that ticked one anyway would be telling a new player they had already
	-- picked.
	wipe(anchors)
	check(P:Current() == nil,
		"an untouched profile is none of them (" .. tostring(P:Current()) .. ")")

	-- APPLYING ONE WRITES IT AND TELLS THE FRAMES TO LOOK AGAIN. The movers put
	-- a frame back from the store on demand rather than watching it, so writing
	-- the table is only half of the job.
	local moved = 0
	local realRestore = A.Movers.RestoreAll
	A.Movers.RestoreAll = function(self)
		moved = moved + 1
		return realRestore(self)
	end

	-- EACH ONE, there and back. Reading the arrangement off the anchors rather
	-- than off a note somebody wrote down is the whole point: a stored answer
	-- goes stale the first time a frame is dragged.
	for _, key in ipairs(P.order) do
		-- A scale no arrangement would pick, so one that set its own shows.
		A.db.profile.scale = 0.45
		check(P:Apply(key), "\"" .. key .. "\" applies")
		check(P:Current() == key,
			"and reads back as itself off the anchors (" ..
			tostring(P:Current()) .. ")")
		check(A.db.profile.scale == 0.45,
			"and leaves the player's scale as it was (" .. tostring(A.db.profile.scale) .. ")")
	end
	A.db.profile.scale = wasScale
	check(moved == #P.order,
		"and every frame is told to look again each time (" .. moved .. ")")

	-- WIPED, NOT MERGED. What the last arrangement moved and this one does not
	-- mention is two layouts at once and belongs to neither.
	anchors.tooltip = { point = "TOPRIGHT", relPoint = "TOPRIGHT", x = -9, y = -9 }
	P:Apply("rows")
	check(anchors.tooltip == nil,
		"applying a preset takes away what the last one moved and this one does "
		.. "not mention")

	-- EXCEPT THE LOCK BUTTON, which is not a position in an arrangement at all.
	-- It is the button that hides the handles, parked wherever the player last
	-- shoved it out of the way; Movers keeps its spot in this same table under
	-- __lockButton precisely because it is NOT a mover entry. Wiping it puts
	-- that button back in the middle of the screen every time somebody tries a
	-- preset on.
	anchors.__lockButton = { point = "CENTER", relPoint = "CENTER", x = 2, y = 164 }
	P:Apply("rows")
	check(anchors.__lockButton ~= nil and anchors.__lockButton.y == 164,
		"where the player parked the lock button survives a preset being applied "
		.. "over it")

	-- AND IT IS NEVER CAPTURED. Shipping it would send one player's idea of
	-- where that button goes to everybody - and would stop Current() 
	-- recognising its own arrangement the moment somebody dragged it.
	local text, count = P:Capture()
	check(text:find("__lockButton", 1, true) == nil,
		"and never goes into a capture")

	-- A LAYOUT CAN BE CAPTURED BACK OUT, which is how these three were made: by
	-- eye, in the game, at a real resolution. Guessing coordinates in a text
	-- editor gives a layout that is plausible in every dimension and right in
	-- none.
	check(type(text) == "string" and text:match("^LAT%d+;") ~= nil,
		"a capture comes back as the bare layout string, ready to paste (" ..
		tostring(type(text)) .. ")")
	check(count > 6 and text:find(";player=", 1, true) ~= nil,
		"naming every frame in it (" .. tostring(count) .. ")")
	check(not text:find("%s"),
		"and holds no whitespace at all - a tab is not reliably carried through"
		.. " a chat frame and out through the clipboard, and this text exists to"
		.. " be pasted")
	check(text:find("s=", 1, true) == nil,
		"with no scale in it, because the scale is the player's, not the arrangement's")

	-- SORTED, so two captures of the same layout are the same text and a diff
	-- shows the line that really changed.
	local order = {}
	for name in text:gmatch(";([%w_]+)=[%w_]+,[A-Z]+,") do order[#order + 1] = name end
	local sorted = true
	for i = 2, #order do
		if order[i] < order[i - 1] then sorted = false end
	end
	check(#order > 1 and sorted,
		"and in a fixed order rather than whatever pairs() felt like (" ..
		#order .. " frames)")

	-- EVERY NODE HANGS FROM ITS PARENT, AND THE TOP OF EACH TREE FROM THE
	-- SCREEN, IN UNITS (Joe, 2026-10-08). Not fractions of the screen.
	--
	-- The first version put a screen node at a fraction of the screen and its
	-- children in units. On a narrower screen the player slid in towards the
	-- centre by its fraction while the target, bonded to it, stayed the same
	-- units to its right - so a centred block went lopsided, and further the
	-- narrower the screen. In units the block is rigid; its anchor is what ties
	-- it to the screen's centre, or an edge to its edge.
	do
		-- A SYMMETRIC block, worked out from the frames' own widths: the player
		-- left of centre and the target bonded to it, the same distance right.
		local UFm = A:GetModule("unitframes")
		local pw, tw = UFm.player:GetWidth(), UFm.target:GetWidth()
		local GAP = 300
		local px = -(GAP / 2 + pw / 2)
		-- Bars 1 and 2, as the last preset applied left them, so the probe
		-- moves no bar the checks after this block depend on.
		probe("__probe", ("LAT1;b=1,2;player=screen,CENTER,CENTER,%d,0;"
			.. "target=player,LEFT,RIGHT,%d,0;chat=screen,BOTTOMLEFT,BOTTOMLEFT,16,54"):format(
			math.floor(px + 0.5), GAP))

		local wasW, wasH = UIParent:GetWidth(), UIParent:GetHeight()
		local function at(width, height)
			UIParent:SetSize(width, height)
			P:Apply("__probe")
			local where = A.Layout:Resolve(P.list.__probe.decoded)
			return where.player, where.target
		end

		-- 3840x1600 and 1920x1080, in the units the client draws in at the
		-- default scale: the same height, 2.4 and 1.78 times as wide.
		local wideP, wideT = at(1843, 768)
		local narrowP, narrowT = at(1365, 768)

		check(wideP and narrowP and wideP.x == narrowP.x and wideT.x == narrowT.x,
			"the main block sits the same units from the centre on an ultrawide and"
			.. " on 16:9 - a fraction of the screen would have slid the player in and"
			.. " left the target where its bond put it (" .. string.format(
			"player %.0f then %.0f, target %.0f then %.0f", wideP and wideP.x or 0,
			narrowP and narrowP.x or 0, wideT and wideT.x or 0, narrowT and narrowT.x or 0) .. ")")
		check(narrowP and narrowT and math.abs(narrowP.x + narrowT.x) <= 1
			and math.abs(narrowP.x) > 0,
			"and stays centred: player and target the same distance either side of"
			.. " the middle (" .. string.format("%.0f, %.0f",
			narrowP and narrowP.x or 0, narrowT and narrowT.x or 0) .. ")")
		-- In HUD units, as the string has it, and to the glass a player sees.
		local gx, gy = _G.__chatGlass()
		check(gx and math.abs(gx - 16) <= 1 and math.abs(gy - 54) <= 1,
			"a node on an edge stays the same units in from that edge, whatever"
			.. " the screen (" .. tostring(gx) .. ", " .. tostring(gy) .. ")")
		check(P:Current() == "__probe",
			"and it is still recognised as the arrangement on screen (" ..
			tostring(P:Current()) .. ")")

		-- A CAPTURE IS IN THE SAME FORM: every record names its parent.
		local text, _, screen = P:Capture()
		check(text:find("player=screen,CENTER,CENTER,", 1, true) ~= nil
			and text:find("target=player,LEFT,RIGHT,300,0", 1, true) ~= nil,
			"a capture names each node's parent, the screen at the top")
		check(not text:find("=S,", 1, true) and not text:find("=B,", 1, true),
			"and holds no canvas position")
		check(type(screen) == "string" and screen:match("^%d+ x %d+$") ~= nil,
			"saying what size screen it was made on, because a block laid out across"
			.. " an ultrawide is wider than a 16:9 screen however it is anchored ("
			.. tostring(screen) .. ")")

		UIParent:SetSize(wasW, wasH)
		P.list.__probe = nil
		P.order[#P.order] = nil
	end

	-- AND A PRESET OWNS THE ACTION BARS, on and off both.
	--
	-- An arrangement that places bar 5 on a profile where bar 5 is switched off
	-- places nothing, and a layout designed around six bars has a hole in it
	-- with two. So a preset records which of the six numbered bars are on and
	-- sets them exactly - a bar it does not use is switched OFF, because
	-- leaving one on where the last arrangement put it is two layouts at once.
	do
		local AB = A:GetModule("actionbars")
		local was = {}
		for _, id in ipairs({ "1", "2", "3", "4", "5", "6" }) do
			was[id] = AB:BarConfig(id).enabled
		end

		probe("__bars", "LAT1;b=1,2,5;player=screen,CENTER,CENTER,0,0")

		-- Switched the other way round to start with, so both directions are
		-- actually exercised rather than one of them happening to be right.
		AB:SetBarEnabled("1", false)
		AB:SetBarEnabled("5", false)
		AB:SetBarEnabled("3", true)

		P:Apply("__bars")
		check(AB:BarConfig("1").enabled and AB:BarConfig("5").enabled,
			"applying an arrangement switches on the bars it uses")
		check(not AB:BarConfig("3").enabled,
			"and switches OFF the ones it does not - a bar left on where the last "
			.. "arrangement put it is two layouts at once")

		-- AND IT IS PART OF THE QUESTION "which arrangement is this". One that
		-- answered "yes, this is the one you have" with three of its bars missing
		-- would be telling the player something plainly untrue.
		check(P:Current() == "__bars",
			"the arrangement reads back as itself with its bars set (" ..
			tostring(P:Current()) .. ")")
		AB:SetBarEnabled("6", true)
		check(P:Current() ~= "__bars",
			"and stops being itself the moment a bar it does not want is switched "
			.. "on (" .. tostring(P:Current()) .. ")")

		-- REBUILT ONCE, not once per bar. SetBarEnabled is the per-bar door and
		-- calls OnConfigChanged itself, so six of them is six teardowns of every
		-- button on the screen for one click.
		local rebuilds = 0
		local realChanged = AB.OnConfigChanged
		AB.OnConfigChanged = function(self)
			rebuilds = rebuilds + 1
			return realChanged(self)
		end
		-- Three bars away from the preset, then one. If the dock were torn
		-- down per bar the first would cost three times the second; the same
		-- number both ways is the whole claim. Counted rather than asserted
		-- as a fixed figure, because Reconfigure rebuilds at the end of an
		-- Apply too and that is not the thing being measured.
		AB:SetBarEnabled("1", false)
		AB:SetBarEnabled("5", false)
		AB:SetBarEnabled("3", true)
		rebuilds = 0
		P:Apply("__bars")
		local three = rebuilds

		AB:SetBarEnabled("3", true)
		rebuilds = 0
		P:Apply("__bars")
		local one = rebuilds
		AB.OnConfigChanged = realChanged
		check(three == one,
			"and three bars changing costs the same rebuild as one - the dock is "
			.. "not torn down once per bar (" .. three .. ", " .. one .. ")")

		-- THE SIX NUMBERED BARS AND NOTHING ELSE. Stance, pet, taxi and the extra
		-- action button are not layout choices - the game gives you one or it does
		-- not, by class and by circumstance - and a preset captured by a mage that
		-- switched off a druid's stance bar would be reaching well past where
		-- things go.
		local stance = AB:BarConfig("stance")
		if stance then
			stance.enabled = true
			check(A.Layout:Decode("LAT1;b=1,stance") == nil,
				"a layout cannot even name the stance bar in its bars")
			P:Apply("__bars")
			check(stance.enabled, "and applying one leaves the stance bar alone")
		end

		-- AND A CAPTURE RECORDS THEM, which is what makes the next arrangement
		-- reproducible at all: the ones on, and by leaving them out, the ones off.
		local text = P:Capture()
		check(text:find(";b=1,2,5;", 1, true) ~= nil,
			"a capture writes which bars are on, and every one it leaves out is off"
			.. " when it is applied")

		for _, id in ipairs({ "1", "2", "3", "4", "5", "6" }) do
			AB:SetBarEnabled(id, was[id])
		end
		P.list.__bars = nil
		P.order[#P.order] = nil
	end

	A.Movers.RestoreAll = realRestore
	wipe(anchors)
	A.db.profile.scale = wasScale
	A:Reconfigure()
end
-- CENTRE OR CENTER (Joe, 2026-10-08): the same word to whoever types it.
-- Through the real slash command, which is where a player meets the name.
print("== presets: either spelling of centre ==")
do
	local P = A.Presets
	local wasScale = A.db.profile.scale
	-- A key with the word in it, whatever C2 calls the shipped ones.
	P.list.__centreProbe = P.list.centre or P.list[P.order[1]]
	local slash = SlashCmdList["AETHERUI"]

	check(P:Find("__CENTERprobe") == "__centreProbe"
		and P:Find("__centreprobe") == "__centreProbe",
		"either spelling of centre finds the same preset, in any case")
	check(P:Find("__nowhere") == nil and P:Find("") == nil and P:Find(nil) == nil,
		"and a name that is not a preset finds nothing")

	wipe(A.db.profile.anchors)
	slash("preset __CenterProbe")
	check(A.Layout:Matches(P.list.__centreProbe.decoded),
		"/lattice preset with the American spelling and odd capitals applies it")

	P.list.__centreProbe = nil
	wipe(A.db.profile.anchors)
	for _, e in pairs(A.Movers.registry) do e.parent, e.free = e.defaultParent, nil end
	A.db.profile.scale = wasScale
	A:Reconfigure()
	A.Movers:RestoreAll()
end

-- THE REFERENCE LAYOUT LANDS WHERE THE BOARD PUTS IT (Joe, 2026-10-08: go the
-- design's way). Lattice handoff 3a with 6a's minimap and tracker, at the
-- board's own 1920 x 1080, read back in the board's pixels: from the screen's
-- top left, through UIParent's own edges.
print("== presets: the reference layout, against the board ==")
do
	local P, M, UFm = A.Presets, A.Movers, A:GetModule("unitframes")
	local wasScale = A.db.profile.scale
	local wasW, wasH = UIParent:GetWidth(), UIParent:GetHeight()
	UIParent:SetSize(768 * 1920 / 1080, 768)
	local ABc, UFc = A.Config:Module("actionbars"), A.Config:Module("unitframes")
	local was = { size = ABc.size, spacing = ABc.spacing, padding = ABc.padding,
		scale = ABc.scale, petScale = UFc.petScale, totScale = UFc.totScale }

	-- TWICE: at the settings the addon ships, and at settings a player might
	-- have - the bars' base size at 62, as an earlier block in this suite leaves
	-- it, the bars module at 0.8, the pet bigger and the ToT smaller. The string
	-- carries none of those, so it has to land on the board through all of
	-- them. It did not: its offsets were in each node's own units, and at a
	-- base size of 62 bar 1 sat 42 px closer to the spine.
	-- A frame's edges in the board's pixels, from the screen's top left -
	-- through UIParent's own edges, since the mock's screen has an origin.
	local function rect(f)
		if not (f and f:GetLeft()) then return nil end
		local k = 1080 / UIParent:GetHeight()
		local UL, UT = UIParent:GetLeft(), UIParent:GetTop()
		local fs = f:GetEffectiveScale() / UIParent:GetEffectiveScale()
		return { l = (f:GetLeft() * fs - UL) * k, r = (f:GetRight() * fs - UL) * k,
			t = (UT - f:GetTop() * fs) * k, b = (UT - f:GetBottom() * fs) * k }
	end
	local function frame(name) return M.registry[name] and M.registry[name].frame end
	local function near(a, b) return a and b and math.abs(a - b) <= 2 end
	local function cx(r) return r and (r.l + r.r) / 2 end
	local function cy(r) return r and (r.t + r.b) / 2 end
	local function say(...)
		local out = {}
		for i = 1, select("#", ...) do
			local v = select(i, ...)
			out[#out + 1] = type(v) == "number" and ("%.1f"):format(v) or tostring(v)
		end
		return " (" .. table.concat(out, ", ") .. ")"
	end
	-- The frames every arrangement places, plus `bars`, in board pixels.
	local function Measure(bars)
		local R = {}
		for _, n in ipairs({ "player", "target", "targettarget", "pet", "party",
			"bar1", "barpet", "barstance", "barextra", "minimap" }) do
			R[n] = rect(frame(n))
		end
		for _, n in ipairs(bars) do R[n] = rect(frame(n)) end
		R.spine = rect(UFm.spine)
		-- THE CHAT IS ITS GLASS: the panel and the edit box hang off
		-- ChatFrame1, and measuring the frame let a chat whose edit box was off
		-- the bottom of the screen pass (Joe, 2026-10-08).
		local _, _, ge = _G.__chatGlass()
		if ge then
			local k = 1080 / UIParent:GetHeight()
			local UL, UT = UIParent:GetLeft(), UIParent:GetTop()
			R.chat = { l = (ge.l - UL) * k, r = (ge.r - UL) * k,
				t = (UT - ge.t) * k, b = (UT - ge.b) * k }
		end
		return R
	end
	-- Every pair of measured frames that overlaps by more than a pixel.
	local function Overlaps(R)
		local names = {}
		for n in pairs(R) do if n ~= "spine" then names[#names + 1] = n end end
		table.sort(names)
		local hits = {}
		for i = 1, #names do
			for j = i + 1, #names do
				local a, b = R[names[i]], R[names[j]]
				if a and b and a.l < b.r - 1 and b.l < a.r - 1 and a.t < b.b - 1 and b.t < a.b - 1 then
					hits[#hits + 1] = names[i] .. "/" .. names[j]
				end
			end
		end
		return hits
	end

	local function Board(tag, s)
		local check = function(ok, msg) return check(ok, "[" .. tag .. "] " .. msg) end
		ABc.size, ABc.spacing, ABc.padding, ABc.scale = s.size, 8, 6, s.bars
		UFc.petScale, UFc.totScale = s.pet, s.tot
		-- The player's own scale, fitted to this screen: what makes a HUD unit
		-- a pixel. The layout does not set it, and must not.
		A.db.profile.scale = 768 / 1080
		A:Reconfigure()
		check(P.list.rows ~= nil and P:Apply("rows"), "the reference layout applies")
		check(A.db.profile.scale == 768 / 1080, "and leaves the player's scale alone")
		if UFm.MeasureSpine then UFm:MeasureSpine() end

		local R = Measure({ "bar2" })

		check(near(cx(R.spine), 960) and near(cy(R.spine), 870),
			"the spine runs on the screen's centre line at y 870" .. say(cx(R.spine), cy(R.spine)))
		check(R.player and R.target and near(R.target.l - R.player.r, 216),
			"the bond is 216 long" .. say(R.target and R.player and R.target.l - R.player.r))
		for _, b in ipairs({ { "bar1", "1", 968, 44 }, { "bar2", "2", 1032, 34 } }) do
			local r = R[b[1]]
			local _, rows, px = A.Layout.BarShape(b[2])
			check(r and near(cx(r), 960) and near(r.t, b[3]) and rows == 1 and px == b[4],
				b[1] .. " is a 12 x 1 row of " .. b[4] .. " px hung from the spine's middle,"
				.. " its top at y " .. b[3] .. say(cx(r), r and r.t, rows, px))
		end
		check(R.targettarget and near(R.targettarget.r, R.target.r) and near(R.targettarget.t, 760),
			"the ToT sits over the target's right edge at y 760"
			.. say(R.targettarget and R.targettarget.r, R.target and R.target.r,
			R.targettarget and R.targettarget.t))
		check(R.pet and near(R.pet.l, R.player.l) and near(R.pet.t, 760),
			"the pet takes the focus slot over the player, mirroring the ToT"
			.. say(R.pet and R.pet.l, R.player and R.player.l, R.pet and R.pet.t))
		check(R.party and near(R.party.l, 60) and near(R.party.t, 420),
			"the party column starts at 60, 420" .. say(R.party and R.party.l, R.party and R.party.t))
		check(R.chat and near(R.chat.l, 24) and near(R.chat.b, 1080 - 24),
			"the chat's glass sits 24 in from the bottom left, all of it on the screen"
			.. say(R.chat and R.chat.l, R.chat and R.chat.b))
		-- AND THE GLASS IS WHAT THE PANEL DOES: Insets() against the panel's
		-- own anchors, so a change to one cannot leave the other measuring air.
		do
			local CM = A:GetModule("chat")
			local l, b, r = CM:Insets()
			local tl, br
			for i = 1, (CM.panel:GetNumPoints() or 0) do
				local pt, rel, _, x, y = CM.panel:GetPoint(i)
				if pt == "TOPLEFT" then tl = { rel = rel, x = x } end
				if pt == "BOTTOMRIGHT" then br = { rel = rel, x = x, y = y } end
			end
			check(tl and br and br.rel == _G.ChatFrame1 and br.x == r and br.y == -b
				and tl.x == -l,
				"and the glass measured is the panel's own anchoring: " .. l .. " either side, "
				.. b .. " below" .. say(tl and tl.x, br and br.x, br and br.y))
		end
		-- 6a's minimap: the disc centred 110 in from the right and 230 down,
		-- with the World trunk under its pill and every node on the screen.
		check(R.minimap and near(cx(R.minimap), 1810) and near(cy(R.minimap), 230),
			"the minimap's centre is at 1810, 230 (6a)" .. say(cx(R.minimap), cy(R.minimap)))
		do
			local t = A.Trunk:Get("world")
			local low = rect(t.frame)
			check(low and low.b <= 1080 - 24 and t.frame:IsShown(),
				"and the World trunk hangs under it, its end above the floor" .. say(low and low.b))
		end
		local CF = frame("chat")
		check(CF and math.abs(CF:GetWidth() - 210) < 1 and math.abs(CF:GetHeight() - 120) < 1,
			"at 210 x 120 of its own units, whatever size the window was - the size"
			.. " travels with the layout" .. say(CF and CF:GetWidth(), CF and CF:GetHeight()))
		-- ACTIONS ARE BONDED TO ACTIONS (Joe, 2026-10-07, held over the strands
		-- brief, which hangs stance off the player and the pet bar off the pet):
		-- all three hang from bar 1.
		for _, n in ipairs({ "barstance", "barpet", "barextra" }) do
			check(M:ParentOf(n) == "bar1", n .. " hangs from bar 1" .. say(M:ParentOf(n)))
		end
		-- From bar 1's EDGES, not its centre: at the bars module's 0.8 bar 1
		-- is 478 wide rather than 650, and hung from its centre they stood 93
		-- off its ends.
		check(R.barstance and near(R.bar1.l - R.barstance.r, 8)
			and near(cy(R.barstance), cy(R.bar1)),
			"the stance bar is a row 8 off bar 1's left end, whatever its width"
			.. say(R.barstance and R.barstance.r, R.bar1 and R.bar1.l))
		check(R.barpet and near(R.barpet.l - R.bar1.r, 8)
			and near(cy(R.barpet), cy(R.bar1)),
			"the pet bar is a row off bar 1's right end"
			.. say(R.barpet and R.barpet.l, R.bar1 and R.bar1.r))
		check(R.barextra and near(R.barextra.r, R.barstance.r) and R.barextra.b <= R.barstance.t
			and R.barextra.t > R.player.b,
			"and the extra button sits over the stance row's right end, under the player"
			.. say(R.barextra and R.barextra.r, R.barextra and R.barextra.t, R.barextra and R.barextra.b))

		-- AND NOTHING SITS ON ANYTHING ELSE. The pet and stance bars once had
		-- only their coded defaults here, measured beside a 36 px bar 1, and
		-- both landed on this layout's 44 px one.
		local hits = Overlaps(R)
		check(#hits == 0, "and no two frames overlap" .. say(#hits > 0 and table.concat(hits, " ") or "none"))
	end

	Board("shipped settings", { size = 36, bars = 1, pet = 0.85, tot = 0.85 })
	Board("a player's settings", { size = 62, bars = 0.8, pet = 1.0, tot = 0.7 })

	-- AN OLD STRING NAMING THE FLOATING TRACKER STILL APPLIES (World trunk step
	-- 5): `quests` is still a known name, and places nothing.
	do
		local old = A.Layout:Decode(P.list.rows.layout .. ";quests=screen,TOPRIGHT,TOPRIGHT,-24,-300")
		check(old and old.records.quests and A.Layout:Apply(old),
			"a layout string from before the trunk, naming quests, still applies")
		check(P:Apply("rows"), "and the reference layout goes back on")
	end

	-- THE STANCE BAR IS ONE ROW FOR EVERY CLASS. It is written 12 x 1, which on
	-- a druid's forms is a row of however many there are - and the layout is
	-- still the one on screen.
	check(P:Current() == "rows", "and it reads back as itself" .. say(P:Current()))
	local wasForms = #_G.__forms
	for i = wasForms + 1, 4 do
		_G.__forms[i] = { texture = "Icons\\Form" .. i, active = false, castable = true }
	end
	fire("UPDATE_SHAPESHIFT_FORMS")
	local cols, rows = A.Layout.BarShape("stance")
	check(cols >= 4 and rows == 1, "four forms stand in one row" .. say(cols, rows))
	check(P:Current() == "rows",
		"and the layout still reads back as itself, whatever the class has"
		.. say(P:Current()))

	-- AND A SHAPE WRITTEN LONGER THAN THE BAR IS FITTED TO IT. A column written
	-- 1 x 12 is a column of four on four forms. Matches compared the written 12
	-- with the 4 drawn, so it said otherwise the moment it was applied.
	local column = A.Layout:Decode((P.list.rows.layout:gsub(
		"(barstance=[^;]*),12x1,30", "%1,1x12,30")))
	check(column and column.records.barstance.rows == 12 and A.Layout:Apply(column),
		"a stance bar written as a column of 12 applies")
	cols, rows = A.Layout.BarShape("stance")
	check(cols == 1 and rows >= 4, "and four forms stand in one column" .. say(cols, rows))
	check(column and A.Layout:Matches(column),
		"and it reads back as itself though the bar has 4, not 12")
	for i = #_G.__forms, wasForms + 1, -1 do _G.__forms[i] = nil end
	fire("UPDATE_SHAPESHIFT_FORMS")

	-- THE SPLIT SEED (strands brief 9c; Joe, 2026-10-08): bar 1 as in rows,
	-- bars 2 and 3 as 28 px columns 18 off the player's left and the target's
	-- right, centred on them (34 px ran off the screen). Stance and pet move
	-- under bar 1, because off its ends they ran into the columns, and the
	-- party moves up to clear bar 2's. Measured with a druid's six forms and
	-- the whole pet bar, the widest each gets.
	for i = wasForms + 1, 6 do
		_G.__forms[i] = { texture = "Icons\\Form" .. i, active = false, castable = true }
	end
	fire("UPDATE_SHAPESHIFT_FORMS")
	local function Split(tag, s)
		local check = function(ok, msg) return check(ok, "[split, " .. tag .. "] " .. msg) end
		ABc.size, ABc.spacing, ABc.padding, ABc.scale = s.size, 8, 6, s.bars
		UFc.petScale, UFc.totScale = s.pet, s.tot
		A.db.profile.scale = 768 / 1080
		A:Reconfigure()
		check(P:Apply("split"), "the Split seed applies")
		check(A.db.profile.scale == 768 / 1080, "and leaves the player's scale alone")
		if UFm.MeasureSpine then UFm:MeasureSpine() end
		local R = Measure({ "bar2", "bar3" })

		local _, rows1, px1 = A.Layout.BarShape("1")
		check(R.bar1 and near(cx(R.bar1), 960) and near(R.bar1.t, 968) and rows1 == 1 and px1 == 44,
			"bar 1 is the same 12 x 1 row of 44 as in rows" .. say(cx(R.bar1), R.bar1 and R.bar1.t, rows1, px1))
		for _, b in ipairs({ { "bar2", "2", "player", "left" }, { "bar3", "3", "target", "right" } }) do
			local r, u = R[b[1]], R[b[3]]
			local cols, rows, px = A.Layout.BarShape(b[2])
			local gap = r and u and (b[4] == "left" and u.l - r.r or r.l - u.r)
			check(r and cols == 1 and rows == 12 and px == 28,
				b[1] .. " is a 1 x 12 column of 28 px" .. say(cols, rows, px))
			check(M:ParentOf(b[1]) == b[3] and near(gap, 18) and near(cy(r), cy(u)),
				"hung 18 off the " .. b[3] .. "'s " .. b[4] .. " edge, centred on it"
				.. say(M:ParentOf(b[1]), gap, cy(r), cy(u)))
		end
		local scols, srows = A.Layout.BarShape("stance")
		check(R.barstance and near(R.barstance.t - R.bar1.b, 8) and near(R.barstance.l, R.bar1.l)
			and scols == 6 and srows == 1,
			"six forms stand in a row 8 under bar 1's left end"
			.. say(R.barstance and R.barstance.t - R.bar1.b, R.barstance and R.barstance.l, R.bar1.l, scols))
		local pcols = A.Layout.BarShape("pet")
		check(R.barpet and near(R.barpet.t - R.bar1.b, 8) and near(R.barpet.r, R.bar1.r) and pcols == 10,
			"the whole pet bar is a row 8 under bar 1's right end"
			.. say(R.barpet and R.barpet.t - R.bar1.b, R.barpet and R.barpet.r, R.bar1.r, pcols))
		for _, n in ipairs({ "barstance", "barpet", "barextra" }) do
			check(M:ParentOf(n) == "bar1", n .. " still hangs from bar 1" .. say(M:ParentOf(n)))
		end

		local off = {}
		for n, r in pairs(R) do
			if n ~= "spine" and (r.l < -1 or r.t < -1 or r.r > 1921 or r.b > 1081) then
				off[#off + 1] = n .. " " .. ("%.0f,%.0f-%.0f,%.0f"):format(r.l, r.t, r.r, r.b)
			end
		end
		table.sort(off)
		check(#off == 0, "everything is on a 1080 screen" .. say(#off > 0 and table.concat(off, " ") or "all"))
		local hits = Overlaps(R)
		check(#hits == 0, "and no two frames overlap" .. say(#hits > 0 and table.concat(hits, " ") or "none"))
		check(R.party and near(R.party.l, 60) and near(R.party.t, 300) and R.party.b < R.bar2.t,
			"the party starts at 60, 300, clear above bar 2's column"
			.. say(R.party and R.party.t, R.party and R.party.b, R.bar2 and R.bar2.t))
		check(P:Current() == "split", "and it reads back as itself" .. say(P:Current()))
	end
	Split("shipped settings", { size = 36, bars = 1, pet = 0.85, tot = 0.85 })
	Split("a player's settings", { size = 62, bars = 0.8, pet = 1.0, tot = 0.7 })

	-- THE BLOCK SEED (strands brief 9a and 9c): bars 1 and 2 as 3 x 4 of 44,
	-- braided side by side into one 6 x 4 block centred under the spine, key
	-- chips on. From board 9a: the spine raised to y 810 to make room, the
	-- block's top at 852. Stance off bar 1's left end, the pet bar off bar 2's
	-- right, the extra button over the stance row.
	local function Block(tag, s)
		local check = function(ok, msg) return check(ok, "[block, " .. tag .. "] " .. msg) end
		ABc.size, ABc.spacing, ABc.padding, ABc.scale = s.size, 8, 6, s.bars
		UFc.petScale, UFc.totScale = s.pet, s.tot
		A.db.profile.scale = 768 / 1080
		A:Reconfigure()
		check(P:Apply("block"), "the Block seed applies")		check(A.db.profile.scale == 768 / 1080, "and leaves the player's scale alone")
		if UFm.MeasureSpine then UFm:MeasureSpine() end
		local R = Measure({ "bar2" })

		check(near(cx(R.spine), 960) and near(cy(R.spine), 810),
			"the spine is raised to y 810, on the centre line" .. say(cx(R.spine), cy(R.spine)))
		for _, id in ipairs({ "1", "2" }) do
			local cols, rows, px = A.Layout.BarShape(id)
			check(cols == 3 and rows == 4 and px == 44,
				"bar " .. id .. " is a 3 x 4 of 44 px" .. say(cols, rows, px))
		end
		check(A.Braids:HostOf("bar2") == "bar1" and A.Braids:Root("bar2") == "bar1",
			"bar 2 is braided onto bar 1" .. say(A.Braids:HostOf("bar2")))
		local l, r = R.bar1 and R.bar1.l, R.bar2 and R.bar2.r
		check(l and r and near((l + r) / 2, 960) and near(R.bar1.t, 852) and near(R.bar2.t, 852)
			and R.bar2.l > R.bar1.l,
			"side by side into one block centred under the spine, its top at y 852"
			.. say(l and r and (l + r) / 2, R.bar1 and R.bar1.t, R.bar2 and R.bar2.t))
		-- One gap across the seam, the strands' own: their buttons line up.
		local AB = A:GetModule("actionbars")
		local function barOf(id)
			for _, b in ipairs(AB.bars) do if tostring(b.id) == id then return b end end
		end
		local s2, g1 = rect(barOf("1").buttons[2]), rect(barOf("1").buttons[3])
		local g2 = rect(barOf("2").buttons[1])
		local gap = s2 and g1 and g1.l - s2.r
		check(g1 and g2 and gap and near(g2.l - g1.r, gap) and near(g2.t, g1.t),
			"one gap across the seam, the strand's own, and the rows level"
			.. say(g1 and g2 and g2.l - g1.r, gap))
		check(AB:KeysShown("1") and AB:KeysShown("2"), "with key chips on for both")

		check(R.barstance and near(R.bar1.l - R.barstance.r, 8) and near(cy(R.barstance), cy(R.bar1)),
			"the stance bar is a row 8 off bar 1's left end"
			.. say(R.barstance and R.bar1.l - R.barstance.r))
		check(R.barpet and near(R.barpet.l - R.bar2.r, 8) and near(cy(R.barpet), cy(R.bar2))
			and M:ParentOf("barpet") == "bar2",
			"the pet bar is a row 8 off bar 2's right end, bonded to it"
			.. say(R.barpet and R.barpet.l - R.bar2.r, M:ParentOf("barpet")))
		check(R.barextra and near(R.barextra.r, R.barstance.r) and R.barextra.b <= R.barstance.t
			and R.barextra.t > R.player.b,
			"and the extra button sits over the stance row's right end, under the player"
			.. say(R.barextra and R.barextra.r, R.barextra and R.barextra.t, R.player and R.player.b))

		local off = {}
		for n, f in pairs(R) do
			if n ~= "spine" and (f.l < -1 or f.t < -1 or f.r > 1921 or f.b > 1081) then
				off[#off + 1] = n .. " " .. ("%.0f,%.0f-%.0f,%.0f"):format(f.l, f.t, f.r, f.b)
			end
		end
		table.sort(off)
		check(#off == 0, "everything is on a 1080 screen" .. say(#off > 0 and table.concat(off, " ") or "all"))
		-- The braid's two docks overlap at the seam by design; nothing else may.
		local hits = {}
		for _, h in ipairs(Overlaps(R)) do
			if h ~= "bar1/bar2" then hits[#hits + 1] = h end
		end
		check(#hits == 0, "and no two frames overlap" .. say(#hits > 0 and table.concat(hits, " ") or "none"))
		check(P:Current() == "block", "and it reads back as itself" .. say(P:Current()))
	end
	Block("shipped settings", { size = 36, bars = 1, pet = 0.85, tot = 0.85 })
	Block("a player's settings", { size = 62, bars = 0.8, pet = 1.0, tot = 0.7 })

	wipe(A.db.profile.anchors)
	SlashCmdList["AETHERUI"]("preset block")
	check(P:Current() == "block", "/lattice preset block applies it" .. say(P:Current()))

	wipe(A.db.profile.anchors)
	SlashCmdList["AETHERUI"]("preset split")
	check(P:Current() == "split", "/lattice preset split applies it" .. say(P:Current()))
	-- Back to the bars rows leaves on, as the blocks after this expect.
	P:Apply("rows")

	for i = #_G.__forms, wasForms + 1, -1 do _G.__forms[i] = nil end
	fire("UPDATE_SHAPESHIFT_FORMS")

	ABc.size, ABc.spacing, ABc.padding, ABc.scale = was.size, was.spacing, was.padding, was.scale
	UFc.petScale, UFc.totScale = was.petScale, was.totScale
	UIParent:SetSize(wasW, wasH)
	wipe(A.db.profile.anchors)
	for _, e in pairs(M.registry) do e.parent, e.free = e.defaultParent, nil end
	A.db.profile.scale = wasScale
	A:Reconfigure()
	M:RestoreAll()
end

-- BRAIDS (strands brief, Core/Braids.lua): strands fused edge to edge into
-- one block, with one pad, one gap and one button size.
print("== braids ==")
do
	local M, B, LY = A.Movers, A.Braids, A.Layout
	local AB = A:GetModule("actionbars")
	local ABc = A.Config:Module("actionbars")
	local T = {
		was = { size = ABc.size, spacing = ABc.spacing, padding = ABc.padding, scale = ABc.scale,
			w = UIParent:GetWidth(), h = UIParent:GetHeight(), ui = A.db.profile.scale },
		cfg = {}, on = {},
	}
	for _, id in ipairs({ "1", "2", "3" }) do
		local c = AB:BarConfig(id)
		T.cfg[id] = { rows = c.rows, cols = c.cols, wrap = c.wrap, size = c.size, scale = c.scale }
		T.on[id] = c.enabled
	end
	-- In UIParent units, at whatever scale the frame is drawn.
	function T.R(f)
		local s = f:GetEffectiveScale() / UIParent:GetEffectiveScale()
		return { l = f:GetLeft() * s, r = f:GetRight() * s, t = f:GetTop() * s, b = f:GetBottom() * s }
	end
	function T.near(a, b) return a and b and math.abs(a - b) <= 0.5 end
	function T.say(...)
		local out = {}
		for i = 1, select("#", ...) do
			local v = select(i, ...)
			out[#out + 1] = type(v) == "number" and ("%.2f"):format(v) or tostring(v)
		end
		return " (" .. table.concat(out, ", ") .. ")"
	end
	function T.bar(id)
		for _, bar in ipairs(AB.bars) do if bar.id == id then return bar end end
	end
	function T.btn(id, i) return T.R(T.bar(id).buttons[i]) end
	-- The gap the strand draws between its own buttons, in UIParent units.
	function T.gap(id)
		return ABc.spacing * T.bar(id).dock:GetEffectiveScale() / UIParent:GetEffectiveScale()
	end
	function T.fresh()
		wipe(A.db.profile.anchors)
		for _, e in pairs(M.registry) do e.parent, e.free = e.defaultParent, nil end
		A:Reconfigure()
	end

	UIParent:SetSize(1920, 1080)
	A.db.profile.scale = 1
	ABc.size, ABc.spacing, ABc.padding, ABc.scale = 36, 8, 6, 1
	local c1, c2, c3 = AB:BarConfig("1"), AB:BarConfig("2"), AB:BarConfig("3")
	-- Three 3 x 4 strands. Bar 2 has a size of its own, which a braid overrides.
	c1.rows, c2.rows, c3.rows = 4, 4, 4
	c1.cols, c2.cols, c3.cols = nil, nil, nil
	c1.wrap, c2.wrap, c3.wrap = "across", "across", "across"
	c1.size, c1.scale, c2.scale, c3.scale, c3.size = nil, 1, 1, 1, nil
	c2.size = 50
	c2.enabled, c3.enabled = true, true
	T.fresh()
	local k = T.gap("1") / 8
	check(math.abs(T.btn("2", 1).r - T.btn("2", 1).l - 50 * k) < 0.5,
		"bar 2 starts at its own 50" .. T.say(T.btn("2", 1).r - T.btn("2", 1).l))

	-- 1. Side by side: bar 2 onto bar 1's right edge.
	check(B:Join("bar2", "bar1", "RIGHT", 0), "bar 2 braids onto bar 1's right edge")
	check(B:HostOf("bar2") == "bar1" and M:ParentOf("bar2") == "bar1",
		"and hangs from bar 1" .. T.say(B:HostOf("bar2"), M:ParentOf("bar2")))
	local a, b = T.btn("1", 3), T.btn("2", 1)
	check(T.near(b.l - a.r, T.gap("1")) and T.near(a.t, b.t),
		"the gap across the seam is the strand's own, and the rows line up"
		.. T.say(b.l - a.r, T.gap("1"), a.t, b.t))
	check(T.near(b.r - b.l, a.r - a.l) and c2.size == 50,
		"bar 2 draws at bar 1's size, and keeps its own setting"
		.. T.say(b.r - b.l, a.r - a.l, c2.size))
	check(select(3, LY.BarShape("2")) == 36, "and its shape reads at that size"
		.. T.say(select(3, LY.BarShape("2"))))
	local pad, d1, d2 = B.pads.bar1, T.R(T.bar("1").dock), T.R(T.bar("2").dock)
	local p = pad and pad:IsShown() and T.R(pad)
	check(p and T.near(p.l, d1.l) and T.near(p.r, d2.r) and T.near(p.t, math.max(d1.t, d2.t))
		and T.near(p.b, math.min(d1.b, d2.b)),
		"one pad covers both" .. T.say(p and p.l, d1.l, p and p.r, d2.r))
	check(T.bar("1").dock._edgeHidden and T.bar("2").dock._edgeHidden and B:Bare("bar1"),
		"and both docks are drawn bare inside it")

	-- 2. The pad and the member follow the host.
	T.bar("1").dock:ClearAllPoints()
	T.bar("1").dock:SetPoint("CENTER", UIParent, "CENTER", -300, 100)
	a, b, p = T.btn("1", 3), T.btn("2", 1), T.R(pad)
	d1, d2 = T.R(T.bar("1").dock), T.R(T.bar("2").dock)
	check(T.near(b.l - a.r, T.gap("1")) and T.near(p.l, d1.l) and T.near(p.r, d2.r),
		"moving bar 1 carries bar 2 and the pad with it" .. T.say(b.l - a.r, p.l, d1.l))
	T.fresh()

	-- 3. Stacked, and a slot along the edge.
	check(B:Join("bar2", "bar1", "BOTTOM", 0), "bar 2 braids under bar 1")
	a, b = T.btn("1", 10), T.btn("2", 1)
	check(T.near(a.b - b.t, T.gap("1")) and T.near(a.l, b.l),
		"stacked, the seam is one gap and the columns line up" .. T.say(a.b - b.t, a.l, b.l))
	check(B:Join("bar2", "bar1", "RIGHT", 1), "a slot down the edge")
	check(T.near(T.btn("2", 1).t, T.btn("1", 4).t),
		"bar 2's first row sits beside bar 1's second" .. T.say(T.btn("2", 1).t, T.btn("1", 4).t))

	-- 4. A chain: bar 3 onto bar 2, which is on bar 1.
	B:Join("bar2", "bar1", "RIGHT", 0)
	check(B:Join("bar3", "bar2", "RIGHT", 0) and B:Root("bar3") == "bar1",
		"bar 3 braids onto bar 2, and the braid is bar 1's" .. T.say(B:Root("bar3")))
	a, b = T.btn("2", 3), T.btn("3", 1)
	p, d1 = T.R(pad), T.R(T.bar("3").dock)
	check(T.near(b.l - a.r, T.gap("1")) and T.near(b.r - b.l, T.btn("1", 1).r - T.btn("1", 1).l),
		"one gap and one size down the chain" .. T.say(b.l - a.r, b.r - b.l))
	check(T.near(p.r, d1.r) and not (B.pads.bar2 and B.pads.bar2:IsShown()),
		"and one pad, bar 1's, reaches bar 3" .. T.say(p.r, d1.r))

	-- 5. Refused: a loop, a bar onto itself, the extra button, and combat.
	check(not B:Join("bar1", "bar2", "LEFT", 0), "bar 1 can't braid onto bar 2, which hangs from it")
	check(not B:Join("bar2", "bar2", "LEFT", 0), "nor a strand onto itself")
	check(not B:Join("barextra", "bar1", "LEFT", 0) and not M.registry.barextra.braid,
		"the extra-action button is not a strand")
	_G.__inCombat = true
	check(not B:Join("bar3", "bar1", "BOTTOM", 0) and not B:Leave("bar3"), "nothing braids in combat")
	_G.__inCombat = false

	-- 6. A member switched off takes the pad down with it if it was the last.
	B:Leave("bar3")
	AB:SetBarEnabled("2", false)
	check(not pad:IsShown() and not T.bar("1").dock._edgeHidden,
		"with bar 2 off, bar 1 has no pad and its own dock back")
	AB:SetBarEnabled("2", true)
	check(pad:IsShown() and B:HostOf("bar2") == "bar1", "and bar 2 back on is braided again")

	-- 7. Leaving: its own size back, still bonded to bar 1.
	check(B:Leave("bar2") and B:HostOf("bar2") == nil and M:ParentOf("bar2") == "bar1",
		"bar 2 leaves the braid and still hangs from bar 1")
	b = T.btn("2", 1)
	check(T.near(b.r - b.l, 50 * k) and not pad:IsShown() and not T.bar("2").dock._edgeHidden,
		"at its own size, with its own dock and no pad" .. T.say(b.r - b.l))

	-- 8. The string: written, read back, and refused when it is not a braid.
	T.fresh()
	B:Join("bar2", "bar1", "RIGHT", 0)
	B:Join("bar3", "bar1", "BOTTOM", 1)
	local text = LY:Encode()
	check(text:find("bar2=bar1,TOPLEFT,TOPRIGHT,[^;]*,3x4,36,braid;")
		and text:find("bar3=bar1,TOPLEFT,BOTTOMLEFT,[^;]*,3x4,36,braid1"),
		"the string says which edge, and the slot past 0" .. T.say(text))
	T.fresh()
	local lay = LY:Decode(text)
	check(lay and LY:Apply(lay) and B:HostOf("bar2") == "bar1" and B:HostOf("bar3") == "bar1",
		"and applied, the braids come back")
	a, b = T.btn("1", 3), T.btn("2", 1)
	check(T.near(b.l - a.r, T.gap("1")) and LY:Matches(lay),
		"seated one gap off, and it reads back as itself" .. T.say(b.l - a.r))
	check(LY:Matches(LY:Decode(LY:Pack(text))), "the packed form too")
	B:Leave("bar2")
	check(not LY:Matches(lay), "and out of the braid it is another layout")
	for _, bad in ipairs({
		"bar2=player,TOPLEFT,TOPRIGHT,0,0,3x4,36,braid",
		"bar2=bar1,CENTER,CENTER,0,0,3x4,36,braid",
		"bar2=bar1,TOPLEFT,TOPRIGHT,0,0,3x4,36,woven",
		"bar2=barextra,TOPLEFT,TOPRIGHT,0,0,3x4,36,braid",
		"chat=bar1,TOPLEFT,TOPRIGHT,0,0,3x4,braid",
	}) do
		check(LY:Decode("LAT1;b=1,2;" .. bad) == nil, "refused: " .. bad)
	end

	-- 9. In unlock: a strand dropped within 8 of an edge braids, the edge
	-- lights first, and dragged away it leaves. A drag places by UIParent's
	-- bottom-left, which the client has at 0, 0 - so the screen gets a rect.
	UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
	T.fresh()
	local h2
	M:Unlock()
	h2 = M.registry.bar2.handle
	local d = T.bar("2").dock
	d:ClearAllPoints()
	-- 5 off the seat on bar 1's right: the docks overlap by 2 x 6 - 8 at it.
	d:SetPoint("TOPLEFT", T.bar("1").dock, "TOPRIGHT", -4 + 5, -3)
	cursorX, cursorY = 900, 500
	_G.__shift = true
	h2:GetScript("OnDragStart")(h2)
	h2:GetScript("OnUpdate")(h2)
	local fb = B.__feedback()
	check(fb and fb:IsShown() and fb.text:GetText() == "BRAID · BAR 1",
		"within 8 of bar 1's right edge, it lights: BRAID · BAR 1"
		.. T.say(fb and fb.text:GetText()))
	h2:GetScript("OnDragStop")(h2)
	_G.__shift = false
	a, b = T.btn("1", 3), T.btn("2", 1)
	check(B:HostOf("bar2") == "bar1" and T.near(b.l - a.r, T.gap("1")) and T.near(a.t, b.t)
		and not fb:IsShown(),
		"and the drop braids it, seated on the seam" .. T.say(B:HostOf("bar2"), b.l - a.r, b.t - a.t))
	h2:GetScript("OnDragStart")(h2)
	h2:GetScript("OnUpdate")(h2)
	local insp = M.__inspector()
	check(insp:IsShown() and insp.rows[5].k:GetText() == "Braided with"
		and insp.rows[5].v:GetText() == "BAR 1",
		"the inspector says what it is braided with" .. T.say(insp.rows[5].v:GetText()))
	-- And its shape, size and energy (strands brief 9b): bar 2 has no key
	-- here, so 60 / 100, and draws at bar 1's 36.
	check(insp.rows[6].k:GetText() == "Shape" and insp.rows[6].v:GetText() == "3 × 4 · across",
		"and its shape" .. T.say(insp.rows[6].k:GetText(), insp.rows[6].v:GetText()))
	check(insp.rows[7].k:GetText() == "Size" and insp.rows[7].v:GetText() == "36 px",
		"its button size, the braid's" .. T.say(insp.rows[7].v:GetText()))
	check(insp.rows[8] and insp.rows[8].k:IsShown() and insp.rows[8].k:GetText() == "Rest / Combat"
		and insp.rows[8].v:GetText() == "60 % / 100 %",
		"and its rest and combat energy" .. T.say(insp.rows[8] and insp.rows[8].v:GetText()))
	h2:GetScript("OnDragStop")(h2)
	check(B:HostOf("bar2") == "bar1", "let go where it sits, it stays in the braid")
	-- With a pad of 10 the docks overlap by 12 at the seat, more than the 8 a
	-- braid reaches: measured from the edge, letting go would unbraid it.
	ABc.padding = 10
	A:Reconfigure()
	h2:GetScript("OnDragStart")(h2)
	h2:GetScript("OnUpdate")(h2)
	h2:GetScript("OnDragStop")(h2)
	check(B:HostOf("bar2") == "bar1", "and still does with the docks overlapping by more than 8")
	ABc.padding = 6
	A:Reconfigure()
	_G.__shift = true
	h2:GetScript("OnDragStart")(h2)
	cursorX = 1000
	h2:GetScript("OnUpdate")(h2)
	check(fb and not fb:IsShown(), "dragged 100 away, nothing lights")
	h2:GetScript("OnDragStop")(h2)
	_G.__shift = false
	check(B:HostOf("bar2") == nil and M:ParentOf("bar2") == "bar1"
		and T.R(T.bar("2").dock).l - T.R(T.bar("1").dock).r > 50,
		"and the drop takes it out of the braid, still bonded to bar 1, where it was dropped"
		.. T.say(B:HostOf("bar2"), M:ParentOf("bar2")))
	M:Lock()
	UIParent.__geom = nil

	-- Back as it was.
	for id, c in pairs(T.cfg) do
		local cfg = AB:BarConfig(id)
		cfg.rows, cfg.cols, cfg.wrap, cfg.size, cfg.scale = c.rows, c.cols, c.wrap, c.size, c.scale
	end
	ABc.size, ABc.spacing, ABc.padding, ABc.scale = T.was.size, T.was.spacing, T.was.padding, T.was.scale
	for id, on in pairs(T.on) do AB:BarConfig(id).enabled = on end
	UIParent:SetSize(T.was.w, T.was.h)
	A.db.profile.scale = T.was.ui
	T.fresh()
	check(not (pad and pad:IsShown()), "and with the braids gone, so is the pad")
end

print("== shape handle ==")
do
	-- STRANDS BRIEF 9b: the bottom-right junction reshapes a strand to the
	-- nearest cols x rows for the dragged extent, shown as a ghost first.
	-- Button size never changes. One table: the file is near the local cap.
	local S = { M = A.Movers, B = A.Braids, AB = A:GetModule("actionbars") }
	S.c = A.Config:Module("actionbars")
	S.was = { size = S.c.size, spacing = S.c.spacing, padding = S.c.padding, scale = S.c.scale,
		w = UIParent:GetWidth(), h = UIParent:GetHeight(), ui = A.db.profile.scale, cfg = {} }
	for _, id in ipairs({ "1", "2" }) do
		local c = S.AB:BarConfig(id)
		S.was.cfg[id] = { rows = c.rows, cols = c.cols, wrap = c.wrap, size = c.size, scale = c.scale,
			buttons = c.buttons, enabled = c.enabled }
	end
	function S.bar(id)
		for _, bar in ipairs(S.AB.bars) do if bar.id == id then return bar end end
	end
	function S.R(f)
		local k = f:GetEffectiveScale() / UIParent:GetEffectiveScale()
		return { l = f:GetLeft() * k, r = f:GetRight() * k, t = f:GetTop() * k, b = f:GetBottom() * k }
	end
	function S.near(a, b) return a and b and math.abs(a - b) <= 0.5 end
	function S.say(...)
		local out = {}
		for i = 1, select("#", ...) do
			local v = select(i, ...)
			out[#out + 1] = type(v) == "number" and ("%.2f"):format(v) or tostring(v)
		end
		return " (" .. table.concat(out, ", ") .. ")"
	end
	function S.fresh()
		wipe(A.db.profile.anchors)
		for _, e in pairs(S.M.registry) do e.parent, e.free = e.defaultParent, nil end
		A:Reconfigure()
	end
	-- Drag bar `id`'s grip to `dx` right of and `dy` below its top-left.
	function S.drag(id, dx, dy, stop)
		local g = S.M.registry["bar" .. id].handle.grip
		local r = S.R(S.bar(id).dock)
		cursorX, cursorY = r.l + dx, r.t - dy
		g:GetScript("OnDragStart")(g)
		local up = g:GetScript("OnUpdate")
		if up then up(g) end
		if stop ~= false then g:GetScript("OnDragStop")(g) end
		return g
	end

	UIParent:SetSize(1920, 1080)
	UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
	A.db.profile.scale = 1
	S.c.size, S.c.spacing, S.c.padding, S.c.scale = 36, 8, 6, 1
	S.c1, S.c2 = S.AB:BarConfig("1"), S.AB:BarConfig("2")
	S.c1.cols, S.c1.rows, S.c1.wrap, S.c1.size, S.c1.scale, S.c1.buttons = nil, 1, "across", nil, 1, 12
	S.c2.cols, S.c2.rows, S.c2.wrap, S.c2.size, S.c2.scale, S.c2.buttons, S.c2.enabled =
		nil, 4, "across", nil, 1, 12, true
	S.fresh()

	-- 1. The shapes twelve buttons can take across, sized as the bar lays them
	-- out: every row length, the uneven ones (5 x 3 has three blanks) included.
	S.shapes = S.M.registry.bar1.reshape.shapes()
	S.list = {}
	for _, s in ipairs(S.shapes) do S.list[#S.list + 1] = s.cols .. "x" .. s.rows end
	check(table.concat(S.list, " ") == "1x12 2x6 3x4 4x3 5x3 6x2 7x2 8x2 9x2 10x2 11x2 12x1",
		"twelve buttons across take every row length" .. S.say(table.concat(S.list, " ")))
	S.d = S.R(S.bar("1").dock)
	check(S.near(S.shapes[12].w, S.d.r - S.d.l) and S.near(S.shapes[12].h, S.d.t - S.d.b),
		"and the one it is in is the size its dock is" .. S.say(S.shapes[12].w, S.d.r - S.d.l))
	check(S.near(S.shapes[3].w, 3 * 36 + 2 * 8 + 12) and S.near(S.shapes[3].h, 4 * 36 + 3 * 8 + 12),
		"3 x 4 at 36 with a gap of 8 and a pad of 6" .. S.say(S.shapes[3].w, S.shapes[3].h))
	check(S.M.NearestShape(S.shapes, 140, 175).cols == 3 and S.M.NearestShape(S.shapes, 600, 40).cols == 12,
		"the nearest shape to an extent wins")
	check(S.M.registry.barextra.reshape == nil, "the extra button has no shape to change")

	-- 2. In unlock: a grip on each strand with shapes to take.
	S.M:Unlock()
	S.g1 = S.M.registry.bar1.handle.grip
	check(S.g1 and S.g1:IsShown(), "bar 1 has a shape handle in unlock")
	check(not (S.M.registry.barextra.handle and S.M.registry.barextra.handle.grip),
		"and the extra button has none")
	S.c2.buttons = 1
	S.AB:OnConfigChanged()
	check(not S.M.registry.bar2.handle.grip:IsShown(),
		"a strand down to one button has only one shape, and its handle goes")
	S.c2.buttons = 12
	S.AB:OnConfigChanged()
	check(S.M.registry.bar2.handle.grip:IsShown(), "and comes back with its buttons")

	-- 3. Dragging: the ghost, where the bar will actually land, and nothing
	-- changed until it is let go.
	S.point = S.bar("1").dock:GetPoint(1)
	S.px, S.py = S.M.PointAt(S.bar("1").dock, S.point)
	S.lat = A.db.profile.anchors.bar1 and A.db.profile.anchors.bar1.lat
	S.drag("1", 140, 175, false)
	S.fb = S.M.__feedback()
	S.gh = S.fb and S.fb.ghostInfo
	check(S.gh and S.fb.ghost:IsShown() and S.fb.ghostText:GetText() == "3 × 4",
		"dragged to 140 x 175, the ghost reads 3 × 4" .. S.say(S.gh and S.fb.ghostText:GetText()))
	check(S.gh and S.near(S.gh.r - S.gh.l, 136) and S.near(S.gh.t - S.gh.b, 180),
		"and is that shape's size" .. S.say(S.gh and S.gh.r - S.gh.l, S.gh and S.gh.t - S.gh.b))
	S.gx = S.gh and (S.point:find("LEFT") and S.gh.l or S.point:find("RIGHT") and S.gh.r
		or (S.gh.l + S.gh.r) / 2)
	S.gy = S.gh and (S.point:find("TOP") and S.gh.t or S.point:find("BOTTOM") and S.gh.b
		or (S.gh.b + S.gh.t) / 2)
	check(S.point ~= "TOPLEFT" and S.near(S.gx, S.px) and S.near(S.gy, S.py),
		"drawn about the point the bar hangs by, not its top-left" .. S.say(S.point, S.gx, S.px, S.gy, S.py))
	S.insp = S.M.__inspector()
	check(S.insp:IsShown() and S.insp.rows[5].k:GetText() == "Shape"
		and S.insp.rows[5].v:GetText() == "3 × 4 · across",
		"the inspector reads the shape it would be" .. S.say(S.insp.rows[5].v:GetText()))
	check(S.c1.rows == 1 and S.bar("1").cols == 12, "and nothing has changed yet")
	S.g1:GetScript("OnDragStop")(S.g1)

	-- 4. Let go: laid out in it, at the same button size, hanging where it did.
	S.d = S.R(S.bar("1").dock)
	check(S.c1.rows == 4 and S.bar("1").cols == 3 and S.bar("1").rows == 4,
		"let go, bar 1 is 3 x 4" .. S.say(S.c1.rows, S.bar("1").cols))
	check(S.near(S.d.r - S.d.l, 136) and S.near(S.M.PointAt(S.bar("1").buttons[1], "TOPRIGHT")
		- S.M.PointAt(S.bar("1").buttons[1], "TOPLEFT"), 36),
		"its buttons the same size" .. S.say(S.d.r - S.d.l))
	S.qx, S.qy = S.M.PointAt(S.bar("1").dock, S.point)
	check(S.near(S.qx, S.px) and S.near(S.qy, S.py) and S.near(S.d.l, S.gh.l) and S.near(S.d.t, S.gh.t),
		"exactly where the ghost was" .. S.say(S.qx, S.px, S.d.l, S.gh.l))
	check(not S.fb.ghost:IsShown() and not S.fb.ghostText:IsShown() and not S.insp:IsShown(),
		"and the ghost and inspector gone")

	-- A strand hung from an EDGE keeps that bond through a reshape: measured
	-- again it would become a centre bond (the Block seed's pet bar, 2026-10-09).
	A.db.profile.anchors.bar2 = { lat = { parent = "bar1", point = "TOPLEFT", relPoint = "BOTTOMLEFT",
		x = 0, y = -10 } }
	S.M:ResolveParents()
	A:Reconfigure()
	S.drag("2", 268, 92)
	S.now = A.db.profile.anchors.bar2.lat
	S.d1, S.d2 = S.R(S.bar("1").dock), S.R(S.bar("2").dock)
	check(S.bar("2").cols == 6 and S.now.parent == "bar1" and S.now.point == "TOPLEFT"
		and S.now.relPoint == "BOTTOMLEFT" and S.now.x == 0 and S.now.y == -10,
		"a strand hung from bar 1's bottom edge keeps that bond through a reshape"
		.. S.say(S.bar("2").cols, S.now.point, S.now.relPoint, S.now.x, S.now.y))
	check(S.near(S.d2.l, S.d1.l) and S.near(S.d1.b - S.d2.t, 10),
		"and still hangs 10 under bar 1's bottom-left" .. S.say(S.d2.l, S.d1.l, S.d1.b - S.d2.t))
	A.db.profile.anchors.bar2 = nil
	S.M:ResolveParents()
	S.c2.cols, S.c2.rows = nil, 4
	A:Reconfigure()

	-- 5. Refused in combat, and a fight mid-drag cancels it.
	_G.__inCombat = true
	S.drag("1", 600, 40)
	check(S.c1.rows == 4 and not S.g1:GetScript("OnUpdate"), "a reshape won't start in combat")
	_G.__inCombat = false
	S.drag("1", 600, 40, false)
	_G.__inCombat = true
	S.g1:GetScript("OnUpdate")(S.g1)
	_G.__inCombat = false
	S.g1:GetScript("OnDragStop")(S.g1)
	check(S.c1.rows == 4 and not S.fb.ghost:IsShown(),
		"and a fight starting mid-drag cancels it" .. S.say(S.c1.rows))
	S.drag("1", 600, 40)
	check(S.c1.rows == 1 and S.bar("1").cols == 12, "out of the fight, dragged wide it is 12 x 1 again")

	-- 6. In a braid: the member reshapes and the pad is laid round it.
	S.B:Join("bar2", "bar1", "RIGHT", 0)
	S.drag("2", 268, 92)
	S.pad, S.d1, S.d2 = S.R(S.B.pads.bar1), S.R(S.bar("1").dock), S.R(S.bar("2").dock)
	check(S.B:HostOf("bar2") == "bar1" and S.bar("2").cols == 6,
		"a braided strand reshapes in the braid" .. S.say(S.bar("2").cols))
	check(S.near(S.pad.r, S.d2.r) and S.near(S.pad.b, math.min(S.d1.b, S.d2.b)),
		"and the pad is laid round its new shape" .. S.say(S.pad.r, S.d2.r, S.pad.b))
	S.B:Leave("bar2")
	S.M:Lock()
	UIParent.__geom = nil

	-- Back as it was.
	for id, c in pairs(S.was.cfg) do
		local cfg = S.AB:BarConfig(id)
		cfg.rows, cfg.cols, cfg.wrap, cfg.size, cfg.scale, cfg.buttons, cfg.enabled =
			c.rows, c.cols, c.wrap, c.size, c.scale, c.buttons, c.enabled
	end
	S.c.size, S.c.spacing, S.c.padding, S.c.scale = S.was.size, S.was.spacing, S.was.padding, S.was.scale
	UIParent:SetSize(S.was.w, S.was.h)
	A.db.profile.scale = S.was.ui
	S.fresh()
end

print("== shapes: uneven, blanks, wrap ==")
do
	-- STRANDS BRIEF: a shape is cols x rows with a wrap, across or down; uneven
	-- shapes leave blanks, drawn dashed in unlock only (Joe, 2026-10-10). The
	-- line in the wrap's direction keeps its length as the button count
	-- changes (Layout.Fit). One table: the file is near the local cap.
	local Z = { AB = A:GetModule("actionbars"), LY = A.Layout, M = A.Movers }
	Z.c = A.Config:Module("actionbars")
	Z.c1 = Z.AB:BarConfig("1")
	Z.was = { size = Z.c.size, spacing = Z.c.spacing, padding = Z.c.padding,
		rows = Z.c1.rows, cols = Z.c1.cols, wrap = Z.c1.wrap, buttons = Z.c1.buttons, bsize = Z.c1.size }
	function Z.bar()
		for _, bar in ipairs(Z.AB.bars) do if bar.id == "1" then return bar end end
	end
	-- Where button i sits in its grid, in cells: column and row from the top-left.
	function Z.cell(i)
		local b = Z.bar().buttons[i]
		local _, _, _, x, y = b:GetPoint(1)
		return math.floor(x / 44 + 0.5), math.floor(-y / 44 + 0.5)
	end
	-- The blanks' cells, in order, from their fills' anchors.
	function Z.blanks()
		local f, out = Z.bar().blanks, {}
		local h = Z.bar().rows * 44 - 8
		for _, t in ipairs(f and f.fills or {}) do
			if t:IsShown() then
				local _, _, _, x, y = t:GetPoint(1)
				out[#out + 1] = ("%d,%d"):format(math.floor(x / 44 + 0.5), math.floor((h - y) / 44 + 0.5))
			end
		end
		return table.concat(out, " ")
	end
	function Z.say(...)
		local out = {}
		for i = 1, select("#", ...) do out[#out + 1] = tostring((select(i, ...))) end
		return " (" .. table.concat(out, ", ") .. ")"
	end
	Z.c.size, Z.c.spacing, Z.c.padding = 36, 8, 6
	Z.c1.size, Z.c1.buttons = nil, 12

	-- 1. A profile from before cols: rows only, read as that many rows.
	Z.c1.cols, Z.c1.rows, Z.c1.wrap = nil, 5, "across"
	Z.AB:OnConfigChanged()
	check(Z.bar().cols == 3 and Z.bar().rows == 4,
		"a profile with only rows reads as before: 5 rows of 12 is 3 x 4" .. Z.say(Z.bar().cols, Z.bar().rows))
	check(Z.LY.Fit(3, nil, 12, "across") == 1 and Z.LY.Fit(6, nil, 12, "across") == 1,
		"and a stance bar written as a column of 12 is a column of 3, or of 6")

	-- 2. Uneven, across: a row of 5 over 12 is 5 x 3 with three blanks at the end.
	check(Z.AB:SetShape("1", 5, nil), "bar 1 set to five a row")
	check(Z.bar().cols == 5 and Z.bar().rows == 3, "is 5 x 3" .. Z.say(Z.bar().cols, Z.bar().rows))
	Z.x, Z.y = Z.cell(6)
	Z.x2, Z.y2 = Z.cell(12)
	check(Z.x == 0 and Z.y == 1 and Z.x2 == 1 and Z.y2 == 2,
		"its sixth button starts the second row, its twelfth is second on the third"
		.. Z.say(Z.x, Z.y, Z.x2, Z.y2))
	check(Z.blanks() == "2,2 3,2 4,2", "three blanks end the last row" .. Z.say(Z.blanks()))
	check(#(Z.bar().blanks.dashes) >= 12 and Z.bar().blanks.dashes[1]:IsShown(),
		"each blank has a dashed edge")

	-- 3. Blanks are seen in unlock only.
	check(not Z.bar().blanks:IsShown(), "locked, the blanks are not drawn")
	Z.M:Unlock()
	check(Z.bar().blanks:IsShown(), "unlocked, they are")
	Z.AB:SetShape("1", 6, nil)
	check(not Z.bar().blanks:IsShown(), "and a full shape, 6 x 2, has none to show")
	Z.AB:SetShape("1", 5, nil)
	check(Z.bar().blanks:IsShown(), "back to 5 x 3, unlocked, they show again")
	Z.M:Lock()
	check(not Z.bar().blanks:IsShown(), "and locking takes them away")

	-- 4. Down: each column filled before the next, and keys keep their buttons.
	check(Z.AB:SetShape("1", nil, 4, "down") and Z.bar().cols == 3 and Z.bar().rows == 4,
		"four a column, down, is 3 x 4" .. Z.say(Z.bar().cols, Z.bar().rows))
	Z.x, Z.y = Z.cell(2)
	Z.x2, Z.y2 = Z.cell(5)
	check(Z.x == 0 and Z.y == 1 and Z.x2 == 1 and Z.y2 == 0,
		"its second button is under its first, its fifth tops the second column"
		.. Z.say(Z.x, Z.y, Z.x2, Z.y2))
	check(Z.bar().buttons[2]:GetAttribute("action") == 2 and Z.bar().buttons[5]:GetAttribute("action") == 5,
		"and each button keeps its own action, so a key still casts what it did")
	Z.AB:SetShape("1", nil, 5, "down")
	check(Z.bar().cols == 3 and Z.bar().rows == 5 and Z.blanks() == "2,2 2,3 2,4",
		"five a column is 3 x 5, its blanks at the foot of the last column"
		.. Z.say(Z.bar().cols, Z.bar().rows, Z.blanks()))
	Z.list = {}
	for _, s in ipairs(Z.M.registry.bar1.reshape.shapes()) do Z.list[#Z.list + 1] = s.cols .. "x" .. s.rows end
	check(table.concat(Z.list, " ") == "12x1 6x2 4x3 3x4 3x5 2x6 2x7 2x8 2x9 2x10 2x11 1x12",
		"the shape handle offers every column length down" .. Z.say(table.concat(Z.list, " ")))
	check(select(2, unpack(Z.AB:ShapeOf("1") and { Z.AB:ShapeOf("1") } or {})) == 5,
		"and ShapeOf reads it back")

	-- 5. One whole line stays one line as buttons come: a druid's row of two
	-- forms is a row of three at the third, not a 2 x 2.
	Z.c1.buttons = 8
	Z.AB:OnConfigChanged()
	Z.AB:SetShape("1", 8, nil, "across")
	check(Z.c1.cols == 12, "a whole row is kept as a row, not as eight" .. Z.say(Z.c1.cols))
	Z.c1.buttons = 10
	Z.AB:OnConfigChanged()
	check(Z.bar().cols == 10 and Z.bar().rows == 1, "so at ten buttons it is still one row"
		.. Z.say(Z.bar().cols, Z.bar().rows))
	Z.c1.buttons = 12

	-- 6. The string: down written and read back; either order with a braid.
	Z.AB:SetShape("1", nil, 4, "down")
	Z.text = Z.LY:Encode()
	check(Z.text:find("bar1=[^;]*,3x4,%d+,down") ~= nil, "the string says down" .. Z.say(Z.text))
	Z.lay = Z.LY:Decode(Z.text)
	check(Z.lay and Z.lay.records.bar1.wrap == "down" and Z.LY:Matches(Z.lay),
		"reads it back, and matches the bar on screen")
	Z.AB:SetShape("1", nil, nil, "across")
	check(not Z.LY:Matches(Z.lay), "the same cells across are another arrangement")
	check(Z.LY:Apply(Z.lay) and Z.c1.wrap == "down" and Z.bar().cols == 3 and Z.bar().rows == 4,
		"and applying it puts the bar back down" .. Z.say(Z.c1.wrap, Z.bar().cols, Z.bar().rows))
	check(Z.LY:Decode("LAT1;b=1,2;bar2=bar1,TOPLEFT,TOPRIGHT,0,0,3x4,36,braid,down")
		and Z.LY:Decode("LAT1;b=1,2;bar2=bar1,TOPLEFT,TOPRIGHT,0,0,3x4,36,down,braid2"),
		"down and a braid read in either order")
	for _, bad in ipairs({
		"bar1=screen,CENTER,CENTER,0,0,3x4,36,down,down",
		"bar1=screen,CENTER,CENTER,0,0,3x4,36,sideways",
		"bar1=screen,CENTER,CENTER,0,0,3x4,36,down,braid,down",
		"chat=screen,CENTER,CENTER,0,0,down",
	}) do
		check(Z.LY:Decode("LAT1;b=1;" .. bad) == nil, "refused: " .. bad)
	end

	-- 7. The inspector, the options and the command.
	check(Z.AB:SetShape("1", nil, 4, "down"), "down again")
	Z.opt = A.Options:Build().args.actionbars.args.bar1.args
	check(Z.opt.wrap and Z.opt.wrap.get() == "down" and Z.opt.line.get() == 4
		and Z.opt.line.name() == "Buttons per column",
		"the options read down, four a column" .. Z.say(Z.opt.wrap and Z.opt.wrap.get(),
			Z.opt.line and Z.opt.line.get()))
	Z.opt.wrap.set(nil, "across")
	Z.opt.line.set(nil, 5)
	check(Z.c1.wrap == "across" and Z.bar().cols == 5 and Z.opt.line.name() == "Buttons per row",
		"and set across, five a row" .. Z.say(Z.c1.wrap, Z.bar().cols))
	check(Z.opt.rows == nil and A.Options:Build().args.actionbars.args.barextra.args.wrap == nil,
		"the old rows slider is gone, and the extra button has no shape")
	SlashCmdList["AETHERUI"]("bar 1 cols 4")
	check(Z.bar().cols == 4 and Z.bar().rows == 3, "/lattice bar 1 cols 4" .. Z.say(Z.bar().cols, Z.bar().rows))
	SlashCmdList["AETHERUI"]("bar 1 rows 2")
	check(Z.bar().cols == 6 and Z.bar().rows == 2, "rows 2 is two rows" .. Z.say(Z.bar().cols, Z.bar().rows))
	SlashCmdList["AETHERUI"]("bar 1 wrap down")
	check(Z.c1.wrap == "down" and Z.bar().rows == 2, "wrap down keeps the shape it can"
		.. Z.say(Z.c1.wrap, Z.bar().cols, Z.bar().rows))
	SlashCmdList["AETHERUI"]("bar 1 wrap sideways")
	check(Z.c1.wrap == "down", "and an unknown wrap changes nothing")
	_G.__inCombat = true
	check(not Z.AB:SetShape("1", 12, nil, "across") and Z.c1.wrap == "down", "nothing reshapes in combat")
	_G.__inCombat = false

	-- Back as it was.
	Z.c1.rows, Z.c1.cols, Z.c1.wrap, Z.c1.buttons, Z.c1.size = Z.was.rows, Z.was.cols, Z.was.wrap,
		Z.was.buttons, Z.was.bsize
	Z.c.size, Z.c.spacing, Z.c.padding = Z.was.size, Z.was.spacing, Z.was.padding
	wipe(A.db.profile.anchors)
	A:Reconfigure()
end

print("== hidden strands ==")
do
	-- STRANDS BRIEF: a strand switched off still exists - a hollow outline
	-- parked along the bottom edge in unlock, one click to show, then drag.
	local H = { AB = A:GetModule("actionbars"), M = A.Movers }
	H.c = A.Config:Module("actionbars")
	H.was = { ui = A.db.profile.scale, w = UIParent:GetWidth(), h = UIParent:GetHeight(), on = {} }
	for _, c in ipairs(H.c.bars) do H.was.on[tostring(c.id)] = c.enabled end
	function H.nodes()
		local out = {}
		for _, n in ipairs(H.AB.park and H.AB.park.nodes or {}) do
			if n:IsShown() then out[#out + 1] = n end
		end
		return out
	end
	function H.node(id)
		for _, n in ipairs(H.nodes()) do if n.id == id then return n end end
	end
	function H.ids()
		local out = {}
		for _, n in ipairs(H.nodes()) do out[#out + 1] = n.id end
		return table.concat(out, " ")
	end
	function H.say(...)
		local out = {}
		for i = 1, select("#", ...) do
			local v = select(i, ...)
			out[#out + 1] = type(v) == "number" and ("%.1f"):format(v) or tostring(v)
		end
		return " (" .. table.concat(out, ", ") .. ")"
	end

	UIParent:SetSize(1920, 1080)
	UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
	A.db.profile.scale = 1
	wipe(A.db.profile.anchors)
	-- Bars 1 and 2 on, every other numbered bar off; stance and pet on.
	for _, c in ipairs(H.c.bars) do
		if c.kind == "action" then c.enabled = (c.id == "1" or c.id == "2") end
	end
	H.c.bars[#H.c.bars].enabled = true
	A:Reconfigure()
	H.want = {}
	for _, c in ipairs(H.c.bars) do
		if c.kind ~= "extra" and not c.enabled then H.want[#H.want + 1] = tostring(c.id) end
	end
	H.want = table.concat(H.want, " ")

	check(not (H.AB.park and H.AB.park:IsShown()), "locked, nothing is parked on screen")
	H.M:Unlock()
	check(H.AB.park and H.AB.park:IsShown() and H.ids() == H.want,
		"unlocked, every hidden strand is parked, in order" .. H.say(H.ids(), H.want))
	H.n3 = H.node("3")
	H.sc, H.sr = H.AB:ShapeOf("3")
	check(H.n3 and H.n3.cols == H.sc and H.n3.rows == H.sr and H.n3.count == 12 and H.n3.dashes[1]:IsShown(),
		"each drawn hollow, in its own shape, a cell a button"
		.. H.say(H.n3 and H.n3.cols, H.n3 and H.n3.rows, H.n3 and H.n3.count))
	check(H.n3 and H.n3.label:GetText() == "BAR 3", "and named" .. H.say(H.n3 and H.n3.label:GetText()))
	H.l, H.r, H.b = 1e9, -1e9, 1e9
	for _, n in ipairs(H.nodes()) do
		local l, b = H.M.PointAt(n, "BOTTOMLEFT")
		local r = H.M.PointAt(n, "TOPRIGHT")
		H.l, H.r, H.b = math.min(H.l, l), math.max(H.r, r), math.min(H.b, b)
	end
	check(math.abs((H.l + H.r) / 2 - 960) < 1 and math.abs(H.b - H.M.Px(24)) < 1,
		"in a row centred along the bottom, 24 up" .. H.say(H.l, H.r, H.b))

	-- The extra button is never a strand, on or off.
	H.ex = H.AB:BarConfig("extra")
	H.ex.enabled = false
	H.AB:OnConfigChanged()
	check(H.ids() == H.want, "the extra button is never parked" .. H.say(H.ids()))
	H.ex.enabled = true
	H.AB:OnConfigChanged()

	-- A strand switched off while unlocked is parked at once.
	H.AB:SetBarEnabled("2", false)
	check(H.node("2") ~= nil, "bar 2 switched off while unlocked is parked at once" .. H.say(H.ids()))
	H.AB:SetBarEnabled("2", true)

	-- 2. One never placed: shown where its node was, still on its parent.
	H.cx, H.cy = H.M.PointAt(H.n3, "CENTER")
	check(A.db.profile.anchors.bar3 == nil, "bar 3 has never been placed")
	H.n3:GetScript("OnClick")(H.n3)
	H.dx, H.dy = H.M.PointAt(H.M.registry.bar3.frame, "CENTER")
	check(H.AB:BarConfig("3").enabled and H.node("3") == nil,
		"one click shows bar 3, and its node is gone" .. H.say(H.ids()))
	check(math.abs(H.dx - H.cx) < 1 and math.abs(H.dy - H.cy) < 1 and A.db.profile.anchors.bar3 ~= nil,
		"where its node was, and kept there" .. H.say(H.dx, H.cx, H.dy, H.cy))

	-- 3. One placed before goes back where it was, not to its node.
	H.d2 = H.M.registry.bar2.frame
	H.d2:ClearAllPoints()
	H.d2:SetPoint("CENTER", UIParent, "BOTTOMLEFT", 400, 700)
	H.M:SaveTree("bar2")
	H.ax, H.ay = H.M.PointAt(H.d2, "CENTER")
	H.AB:SetBarEnabled("2", false)
	H.n2 = H.node("2")
	H.n2:GetScript("OnClick")(H.n2)
	H.bx, H.by = H.M.PointAt(H.M.registry.bar2.frame, "CENTER")
	check(math.abs(H.bx - H.ax) < 1 and math.abs(H.by - H.ay) < 1,
		"bar 2, placed before, goes back where it was" .. H.say(H.bx, H.ax, H.by, H.ay))

	-- 4. Not in a fight: showing one builds secure buttons.
	H.n4 = H.node("4")
	_G.__inCombat = true
	H.n4:GetScript("OnClick")(H.n4)
	_G.__inCombat = false
	check(not H.AB:BarConfig("4").enabled and H.node("4") ~= nil, "a click in combat shows nothing")

	-- 5. Dragged back to the row, a strand is hidden (Joe, 2026-10-10).
	function H.drag(name, x, y, stop)
		local h = H.M.registry[name].handle
		local f = H.M.registry[name].frame
		local cx, cy = H.M.PointAt(f, "CENTER")
		cursorX, cursorY = cx, cy
		h:GetScript("OnDragStart")(h)
		cursorX, cursorY = x, y
		h:GetScript("OnUpdate")(h)
		if stop ~= false then h:GetScript("OnDragStop")(h) end
		return h
	end
	-- Its record as a string: the bond if it has one, else its screen place.
	function H.rec(name)
		local r = A.db.profile.anchors[name]
		local h = r and (r.lat or r)
		return h and ("%s %s %s %d %d"):format(tostring(h.parent), tostring(h.point), tostring(h.relPoint),
			h.x or 0, h.y or 0) or "none"
	end
	H.was3 = H.rec("bar3")
	H.h3 = H.drag("bar3", 960, 600, false)
	H.s = H.AB.park.strip
	check(H.s.rect and H.s.text:IsShown() and H.s.text:GetText() == "DROP HERE TO HIDE · SHIFT TO PLACE",
		"dragging a strand shows the drop strip round the row" .. H.say(H.s.text:GetText()))
	H.mx, H.my = (H.s.rect.l + H.s.rect.r) / 2, (H.s.rect.b + H.s.rect.t) / 2
	cursorX, cursorY = H.mx, H.my
	H.h3:GetScript("OnUpdate")(H.h3)
	check(H.s.text:GetText() == "HIDE · BAR 3" and not (H.M.__feedback() and H.M.__feedback().bondInfo),
		"on it, it lights - HIDE · BAR 3 - and offers no bond" .. H.say(H.s.text:GetText()))
	H.h3:GetScript("OnDragStop")(H.h3)
	check(not H.AB:BarConfig("3").enabled and H.node("3") ~= nil and not H.s.rect,
		"let go there, bar 3 is hidden and parked, and the strip goes" .. H.say(H.ids()))
	check(H.was3 ~= "none" and H.rec("bar3") == H.was3,
		"its place kept as it was before the drag, not where it was dropped" .. H.say(H.was3, H.rec("bar3")))
	-- With Shift held, on the strip is just a place to put it (Joe, 2026-10-10).
	H.h2 = H.drag("bar2", 960, 600, false)
	H.s = H.AB.park.strip
	_G.__shift = true
	cursorX, cursorY = (H.s.rect.l + H.s.rect.r) / 2, (H.s.rect.b + H.s.rect.t) / 2
	H.h2:GetScript("OnUpdate")(H.h2)
	check(H.s.text:GetText() == "DROP HERE TO HIDE · SHIFT TO PLACE",
		"with Shift held the strip does not light" .. H.say(H.s.text:GetText()))
	H.top = H.s.rect.t
	H.h2:GetScript("OnDragStop")(H.h2)
	_G.__shift = false
	H.px, H.py = -1e9, -1e9
	if H.M.registry.bar2 then H.px, H.py = H.M.PointAt(H.M.registry.bar2.frame, "CENTER") end
	check(H.AB:BarConfig("2").enabled and math.abs(H.px - cursorX) < 40 and H.py < H.top + 40,
		"and the drop places bar 2 there, shown" .. H.say(H.px, cursorX, H.py))
	-- Off the strip it is an ordinary drop.
	H.drag("bar2", 700, 500)
	check(H.AB:BarConfig("2").enabled and H.node("2") == nil, "dropped anywhere else, a strand stays shown")
	-- Whatever hangs from a hidden strand stays where it was: bar 1 is put
	-- back before it goes, and comes back there.
	H.st = H.M.registry.barstance
	H.sx, H.sy = H.M.PointAt(H.st.frame, "CENTER")
	H.b1x, H.b1y = H.M.PointAt(H.M.registry.bar1.frame, "CENTER")
	H.s = H.AB.park.strip
	H.drag("bar1", 960, 30)
	H.tx, H.ty = H.M.PointAt(H.st.frame, "CENTER")
	check(not H.AB:BarConfig("1").enabled and math.abs(H.tx - H.sx) < 1 and math.abs(H.ty - H.sy) < 1,
		"hiding bar 1 leaves its stance bar where it was" .. H.say(H.tx, H.sx, H.ty, H.sy))
	H.n1 = H.node("1")
	H.n1:GetScript("OnClick")(H.n1)
	H.cx, H.cy = H.M.PointAt(H.M.registry.bar1.frame, "CENTER")
	check(math.abs(H.cx - H.b1x) < 1 and math.abs(H.cy - H.b1y) < 1,
		"and shown again, bar 1 is back where it was" .. H.say(H.cx, H.b1x, H.cy, H.b1y))
	check(H.M.registry.barextra.park == nil, "the extra button cannot be dragged into hiding")
	-- With nothing hidden there is still somewhere to drop.
	for _, c in ipairs(H.c.bars) do c.enabled = true end
	H.AB:OnConfigChanged()
	check(not H.AB.park:IsShown(), "with every strand shown and nothing dragged, no row")
	H.hd = H.drag("bar2", 960, 600, false)
	check(H.AB.park:IsShown() and H.AB.park.strip.rect ~= nil, "but drag one and the strip is there")
	H.hd:GetScript("OnDragStop")(H.hd)
	check(not H.AB.park:IsShown(), "and gone again when it is let go elsewhere")

	-- 6. Locking takes the row away; the options call it Visible.
	H.M:Lock()
	check(not H.AB.park:IsShown(), "and locking takes the parked row away")
	H.opt = A.Options:Build().args.actionbars.args
	check(H.opt.bar3.args.enabled.name == "Visible" and H.opt.barextra.args.enabled.name == "Enabled",
		"a strand's switch is Visible; the extra button's is still Enabled")

	-- Back as it was.
	for _, c in ipairs(H.c.bars) do c.enabled = H.was.on[tostring(c.id)] end
	UIParent:SetSize(H.was.w, H.was.h)
	UIParent.__geom = nil
	A.db.profile.scale = H.was.ui
	wipe(A.db.profile.anchors)
	A:Reconfigure()
end

print("== world trunk ==")
do
	-- LATTICE 6a: a strand hanging from the minimap's pill, with branch nodes
	-- on it - 24 px diamonds 72 apart, an 80 px stub toward the screen's centre
	-- and a label over it; one branch open at a time.
	local T = { M = A.Movers, MM = A:GetModule("minimap"), QL = A:GetModule("questlog") }
	T.t = A.Trunk:Get("world")
	function T.near(a, b, tol) return a and b and math.abs(a - b) <= (tol or 0.5) end
	function T.say(...)
		local out = {}
		for i = 1, select("#", ...) do
			local v = select(i, ...)
			out[#out + 1] = type(v) == "number" and ("%.1f"):format(v) or tostring(v)
		end
		return " (" .. table.concat(out, ", ") .. ")"
	end
	T.was = { ui = A.db.profile.scale, w = UIParent:GetWidth(), h = UIParent:GetHeight() }
	UIParent:SetSize(1920, 1080)
	UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
	A.db.profile.scale = 1
	wipe(A.db.profile.anchors)
	A:Reconfigure()
	T.f = T.t.frame
	T.q = T.t:Node("questlog")

	-- 1. It hangs from the pill, its nodes in order down it.
	check(T.f and T.f:IsShown() and T.t.root == T.MM.pill, "the World trunk hangs from the minimap's pill")
	T.pb = select(2, T.M.PointAt(T.MM.pill, "BOTTOM"))
	T.ft = select(2, T.M.PointAt(T.f, "TOP"))
	check(T.near(T.pb - T.ft, 30), "its top end-cap 30 under the pill" .. T.say(T.pb - T.ft))
	check(T.q and T.q.button:IsShown() and T.near(select(2, T.M.PointAt(T.f, "TOP"))
		- select(2, T.M.PointAt(T.q.button, "CENTER")), 45),
		"the Quest Log node first, 40 under the cap" .. T.say(T.q and T.q.y))
	check(T.q.button.label:GetText() == "QUEST LOG", "labelled in capitals" .. T.say(T.q.button.label:GetText()))
	T.lr = T.M.PointAt(T.q.button.label, "RIGHT")
	T.nl = T.M.PointAt(T.q.button, "LEFT")
	check(T.near(T.nl - T.lr, 8), "its label ends 8 short of the node, close to the trunk (Joe)"
		.. T.say(T.nl - T.lr))
	T.c = T.t:Node("calendar")
	check(T.c and not T.c.button:IsShown(), "no calendar node on a client without one")
	check(T.f:GetScale() == A.db.profile.scale, "at the HUD's scale")

	-- 2. The stub runs toward the centre: left, on the right-hand edge.
	T.sx = T.M.PointAt(T.q.button.stub, "LEFT")
	T.bx = T.M.PointAt(T.q.button, "LEFT")
	T.px = T.M.PointAt(T.MM.pill, "CENTER")
	check(T.t.side == -1 and T.near(T.bx - T.sx, 80),
		"on the right-hand edge its stub runs 80 left, toward the centre"
		.. T.say(T.t.side, T.bx - T.sx, T.px, T.MM.pill:GetCenter()))

	-- 3. The Quest Log opens as its branch, beside the stub, and lights it.
	T.q.button:GetScript("OnClick")(T.q.button)
	T.win = T.QL.win
	T.wr, T.wy = T.M.PointAt(T.win, "RIGHT")
	T.ny = select(2, T.M.PointAt(T.q.button, "CENTER"))
	check(T.win:IsShown() and T.near(T.wr, T.sx - 5.5) and T.near(T.wy, T.ny),
		"clicked, the log opens with its edge at the stub's end, level with the node"
		.. T.say(T.wr, T.sx - 5.5, T.wy, T.ny))
	check(T.q.lit and T.q.button.glow:IsShown() and T.q.button.junction:IsShown(),
		"and the node is lit, a junction at the stub's end")
	T.q.button:GetScript("OnClick")(T.q.button)
	check(not T.win:IsShown() and not T.q.lit and not T.q.button.glow:IsShown(),
		"clicked again, the log closes and the node goes idle")
	-- However it is opened: the L key goes through QL:Toggle.
	T.win:ClearAllPoints()
	T.win:SetPoint("CENTER", UIParent, "CENTER", 0, 0)
	T.QL:Toggle()
	T.wr = T.M.PointAt(T.win, "RIGHT")
	check(T.win:IsShown() and T.near(T.wr, T.sx - 5.5) and T.q.lit,
		"opened by the L key it is still the node's branch, lit" .. T.say(T.wr))

	-- 4. One branch at a time: the calendar, on a client that has one.
	_G.CalendarFrame = CreateFrame("Frame", "CalendarFrame", UIParent)
	_G.CalendarFrame:Hide()
	_G.ToggleCalendar = function() _G.CalendarFrame:SetShown(not _G.CalendarFrame:IsShown()) end
	T.t:Refresh()
	check(T.c.button:IsShown() and select(2, T.M.PointAt(T.c.button, "CENTER"))
		< select(2, T.M.PointAt(T.q.button, "CENTER")) - 71,
		"a client with a calendar gets its node, below the Quest Log")
	T.c.button:GetScript("OnClick")(T.c.button)
	check(_G.CalendarFrame:IsShown() and not T.win:IsShown() and T.c.lit and not T.q.lit,
		"opening the calendar closes the log: one branch at a time")
	T.c.button:GetScript("OnClick")(T.c.button)
	check(not _G.CalendarFrame:IsShown() and not T.c.lit, "and clicked again it closes")
	-- Never loaded for the first time in a fight. ToggleCalendar loads it, as
	-- the client's does, so only the guard can keep it unloaded.
	_G.CalendarFrame = nil
	_G.ToggleCalendar = function()
		_G.CalendarFrame = _G.CalendarFrame or CreateFrame("Frame", "CalendarFrame", UIParent)
		_G.CalendarFrame:Show()
	end
	_G.__inCombat = true
	T.c.button:GetScript("OnClick")(T.c.button)
	_G.__inCombat = false
	check(_G.CalendarFrame == nil, "the calendar is not loaded in combat")
	_G.ToggleCalendar = nil

	-- 4b. Tracking is a menu, not a branch: the client's own where it has one,
	-- and on Era the right-click's cancel (Joe's Era character lists none).
	T.tr = T.t:Node("tracking")
	check(T.tr and T.tr.button:IsShown() and T.tr.button.label:GetText() == "TRACKING",
		"a Tracking node on the trunk")
	check(select(1, T.tr.button.icon:GetTexCoord()) == select(2, A.Media:Icon("tracking")),
		"wearing the tracking icon")
	T.q.button:GetScript("OnClick")(T.q.button)
	_G.__trackingMenu, _G.__trackingCancelled = nil, nil
	T.tr.button:GetScript("OnClick")(T.tr.button)
	check(T.win:IsShown() and T.q.lit, "opening it leaves the open branch alone")
	if _G.__flavour == "camelot" then
		check(_G.__trackingMenu ~= nil and _G.__trackingCancelled == nil,
			"on Forever it opens the client's tracking menu")
		check(select(2, MinimapCluster.Tracking.Button:GetPoint(1)) == T.tr.button,
			"parked on the node first, so the menu opens there and not off in a corner")
	else
		check(_G.__trackingCancelled == true and _G.__trackingMenu == nil,
			"on Era, with no tracking list, it cancels the tracking buff")
		-- With a list, a menu of the list.
		T.on = { false, true }
		_G.C_Minimap = {
			GetNumTrackingTypes = function() return 2 end,
			GetTrackingInfo = function(i) return { name = ({ "Find Herbs", "Find Minerals" })[i], active = T.on[i] } end,
			SetTracking = function(i, v) T.on[i] = v end,
		}
		_G.__trackingCancelled = nil
		T.tr.button:GetScript("OnClick")(T.tr.button)
		check(_G.__trackingMenu == T.tr.button and not _G.__trackingCancelled,
			"on Era with a tracking list, a menu at the node instead of a cancel")
		T.boxes = {}
		_G.__menuGenerator(nil, { CreateCheckbox = function(_, name, get, set)
			T.boxes[#T.boxes + 1] = { name = name, get = get, set = set }
		end })
		check(#T.boxes == 2 and T.boxes[1].name == "Find Herbs" and not T.boxes[1].get()
			and T.boxes[2].get(), "a checkbox per type, ticked when on")
		T.boxes[1].set()
		check(T.on[1] == true, "and ticking one turns it on")
		_G.C_Minimap = nil
	end
	T.q.button:GetScript("OnClick")(T.q.button)

	-- 5. Dropped on the left half, the stubs turn round.
	T.MM.frame:ClearAllPoints()
	T.MM.frame:SetPoint("TOPLEFT", UIParent, "TOPLEFT", 24, -24)
	T.t:Refresh()
	T.sx = T.M.PointAt(T.q.button.stub, "RIGHT")
	T.bx = T.M.PointAt(T.q.button, "RIGHT")
	check(T.t.side == 1 and T.near(T.sx - T.bx, 80), "on the left half its stubs run right"
		.. T.say(T.t.side, T.sx - T.bx))

	-- 6. No map, no trunk; the log off, no node.
	A:SetModuleEnabled("questlog", false)
	check(not T.q.button:IsShown(), "the quest log switched off takes its node with it")
	A:SetModuleEnabled("questlog", true)
	A:SetModuleEnabled("minimap", false)
	check(not T.f:IsShown(), "and the minimap switched off takes the trunk")
	A:SetModuleEnabled("minimap", true)
	check(T.f:IsShown() and T.q.button:IsShown(), "both back, the trunk and its node are back")

	-- Back as it was.
	T.QL:Hide()
	UIParent:SetSize(T.was.w, T.was.h)
	UIParent.__geom = nil
	A.db.profile.scale = T.was.ui
	wipe(A.db.profile.anchors)
	A:Reconfigure()
end

-- THE LAYOUT STRING (parent model phase C, Core/Layout.lua): a whole
-- arrangement as one line, read back, refused whole when it is wrong.
print("== energy ==")
do
	-- STRANDS BRIEF: every strand has a rest and a combat alpha and a
	-- hover-only flag. Defaults 100 / 100 for a strand with any key bound,
	-- 60 / 100 for one with none; hovering brings it back within 120 ms. A
	-- braid's pad takes the highest rest among its members.
	local AB, F, M, B = A:GetModule("actionbars"), A.Fader, A.Movers, A.Braids
	local fcfg = A.db.profile.fader
	local was = { enabled = fcfg.enabled, delay = fcfg.delay, target = fcfg.keepOnTarget,
		hurt = fcfg.keepOnHurt, bar2 = AB:BarConfig("2").enabled }
	fcfg.enabled, fcfg.keepOnTarget, fcfg.keepOnHurt = true, false, false
	F:Refresh()
	local function barOf(id)
		for _, b in ipairs(AB.bars) do if tostring(b.id) == id then return b end end
	end
	AB:SetBarEnabled("2", true)
	local b1, b2 = barOf("1"), barOf("2")
	local c1, c2 = AB:BarConfig("1"), AB:BarConfig("2")
	local function target(f) local e = F.watched[f]; return e and e.target end
	local function near(a, b) return a and b and math.abs(a - b) < 0.01 end
	local function say(...)
		local out = {}
		for i = 1, select("#", ...) do out[#out + 1] = tostring((select(i, ...))) end
		return " (" .. table.concat(out, ", ") .. ")"
	end
	local function awake() F:Touch(); tick(0.1) end

	-- A BAR FIRST BUILT AFTER LOGIN, by SyncBars: only login registered docks
	-- with the fader, so one switched on later was never faded at all. Every
	-- bar here is built by now, so one is taken off the fader, as such a bar
	-- was, and the next config pass has to put it on.
	F:Unregister(b2.dock)
	AB:OnConfigChanged()
	check(F.watched[b2.dock] and F.watched[b2.dock].energy,
		"a bar the fader does not know is put on it, by its energy, on the next config pass")
	awake()
	check(F.state == "awake" and near(target(b1.dock), 1) and near(target(b2.dock), 0.6),
		"at rest a keybound strand is at 100 and one with no key at 60"
		.. say(F.state, target(b1.dock), target(b2.dock)))
	_G.__inCombat = true
	awake()
	check(near(target(b2.dock), 1), "and in a fight both are at 100" .. say(target(b2.dock)))
	_G.__inCombat = false

	c2.energyAuto, c2.rest, c2.combat = false, 0.3, 0.8
	awake()
	check(near(target(b2.dock), 0.3), "a strand's own rest, once set" .. say(target(b2.dock)))
	_G.__inCombat = true
	awake()
	check(near(target(b2.dock), 0.8), "and its own combat" .. say(target(b2.dock)))
	_G.__inCombat = false

	b2.dock.__mouseOver = true
	awake()
	check(near(target(b2.dock), 1) and F.watched[b2.dock].fadeIn <= 0.12,
		"hovered, it comes back to 100 within 120 ms"
		.. say(target(b2.dock), F.watched[b2.dock].fadeIn))
	b2.dock.__mouseOver = nil
	awake()
	check(near(target(b2.dock), 0.3) and F.watched[b2.dock].fadeIn > 0.12,
		"and off it, back to its rest at the usual pace")

	c2.hoverOnly = true
	awake()
	check(near(target(b2.dock), 0), "hover-only is nothing until hovered" .. say(target(b2.dock)))
	b2.dock.__mouseOver = true
	awake()
	check(near(target(b2.dock), 1), "and all of it when hovered")
	b2.dock.__mouseOver = nil
	c2.hoverOnly = false

	-- The HUD's own idle dim stacks on top: a strand at 30 idles to 30 % of it.
	fcfg.delay = 1
	F:Touch()
	for _ = 1, 15 do tick(0.1) end
	check(F.state == "idle" and near(target(b2.dock), target(b1.dock) * 0.3)
		and target(b1.dock) < 1,
		"idle dims every strand by the same amount, its energy kept"
		.. say(F.state, target(b1.dock), target(b2.dock)))
	fcfg.delay = was.delay

	M.unlocked = true
	awake()
	check(near(target(b2.dock), 1), "in unlock every strand is at 100, to place it")
	M.unlocked = false

	-- Energy is the strand's own, not the idle fader's: with that switched off
	-- a strand still rests where it was set.
	fcfg.enabled = false
	F:Refresh()
	for _ = 1, 10 do tick(0.1) end
	check(near(target(b2.dock), 0.3) and math.abs(b2.dock:GetAlpha() - 0.3) < 0.05,
		"with the idle fade off, a strand still rests where it was set"
		.. say(target(b2.dock), b2.dock:GetAlpha()))
	fcfg.enabled = true
	F:Refresh()

	-- A braid's pad takes the highest rest among its members.
	c1.energyAuto, c1.rest = false, 0.4
	B:Join("bar2", "bar1", "RIGHT", 0)
	local pad = B.pads.bar1
	awake()
	check(pad and pad:IsShown() and near(target(pad), 0.4),
		"a braid's pad takes the highest rest among its strands" .. say(pad and target(pad)))
	c2.rest = 0.5
	awake()
	check(near(target(pad), 0.5) and near(target(b1.dock), 0.4) and near(target(b2.dock), 0.5),
		"whichever strand that is, and each strand keeps its own"
		.. say(target(pad), target(b1.dock), target(b2.dock)))
	B:Leave("bar2")

	-- The options: each strand's page, not the extra button's.
	local abg = A.Options:Build().args.actionbars
	local e = abg.args.bar2.args
	check(e.energyAuto and e.rest and e.combat and e.hoverOnly
		and abg.args.barextra.args.rest == nil,
		"every strand's page has its energy, and the extra button has none")
	check(type(e.rest.disabled) == "function" and e.rest.disabled() == false,
		"its rest and combat are there to set while it is not automatic")
	c2.energyAuto = true
	check(e.rest.disabled() == true, "and greyed out while it is")

	-- Back as it was.
	c1.energyAuto, c1.rest = true, 1
	c2.energyAuto, c2.rest, c2.combat = true, 1, 1
	fcfg.enabled, fcfg.keepOnTarget, fcfg.keepOnHurt = was.enabled, was.target, was.hurt
	AB:SetBarEnabled("2", was.bar2)
	F:Refresh()
end

print("== layout string ==")
do
	local LY, M = A.Layout, A.Movers
	local anchors = A.db.profile.anchors
	local wasScale = A.db.profile.scale
	local AB = A:GetModule("actionbars")
	local wasBar2 = AB:BarConfig("2").enabled

	-- Bar 8 is a name this addon knows and, switched off, nothing re-measures:
	-- its bond is exactly what the string said.
	-- The pet is set free by naming the screen: its module hangs it from the
	-- player, and there is no separate flag for that any more.
	local TEXT = "LAT1;b=1;barextra=player,CENTER,CENTER,0,40;"
		.. "bar8=bar1,BOTTOM,CENTER,0,-60;"
		.. "chat=screen,BOTTOMLEFT,BOTTOMLEFT,14,38;"
		.. "pet=screen,TOPRIGHT,TOPRIGHT,-20,-150"
	local layout, err = LY:Decode(TEXT)
	check(layout ~= nil, "a layout string decodes (" .. tostring(err) .. ")")
	-- The player's scale, fitted to a 1080 screen. The string does not carry
	-- one, so it is whatever the player has; this one makes chat's units -
	-- UIParent's - differ from the HUD's, which the chat check below is about.
	A.db.profile.scale = 768 / 1080
	anchors.__lockButton = { point = "CENTER", relPoint = "CENTER", x = 2, y = 164 }
	check(LY:Apply(layout), "and applies")

	local lat = anchors.bar8 and anchors.bar8.lat
	check(lat and lat.parent == "bar1" and lat.point == "BOTTOM" and lat.y == -60,
		"a bonded node is written as its bond, in its own units")
	check(anchors.pet and anchors.pet.free == true and M:ParentOf("pet") == nil,
		"a node its module hangs from another, named on the screen, is set free"
		.. " of it (" .. tostring(M:ParentOf("pet")) .. ")")
	-- The store is in the node's own units, of the frame; the string in HUD
	-- units, of the glass. Chat is at UIParent's scale, not the HUD's, and its
	-- glass reaches past its frame, so the two differ for it twice over - which
	-- is what this checks: the 14 and 38 written are where the glass is.
	local gx, gy = _G.__chatGlass()
	check(gx and LY.Ratio("chat") > 1.1 and math.abs(gx - 14) <= 1 and math.abs(gy - 38) <= 1,
		"and a node on the screen is placed in HUD units from its anchor, as written ("
		.. tostring(gx) .. ", " .. tostring(gy) .. ")")
	check(M:ParentOf("barextra") == "player",
		"and a node the string bonds elsewhere hangs from that parent now ("
		.. tostring(M:ParentOf("barextra")) .. ")")
	check(anchors.__lockButton and anchors.__lockButton.y == 164,
		"the lock pill's spot is not part of a layout and survives one")
	check(LY:Matches(layout), "and it reads back as the layout on screen")

	local out = LY:Encode()
	check(out:find("bar8=bar1,BOTTOM,CENTER,0,-60", 1, true)
		and out:find("pet=screen,TOPRIGHT,TOPRIGHT,-20,-150", 1, true)
		and not out:find("__lockButton", 1, true),
		"exported again, the bond, the freed node on the screen and nothing else"
		.. " ride along")
	local names = {}
	for n in out:gmatch(";([%w_]+)=[%w_]+,[A-Z]+,") do names[#names + 1] = n end
	local sorted = #names > 1
	for i = 2, #names do if names[i] < names[i - 1] then sorted = false end end
	check(sorted, "in a fixed order, so one arrangement is always one string")

	-- ANOTHER SCREEN: nothing in the string depends on its size.
	local wasW, wasH = UIParent:GetWidth(), UIParent:GetHeight()
	local chatX = anchors.chat.x
	UIParent:SetSize(wasW * 1.5, wasH)
	LY:Apply(layout)
	check(anchors.bar8.lat.y == -60 and anchors.chat.x == chatX,
		"on a wider screen the bond is the same and the screen node is the same"
		.. " units from its edge (" .. chatX .. " then " .. anchors.chat.x .. ")")
	UIParent:SetSize(wasW, wasH)

	-- REFUSED, WHOLE.
	local function refused(text, what)
		local l, e = LY:Decode(text)
		check(l == nil and type(e) == "string" and e ~= "",
			what .. " is refused, saying why (" .. tostring(e) .. ")")
	end
	refused("LAT2;b=1", "another version")
	-- THE SCALE IS THE PLAYER'S. A string carrying one is from before that was
	-- settled, and its offsets are in units nothing reads any more.
	refused("LAT1;s=0.71;b=1", "a scale, which is the player's to set")
	refused("LAT1;b=1;nonsense=screen,CENTER,CENTER,0,0", "a node this addon never had")
	refused("LAT1;b=1;bar8=nonsense,CENTER,CENTER,0,0", "a parent this addon never had")
	refused("LAT1;b=1;bar8=bar9,CENTER,CENTER,0,0;bar9=bar8,CENTER,CENTER,0,0",
		"a loop")
	refused("LAT1;b=1;player=bar1,CENTER,CENTER,0,0;bar1=spine,CENTER,CENTER,0,0",
		"a loop through the spine, which belongs to the player")
	refused("LAT1;b=1;chat=screen,BOTTOMLEFT,BOTTOMLEFT,nan,0", "a number that is not one")
	refused("LAT1;b=1;chat=screen,MIDDLE,BOTTOMLEFT,0,0", "a point the client has not got")
	refused("LAT1;b=1;chat=S,BOTTOMLEFT,BOTTOMLEFT,0.01000,0.05000",
		"a canvas position, as the first version wrote one")
	refused("LAT1;b=1;bar8=B,bar1,BOTTOM,CENTER,0,-60",
		"and the first version's bond, with its marker")
	refused("LAT1;b=1;target=screen,CENTER,CENTER,0,0",
		"the target hung from anything but the player, which it is one piece with")
	refused("", "nothing at all")

	-- KEY CHIPS RIDE ALONG: k= names the bars, of those b= switches on, that
	-- show them. The Block seed is the one that says so (strands brief 9c).
	check(out:find("^LAT1;b=1;k=1;") ~= nil,
		"exported, the bars showing key chips follow the bars that are on ("
		.. out:sub(1, 20) .. ")")
	local chips, cerr = LY:Decode("LAT1;b=1,2;k=2")
	check(chips and chips.keys and chips.keys["2"] and not chips.keys["1"],
		"k= decodes to the strands that show chips (" .. tostring(cerr) .. ")")
	check(chips and LY:Apply(chips) and AB:KeysShown("1") == false and AB:KeysShown("2") == true,
		"and applied, bar 1's chips go and bar 2's show")
	check(LY:Matches(chips), "and it reads back as itself")
	AB:BarConfig("2").keys = false
	check(not LY:Matches(chips), "a strand whose chips differ is another arrangement")
	local plain = LY:Decode("LAT1;b=1,2")
	check(plain and plain.keys == nil and LY:Matches(plain) and LY:Apply(plain)
		and AB:KeysShown("2") == false,
		"a string without k= says nothing about chips, and leaves them as they are")
	refused("LAT1;b=1;k=2", "chips on a bar the string leaves off")
	refused("LAT1;b=1;k=x", "chips on a bar that is not a number")
	AB:BarConfig("1").keys, AB:BarConfig("2").keys = true, true
	LY:Apply(layout)

	_G.__inCombat = true
	local before = anchors.chat.x
	local ok, why = LY:Apply(layout)
	_G.__inCombat = false
	check(not ok and why == A.L.layout.err.combat and anchors.chat.x == before,
		"and nothing is applied in combat")

	-- THE WINDOW: the string in the box, the reason when one is refused.
	SlashCmdList["AETHERUI"]("layout")
	local f = LY.frame
	check(f and f:IsShown() and f.box:GetText() == LY:Pack(LY:Encode())
		and f.box:GetText():find("^!LAT1!") ~= nil,
		"/lattice layout opens the window with the arrangement in it, in the"
		.. " share form")
	LY:ApplyText("LAT9;nope")
	check(f.status:GetText() and f.status:GetText():find("LAT9", 1, true),
		"a refused paste says why, in the window")
	LY:ApplyText(TEXT)
	check(f.status:GetText() == A.L.layout.window.applied, "and a good one is applied")
	f:Hide()

	-- A PROFILE FROM BEFORE THE LANES. The floating cast bars left `cast` and
	-- `targetcast` in every profile that ever moved them, and exporting wrote
	-- them out - so Joe's own string came back "names cast, which isn't a
	-- frame Lattice has" (2026-10-08). This suite's profile had never held one.
	anchors.cast = { point = "CENTER", relPoint = "CENTER", x = -430, y = -31 }
	anchors.targetcast = { point = "CENTER", relPoint = "CENTER", x = 429, y = -34 }
	local legacy = LY:Encode()
	check(not legacy:find("cast=", 1, true),
		"a position left behind by a frame that is gone is not exported")
	local back, why2 = LY:Decode(legacy)
	check(back ~= nil and LY:Apply(back),
		"so what Export writes, Apply takes back (" .. tostring(why2) .. ")")

	-- And the empty layout still matches a profile whose only positions are
	-- leftovers: they move nothing.
	wipe(anchors)
	anchors.cast = { point = "CENTER", relPoint = "CENTER", x = -430, y = -31 }
	local bareBars = {}
	for id, on in pairs(LY.BarsNow() or {}) do bareBars[id] = on or nil end
	check(LY:Matches({ bars = bareBars, records = {} }),
		"and a leftover position does not make an untouched profile look moved")

	-- A BAR CARRIES ITS SHAPE AND SIZE (the strands brief's seeds are parents
	-- and shapes). Rows is what a bar stores; size is the button as drawn.
	local AB1 = AB:BarConfig("1")
	local wasRows, wasBarScale = AB1.rows, AB1.scale
	wipe(anchors)
	A:Reconfigure()
	M:RestoreAll()
	local untouched = LY:Encode()
	check(untouched:find(";bar1=[%w_]+,[A-Z]+,[A-Z]+,%-?%d+,%-?%d+,12x1,%d+") ~= nil,
		"a bar nobody has moved is still written, with its shape - a seed of"
		.. " untouched bars would otherwise say nothing (" .. untouched:sub(1, 120) .. ")")

	local SHAPED = "LAT1;b=1;bar1=spine,BOTTOM,CENTER,0,-96,3x4,28"
	local shaped, whyShaped = LY:Decode(SHAPED)
	check(shaped and shaped.records.bar1.rows == 4 and shaped.records.bar1.px == 28,
		"a bar record reads its shape and size (" .. tostring(whyShaped) .. ")")
	LY:Apply(shaped)
	local c1, r1, px1 = LY.BarShape("1")
	check(AB1.rows == 4 and c1 == 3 and r1 == 4 and px1 == 28,
		"and applying it draws the bar 3 x 4 at 28 px (" .. tostring(c1) .. "x"
		.. tostring(r1) .. " at " .. tostring(px1) .. ")")
	check(LY:Encode():find("bar1=spine,BOTTOM,CENTER,0,-96,3x4,28", 1, true) ~= nil,
		"and writes it back exactly")
	check(LY:Matches(shaped), "and reads back as the layout on screen")
	AB1.cols = 12
	check(not LY:Matches(shaped),
		"but a bar in another shape is another arrangement, wherever it sits")

	refused("LAT1;b=1;barextra=bar1,BOTTOM,CENTER,0,0,1x1,30",
		"a shape on the extra-action button, which is one button")
	refused("LAT1;b=1;chat=screen,BOTTOMLEFT,BOTTOMLEFT,14,38,12x1,36",
		"a shape on something that is not a bar")
	refused("LAT1;b=1;bar1=spine,BOTTOM,CENTER,0,-96,0x12,36", "a shape of nothing")
	refused("LAT1;b=1;bar1=spine,BOTTOM,CENTER,0,-96,12x1,200", "a button 200 px across")

	-- THE CHAT WINDOW CARRIES ITS SIZE (Joe, 2026-10-08), in its own units -
	-- its text and its smallest size are in UIParent's - and nothing else does.
	do
		local CF = _G.ChatFrame1
		local cw, ch = CF:GetWidth(), CF:GetHeight()
		local saved = A.db.char.chat or {}
		local sw0, sh0 = saved.w, saved.h
		local sized, whySized = LY:Decode("LAT1;b=1;chat=screen,BOTTOMLEFT,BOTTOMLEFT,24,24,320x160")
		check(sized and sized.records.chat.w == 320 and sized.records.chat.h == 160,
			"a chat record with a size decodes (" .. tostring(whySized) .. ")")
		check(sized and LY:Apply(sized), "and applies")
		check(math.abs(CF:GetWidth() - 320) < 1 and math.abs(CF:GetHeight() - 160) < 1,
			"and the window takes that size, in its own units (" .. ("%.1f x %.1f"):format(
			CF:GetWidth(), CF:GetHeight()) .. ")")
		check(LY:Encode():find("chat=screen,BOTTOMLEFT,BOTTOMLEFT,24,24,320x160", 1, true) ~= nil,
			"and is written back with it (" .. tostring(LY:Encode():match("chat=[^;]*")) .. ")")
		check(LY:Matches(sized), "and reads back as the layout on screen")
		CF:SetSize(cw + 40, ch)
		check(not LY:Matches(sized), "but a window of another size is another arrangement")
		CF:SetSize(cw, ch)
		if A.db.char.chat then A.db.char.chat.w, A.db.char.chat.h = sw0, sh0 end
	end
	refused("LAT1;b=1;chat=screen,BOTTOMLEFT,BOTTOMLEFT,24,24,0x150", "a window of no width")
	refused("LAT1;b=1;player=screen,CENTER,CENTER,0,0,300x150",
		"a size on something that is not the chat window")

	-- AND NOTHING OPTIONS CAN SET IS REFUSED: the extremes of the base size and
	-- the bar scale both export and import. A limit tighter than options would
	-- be the cast-bar bug again - a string Export writes that Apply refuses.
	for _, ext in ipairs({ { 24, 0.4 }, { 80, 2.0 } }) do
		local wasSize = AB1.size
		AB1.size, AB1.scale = ext[1], ext[2]
		local text = LY:Encode()
		local back, whyBack = LY:Decode(text)
		check(back ~= nil, ("a bar at size %d and scale %.1f exports and imports (%s)"):format(
			ext[1], ext[2], tostring(whyBack)))
		AB1.size = wasSize
	end

	-- THE SHARE FORM: the readable text, Deflated and Base64'd behind its
	-- version, through C_EncodingUtil - real Deflate in this mock.
	local plain = LY:Encode()
	local packed = LY:Pack(plain)
	check(packed:find("^!LAT1![%w%+/=]+$") ~= nil and #packed < #plain,
		"the share form is the version, then Base64, and shorter than the text ("
		.. #packed .. " against " .. #plain .. ")")
	check(LY:Unpack(packed) == plain, "and unpacks to exactly the text it was made from")
	local viaPacked = LY:Decode(packed)
	check(viaPacked and LY:Matches(viaPacked),
		"and a packed string imports like the plain one")
	check(LY:Decode(plain) ~= nil, "the readable form still imports as it is")

	refused(packed:sub(1, math.floor(#packed / 2)), "a share string cut short in a paste")
	refused(packed:sub(1, -6) .. "QUJD" .. packed:sub(-1),
		"a share string with characters changed in it")
	refused("!LAT2!" .. packed:sub(7), "a share string of another version")
	check(select(2, LY:Decode(packed:sub(1, 30))) == A.L.layout.err.packed,
		"and the cut-short one says so in words, rather than naming a part")

	-- WHATEVER COMES WITH IT IS LEFT BEHIND. Joe pasted the whole table the old
	-- capture printed - `test = {`, the screen comment, `layout = "..."` - and
	-- the box refused it. A string off a forum or out of Discord arrives the
	-- same way: in quotes, after a label, with a line ending on it.
	local wrapped = {
		{ "    test = {\n        -- captured on a 4056 x 1690 screen\n        layout = \""
			.. plain .. "\",\n    },", "the table capture used to print" },
		{ "\"" .. plain .. "\"", "the readable string in quotes" },
		{ "layout: " .. plain .. "\r\n", "the readable string after a label" },
		{ "  " .. packed .. "  \n", "the share string with space round it" },
		{ "'" .. packed .. "'.", "the share string in quotes, with a full stop" },
	}
	for _, w in ipairs(wrapped) do
		local got, whyGot = LY:Decode(w[1])
		check(got ~= nil and LY:Matches(got),
			"a layout pasted as " .. w[2] .. " imports as the string alone ("
			.. tostring(whyGot) .. ")")
	end
	refused("test = { layout = \"hello\" }", "text with no layout string in it")

	AB1.rows, AB1.scale = wasRows, wasBarScale

	-- Everything back the way the suite had it.
	wipe(anchors)
	for _, e in pairs(M.registry) do e.parent, e.free = e.defaultParent, nil end
	A.db.profile.scale = wasScale
	AB:SetBarEnabled("2", wasBar2)
	A:Reconfigure()
	M:RestoreAll()
end

print("== zen: it eases out rather than snapping ==")
do
	local Z = A:GetModule("zen")
	local cfg = A.Config:Module("zen")
	local f = Z.frame

	-- ZEN ENDING WANTS A SHAPE OF ITS OWN. It used to borrow the HUD's
	-- fade-in - 0.30 - and step PROPORTIONALLY, fourteen per cent of whatever
	-- was left every frame. An exponential decay is front-loaded: half of it
	-- is gone in five frames and the rest trails away under the eye, which
	-- reads as a snap with a tail rather than as something ending.
	-- Through the module's own door, which is what registers the ticker that
	-- drives the fade - the fade function itself is a file local.
	Z:SetActive(false)
	f:SetAlpha(1)
	Z._out = nil

	-- A TENTH OF THE WAY IN it has barely moved, because smoothstep is slow
	-- at both ends. The old curve was a fifth of the way gone by here.
	tick((cfg.easeOut or 0.8) * 0.1)
	check(f:GetAlpha() > 0.9,
		"a tenth of the way out, zen has barely started to go (" ..
		string.format("%.2f", f:GetAlpha()) .. ")")

	-- HALFWAY THROUGH IT IS HALFWAY OUT, which is what a fixed time buys: the
	-- fade is the same length however far it has to travel.
	tick((cfg.easeOut or 0.8) * 0.4)
	check(math.abs(f:GetAlpha() - 0.5) < 0.08,
		"halfway through the time, halfway out (" ..
		string.format("%.2f", f:GetAlpha()) .. ")")

	-- AND IT IS STILL GOING AT HALF A SECOND, which is the whole of the
	-- report: the old one was done in a fifth of that.
	check((cfg.easeOut or 0.8) >= 0.5,
		"and the whole of it takes at least half a second (" ..
		tostring(cfg.easeOut) .. "s)")

	-- THEN IT ARRIVES. The rest of the time and a frame to park.
	tick((cfg.easeOut or 0.8) * 0.6)
	tick(0.05)
	check(f:GetAlpha() <= 0.001,
		"and it gets all the way there (" ..
		string.format("%.3f", f:GetAlpha()) .. ")")

	-- FROM WHEREVER IT HAD GOT TO. The player can move at any point in the
	-- fade IN, so the fade out starts from that alpha and still takes its own
	-- time rather than being quicker because there was less to do.
	Z:SetActive(false)
	f:SetAlpha(0.5)
	Z._out = nil
	tick((cfg.easeOut or 0.8) * 0.5)
	check(math.abs(f:GetAlpha() - 0.25) < 0.05,
		"starting from half, it is a quarter at the halfway mark - the same "
		.. "length of fade, not a quicker one (" ..
		string.format("%.2f", f:GetAlpha()) .. ")")

	-- AND THE TRACK FADES WITH IT. This used to ramp only for somebody whose
	-- own music volume was UNDER zen's floor; anybody above it got no ramp at
	-- all - the track started at full and StopMusic cut it dead.
	do
		local seen = {}
		local realSet = _G.SetCVar
		_G.SetCVar = function(name, value)
			if name == "Sound_MusicVolume" then seen[#seen + 1] = tonumber(value) end
			return realSet(name, value)
		end

		-- Well above zen's floor, which is the case that had no ramp.
		realSet("Sound_MusicVolume", "1.0")
		Z._audio = nil
		Z:SetAudio(1)
		Z:SetAudio(0.5)
		Z:SetAudio(0.1)
		_G.SetCVar = realSet

		-- COUNTED, not indexed: Borrow writes only when the value CHANGES, so at
		-- the top of the fade - where the track plays at the player's own level -
		-- there is nothing to write and no call to see.
		local falling = #seen > 0
		for i = 2, #seen do
			if seen[i] >= seen[i - 1] then falling = false end
		end
		local low = seen[#seen]
		check(falling and #seen >= 2,
			"the track's volume comes down with the readout rather than playing "
			.. "at full until StopMusic cuts it (" ..
			table.concat(seen, " to ") .. ")")
		check(low and low < 0.2,
			"and is all but silent by the time the readout is (" ..
			tostring(low) .. ")")

		-- AND THE PLAYER'S OWN SETTING COMES BACK, whatever we left it at.
		Z:RestoreAudio()
		check(tonumber(GetCVar("Sound_MusicVolume")) == 1.0,
			"and the player's own volume is handed back untouched (" ..
			tostring(GetCVar("Sound_MusicVolume")) .. ")")
	end

	Z.want = 0
	f:SetAlpha(0)
	Z._out = nil
end
print("== toolbox: the trunk breathes with everything else ==")
do
	local TBm = A:GetModule("toolbox")
	-- The glyph and the trunk sit on screen at all times, next to things that
	-- dim when you stand still; the branches and pins hang off the trunk.
	check(A.Fader.watched[TBm.root] ~= nil, "the glyph is registered with the fader")
	check(A.Fader.watched[A.Trunk:Get("toolbox").frame] ~= nil, "and so is the trunk")
	check(TBm.rail == nil and TBm.panel == nil and TBm.scrim == nil,
		"and the drawer, its rail and its scrim are gone")
end

print("== toolbox: the trunk, on the board ==")
do
	-- LATTICE 5b and 6a at 1920 x 1080: the Cell glyph at (40, 300), the first
	-- node 72 under it and the rest 72 apart, stubs toward the centre, the
	-- pinned addons hanging below the last node.
	local TBm, LN = A:GetModule("toolbox"), A.Launchers
	local K = { t = A.Trunk:Get("toolbox"), M = A.Movers,
		was = { ui = A.db.profile.scale, w = UIParent:GetWidth(), h = UIParent:GetHeight() } }
	function K.near(a, b) return a and b and math.abs(a - b) <= 0.5 end
	function K.at(f, p)
		local x, y = K.M.PointAt(f, p or "CENTER")
		return x, y and (UIParent:GetHeight() - y)
	end
	UIParent:SetSize(1920, 1080)
	UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
	A.db.profile.scale = 1
	A:Reconfigure()
	TBm:SetDock("LEFT")

	K.rx, K.ry = K.at(TBm.root)
	check(TBm.root:IsShown() and K.near(K.rx, 40) and K.near(K.ry, 300),
		"the Cell glyph sits at 40, 300" .. " (" .. tostring(K.rx) .. ", " .. tostring(K.ry) .. ")")
	check(TBm.root.glyph:GetTexture() == A.Media.texture.icon, "wearing the addon's mark")
	K.ys, K.order = {}, { "menu", "widgets", "addons", "settings", "news" }
	for i, key in ipairs(K.order) do
		local n = K.t:Node(key)
		local x, y = K.at(n.button)
		K.ys[i] = y
		check(n.button:IsShown() and K.near(x, 40) and K.near(y, 300 + 72 * i),
			key .. " is node " .. i .. ", at 40, " .. (300 + 72 * i) .. " (" .. tostring(x) .. ", " .. tostring(y) .. ")")
	end
	check(K.t.side == 1, "its stubs run right, toward the centre")
	check(K.t:Node("menu").button.label:GetText() == "MENU"
		and K.t:Node("news").button.label:GetText() == "WHAT'S NEW", "labelled in capitals")

	-- Pins: three launchers pinned hang below What's new, 32 apart, each the
	-- addon's own button on a bare node of the trunk.
	for i = 1, 3 do
		_G.__makeLDB("RailFit" .. i, "launcher")
		_G.__makeDBIcon("RailFit" .. i)
	end
	LN:Scan()
	TBm:ClaimPins()
	for i = 1, 3 do TBm:SetPinned("RailFit" .. i, true) end
	K.bottom = K.t.frame:GetHeight()
	for i = 1, 3 do
		local e = LN.byKey["RailFit" .. i]
		local node = TBm.pinNodes[i]
		local x, y = K.at(e.button)
		check(e.button:GetParent() == node.button and node.button:IsShown()
			and K.near(x, 40) and K.near(y, K.ys[5] + 36 + 32 * (i - 1))
			and math.abs(e.button:GetWidth() - 24) < 0.5,
			"pin " .. i .. " hangs on the trunk below the last node, 24 across ("
			.. tostring(x) .. ", " .. tostring(y) .. ")")
	end
	check(not TBm.pinNodes[1].button.fill:IsShown(), "on a bare node: no diamond of its own")
	_G.__makeLDB("RailFit4", "launcher"); _G.__makeDBIcon("RailFit4")
	LN:Scan(); TBm:ClaimPins(); TBm:SetPinned("RailFit4", true)
	check(K.t.frame:GetHeight() > K.bottom, "one more pin makes the strand longer ("
		.. tostring(K.bottom) .. " -> " .. tostring(K.t.frame:GetHeight()) .. ")")
	TBm:SetPinned("RailFit4", false)
	check(not TBm.pinNodes[4].button:IsShown() and LN:OwnerOf(LN.byKey.RailFit4) == TBm,
		"unpinned, its node goes and the button is still ours, parked")

	-- Swapped: the trunk on the right, the minimap mirrored to the left.
	K.MM = A:GetModule("minimap")
	K.mx = K.at(K.MM.frame)
	check(K.mx and K.mx > 960, "the minimap starts on the right")
	check(TBm:SetDock("RIGHT"), "docked right")
	K.rx = K.at(TBm.root)
	check(K.near(K.rx, 1880) and K.t.side == -1, "the glyph is 40 in from the right edge, stubs left ("
		.. tostring(K.rx) .. ")")
	K.mx2 = K.at(K.MM.frame)
	check(K.near(K.mx2, 1920 - K.mx), "and the minimap is mirrored to the left ("
		.. tostring(K.mx) .. " -> " .. tostring(K.mx2) .. ")")
	check(A.Trunk:Get("world").side == 1, "its trunk's stubs turned round")
	check(not TBm:SetDock("TOP"), "top is refused: left or right only")
	TBm:SetDock("LEFT")
	check(K.near(K.at(K.MM.frame), K.mx), "back left, the minimap goes home")

	-- In unlock, a drag of the glyph to the other half swaps the trunks.
	K.open, K.opened = A.Options.Open, 0
	A.Options.Open = function() K.opened = K.opened + 1 return true end
	A.Movers:Unlock()
	TBm.root:GetScript("OnDragStart")(TBm.root)
	__setCursor(1500 * UIParent:GetEffectiveScale(), 500)
	TBm.root:GetScript("OnDragStop")(TBm.root)
	check(TBm:Dock() == "RIGHT", "dragging the glyph to the right half docks it right")
	TBm.root:GetScript("OnClick")(TBm.root)
	check(K.opened == 0, "and the release is not taken for a click")
	A.Movers:Lock()
	TBm.root:GetScript("OnDragStart")(TBm.root)
	__setCursor(200 * UIParent:GetEffectiveScale(), 500)
	TBm.root:GetScript("OnDragStop")(TBm.root)
	check(TBm:Dock() == "RIGHT", "locked, the glyph does not drag")
	TBm.root:GetScript("OnClick")(TBm.root)
	check(K.opened == 1, "and a click on it opens the settings")
	A.Options.Open = K.open
	TBm:SetDock("LEFT")

	for i = 1, 4 do TBm:SetPinned("RailFit" .. i, false) end
	UIParent:SetSize(K.was.w, K.was.h)
	UIParent.__geom = nil
	A.db.profile.scale = K.was.ui
	A:Reconfigure()
end

print("== world trunk: mail, and what the client will not tell us ==")
do
	-- The Mail node (Core/Mail.lua), which took over from the Toolbox's rail
	-- envelope and drawer section (Lattice 6a).
	local M = { t = A.Trunk:Get("world"), TB = A:GetModule("toolbox"), QL = A:GetModule("questlog") }
	M.node = M.t:Node("mail")
	M.b = M.node and M.node.button
	check(M.b and M.b:IsShown(), "the World trunk carries a Mail node")
	check(M.TB.rail == nil and M.TB.content == nil,
		"and the Toolbox carries no mail: no rail and no drawer for it to be in")
	check(MMm.mail == nil, "nor does the minimap keep a mail frame of its own")
	check(M.node.order > M.t:Node("questlog").order and M.node.order < M.t:Node("tracking").order
		and M.t:Node("tracking").order < M.t:Node("calendar").order,
		"down the trunk: Quest Log, the quests, Mail, Tracking, Calendar")

	_G.__mail, _G.__mailFrom = false, nil
	fire("UPDATE_PENDING_MAIL")
	M.empty = select(2, A.Media:Icon("mail"))
	M.full = select(2, A.Media:Icon("mailfull"))
	check(M.empty ~= M.full, "empty and full are different cells of the sheet")
	check(select(1, M.b.icon:GetTexCoord()) == M.empty and not M.b.dot:IsShown(),
		"no mail: the empty envelope and no dot")

	-- The branch, beside the stub like every other.
	M.b:GetScript("OnClick")(M.b)
	M.p = A.Mail.panel
	check(M.p and M.p:IsShown() and M.node.lit, "clicked, the Mail branch opens and the node is lit")
	if M.t.side < 0 then
		M.edge, M.want = A.Movers.PointAt(M.p, "RIGHT"), A.Movers.PointAt(M.b.stub, "LEFT") - 5.5
	else
		M.edge, M.want = A.Movers.PointAt(M.p, "LEFT"), A.Movers.PointAt(M.b.stub, "RIGHT") + 5.5
	end
	check(M.edge and M.want and math.abs(M.edge - M.want) < 0.5,
		"its edge at the stub's end (" .. tostring(M.edge) .. " vs " .. tostring(M.want) .. ")")
	check(M.p.rows[1]:IsShown() and M.p.rows[1].name:GetText() == "No unread mail"
		and M.p.rows[1].chip.label:GetText() == "0",
		"an empty box is one quiet line (got " .. tostring(M.p.rows[1].name:GetText()) .. ")")
	check(not M.p.rows[2]:IsShown() and M.p.hint:GetText() == "",
		"only the one, and no hint saying it again")

	-- Mail arrives with the branch open.
	_G.__mail, _G.__mailFrom = true, { "Thrall", "Sylvanas" }
	fire("UPDATE_PENDING_MAIL")
	check(select(1, M.b.icon:GetTexCoord()) == M.full and M.b.dot:IsShown(),
		"mail: the full envelope, and the dot")
	check(M.b.dot:GetWidth() == 7, "a 7 px dot (" .. tostring(M.b.dot:GetWidth()) .. ")")
	check(M.p.rows[1].name:GetText() == "Thrall" and M.p.rows[2].name:GetText() == "Sylvanas"
		and not M.p.rows[3]:IsShown(), "the branch lists the senders the client named, in order")
	check(M.p.rows[1].chip.label:GetText() == "T" and M.p.rows[2].chip.label:GetText() == "S",
		"each with its initial")
	check(M.p.hint:GetText() == "2 new", "the count is exact below the client's cap ("
		.. tostring(M.p.hint:GetText()) .. ")")
	check(not M.p.note:IsShown(), "with no note under two")
	M.h = M.p:GetHeight()

	-- At the cap the number stops being a total.
	_G.__mailFrom = { "Thrall", "Sylvanas", "Jaina" }
	fire("UPDATE_PENDING_MAIL")
	check(M.p.hint:GetText() == "3+ new" and M.p.rows[3]:IsShown(),
		"at three it reads 3+: three is the client's cap, not the total ("
		.. tostring(M.p.hint:GetText()) .. ")")
	check(M.p.note:IsShown() and M.p.note:GetText() == "The game names only three senders.",
		"and says the game names only three")
	check(M.p:GetHeight() > M.h, "the branch grows to hold them ("
		.. tostring(M.h) .. " -> " .. tostring(M.p:GetHeight()) .. ")")

	-- Mail with nobody's name on it: auction house and NPC mail.
	_G.__mailFrom = nil
	fire("UPDATE_PENDING_MAIL")
	check(M.b.dot:IsShown() and M.p.rows[1].chip.label:GetText() == "?"
		and M.p.rows[1].name:GetText() == "Senders show after a mailbox visit"
		and not M.p.rows[2]:IsShown(),
		"mail with no sender: one row saying where the names are")
	check(M.p.hint:GetText() == HAVE_MAIL and not M.p.note:IsShown(),
		"and the client's own wording for the hint")

	-- WHAT THE MAILBOX KNOWS.
	_G.__inbox = {
		{ sender = "Thrall",   subject = "Warchief business", read = false },
		{ sender = "Thrall",   subject = "Again",             read = false },
		{ sender = "Vol'jin",  subject = "Darkspear",         read = false },
		{ sender = "Cairne",   subject = "Read already",      read = true  },
		{ sender = "Sylvanas", subject = "Forsaken",          read = false },
	}
	fire("MAIL_INBOX_UPDATE")
	M.has, M.senders, M.unread, M.stale = A.Mail:State()
	check(M.unread == 4, "a true unread count at a mailbox, the read one left out ("
		.. tostring(M.unread) .. ")")
	check(#M.senders == 3 and M.senders[1] == "Thrall" and M.senders[2] == "Vol'jin",
		"senders once each, in the box's order")
	check(M.stale == true, "and flagged as remembered rather than current")
	check(A.db.char.toolbox.mail and A.db.char.toolbox.mail.unread == 4,
		"kept where the Toolbox kept it, so nothing saved is lost")
	check(M.p.hint:GetText() == "4 unread \194\183 last visit" and M.p.rows[1].chip.label:GetText() == "T",
		"the branch marks them as the last visit (" .. tostring(M.p.hint:GetText()) .. ")")
	check(not M.p.note:IsShown(), "no cap note: the box's own list is not capped")

	-- Walk away: the record outlives the mailbox.
	_G.__inbox = nil
	fire("UPDATE_PENDING_MAIL")
	check(select(3, A.Mail:State()) == 4, "and it survives leaving the mailbox")
	-- The client's answer wins when it has one.
	_G.__mailFrom = { "Jaina" }
	fire("UPDATE_PENDING_MAIL")
	M.has, M.senders, M.unread, M.stale = A.Mail:State()
	check(M.senders[1] == "Jaina" and #M.senders == 1 and not M.stale and not M.unread,
		"mail that arrives now is named by the client and takes precedence")
	-- An empty box clears the record, rather than leaving zeroes.
	_G.__mailFrom = nil
	_G.__inbox = { { sender = "Thrall", read = true } }
	fire("MAIL_INBOX_UPDATE")
	check(select(3, A.Mail:State()) == nil and A.Mail:Record() == nil,
		"an empty box clears the record, and nothing is left in saved variables")
	_G.__inbox = nil

	-- A name that starts with a multi-byte character gives a whole one.
	_G.__mail, _G.__mailFrom = true, { "\195\150lrun", "Thrall" }
	fire("UPDATE_PENDING_MAIL")
	check(M.p.rows[1].chip.label:GetText() == "\195\150",
		"a multi-byte initial is a whole character (" .. tostring(M.p.rows[1].chip.label:GetText()) .. ")")

	-- Emptied at a mailbox: MAIL_INBOX_UPDATE alone puts the envelope back.
	_G.__mail, _G.__mailFrom = false, nil
	fire("MAIL_INBOX_UPDATE")
	check(select(1, M.b.icon:GetTexCoord()) == M.empty and not M.b.dot:IsShown(),
		"emptying the box at a mailbox puts the empty envelope back")

	-- One branch at a time, Escape, the retract, and its own node again.
	M.q = M.t:Node("questlog")
	M.q.button:GetScript("OnClick")(M.q.button)
	check(not M.p:IsShown() and M.QL.win:IsShown() and not M.node.lit,
		"opening the Quest Log closes the Mail branch")
	M.q.button:GetScript("OnClick")(M.q.button)
	M.found = false
	for _, n in ipairs(UISpecialFrames or {}) do if n == M.p:GetName() then M.found = true end end
	check(M.found, "Escape closes it: the branch is in UISpecialFrames")
	M.b:GetScript("OnClick")(M.b)
	M.t:SetRetracted(true, true)
	check(not M.p:IsShown(), "the trunk retracting takes the branch with it")
	M.t:SetRetracted(false, true)
	M.b:GetScript("OnClick")(M.b)
	M.b:GetScript("OnClick")(M.b)
	check(not M.p:IsShown() and not M.node.lit, "and clicking its node again closes it")
end

print("== launchers: what counts as somebody's button ==")
do
	local LN = A.Launchers

	-- These assertions used to live in "the button drawer". The drawer is gone -
	-- the Toolbox rail is the only surface now - but what it knew about OTHER
	-- ADDONS' buttons is the hardest-won thing in this codebase and none of it
	-- was about minimaps. It moved with the code.

	local dbi = _G.__makeDBIcon("BigWigs")
	local own = CreateFrame("Button", "SomeAddonMinimapButton", Minimap)
	own:SetScript("OnDragStart", function() end)
	local pin = CreateFrame("Frame", "QuestieFramePin42", Minimap)
	local bliz = CreateFrame("Button", "MiniMapTracking", Minimap)
	_G.__secureNames["MiniMapTracking"] = true

	LN:Scan()

	check(LN.seen[dbi] ~= nil, "a LibDBIcon button is found")
	check(LN.seen[own] ~= nil, "and so is an addon that rolled its own")
	check(LN.seen[pin] == nil,
		"but a map pin is not - Questie and HandyNotes put THOUSANDS of children"
		.. " on the minimap and none of them is a button")
	check(LN.seen[bliz] == nil,
		"and neither is Blizzard's own furniture, which issecurevariable sorts"
		.. " from the arrivals with no name list to keep up to date")

	-- Pacified, so the library stops yanking them back onto the ring.
	local e = LN.seen[dbi]
	LN:Claim(e, {})
	check(dbi.__locked,
		"a LibDBIcon button is Locked THROUGH the library, which is the"
		.. " supported way and survives a Refresh - its drag handler recomputes"
		.. " an angle from the cursor and re-anchors every frame otherwise")
	local eo = LN.seen[own]
	LN:Claim(eo, {})
	check(own:GetScript("OnDragStart") == nil,
		"and a hand-rolled one has its drag scripts taken off instead")

	-- Skinned by the SERVICE, so every surface gets the same treatment. It used
	-- to happen inside the drawer's Collect, which would have left the rail
	-- showing whatever bevel each addon shipped.
	check(dbi.__aetherSkinned and dbi.__aetherRing ~= nil,
		"skinning happens in Core/Launchers.lua rather than in whichever module"
		.. " claimed the button - it is a fact about somebody else's frame, not"
		.. " about a minimap")
	check(dbi.border == nil or not dbi.border:IsShown(),
		"with whatever bevel it arrived with switched off")

	do
		-- The rule is "keep the icon, hide every other texture", not "match the
		-- bevel against a list of known files" - an addon's border is whatever
		-- that addon shipped, and there is no list that covers that.
		local kept, hidden = 0, 0
		for _, r in ipairs({ dbi.icon, dbi.border, dbi.background }) do
			if r and r.IsShown then
				if r:IsShown() then kept = kept + 1 else hidden = hidden + 1 end
			end
		end
		check(kept == 1 and hidden == 2,
			"the icon is kept and everything else is hidden (" .. kept
			.. " kept, " .. hidden .. " hidden)")
	end

	-- SOMEBODY ELSE'S SPELLING OF "MINIMAP". There is no agreed one - Blizzard's
	-- own interface says MiniMapTracking and MinimapBorder in the same breath,
	-- and addons follow whichever they read first. SmartBuff's button is
	-- SmartBuff_MiniMapButton, which every pattern here was written past, so it
	-- stayed on the ring beside the map while the same addon's broker launcher
	-- sat in the drawer and the player had the button twice.
	do
		_G.__makeLDB("SmartBuff", "launcher")
		local loose = CreateFrame("Button", "SmartBuff_MiniMapButton", Minimap)
		LN:Scan()

		local entry = LN.seen[loose]
		check(entry ~= nil,
			"a button that spells it MiniMapButton is collected too - the word"
			.. " has two spellings and both are somebody's button")
		check(entry == LN.byKey["SmartBuff"],
			"and joins the launcher its own addon registered rather than arriving"
			.. " as a second entry: Broker_SmartBuff registers SmartBuff and"
			.. " SmartBuff builds SmartBuff_MiniMapButton, and the same addon"
			.. " twice in the drawer is the bug the player was reporting")
		check(entry.button == loose and not entry.owned,
			"with the addon's real button in place of our proxy, because that is"
			.. " the one carrying its own click behaviour")
	end

	-- AND WHEN THE NAME DOES NOT SAY. Enchantrix registers a launcher called
	-- "Enchantrix" and builds a button called EnxMiniMapIcon, and no amount of
	-- stripping "minimap icon" off one end of that gets to the other. The client
	-- knows, though: issecurevariable's second return is the addon that tainted
	-- the global, which is the only thing in the game that can say so.
	do
		_G.__makeLDB("Enchantrix", "launcher")
		local enx = CreateFrame("Button", "EnxMiniMapIcon", Minimap)
		_G.__taintedBy["EnxMiniMapIcon"] = "Enchantrix"
		LN:Scan()

		local entry = LN.seen[enx]
		check(entry == LN.byKey["Enchantrix"],
			"a button whose name shares nothing with its addon still joins that"
			.. " addon's launcher, because the client is asked who made it rather"
			.. " than the name being read for clues")
		check(LN.byKey["EnxMiniMapIcon"] == nil,
			"and no second entry is left under the button's own name")
	end

	-- Arrivals after the sweep. There is no event for "a child was added to the
	-- minimap", so the registry callback is the only thing that catches an addon
	-- finishing its load late.
	local late = _G.__makeDBIcon("Later")
	check(LN.seen[late] ~= nil,
		"a button created after the sweep arrives through LibDBIcon's own"
		.. " creation callback")

	-- Somebody else's "hide until you hover the minimap".
	--
	-- This is the one that looked most like our bug and was least like it. The
	-- flag is per button, but the library's handlers walk the WHOLE registry, so
	-- hovering anything anywhere faded every adopted button back out a second
	-- later. On a minimap that preference is reasonable; on a rail in a drawer
	-- it is just a missing icon, and it followed the button when we adopted it.
	do
		local ldbi = LibStub("LibDBIcon-1.0", true) or _G.__ldbi
		local fade = _G.__makeDBIcon("Fader")
		_G.__makeLDB("Fader", "launcher")
		ldbi:ShowOnEnter("Fader", true)
		check(fade.showOnMouseover and fade:GetAlpha() == 0,
			"an addon really can hide a registered button until mouseover")

		-- Note the ORDER this test happens in, because it is the order the game
		-- happens in: __makeDBIcon fires LibDBIcon_IconCreated, we adopt the
		-- button in that callback, and only THEN does the other addon's handler
		-- for the same callback set the flag. Prepare has already run and will
		-- early-out for the rest of the session, so a fix that only lives there
		-- leaves the button faded until the next full layout.
		LN:Scan()
		local fe = LN.seen[fade]
		check(fe and fe._prepared,
			"the button was adopted BEFORE the flag was set - both addons are"
			.. " listening to the same LibDBIcon callback")

		LN:Claim(fe, {})

		check(not fade.showOnMouseover,
			"adopting a button clears it - alpha alone would lose to the next"
			.. " fadeOut, and the flag is the only thing gating that call")
		check(fade:GetAlpha() == 1, "and the button is visible now")

		ldbi:__mouseLeftEverything()
		check(fade:GetAlpha() == 1,
			"so the cursor leaving something else entirely no longer takes it"
			.. " away - the library fades every button it knows about, not the"
			.. " one being hovered")

		LN:Release(fe)
	end

	LN:Release(LN.seen[dbi]); LN:Release(LN.seen[own])
end

print("== launchers: the two mechanisms, merged ==")
do
	local LN = A.Launchers
	local ldb = LibStub("LibDataBroker-1.1")

	-- The guard test. Everything else in this block is only meaningful if the
	-- library really is the one with the metatable, so prove it first: a real
	-- dataobj keeps nothing on the table itself.
	do
		local obj = _G.__makeLDB("ProbeAddon", "launcher")
		local n = 0
		for _ in pairs(obj) do n = n + 1 end
		check(n == 0 and obj.type == "launcher",
			"a real LDB dataobj is EMPTY to pairs() while indexing fine - every"
			.. " field lives in the library's attributestorage behind __index."
			.. " A mock that stored them on the table would be the one shape in"
			.. " which walking one works, and this whole block would prove"
			.. " nothing (" .. n .. " keys, type=" .. tostring(obj.type) .. ")")
	end

	-- A launcher whose addon never made a minimap button. The OLD collector
	-- could not see this at all: it only ever walked what was already parented
	-- onto the map.
	local clicked
	_G.__makeLDB("LauncherOnly", "launcher", {
		label = "Launcher Only",
		OnClick = function(_, btn) clicked = btn or true end,
	})
	LN:Scan()
	A:GetModule("toolbox"):ClaimPins()

	local e = LN.byKey["LauncherOnly"]
	check(e ~= nil, "an LDB launcher with no minimap button is found at all -"
		.. " which the minimap-only collector could never do")
	check(e and e.button and e.owned,
		"and is given a proxy frame of OUR making, so every consumer has exactly"
		.. " one job: place entry.button")
	A:GetModule("toolbox"):ClaimPins()
	check(e and A.Launchers:OwnerOf(e) ~= nil,
		"and the rail adopts it alongside the real buttons")

	-- Read at call time, never captured. An addon is entitled to swap its own
	-- handler after login.
	LN:Click(e, "LeftButton")
	check(clicked == "LeftButton", "clicking it runs the object's OnClick")
	e.obj.OnClick = function() clicked = "replaced" end
	LN:Click(e, "LeftButton")
	check(clicked == "replaced",
		"and a handler swapped AFTER registration is the one that runs - Titan"
		.. " re-reads it at click time for this reason, and a captured reference"
		.. " would go stale silently rather than erroring")

	-- Both mechanisms, one addon. LibDBIcon keys lib.objects by the LDB name,
	-- which is the whole basis of the dedupe.
	local before = LN:Count()
	_G.__makeLDB("BothWays", "launcher", { label = "Both Ways" })
	local btn = _G.__makeDBIcon("BothWays")
	LN:Scan()
	A:GetModule("toolbox"):ClaimPins()
	check(LN:Count() == before + 1,
		"an addon offering a launcher AND a LibDBIcon button is ONE entry, not"
		.. " two - they share a name, which is what LibDBIcon keys on ("
		.. before .. " -> " .. LN:Count() .. ")")
	local both = LN.byKey["BothWays"]
	check(both and both.button == btn and not both.owned,
		"and the real button wins over the proxy - it is the one carrying that"
		.. " addon's own click behaviour")

	-- A data source is a readout, not something to click.
	_G.__makeLDB("SomeReadout", "data source", { text = "1234" })
	LN:Scan()
	A:GetModule("toolbox"):ClaimPins()
	check(LN.byKey["SomeReadout"] == nil,
		"a `data source` is NOT an addon entry - it is a number to display, and"
		.. " the Toolbox puts those to a different use entirely")

	-- One owner. Two surfaces positioning the same borrowed frame is a bug that
	-- only appears for whoever has both switched on.
	-- One owner. The Toolbox rail holds every entry now, so the case worth
	-- pinning down is a second surface trying to take one from it.
	local holder = LN:OwnerOf(both)
	local other = {}
	check(holder ~= nil, "something owns it")
	check(not LN:Claim(both, other),
		"a second surface cannot claim an entry the first one holds")
	check(LN:OwnerOf(both) == holder, "the first owner keeps it")
	check(LN:Claim(both, other, true),
		"and a FORCED claim takes it, which is what a pin is")

	-- Releasing PARKS it rather than leaving it stranded wherever its last owner
	-- put it. That is the fix for an unpinned icon sitting on top of the gear:
	-- unowned used to mean laid out by nobody, so it persisted where it was.
	LN:Release(both, other)
	check(both._parked, "and releasing parks it")
	A:GetModule("toolbox"):ClaimPins()
end

print("== reading surfaces reach solid ==")
do
	local cfg = A.db.profile.glass
	local was = cfg.readOpacity

	-- 100% MUST MEAN 100%. The fill art's own alpha carries the top-light
	-- falloff as well as the shape - 0.89 in the middle, less at the foot - and
	-- a vertex tint MULTIPLIES that, so no colour however solid could push a
	-- reading surface past 89%. The setting said 100 and the panel did not.
	cfg.readOpacity = 1
	check(math.abs((A.Palette:ReadingFill()[4] or 0) - 1) < 0.001,
		"at 100% the reading colour is solid ("
		.. string.format("%.2f", A.Palette:ReadingFill()[4] or 0) .. ")")

	local QLm = A:GetModule("questlog")
	QLm.win:SetFillColor(A.Palette:ReadingFill())
	check(QLm.win._backing ~= nil, "and the panel gets a plate behind it")
	local plate = QLm.win._backing[1] and { QLm.win._backing[1]:GetVertexColor() }
	check(plate and math.abs(plate[4] - 1) < 0.001,
		"opaque, because at a request of 1 nothing else can close the gap ("
		.. string.format("%.2f", plate and plate[4] or 0) .. ")")

	-- BUILT ON DEMAND, and only when it is needed. The HUD's surfaces are meant
	-- to be seen through, so nine textures a panel for a case that never arises
	-- is nine textures a panel wasted.
	cfg.readOpacity = 0
	QLm.win:SetFillColor(A.Palette:ReadingFill())
	check(QLm.win._backing[1]:IsShown() == false,
		"and it goes away again when the surface is meant to be seen through")

	local plain = A.Glass.CreatePanel(UIParent, { corner = 12 })
	plain:SetFillColor(A.Palette.c.glass)
	check(plain._backing == nil, "a surface nobody asked to be solid never grows one")

	-- THE TRUNKS' BRANCHES ARE READING SURFACES TOO: small text over whatever
	-- is behind them, and re-tinted on a restyle.
	local TBm = A:GetModule("toolbox")
	TBm:SetOpen(true, nil, "menu")
	cfg.readOpacity = 0.6
	A:Restyle()
	local want = A.Palette:ReadingFill()[4]
	check(math.abs((TBm.panels.menu._fillColor[4] or 0) - want) < 0.001,
		"a Toolbox branch is at the readable opacity too")
	TBm:SetOpen(false)

	cfg.readOpacity = was
	A:Restyle()
end

print("== xp hairline ==")
local XPm = A:GetModule("xpbar")
check(XPm and XPm.enabled and XPm.frame, "xpbar module built")
check(XPm.frame:IsShown(), "xp bar visible below max level")
-- WHAT IS LEFT, not what is done. "86% Level 15" is two facts about where you
-- have been; the line counts DOWN to the level you are working towards, which is
-- what anybody watching it is actually watching.
check(XPm.frame.text:GetText() == "14% to Level 16",
	"the readout counts down to the next level ("
	.. tostring(XPm.frame.text:GetText()) .. ")")

-- ROUNDED UP, so it never reads 0% while there is still experience to earn -
-- the one number a countdown must not show early.
do
	local wasXP = _G.__xp
	_G.__xp = _G.__xpMax - 1
	XPm.Update()
	check(XPm.frame.text:GetText():find("^1%% to"),
		"one point short of a level still reads 1%, never 0 ("
		.. tostring(XPm.frame.text:GetText()) .. ")")
	_G.__xp = 0
	XPm.Update()
	check(XPm.frame.text:GetText():find("^100%% to"),
		"and a fresh level reads 100% (" .. tostring(XPm.frame.text:GetText()) .. ")")
	_G.__xp = wasXP
	XPm.Update()
end

-- WHICH CORNER, because the bottom corners are where everybody's other addons
-- put things. Re-anchored rather than rebuilt, and CLEARED first: a FontString
-- keeps whatever anchors it was last given, so setting the new corner without
-- clearing the old leaves it spanned between the two.
do
	local cfg = A.Config:Module("xpbar")
	local function corner()
		local p, _, rel = XPm.frame.text:GetPoint(1)
		return p .. "/" .. tostring(rel) .. "/" .. XPm.frame.text:GetNumPoints()
	end
	cfg.textSide = "LEFT"
	XPm:OnConfigChanged()
	check(corner() == "BOTTOMLEFT/TOPLEFT/1", "the readout moves to the left corner ("
		.. corner() .. ")")
	check(XPm.frame.text:GetJustifyH() == "LEFT", "and justifies with it")
	cfg.textSide = "RIGHT"
	XPm:OnConfigChanged()
	check(corner() == "BOTTOMRIGHT/TOPRIGHT/1", "and back to the right ("
		.. corner() .. ")")
	check(XPm.frame.text:GetJustifyH() == "RIGHT", "justifying with it again")
end
check(XPm.frame.rested:IsShown(), "rested overlay shown when rest is banked")
_G.__units.player.level = 60
fire("PLAYER_LEVEL_UP")
check(not XPm.frame:IsShown(), "xp bar hides at max level")
_G.__units.player.level = 15
fire("PLAYER_LEVEL_UP")

print("== toolbox: the branches ==")
do
	local TBm = A:GetModule("toolbox")
	local B = { t = A.Trunk:Get("toolbox"), M = A.Movers,
		was = { ui = A.db.profile.scale, w = UIParent:GetWidth(), h = UIParent:GetHeight() } }
	check(TBm and TBm.enabled and TBm.root, "toolbox module built")
	UIParent:SetSize(1365, 768)          -- the real virtual screen at 16:9
	UIParent:SetGeom({ cx = 682.5, cy = 384, left = 0, right = 1365, bottom = 0, top = 768 })
	TBm:SetDock("LEFT")

	-- Each node opens its own branch beside its stub, lit, one at a time, and
	-- the branch is on the screen at the design's scale and at 1.0.
	for _, sc in ipairs({ 0.71, 1.0 }) do
		A.db.profile.scale = sc
		A:Reconfigure()
		for _, b in ipairs(TBm.BRANCHES) do
			local n = B.t:Node(b.key)
			n.button:GetScript("OnClick")(n.button, "LeftButton")
			local p = TBm.panels[b.key]
			local l, r = B.M.PointAt(p, "LEFT"), B.M.PointAt(p, "RIGHT")
			local _, top = B.M.PointAt(p, "TOP")
			local _, bot = B.M.PointAt(p, "BOTTOM")
			local sl = B.M.PointAt(n.button.stub, "RIGHT")
			local gap = 5.5 * B.t.frame:GetEffectiveScale() / UIParent:GetEffectiveScale()
			check(p:IsShown() and n.lit and TBm:OpenKey() == b.key,
				"at " .. sc .. " the " .. b.key .. " node opens its branch, lit, and only it")
			check(l and math.abs(l - sl - gap) < 0.5,
				"beside its stub (" .. tostring(l) .. " vs " .. tostring(sl + gap) .. ")")
			check(l >= -0.5 and r <= 1365.5 and bot >= -0.5 and top <= 768.5,
				"and all of it on the screen (" .. string.format("%.0f..%.0f x %.0f..%.0f", l, r, bot, top) .. ")")
		end
		B.t:Node("news").button:GetScript("OnClick")(B.t:Node("news").button, "LeftButton")
		check(not TBm:IsOpen(), "clicked again, the open one closes")
	end
	A.db.profile.scale = 0.71
	A:Reconfigure()

	-- The side persists per character; the drawer's top and bottom come back
	-- on the left (decision 4c).
	check(A.db.char.toolbox.docked == "LEFT", "the side is the character's")
	A.db.char.toolbox.docked = "BOTTOM"
	check(TBm:Dock() == "LEFT" and A.db.char.toolbox.docked == "LEFT",
		"a character docked at the bottom under the drawer comes back on the left")
	check(not TBm:SetDock("SIDEWAYS") and TBm:Dock() == "LEFT", "an edge that is not a side is refused")
	_G.__inCombat = true
	check(not TBm:SetDock("RIGHT") and TBm:Dock() == "LEFT",
		"and the sides do not swap in combat, where the minimap is not ours to move")
	_G.__inCombat = false

	-- THE OTHER ENERGY: in a fight the nodes stay, the labels go and the open
	-- branch closes (README "Two energies for trunks").
	TBm:SetOpen(true, nil, "addons")
	_G.__inCombat = true
	fire("PLAYER_REGEN_DISABLED")
	B.menu = B.t:Node("menu").button
	check(not TBm:IsOpen() and B.menu:IsShown() and B.menu:GetAlpha() > 0.99
		and B.menu.label:GetAlpha() == 0,
		"in a fight: nodes only, labels off, the open branch shut")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(B.menu.label:GetAlpha() > 0.99, "and the labels come back after it")

	-- WHAT'S NEW: a dot at the node's top-right in the info blue while this
	-- version's notes are unread, gone once its branch has been opened.
	A.db.char.toolbox.newsSeen = nil
	B.t:Paint()
	B.news = B.t:Node("news").button
	check(B.news.dot:IsShown(), "unread notes put a dot on What's new")
	do
		local r, g, b = B.news.dot:GetVertexColor()
		local i = A.Palette.c.info
		check(math.abs(r - i[1]) < 0.01 and math.abs(g - i[2]) < 0.01 and math.abs(b - i[3]) < 0.01,
			"in the info blue")
	end
	TBm:SetOpen(true, nil, "news")
	check(not B.news.dot:IsShown() and A.db.char.toolbox.newsSeen == TBm:NewsVersion(),
		"and opening the branch reads them")
	TBm:SetOpen(false)

	UIParent:SetSize(B.was.w, B.was.h)
	UIParent.__geom = nil
	A.db.profile.scale = B.was.ui
	A:Reconfigure()
end

print("== toolbox: widgets are published, not drawn ==")
do
	local TBm = A:GetModule("toolbox")
	local ldb = LibStub("LibDataBroker-1.1")
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, nil, "widgets")
	local WP = TBm.panels.widgets

	-- Published, so anybody displaying LDB gets them. That is the point: a
	-- player running Titan sees AetherUI's XP/hr without us doing anything.
	local missing = {}
	for _, p in ipairs(TBm.PROVIDERS) do
		if not ldb:GetDataObjectByName("AetherUI_" .. p.key) then
			missing[#missing + 1] = p.key
		end
	end
	check(#missing == 0,
		"all six widgets are registered as LDB data sources rather than drawn"
		.. " straight onto the panel - so Titan and Bazooka show them for free,"
		.. " and somebody else can write a seventh in ten lines (missing: "
		.. (#missing > 0 and table.concat(missing, ",") or "none") .. ")")

	local gold = ldb:GetDataObjectByName("AetherUI_Gold")
	check(gold and gold.type == "data source",
		"and as `data source`, not `launcher` - they are readouts, and a"
		.. " launcher is a thing you click")

	-- One reading each (README "Panel vocabulary": the value over a 7 px
	-- hollow diamond on a strand, the label under it), three to a row.
	check(#WP.cells >= 6 and WP.cells[6]:IsShown(), "the Widgets branch draws a reading per source")
	check(WP.cells[1].label:GetText() == "Gold",
		"with the object's own label under the value, not a name we invented")
	check(WP.cells[1].node:GetTexture() == A.Media.texture.diamondRim and WP.cells[1].strand:IsShown(),
		"on a hollow diamond and a strand")
	check(select(5, WP.cells[4]:GetPoint(1)) < select(5, WP.cells[3]:GetPoint(1)),
		"three to a row: the fourth starts the second")
	do
		local _, _, _, _, y = WP.cells[6]:GetPoint(1)
		check(-y + WP.cells[6]:GetHeight() <= WP:GetHeight() + 0.5,
			"and the branch is tall enough to hold them all")
	end

	-- THE mapping test. A third-party source that writes only `text` - which is
	-- what almost all of them do - must render, and must fall back to its
	-- registered name when it has no label to offer.
	do
		local big, small = TBm:CardText("SomeAddon_Thing", { text = "42" })
		check(big == "42" and small == "SomeAddon_Thing",
			"a source with only `text` renders it, and falls back to its"
			.. " registered name for the label - which is at least a true"
			.. " statement about where the number came from")

		local b2, s2 = TBm:CardText("X", { value = "17", suffix = "ms", label = "Ping" })
		check(b2 == "17ms" and s2 == "Ping",
			"and value + suffix + label is the deck's own shape")

		-- Render, do not interpret. These arrive with escapes already in them.
		local b3 = TBm:CardText("X", { text = "|cff00ff0042|r" })
		check(b3 == "|cff00ff0042|r",
			"a `text` that already carries colour escapes is passed through"
			.. " untouched - parsing somebody else's formatting to recover a"
			.. " number is how a display breaks on the addon it was not tested"
			.. " against")

		local b4 = TBm:CardText("X", nil)
		check(b4 == "\226\128\148",
			"and a source that is not there at all reads as an em dash rather"
			.. " than as a zero, which is a number and would be a lie")
	end

	-- A third party's source joins the grid because the grid is a LIST.
	do
		_G.__makeLDB("ThirdParty_Widget", "data source", { text = "99", label = "Theirs" })
		local c = A.db.char.toolbox
		local was = c.widgets
		c.widgets = { "AetherUI_Gold", "ThirdParty_Widget" }
		TBm:RefreshWidgets()
		check(WP.cells[2].label:GetText() == "Theirs"
			and WP.cells[2].value:GetText() == "99",
			"somebody else's data source draws in the branch with no wiring at"
			.. " all - it is a list of names, not a layout of six")
		check(not WP.cells[3]:IsShown(),
			"and a shorter list hides the surplus readings rather than leaving"
			.. " stale ones on screen - frames cannot be destroyed, so the pool"
			.. " is by index and the tail is hidden")
		c.widgets = was
		TBm:RefreshWidgets()
	end

	-- XP/hr is the one that can confidently lie.
	do
		TBm._xp = { gained = 0, from = GetTime(), last = 500, lastMax = 1000 }
		check(TBm:XPRate() == nil,
			"under a minute of session there is NO rate - only a short window"
			.. " with a big number extrapolated out of it, which is the aura"
			.. " tile's rule about refusing to print a timer it does not have")

		-- A level-up resets the numerator, not the session. UnitXP drops to near
		-- zero and UnitXPMax changes, so the delta across the boundary is
		-- (max - before) + after. Getting this wrong silently loses a level's
		-- worth of XP from the rate every time somebody dings.
		TBm._xp = { gained = 0, from = GetTime() - 3600, last = 900, lastMax = 1000 }
		local wasXP, wasMax = _G.__xp, _G.__xpMax
		_G.__xp, _G.__xpMax = 50, 1200
		TBm:XPTick(true)
		check(TBm._xp.gained == 150,
			"and a level-up counts the crossing - (1000-900) + 50 = 150, not"
			.. " 50-900 = -850 (got " .. TBm._xp.gained .. ")")
		_G.__xp, _G.__xpMax = wasXP, wasMax
	end

	-- Polling follows the Widgets branch, and only that branch.
	TBm:SetOpen(false)
	check(not TBm._polling,
		"a shut branch polls nothing - the two widgets that cannot be"
		.. " event-driven are the only pollers, and nobody is looking at them")
	TBm:SetOpen(true, nil, "menu")
	check(not TBm._polling, "nor does another branch")
	TBm:SetOpen(true, nil, "widgets")
	check(TBm._polling, "and it starts again when the Widgets branch opens")
	TBm:SetOpen(false)

	-- The unread dot needs a notion of read, or it is always lit or never.
	A.db.char.toolbox.newsSeen = nil
	check(TBm:NewsUnread(), "the what's-new dot is lit before the notes are read")
	TBm:MarkNewsRead()
	check(not TBm:NewsUnread(), "and goes out once they have been")
	check(A.db.char.toolbox.newsSeen == TBm:NewsVersion(),
		"remembering WHICH version was read, so the next release lights it"
		.. " again rather than it being a one-time dismissal")
	check(TBm:NewsVersion() == A.version,
		"and the version it remembers is the RUNNING one, taken from the .toc"
		.. " through the changelog rather than from a literal in the module -"
		.. " the pair had to be edited together every release and nothing"
		.. " checked that either had been (" .. tostring(TBm:NewsVersion())
		.. " vs " .. tostring(A.version) .. ")")

	-- The What's new branch's text comes from the changelog: the current
	-- entry's own lines, verbatim, up to three, each on a small node.
	do
		local realLog = A.CHANGELOG
		A.CHANGELOG = {
			{ version = A.version, date = "2026-01-01",
			  lines = { "One.", "Two.", "Three.", "Four." } },
			{ version = "0.0.1", date = "2025-12-01", lines = { "Older." } },
		}
		TBm:SetOpen(true, nil, "news")
		local NP = TBm.panels.news
		check(NP.lines[1].text:GetText() == "One." and NP.lines[3].text:GetText() == "Three."
			and not (NP.lines[4] and NP.lines[4].text:IsShown()),
			"the branch shows the entry's first three lines, verbatim")
		check(NP.head.hint:GetText():find(A.version, 1, true) ~= nil,
			"with the running version on its heading (" .. tostring(NP.head.hint:GetText()) .. ")")

		-- Re-read, not just right because it was built right.
		local realVersion = A.version
		A.version = "9.9.9"
		A.CHANGELOG[1].version = "9.9.9"
		TBm:RefreshNews()
		check(NP.head.hint:GetText():find("9.9.9", 1, true) ~= nil,
			"and re-reads it rather than keeping what it was built with")
		A.version = realVersion
		A.CHANGELOG[1].version = realVersion

		-- Notes, for the rest: offered because there is a fourth line and an
		-- older release, and following it counts as reading them.
		TBm:RefreshNews()
		check(NP.notes:IsShown(), "a Notes link is offered when there is more")
		do
			local _, _, _, _, y = NP.notes:GetPoint(1)
			check(-y + NP.notes:GetHeight() <= NP:GetHeight() + 0.5,
				"inside the branch, under the last line rather than through it")
			local _, _, _, _, ly = NP.lines[3].text:GetPoint(1)
			check(-ly + NP.lines[3].text:GetStringHeight() <= -y + 0.5,
				"and below the text")
		end
		A.db.char.toolbox.newsSeen = nil
		NP.notes:GetScript("OnClick")(NP.notes)
		check(not TBm:NewsUnread() and not TBm:IsOpen(),
			"and following it reads them and puts the branch away for the window")

		-- One entry, fully shown, with nothing behind it: no link.
		A.CHANGELOG = { { version = A.version, date = "2026-01-01", lines = { "One line." } } }
		check(not TBm:NewsHasMore(), "a release with one line and no history has nothing more")
		A.CHANGELOG = { { version = A.version, date = "2026-01-01",
			lines = { "One.", "Two.", "Three.", "Four." } } }
		check(TBm:NewsHasMore(), "but a fourth line the branch has no room for counts as more")
		A.CHANGELOG = realLog
	end

	TBm:SetOpen(false)
end

print("== toolbox: settings tiles, three kinds of thing ==")
do
	local TBm = A:GetModule("toolbox")
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, nil, "settings")
	local SP = TBm.panels.settings
	local function Row(key)
		for _, r in ipairs(SP.rows) do
			if r:IsShown() and r.__tile and r.__tile.key == key then return r end
		end
	end

	check(SP and #SP.rows >= 4, "the Settings branch is built, a row per setting")

	-- README "Panel vocabulary": a toggle is a 24 px diamond on a strand, lit
	-- (accent fill and glow, a dark icon, ON) or not (glass, a 45 % rim, OFF).
	do
		local r = SP.rows[1]
		check(r.fill:GetWidth() == 24 and r.fill:GetTexture() == A.Media.texture.diamond
			and r.rim:GetTexture() == A.Media.texture.diamondRim,
			"each setting is a 24 px diamond")
		check(r.strand:IsShown() and select(2, r.strand:GetPoint(1)) == r.fill,
			"on a strand out to its label")
		check(select(2, r.name:GetPoint(1)) == r.strand, "with the label at the strand's end")
		local _, _, _, _, y1 = SP.rows[1]:GetPoint(1)
		local _, _, _, _, y4 = SP.rows[4]:GetPoint(1)
		check(-y4 + SP.rows[4]:GetHeight() <= SP:GetHeight(), "every row inside the branch")
		check(y4 < y1, "one under another")
	end

	-- A config path, written the way the options panel writes it.
	local zen = TBm.TILES[1]
	check(zen.kind == "setting" and zen.path[2] == "zen", "the first tile is Zen")
	local wasZen = A.db.profile.modules.zen.enabled
	A.db.profile.modules.zen.enabled = true
	check(TBm:TileState(zen) == true, "reading a setting tile reads the config")
	TBm:ToggleTile(zen)
	check(A.db.profile.modules.zen.enabled == false, "and toggling writes it")

	-- ...and the module actually goes down. Writing `enabled = false` and
	-- stopping there leaves it running with its own setting saying it is off,
	-- which is the bug the options panel already paid for once.
	check(A:GetModule("zen").enabled == false,
		"and the MODULE is torn down, not just the flag - `modules.<n>.enabled`"
		.. " is recognised by the shape of the path, exactly as Options.Set does"
		.. " it, so a tile cannot forget what a page remembered")
	TBm:ToggleTile(zen)
	check(A:GetModule("zen").enabled == true, "and comes back")
	A.db.profile.modules.zen.enabled = wasZen

	-- A MODE. No stored value behind it at all: it is read off the module that
	-- owns the state, and it is off at every login by definition.
	local lock
	for _, t in ipairs(TBm.TILES) do if t.key == "lock" then lock = t end end
	check(lock and lock.kind == "mode", "there is an Unlock frames tile")

	A.Movers:Lock()
	check(TBm:TileState(lock) == false, "locked reads Off")
	TBm:ToggleTile(lock)
	check(A.Movers.unlocked == true,
		"and toggling it moves the MOVERS flag rather than a copy in the"
		.. " profile - /aether lock and the options panel move the same one, and"
		.. " a second answer would go stale the first time either was used")
	check(TBm:TileState(lock) == true, "which reads back On")

	-- Changed BEHIND the tile's back, which is the case a cached value gets
	-- wrong and the whole reason `mode` reads through to the module.
	A.Movers:Lock()
	check(TBm:TileState(lock) == false,
		"and /aether lock, which never touches the Toolbox, is seen by the tile"
		.. " on the next read")

	-- ...and the tile is REDRAWN, not merely readable.
	--
	-- TileState reading through to A.Movers is the right design and was never
	-- the bug: the tile is only painted when something calls RefreshTiles, and
	-- unlocking from the options panel or with a slash command called nothing.
	-- So the drawer sat there saying "On" with the frames locked - a live value
	-- nobody had asked for. Every route through Movers announces itself now, so
	-- this is the check that the announcement is wired to the paint.
	do
		TBm:SetOpen(true, nil, "settings")
		local frame = Row("lock")
		check(frame ~= nil, "the lock setting is in the branch")
		if frame then
			A.Movers:Unlock()
			check(frame.state:GetText() == "ON" and frame.glow:IsShown(),
				"unlocking repaints it without anybody asking (got "
				.. tostring(frame.state:GetText()) .. ")")
			A.Movers:Lock()
			check(frame.state:GetText() == "OFF" and not frame.glow:IsShown(),
				"and locking again repaints it back (got "
				.. tostring(frame.state:GetText()) .. ")")
		end
	end

	-- Switching a mode ON gets the branch out of the way. You cannot drag a
	-- frame that is underneath the panel you used to unlock it.
	TBm:SetOpen(true, nil, "settings")
	Row("lock"):GetScript("OnClick")(Row("lock"))
	check(A.Movers.unlocked and not TBm:IsOpen(),
		"turning a mode on from its row closes the branch - both of these are"
		.. " things you do TO the screen")
	TBm:SetOpen(true, nil, "settings")
	check(TBm:IsOpen(), "...and the branch reopens")
	TBm:ToggleTile(lock)
	check(TBm:IsOpen() and not A.Movers.unlocked,
		"but switching one OFF leaves it open - then you are finished rather"
		.. " than starting")
	A.Movers:Lock()

	-- Every tile explains itself. Two of these four do something drastic
	-- enough to the screen that finding out by pressing it is not reasonable.
	do
		local missing = {}
		for _, t in ipairs(TBm.TILES) do
			if not t.tip or t.tip == "" then missing[#missing + 1] = t.key end
		end
		check(#missing == 0,
			"every settings tile carries a tooltip ("
			.. (#missing > 0 and table.concat(missing, ", ") or "all four") .. ")")

		-- Read at HOVER time off __tile, not captured when the frame was built.
		-- These frames are reused - a launcher the player adds takes whichever
		-- slot is next - so a closed-over tile describes what the frame used to
		-- be.
		local f = SP.rows[1]
		f.__tile = TBm.TILES[2]
		f:GetScript("OnEnter")(f)
		local shown = _G.GameTooltipTextLeft1:GetText()
		check(shown == TBm.TILES[2].label,
			"and the tooltip describes whatever the row is showing NOW (got "
			.. tostring(shown) .. ")")
		f:GetScript("OnLeave")(f)
		f.__tile = TBm.TILES[1]
	end

	-- The four the deck asks for, and nothing else.
	--
	-- `combat` was the second and has gone to the options panel, where it was
	-- already configurable - the deck draws four tiles and the one thing with no
	-- home anywhere else was the in-flight player, which needs a switch of its
	-- own precisely because the flight TIMER is not what it switches.
	do
		local keys = {}
		for _, t in ipairs(TBm.TILES) do keys[#keys + 1] = t.key end
		check(table.concat(keys, ",") == "zen,ifec,lock,keybinds",
			"the four settings tiles, in order (got " .. table.concat(keys, ",")
			.. ")")
		for _, t in ipairs(TBm.TILES) do
			check(A.Media:Icon(t.key) ~= nil,
				t.key .. " has a glyph on the sheet - a tile's key IS its icon"
				.. " name, so a rename here is a blank chip there")
		end
	end

	-- The skin picker is four swatch chips, not a toggle tile, and it is not
	-- built yet. NOT BUILT rather than built and hidden: a hidden control is
	-- still a control somebody has to maintain. Delete this check when the
	-- swatches land, rather than leaving it to fail as the reminder.
	do
		local found
		for _, t in ipairs(TBm.TILES) do
			if t.path and t.path[#t.path] == "skin" then found = true end
		end
		check(not found,
			"there is no skin tile - the family is picked from four swatches in"
			.. " the settings, and a tile built and hidden is a control somebody"
			.. " still has to keep working")
	end

	-- The diamond carries the state, visibly: the accent all over when on, and
	-- not merely "different" from off.
	do
		TBm:SetOpen(true, nil, "settings")
		A.db.profile.modules.zen.enabled = true
		TBm:RefreshTiles()
		local a = A.Palette.c.accent
		local r, g, b = Row("zen").fill:GetVertexColor()
		check(math.abs(r - a[1]) < 0.01 and math.abs(g - a[2]) < 0.01 and math.abs(b - a[3]) < 0.01
			and Row("zen").state:GetText() == "ON",
			"on, the diamond is filled with the accent and says ON")
		A.db.profile.modules.zen.enabled = false
		TBm:RefreshTiles()
		r, g, b = Row("zen").fill:GetVertexColor()
		check(math.abs(r - a[1]) > 0.1 and Row("zen").state:GetText() == "OFF",
			"and off it is the quiet glass and says OFF")
		A.db.profile.modules.zen.enabled = wasZen
		TBm:RefreshTiles()
	end

	-- A launcher is not a toggle, and must not pretend to be one.
	do
		local clicked = false
		_G.__makeLDB("TileLauncher", "launcher", {
			label = "Tile Launcher",
			OnClick = function() clicked = true end,
		})
		A.Launchers:Scan()
		A:GetModule("toolbox"):ClaimPins()

		local c = A.db.char.toolbox
		c.tiles = { "TileLauncher" }
		TBm:RefreshTiles()

		local list = TBm:TileList()
		local lt = list[#list]
		check(lt and lt.kind == "launcher", "a launcher joins the tile grid")
		check(TBm:TileState(lt) == nil,
			"and has NO state - an LDB launcher is a button, not a toggle, and"
			.. " nothing in the protocol can answer 'are you on'")

		TBm:SetOpen(true, nil, "settings")
		local frame = Row("TileLauncher")
		check(frame and frame.state:GetText() == "",
			"so its row draws no ON or OFF. Inventing one would be a control"
			.. " saying something it cannot know")

		frame:GetScript("OnClick")(frame)
		check(clicked, "and clicking it runs the launcher instead of toggling")

		c.tiles = nil
		TBm:RefreshTiles()
	end

	TBm:SetOpen(false)
end

print("== toolbox: the addon list is a superset of the useful one ==")
do
	local TBm = A:GetModule("toolbox")
	local MMx = A:GetModule("minimap")
	local LN  = A.Launchers
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, nil, "addons")

	-- A launcher for one of the mocked addons, and one addon with nothing.
	local ran = false
	_G.__makeLDB("Questie", "launcher", {
		label = "Questie",
		icon = "Interface\\Icons\\INV_Misc_Map01",
		OnClick = function() ran = true end,
	})
	LN:Scan()
	TBm:ClaimPins()
	TBm:RefreshAddons()

	local rows = TBm:AddonRows()
	local byName = {}
	for _, r in ipairs(rows) do byName[r.name] = r end

	check(byName["PlainAddon"] == nil,
		"an addon with NO launcher is not listed at all. Listing everything put"
		.. " twenty-five rows on screen of which fifteen did nothing, and that"
		.. " buried the ten that worked - what you want from this panel is what"
		.. " you can REACH, and the Blizzard addon list is where the rest lives")
	check(byName["Questie"] and byName["Questie"].entry ~= nil,
		"and one with a launcher is, carrying its entry")

	do
		local bad = 0
		for _, r in ipairs(rows) do if not r.entry then bad = bad + 1 end end
		check(bad == 0,
			"every row has something behind it, so there is no inert case left"
			.. " to design around (" .. bad .. " without)")
		check(TBm._addonsLoaded == #_G.__addons,
			"and the module still counts how many addons are LOADED - the number"
			.. " worth one line in the header rather than twenty-five rows (got "
			.. tostring(TBm._addonsLoaded) .. " of " .. #_G.__addons .. ")")
	end

	-- Icons: about half the addons on a machine declare one. The letter tile is
	-- the base case, not a placeholder.
	do
		-- A launcher with no icon at all. LDB requires one of LibDBIcon but not
		-- of a launcher, and only about half the addons on a machine declare
		-- ## IconTexture either - so the letter tile is the base case rather
		-- than a placeholder.
		_G.__makeLDB("Naked", "launcher", { label = "Naked Addon", icon = false })
		A.Launchers:Scan()
		TBm:ClaimPins()
		TBm:RefreshAddons()
		local rows2 = TBm:AddonRows()

		local qi, ni
		for i, r in ipairs(rows2) do
			if r.name == "Questie" then qi = TBm.panels.addons.rows[i] end
			if r.name == "Naked" then ni = TBm.panels.addons.rows[i] end
		end
		check(qi and qi.icon:IsShown(), "an addon that declares an icon gets it")
		check(ni and not ni.icon:IsShown() and ni.initial:GetText() == "N",
			"and one that declares none gets its initial - a grid where half the"
			.. " tiles are a question mark looks broken, and the handoff's 'use"
			.. " real addon icons' cannot be followed for the half without one")
	end

	-- Pinning. This is the ownership handover the plan called out: pinning is an
	-- explicit instruction to put the addon on the RAIL, so it takes the entry
	-- even though the minimap drawer already had it.
	do
		local entry = LN.byKey["Questie"]
		check(entry ~= nil, "the Questie launcher exists")
		local firstOwner = LN:OwnerOf(entry)
		check(firstOwner == TBm,
			"the rail has it to begin with - it adopts every launcher now that"
			.. " the drawer is gone, because an unclaimed button is one nobody"
			.. " positions and a LibDBIcon button nobody positions is still"
			.. " sitting on the minimap ring (" .. tostring(firstOwner) .. ")")

		-- The row's own pin: a 7 px diamond, hollow until pinned.
		local qrow
		for _, r in ipairs(TBm.panels.addons.rows) do
			if r:IsShown() and r.__row and r.__row.name == "Questie" then qrow = r end
		end
		check(qrow and qrow.pin.glyph:GetTexture() == A.Media.texture.diamondRim
			and qrow.pin.glyph:GetWidth() == 7, "each row carries a hollow 7 px diamond to pin it")
		qrow.pin:GetScript("OnClick")(qrow.pin)
		check(TBm:IsPinned("Questie"), "clicking it pins the addon")
		check(qrow.pin.glyph:GetTexture() == A.Media.texture.diamond, "and the diamond fills")
		check(LN:OwnerOf(entry) == TBm,
			"and TAKES the entry - a pin is an instruction to put it on the trunk,"
			.. " so it overrides rather than being refused")
		check(entry.button:GetParent() == TBm.pinNodes[1].button,
			"the button moves onto the trunk, where it is reachable with no"
			.. " branch open")

		-- ...and it STAYS visible after the library refreshes itself.
		--
		-- LibDBIcon pins strata and level so reparenting cannot shuffle its
		-- buttons behind things, and re-applies that on its own Refresh and
		-- Show. Once it has, our SetFrameStrata is refused: the button sits at
		-- MEDIUM level 8 while the rail is FULLSCREEN_DIALOG, the rail's own
		-- panel art paints over it, and the pin looks like it disappeared -
		-- coming back on a reload, because nothing had refreshed yet.
		--
		-- A REAL LibDBIcon button, not one of our proxies: Prepare skips frames
		-- we made, and a proxy is the one kind no library ever touches. The
		-- first version of this test used one and proved nothing.
		do
			_G.__makeLDB("RefreshMe", "launcher", { label = "Refresh Me" })
			local rb = _G.__makeDBIcon("RefreshMe")
			LN:Scan()
			TBm:ClaimPins()
			TBm:SetPinned("RefreshMe", true)

			local re = LN.byKey["RefreshMe"]
			check(re and re.button == rb and not re.owned,
				"a real LibDBIcon button backs the entry")

			-- What Refresh does, in this order: unpin, restore its own strata
			-- and level, re-pin. Setting the flags first would have the mock
			-- refuse the change, which is how a broken version passes.
			rb.__fixedStrata, rb.__fixedLevel = false, false
			rb:SetFrameStrata("MEDIUM")
			rb:SetFrameLevel(8)
			rb.__fixedStrata, rb.__fixedLevel = true, true
			check(rb:GetFrameStrata() == "MEDIUM",
				"the library really has dragged it back down first")

			TBm:LayoutPins()
			local host = TBm.pinNodes[2].button
			check(rb:GetFrameStrata() == host:GetFrameStrata(),
				"a library that re-pins its button between layouts does not"
				.. " strand it behind the trunk - Prepare runs on EVERY layout,"
				.. " not just when the entry is claimed (got "
				.. rb:GetFrameStrata() .. ")")
			check(rb:GetFrameLevel() > host:GetFrameLevel(),
				"and it sits above the trunk's own art rather than under it")

			TBm:SetPinned("RefreshMe", false)
		end

		-- ...and UNPINNING has to take it off again, rather than leave it
		-- where the trunk put it.
		do
			local host = TBm.pinNodes[1].button
			TBm:TogglePin("Questie")
			check(not TBm:IsPinned("Questie"), "unpinning drops the pin")
			local _, rel = entry.button:GetPoint(1)
			check(rel ~= host, "and the button LEAVES the trunk")
			check(entry._parked and entry.button:GetAlpha() == 0,
				"parked rather than hidden - it may carry a secure template, and"
				.. " hiding a frame with a protected descendant is refused in"
				.. " combat")
			TBm:TogglePin("Questie")
		end

		local _, anchoredTo = entry.button:GetPoint(1)
		check(anchoredTo == TBm.pinNodes[1].button,
			"pinned again, it is anchored on its node and nowhere else")

		TBm:TogglePin("Questie")
		check(not TBm:IsPinned("Questie"), "unpinning removes it")
	end

	-- Never Hide a collected button. It may carry a secure template, and
	-- hiding a frame with a protected descendant is refused in combat.
	do
		TBm:TogglePin("Questie")
		local entry = LN.byKey["Questie"]
		_G.__inCombat = true
		fire("PLAYER_REGEN_DISABLED")
		TBm:SetOpen(false)
		TBm:SetOpen(true, nil, "addons")
		check(entry.button:IsShown(),
			"a fight, and branches opening and closing, never hide a pinned button")
		_G.__inCombat = false
		fire("PLAYER_REGEN_ENABLED")
		TBm:TogglePin("Questie")
	end

	TBm:SetOpen(false)
end

print("== toolbox: the micro menu, rebuilt rather than adopted ==")
do
	local TBm = A:GetModule("toolbox")
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, nil, "menu")
	local MP = TBm.panels.menu

	-- Blizzard's own frames are left exactly where the action bar sweep put
	-- them. Adopting them would start a three-way argument over ownership with
	-- ActionBars and QuestLog; building nine of our own costs a table.
	check(_G.CharacterMicroButton == nil or not _G.CharacterMicroButton:IsShown(),
		"Blizzard's micro buttons stay hidden - these are ours, so nothing has"
		.. " to negotiate who owns theirs")

	local list = TBm:MicroList()
	check(#list >= 6, "the row is built (" .. #list .. " buttons)")

	-- BOTH SOCIAL AND GUILD, AND A BAG. TEN, IN TWO FIVES.
	--
	-- Blizzard's two are mutually exclusive - each mixin reads
	-- `useClassicGuildUI` and shows only when the other does not - so its own
	-- strip carries eight of the nine it declares. That is a constraint on a
	-- fixed row of nine slots, and this row is neither fixed nor nine.
	--
	-- Both destinations exist and work whichever way that CVar is set, so
	-- picking one left the other unreachable from the drawer for no reason -
	-- and the picking was a piece of CVar archaeology that had already got it
	-- wrong once. Reported from the game twice.
	do
		local function has(key)
			for _, m in ipairs(TBm:MicroList()) do
				if m.key == key then return true end
			end
		return false
	end

	-- WHATEVER THE CLIENT'S OWN PAIR IS DOING, we carry both.
	for _, how in ipairs({ "social", "guild", "down" }) do
		_G.__microPair(how)
		for _, cv in ipairs({ "0", "1" }) do
			_G.__cvars.useClassicGuildUI = cv
			check(has("social") and has("guild"),
				"Social and Guild are both in the row, with the client's pair " ..
				how .. " and the CVar " .. cv)
		end
	end
	_G.__microPair("social")
	_G.__cvars.useClassicGuildUI = "1"

	-- AND A BAG, which Blizzard's strip has not got at all: the backpack
	-- lives on a bar of its own. Through the global rather than through our
	-- module, because the global is what our module hooks - so the entry
	-- behaves the same with the bags module on, off, or never loaded.
	check(has("bags"), "and there is a Bags entry")

	check(#TBm:MicroList() == 10,
		"ten entries, which is two rows of five rather than an odd nine (" ..
		#TBm:MicroList() .. ")")
	end

	-- Every action is probed. A global that is not there is a button that is
	-- not drawn, rather than one that errors when somebody clicks it.
	do
		local was = _G.ToggleTalentFrame
		_G.ToggleTalentFrame = nil
		local gone = true
		for _, m in ipairs(TBm:MicroList()) do
			if m.key == "talents" then gone = false end
		end
		check(gone,
			"a button whose global this client does not have is not drawn at"
			.. " all - not drawn and dead, which is a button that errors the"
			.. " first time somebody trusts it")
		_G.ToggleTalentFrame = was
	end

	-- AND A GLOBAL THAT IS THERE AND WILL NOT WORK, which is the harder half and
	-- the one that shipped. ToggleTalentFrame exists at every level and returns
	-- silently below ten: the door was drawn, lit, clickable and inert, and
	-- nothing on screen said why. Blizzard's own talent button hides itself on
	-- exactly this test.
	do
		local wasLevel = _G.__units.player.level
		local wasCount = #TBm:MicroList()

		_G.__units.player.level = 9
		TBm:RefreshMicro()

		local has9 = false
		for _, m in ipairs(TBm:MicroList()) do
			if m.key == "talents" then has9 = true end
		end
		check(not has9,
			"below the level the client will open it at, the Talents door is not"
			.. " offered - a door that does nothing is worse than no door,"
			.. " because there is nothing to report")

		-- IT IS THE DOOR THAT GOES, NOT THE ROW. Everything else is still there
		-- and the count moves by exactly one; a probe that threw would take the
		-- whole menu with it and this is what says it did not.
		check(#TBm:MicroList() == wasCount - 1,
			"and only that one - " .. (wasCount - 1) .. " left (" ..
			#TBm:MicroList() .. ")")

		-- THE ROW IS NOT FIXED FOR THE SESSION, which is what MicroList was
		-- being treated as. It was worked out at build and on a config change,
		-- so a character who dinged 10 with the drawer open went on not having
		-- the door until they opened the settings and closed them again.
		_G.__units.player.level = 10
		fire("PLAYER_LEVEL_UP", 10)
		local backAgain = false
		for _, m in ipairs(TBm:MicroList()) do
			if m.key == "talents" then backAgain = true end
		end
		check(backAgain,
			"and at ten the client will open it again, so the door belongs in"
			.. " the row")

		-- WHICH THE CHECK ABOVE DOES NOT PROVE IS ON SCREEN, and the difference
		-- matters: MicroList builds a fresh table every call, so it answers
		-- correctly whether or not anything has redrawn. Deleting the level-up
		-- registration leaves that check passing and only this one fails.
		local drawn = 0
		for _, b in ipairs(MP.cells or {}) do
			if b:IsShown() then drawn = drawn + 1 end
		end
		check(drawn == #TBm:MicroList(),
			"and the buttons on screen match it (" .. drawn .. " of " ..
			#TBm:MicroList() .. ")")

		_G.__units.player.level = wasLevel
		TBm:RefreshMicro()
	end

	-- The actions are Blizzard's own, read off their handlers rather than
	-- guessed - guessing gets one of nine subtly wrong and nobody notices until
	-- they click it.
	do
		TBm:RefreshMicro()
		local fired = {}
		local saved = {}
		local names = {
			character = "ToggleCharacter", spellbook = "ToggleSpellBook",
			quests = "ToggleQuestLog", map = "ToggleWorldMap",
			help = "ToggleHelpFrame",
		}
		for key, g in pairs(names) do
			saved[g] = _G[g]
			_G[g] = function(arg) fired[key] = arg or true end
		end

		for i, m in ipairs(TBm._microList) do
			local btn = MP.cells[i]
			if btn and names[m.key] then btn:GetScript("OnClick")(btn) end
		end

		check(fired.character == "PaperDollFrame",
			"the character button calls ToggleCharacter with the frame name"
			.. " Blizzard's own XML passes, not a bare toggle")
		check(fired.spellbook == "spell",
			"the spellbook passes BOOKTYPE_SPELL")
		check(fired.quests == true, "and the quest log goes through"
			.. " ToggleQuestLog - which is OURS, since the quest log module"
			.. " replaced the global")
		check(fired.map == true and fired.help == true, "map and help fire too")

		for g, fn in pairs(saved) do _G[g] = fn end
	end

	-- AND FIVE TO A ROW, which is the point of there being ten.
	--
	-- Nine across a four-wide grid is 4 + 4 + 1, and the odd one on its own
	-- line reads as something having gone wrong rather than as a menu.
	do
		TBm:SetDock("LEFT")
		TBm:SetOpen(true, nil, "menu")
		TBm:RefreshMicro()
		local rows = {}
		for i = 1, #TBm._microList do
			local btn = MP.cells[i]
			local _, _, _, _, y = btn:GetPoint(1)
			local key = string.format("%.0f", y or 0)
			rows[key] = (rows[key] or 0) + 1
		end
		local n, sizes = 0, {}
		for _, count in pairs(rows) do n = n + 1; sizes[#sizes + 1] = count end
		table.sort(sizes)
		check(n == 2 and sizes[1] == 5 and sizes[2] == 5,
			"the Menu branch lays the ten out five and five (decision 4b; " .. n .. " rows of " ..
			table.concat(sizes, "+") .. ")")
		local last = MP.cells[#TBm._microList]
		local _, _, _, x, y = last:GetPoint(1)
		check(x + last:GetWidth() <= MP:GetWidth() + 0.5 and -y + last:GetHeight() <= MP:GetHeight() + 0.5,
			"all of them inside the branch")
	end

	-- THE DOOR WHOSE WINDOW IS OPEN IS LIT (board 6a), however it was opened.
	do
		local function cell(key)
			for i, m in ipairs(TBm._microList) do if m.key == key then return MP.cells[i] end end
		end
		_G.WorldMapFrame = _G.WorldMapFrame or CreateFrame("Frame", "WorldMapFrame", UIParent)
		_G.WorldMapFrame:Hide()
		TBm:PaintMenu()
		check(not cell("map").__lit, "the Map door is idle with the map shut")
		_G.WorldMapFrame:Show()
		TBm:PaintMenu()
		check(cell("map").__lit and cell("map").__aetherSkin._fillColor == A.Palette.c.accent,
			"and lit, filled with the accent, with it open")
		_G.WorldMapFrame:Hide()
		check(MP:GetScript("OnShow") ~= nil, "a ticker follows windows opened any other way while the branch is up")
	end

	-- AND THE TWO THAT DO NOT GO THROUGH A Toggle GLOBAL.
	do
		TBm:RefreshMicro()
		local function press(key)
			for i, m in ipairs(TBm._microList) do
				if m.key == key then
					local btn = MP.cells[i]
					btn:GetScript("OnClick")(btn)
					return true
				end
			end
		end

		-- BAGS opens ours, because ToggleAllBags is the global our own module
		-- hooks - so this one line of wiring covers the module being on and off.
		local Bg = A:GetModule("bags")
		Bg:Hide()
		press("bags")
		check(Bg.frames and Bg.frames.bags and Bg.frames.bags:IsShown(),
			"the Bags entry opens our bag window through the hooked global")
		Bg:Hide()

		-- MENU OPENS THE MENU, EVEN WITH A WINDOW OPEN.
		--
		-- ToggleGameMenu is the escape handler: it walks a chain of "is there
		-- anything to close first" and reaches the menu only at the end, and
		-- CloseAllWindows is one of the links. Wired to it, the button closed
		-- something instead and the menu never appeared - which from a drawer
		-- full of buttons is most of the time. Reported from the game as the
		-- Menu button doing nothing.
		_G.GameMenuFrame:Hide()
		_G.__escClosable = 1
		press("menu")
		check(_G.GameMenuFrame:IsShown(),
			"the Menu entry opens the game menu with a window still open, rather "
			.. "than behaving as Escape and closing that instead")
		check(_G.__escClosable == 0,
			"and shuts the windows on the way, the way Blizzard's own Menu button "
			.. "does")

		-- AND CLOSES IT AGAIN, because it is one button and not two.
		press("menu")
		check(not _G.GameMenuFrame:IsShown(),
			"and closes it again on a second press")
	end

	TBm:SetOpen(false)
end

print("== toolbox: the options page and the diagnostic ==")
do
	local TBm = A:GetModule("toolbox")
	local run = SlashCmdList["AETHERUI"]

	-- The page exists and its paths resolve. The options walker already asserts
	-- every path in the tree resolves; what it CANNOT assert is that moving a
	-- control changes anything, which is the same silent no-op as a mistyped
	-- path and is what the next two blocks are for.
	local tree = A.Options:Build()
	check(tree.args.toolbox ~= nil, "there is a Toolbox page")
	check(tree.args.toolbox.order == A.Options.PAGE_ORDER.toolbox,
		"in its declared slot rather than wherever the running counter landed")

	-- A column slider that writes a number nothing re-reads is a control that
	-- does nothing, which is exactly what a typo in a path produces - and the
	-- walker cannot tell the two apart.
	do
		local cfg = A.db.profile.modules.toolbox
		TBm:SetDock("LEFT")
		TBm:SetOpen(true, nil, "widgets")

		local was = cfg.widgetColumns
		cfg.widgetColumns = 3
		A:Reconfigure()
		local w3 = TBm.panels.widgets.cells[1]:GetWidth()
		cfg.widgetColumns = 2
		A:Reconfigure()
		local w2 = TBm.panels.widgets.cells[1]:GetWidth()
		check(w2 > w3,
			"the widget column slider actually re-lays the branch - two columns"
			.. " make wider readings than three (" .. string.format("%.0f", w2)
			.. " vs " .. string.format("%.0f", w3) .. ")")
		cfg.widgetColumns = was
		A:Reconfigure()
		check(cfg.scrim == nil and cfg.tileColumns == nil and tree.args.toolbox.args.scrim == nil,
			"and the drawer's scrim and tile settings are gone with it")
		TBm:SetOpen(false)
	end

	-- The command.
	run("toolbox dock right")
	check(TBm:Dock() == "RIGHT", "/lattice toolbox dock moves it")
	run("toolbox dock bottom")
	check(TBm:Dock() == "RIGHT", "and top or bottom is refused: left or right only")
	run("toolbox dock left")
	run("toolbox open")
	check(TBm:OpenKey() == "menu", "/lattice toolbox open opens the Menu branch")
	run("toolbox open addons")
	check(TBm:OpenKey() == "addons", "or the one named")
	run("toolbox close")
	check(not TBm:IsOpen(), "and close shuts it")
	run("toolbox toggle settings")
	check(TBm:OpenKey() == "settings", "toggle opens a named branch")
	run("toolbox toggle settings")
	check(not TBm:IsOpen(), "and shuts it")

	do
		_G.__makeLDB("CmdLauncher", "launcher", { label = "Cmd Launcher" })
		A.Launchers:Scan()
		A:GetModule("toolbox"):ClaimPins()
		run("toolbox pin CmdLauncher")
		check(TBm:IsPinned("CmdLauncher"), "/aether toolbox pin pins")
		run("toolbox pin cmdlauncher")
		check(not TBm:IsPinned("CmdLauncher"),
			"and matches the name however it was typed")
		run("toolbox pin CmdLauncher")
		run("toolbox pin CmdLauncher")
		check(not TBm:IsPinned("CmdLauncher"), "and unpins")
		run("toolbox pin NoSuchAddon")
		check(not TBm:IsPinned("NoSuchAddon"),
			"the command refuses a name that resolves to no launcher")
		-- ...and so does the module, which is a separate guard. The command's
		-- own resolve loop bails first, so going through it never reaches this
		-- one - and a pin recorded against nothing is a rail slot that can
		-- never draw and never be cleared from the panel.
		check(TBm:SetPinned("NoSuchAddon", true) == false
			and not TBm:IsPinned("NoSuchAddon"),
			"and SetPinned refuses it directly too, rather than recording a pin"
			.. " that can never draw")
	end

	check(pcall(run, "toolbox"),
		"and /aether toolbox reports without erroring - a diagnostic that throws"
		.. " is the one thing worse than no diagnostic")
end

print("== toolbox: menu names, and a pill asked to be tall ==")
do
	local TBm = A:GetModule("toolbox")
	-- MENU buttons carry a readable name, not only a glyph and a tooltip.
	TBm:SetOpen(true, nil, "menu")
	do
		local first = TBm.panels.menu.cells[1]
		check(first and first.name and first.name:GetText() ~= "",
			"each Menu door shows its name under the glyph - a label you can"
			.. " read beats a glyph you have to decode (" ..
			tostring(first and first.name and first.name:GetText()) .. ")")
	end
	TBm:SetOpen(false)

	-- A PILL is a horizontal capsule; asked for a tall shape it clamps its
	-- caps to half the WIDTH, so it can never draw outside its own bounds.
	do
		local tall = A.Glass.CreatePill(UIParent, {})
		tall:SetSize(40, 200)
		local cap = tall._fill[1]:GetWidth()
		check(cap <= 20 + 0.5,
			"a pill asked for a tall shape clamps its caps to half its width (cap "
			.. string.format("%.0f", cap) .. " of a 40-wide frame)")
		tall:Hide()
	end
end

print("== the changelog, and the version it belongs to ==")
do
	-- The .toc is read from DISK here, not from the mock. A.version comes from
	-- GetAddOnMetadata, which the harness mocks - so every check in this file
	-- that touches a version is checking a value the harness itself chose. This
	-- is the one place the real file is opened, and it is what makes "you cannot
	-- ship a version with no notes" a fact rather than a hope.
	local tocVersion
	do
		local f = io.open("AetherUI.toc", "r")
		if f then
			for line in f:lines() do
				local v = line:match("^##%s*Version:%s*(%S+)")
				if v then tocVersion = v break end
			end
			f:close()
		end
	end
	check(tocVersion ~= nil, "AetherUI.toc declares a version (" ..
		tostring(tocVersion) .. ")")

	-- THE ADDON LIST'S ICON, and the second place that texture path is written.
	--
	-- The .toc is read before a line of this addon runs, so it cannot ask
	-- Media.texture.icon what the path is - it has to spell it out. Which means
	-- renaming the file fixes the Lua, ships, and leaves the addon list drawing
	-- nothing at all beside the title: an inline texture escape that resolves to
	-- no file is not an error anywhere, it is just a gap.
	do
		local tocIcon
		local f = io.open("AetherUI.toc", "r")
		if f then
			for line in f:lines() do
				local v = line:match("^##%s*IconTexture:%s*(%S+)")
				if v then tocIcon = v break end
			end
			f:close()
		end
		check(tocIcon ~= nil,
			"AetherUI.toc names an icon for the addon list, rather than taking"
			.. " the question mark (" .. tostring(tocIcon) .. ")")
		check(tocIcon == A.Media.texture.icon,
			"and it is the same path Media.texture.icon resolves to")
	end

	-- AND THE SAME FILES THE CLIENT LOADS. This file keeps its own list, in its
	-- own order, and the two drifted the moment a module was added: Timers.lua
	-- went into the .toc and shipped, while every check in here ran against an
	-- addon that did not contain it. A module nobody tests looks perfect.
	do
		local inToc, missing = {}, {}
		local f = io.open("AetherUI.toc", "r")
		if f then
			for line in f:lines() do
				local path = line:match("^(%S+%.lua)%s*$")
				if path then inToc[#inToc + 1] = path:gsub("\\", "/") end
			end
			f:close()
		end

		local loaded = {}
		for _, name in ipairs(FILES) do loaded[name] = true end

		for _, path in ipairs(inToc) do
			-- Libs are somebody else's and are stubbed rather than loaded.
			if not path:find("^Libs/") and not loaded[path] then
				missing[#missing + 1] = path
			end
		end

		check(#inToc > 0, "the .toc lists files to load (" .. #inToc .. ")")
		check(#missing == 0,
			"and every one of them is loaded by this suite too - a file in the"
			.. " .toc and not in here ships to players while being invisible to"
			.. " every check in this file"
			.. (#missing > 0 and (": " .. table.concat(missing, ", ")) or ""))
	end

	local log = A.CHANGELOG
	check(type(log) == "table" and #log > 0, "and Core/Changelog.lua has entries")

	-- The RUNNING version is the one in that file. Everything downstream -
	-- which changelog entry is current, what the card says, what the unread dot
	-- is remembered against, what the chip reads - hangs off A.version, and the
	-- mock used to answer a literal of its own. Every one of those checks then
	-- agreed with the harness about a version nobody was running.
	check(A.version == tocVersion,
		"and A.version is that same version rather than something the harness"
		.. " made up (" .. tostring(A.version) .. " vs .toc "
		.. tostring(tocVersion) .. ")")

	if tocVersion and log and #log > 0 then
		check(log[1].version == tocVersion,
			"the newest changelog entry is the version being shipped - bump the"
			.. " .toc without writing the notes and the drawer confidently shows"
			.. " the PREVIOUS release's news with no dot on it, which is the"
			.. " failure this file exists to make impossible (changelog "
			.. tostring(log[1].version) .. " vs .toc " .. tocVersion .. ")")
	end

	-- Newest first, and strictly. Two entries claiming one version, or an older
	-- one above a newer, both produce a card showing the wrong release.
	do
		local ordered, why = true, nil
		for i = 2, #log do
			if not A:VersionNewer(log[i - 1].version, log[i].version) then
				ordered = false
				why = log[i - 1].version .. " is not newer than " .. log[i].version
				break
			end
		end
		check(ordered, "every entry is strictly newer than the one below it"
			.. (why and (" (" .. why .. ")") or ""))
	end

	do
		local complete = true
		for _, e in ipairs(log) do
			if type(e.version) ~= "string" or type(e.date) ~= "string"
				or type(e.lines) ~= "table" or #e.lines == 0 then
				complete = false
			end
		end
		check(complete, "and every entry carries a version, a date and at least"
			.. " one line - an entry with no lines is a release that says nothing")
	end

	-- Component-wise, not string compare. "0.10.0" < "0.9.9" alphabetically, and
	-- that is the classic way a version check ships backwards.
	check(A:VersionNewer("0.10.0", "0.9.9"),
		"0.10.0 is newer than 0.9.9 - compared component by component, where a"
		.. " string compare gets it exactly backwards")
	check(A:VersionNewer("1.0.0", "0.99.99"), "and a major beats everything under it")
	check(not A:VersionNewer("0.2.0", "0.2.0"), "the same version is not newer than itself")
	check(not A:VersionNewer("0.2.0", "0.2.1"), "and a build number counts")
	do
		local a, b, c = A:ParseVersion("nonsense")
		check(a == 0 and b == 0 and c == 0,
			"something unparseable is zero rather than an error - it then sorts"
			.. " below every real version, which is the safe direction")
		-- And a NON-string, which is the case the guard is actually for: a
		-- string that does not match simply fails the pattern, where nil or a
		-- number reaches string.match and throws. Testing only "nonsense" never
		-- runs the guard at all.
		local ok, n1 = pcall(A.ParseVersion, A, nil)
		check(ok and n1 == 0, "and so is nothing at all, rather than an error"
			.. " out of string.match")
		check(select(2, pcall(A.ParseVersion, A, 3)) == 0,
			"or a number, which is what a .toc read by something else hands back")
	end

	-- A build whose version has no entry shows the notes for what is RUNNING.
	--
	-- The version asked for is a FIXTURE's. This named 0.1.0, which was in the
	-- shipped changelog for as long as there was a pre-release history and is
	-- not in it now - so the check was really asserting that a particular old
	-- release had never been deleted.
	do
		local realLog = A.CHANGELOG
		A.CHANGELOG = {
			{ version = "2.0.0", date = "2026-02-01", lines = { "Newest." } },
			{ version = "1.5.0", date = "2026-01-01", lines = { "Older." } },
		}
		local entry = A:Notes("1.5.0")
		check(entry and entry.version == "1.5.0",
			"asking for a specific version gets that version's notes")
		local missing = A:Notes("9.9.9")
		check(missing == A.CHANGELOG[1],
			"and a version with no entry falls back to the newest rather than to"
			.. " an empty card")
		A.CHANGELOG = realLog
	end
end

print("== toolbox: the addon list scrolls to what it cut ==")
do
	local TBm = A:GetModule("toolbox")
	local oldW, oldH = UIParent:GetWidth(), UIParent:GetHeight()
	local oldScale = A.db.profile.scale
	UIParent:SetSize(1365, 768)
	A.db.profile.scale = 0.71

	-- Enough launchers that the list cannot fit in ten rows.
	for i = 1, 30 do _G.__makeLDB("ScrollTest" .. i, "launcher") end
	A.Launchers:Scan()

	TBm:SetDock("LEFT")
	TBm:SetOpen(true, nil, "addons")
	TBm._addonOffset = 0
	TBm:RefreshAddons()

	local AP = TBm.panels.addons
	local c = { addons = AP.rows, addonsHint = AP.head.hint, addonsArrow = AP.arrow }
	local function firstShown()
		for i, row in ipairs(c.addons) do if row:IsShown() then return i end end
	end
	local function shownCount()
		local n = 0
		for _, row in ipairs(c.addons) do if row:IsShown() then n = n + 1 end end
		return n
	end

	check((TBm._addonsCut or 0) > 0,
		"with " .. #(TBm._addonRows or {}) .. " addons the list is cut ("
		.. tostring(TBm._addonsCut) .. " off the end)")
	do
		local _, _, _, _, y = c.addons[1]:GetPoint(1)
		check(-y >= 16 + 14, "the rows start below the heading")
		local last
		for _, row in ipairs(c.addons) do if row:IsShown() then last = row end end
		local _, _, _, _, ly = last:GetPoint(1)
		check(-ly + last:GetHeight() <= AP:GetHeight() + 0.5,
			"and the branch is tall enough for what it shows")
	end
	check(firstShown() == 1, "and starts at the top")
	local window = shownCount()
	check(window == 20, "showing ten rows of two (" .. window .. ")")

	-- The hint says it MOVES rather than counting what went.
	check(c.addonsHint:GetText():find("scroll", 1, true) ~= nil,
		"the heading says the list scrolls (" .. tostring(c.addonsHint:GetText())
		.. ")")
	check(c.addonsArrow:IsShown(), "with an arrow beside it")
	check(math.abs((c.addonsArrow.__rotation or 0) - 0) < 0.01,
		"pointing DOWN at the top of the list, which is where the rest of it is"
		.. " - Chevron.tga is a V, so down is rotation zero and up is pi")

	-- Wheel down, anywhere over the branch.
	local catch = AP
	check(catch:GetScript("OnMouseWheel") ~= nil,
		"the branch takes the wheel, so it works anywhere over the list rather"
		.. " than only over a row")
	catch:GetScript("OnMouseWheel")(catch, -1)
	local cols = 2
	check(firstShown() == 1 + cols,
		"one notch down moves the list by a whole ROW - stepping by one entry"
		.. " would swap which column every name is in and the list would appear"
		.. " to shuffle rather than scroll (first shown "
		.. tostring(firstShown()) .. ")")
	check(shownCount() == window,
		"the window is the same size, so a row came off the top as one arrived"
		.. " at the bottom (" .. shownCount() .. " vs " .. window .. ")")

	catch:GetScript("OnMouseWheel")(catch, 1)
	check(firstShown() == 1, "and one notch up puts it back")

	-- A row takes the wheel too, because that is where the cursor usually is.
	c.addons[1]:GetScript("OnMouseWheel")(c.addons[1], -1)
	check(firstShown() == 1 + cols, "the rows take the wheel as well")

	-- The ends. Scrolling past either is clamped rather than running off into a
	-- list showing nothing.
	for _ = 1, 50 do catch:GetScript("OnMouseWheel")(catch, -1) end
	local listTotal = #(TBm._addonRows or {})
	check(shownCount() > 0 and shownCount() <= window,
		"wound hard against the bottom the window is not parked past the last"
		.. " row showing nothing (" .. shownCount() .. " of " .. window .. ")")

	-- AND THE LAST ONE IS ON IT. The offset moves a whole row at a time, so the
	-- final page has to start on a row boundary at or PAST the point where the
	-- window reaches the end of the list. Taking the boundary below it instead
	-- leaves the last launcher one slot under the fold with nowhere left to
	-- scroll - and that only shows on an ODD number of them, because an even
	-- one lands on the boundary exactly and loses nothing.
	check(c.addons[listTotal] and c.addons[listTotal]:IsShown(),
		"and the last of the " .. listTotal .. " is on screen")
	check(TBm._addonsMore == 0, "with nothing left below")
	check(math.abs((c.addonsArrow.__rotation or 0) - math.pi) < 0.01,
		"and the arrow has turned UP, because that is the only way left to go")
	check(TBm._addonOffset % cols == 0,
		"the offset is still on a row boundary after the clamp, or the two"
		.. " columns swap over (" .. tostring(TBm._addonOffset) .. ")")

	for _ = 1, 50 do catch:GetScript("OnMouseWheel")(catch, 1) end
	check(TBm._addonOffset == 0 and firstShown() == 1,
		"and hard against the top it stops at the first row")
	check(math.abs((c.addonsArrow.__rotation or 0) - 0) < 0.01,
		"with the arrow pointing down again")

	-- Scrolled down, then given room: the list must not stay parked below its
	-- own last row, showing nothing.
	for _ = 1, 50 do catch:GetScript("OnMouseWheel")(catch, -1) end
	check(TBm._addonOffset > 0, "scrolled to the end ("
		.. TBm._addonOffset .. ")")
	do
		local realRows = TBm._addonRows
		TBm._addonRows = { realRows[1], realRows[2] }
		TBm:Fill("addons")
		check(TBm._addonOffset == 0 and firstShown() == 1,
			"a list that shrinks until it fits pulls the offset back to the top"
			.. " rather than leaving it scrolled past rows it is now showing")
		check(not c.addonsArrow:IsShown(),
			"and the arrow goes, because there is nowhere to scroll to")
		check(c.addonsHint:GetText():find("scroll", 1, true) == nil,
			"as does the word (" .. tostring(c.addonsHint:GetText()) .. ")")
		TBm._addonRows = realRows
		TBm:Fill("addons")
	end

	-- An offset written from nowhere near the list is clamped by the layout too.
	TBm._addonOffset = 9999
	TBm:Fill("addons")
	check(shownCount() > 0 and TBm._addonsMore == 0,
		"and an offset past the end of the list is clamped by the layout rather"
		.. " than believed (" .. tostring(TBm._addonOffset) .. ", showing "
		.. shownCount() .. ")")

	-- An ODD number of addons, which is the only way the clamp itself can land
	-- off a row boundary.
	--
	-- The wheel steps by whole rows from zero, so every offset it produces is a
	-- multiple of the column count; the clamp is the one place a stray value can
	-- come from, and only when the list length and the window size differ by an
	-- odd number. With an even list the boundary correction is unreachable and
	-- deleting it changes nothing - which is exactly what a mutation showed.
	do
		local realRows = TBm._addonRows
		local odd = {}
		for i = 1, 25 do odd[i] = realRows[i] end
		TBm._addonRows = odd
		TBm._addonOffset = 9999
		TBm:Fill("addons")
		check(TBm._addonOffset % 2 == 0,
			"clamping an odd-length list still lands on a row boundary (offset "
			.. tostring(TBm._addonOffset) .. " of " .. #odd .. " addons)")
		local first = firstShown()
		local firstX = select(4, c.addons[first]:GetPoint(1))
		local nextX  = select(4, c.addons[first + 1]:GetPoint(1))
		check(first and nextX > firstX,
			"so the first row on screen is in the LEFT column and the second is"
			.. " beside it - an offset one out puts every name in the other"
			.. " column and the list reads as shuffled (x " .. tostring(firstX)
			.. " then " .. tostring(nextX) .. ")")
		TBm._addonRows = realRows
		TBm._addonOffset = 0
		TBm:Fill("addons")
	end

	TBm._addonOffset = 0
	UIParent:SetSize(oldW, oldH)
	A.db.profile.scale = oldScale
	TBm:SetDock("LEFT")
	TBm:RefreshAddons()
	TBm:SetOpen(false)
end

print("== toolbox: the trunk owns the launchers ==")
do
	local TBm = A:GetModule("toolbox")
	local LN  = A.Launchers
	local mcfg = A.db.profile.modules.minimap
	local was = mcfg.drawer
	mcfg.drawer = false

	TBm:SetDock("LEFT")
	A.Launchers:Scan()
	TBm:ClaimPins()
	TBm:LayoutPins()

	-- An unclaimed launcher is one NOBODY positions - and a LibDBIcon button
	-- nobody positions is still sitting on the minimap ring. So the Toolbox
	-- adopts the lot.
	local orphan
	for e in LN:Iterate() do
		if not LN:OwnerOf(e) then orphan = e.key break end
	end
	check(orphan == nil,
		"every launcher has an owner (" .. tostring(orphan) .. ")")

	-- ...and the ones that are not pinned are PARKED rather than drawn. Never
	-- hidden: they belong to other addons and may carry secure templates.
	do
		local unpinned
		for e in LN:Iterate() do
			if LN:OwnerOf(e) == TBm and not TBm:IsPinned(e.key) and not e.owned then
				unpinned = e break
			end
		end
		if unpinned then
			check(unpinned._parked and unpinned.button:IsShown(),
				"an unpinned launcher is parked off screen rather than hidden -"
				.. " hiding a frame with a protected descendant is refused in"
				.. " combat, which is exactly when a drawer gets opened")
			check(unpinned.button:GetAlpha() == 0,
				"and it really is invisible rather than merely moved")
		end
	end

	-- The drawer is off by default, and that is the fix for the vanishing
	-- buttons: it shows its contents ON HOVER, so anything the rail had not
	-- claimed sat in a frame at alpha 0 until somebody hovered the zone pill.
	check(A.Config.defaults.profile.modules.minimap.drawer == nil
		and A:GetModule("minimap").drawer == nil,
		"there is no minimap drawer at all - not a setting, not a hidden frame."
		.. " Defaulting it off was not enough: two surfaces collecting the same"
		.. " buttons meant which one owned a given button depended on load"
		.. " order, and the drawer showed its contents ON HOVER, so anything the"
		.. " rail had not claimed vanished until somebody hovered the pill")

	mcfg.drawer = was
end

print("== toolbox: pins survive a reload ==")
do
	local TBm = A:GetModule("toolbox")
	local LN  = A.Launchers
	TBm:SetDock("LEFT")

	-- Pin something, then simulate the shape of a reload: the saved list is
	-- still there, but the launcher registry starts empty and refills over the
	-- next fifteen seconds as each addon finishes loading and LibDBIcon
	-- announces its button.
	--
	-- Claiming pins ONCE at enable caught only whatever had already arrived. An
	-- addon that loaded a moment later stayed in the saved list and never
	-- reached the rail - which from the outside is indistinguishable from the
	-- pin not having been saved at all, and was reported as exactly that.
	_G.__makeLDB("SlowAddon", "launcher", { label = "Slow Addon" })
	A.Launchers:Scan()
	TBm:TogglePin("SlowAddon")
	check(TBm:IsPinned("SlowAddon"), "pinned")

	local saved = A.db.char.toolbox.pinned
	check(saved and #saved == 1 and saved[1] == "SlowAddon",
		"and the pin is in the CHARACTER scope, which is what a reload restores")

	-- The reload. Registry cleared, saved list kept.
	local keptEntries, keptSeen, keptOwners = LN.entries, LN.seen, LN.owners
	local keptByKey = LN.byKey
	LN.entries, LN.byKey, LN.seen, LN.owners = {}, {}, {}, {}

	TBm:ClaimPins()
	TBm:LayoutPins()
	check(TBm:IsPinned("SlowAddon"),
		"straight after the reload the pin is still recorded, even though the"
		.. " addon it names has not loaded yet")

	-- ...and now the addon arrives, the way it really does.
	_G.__makeLDB("SlowAddon2", "launcher", { label = "Slow Addon" })
	LN.byKey["SlowAddon"] = { key = "SlowAddon", label = "Slow Addon",
		source = "ldb", button = CreateFrame("Button", nil, UIParent), owned = true }
	LN.entries[1] = LN.byKey["SlowAddon"]
	LN:Changed()

	local entry = LN.byKey["SlowAddon"]
	check(LN:OwnerOf(entry) == TBm,
		"and when it finally arrives the pin CLAIMS it - re-claimed on every"
		.. " launcher change rather than once at enable, or a slow addon is a"
		.. " pin that silently never draws")
	check(entry.button:GetParent() == TBm.pinNodes[1].button,
		"so it lands on the trunk without anybody touching the pin again")

	LN.entries, LN.byKey, LN.seen, LN.owners = keptEntries, keptByKey, keptSeen, keptOwners
	TBm:SetPinned("SlowAddon", false)
end

print("== zen: the corner glyph is small-circle art ==")
do
	local Z = A:GetModule("zen")
	local cp = Z.frame and Z.frame.corner
	check(cp ~= nil, "the corner block exists")
	if cp then
		-- Drawn at about sixteen pixels. Circle-Mask and Ring are 256 because
		-- the minimap MAGNIFIES them; here they were being minified sixteen
		-- times, and the client does not mipmap UI textures - which is the
		-- fringe around the glyph that got reported, the same one the settings
		-- chips had.
		check(cp.disc:GetTexture() == A.Media.texture.chipDisc,
			"the disc is the 64px chip art rather than a flat texture masked by"
			.. " the 256px Circle-Mask - a mask's edge is the client's to"
			.. " anti-alias and it does that poorly")
		check(cp.rim:GetTexture() == A.Media.texture.chipRim,
			"and so is the rim")
		check(cp.rim:GetWidth() > cp.disc:GetWidth(),
			"which still laps proud of the disc it edges (" ..
			string.format("%.1f vs %.1f", cp.rim:GetWidth(), cp.disc:GetWidth()) .. ")")
	end
end

print("== tooltips: wide enough for the widest ROW ==")
do
	local TTm = A:GetModule("tooltips")
	local tip = GameTooltip
	local bar = tip.aetherBar or _G.GameTooltipStatusBar

	if bar and bar.aetherValue then
		tip.aetherWantW = nil
		bar:SetMinMaxValues(0, 1003)
		bar:SetValue(1003)
		TTm:UpdateStatusBar(bar)

		local need = (bar.aetherLabel:GetStringWidth() or 0)
			+ (bar.aetherValue:GetStringWidth() or 0)
		check((tip.aetherWantW or 0) > need,
			"the health row asks the tooltip for room. A tooltip sizes itself to"
			.. " its text LINES, and these two are our own FontStrings anchored"
			.. " under the bar - invisible to that maths - so 'Health' and"
			.. " '1,003 / 1,003' collided in the middle of a narrow tooltip"
			.. " while every real line fitted (" .. string.format("%.0f", tip.aetherWantW or 0)
			.. " for " .. string.format("%.0f", need) .. " of text)")

		-- Whichever wants MORE wins, rather than whichever ran last.
		tip.aetherWantW = 999
		TTm:UpdateStatusBar(bar)
		check(tip.aetherWantW == 999,
			"and it never lowers a requirement somebody else already made - the"
			.. " elite chip asks for room through the same running maximum")
		tip.aetherWantW = nil
	end
end

print("== toolbox: the icon sheet ==")
do
	local TBm = A:GetModule("toolbox")
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, nil, "menu")

	-- THE ORDER HAS TO AGREE WITH THE GENERATOR. Media indexes the atlas by
	-- position, so one name inserted in Tools/generate_textures.py and not here
	-- shifts every icon after it - sixteen wrong pictures, no error anywhere,
	-- and nothing on screen that looks like a bug rather than a bad choice.
	--
	-- So the generator is READ rather than trusted. It is the only way this can
	-- be checked at all without a human comparing two lists.
	do
		local f = io.open("Tools/generate_textures.py", "r")
		check(f ~= nil, "the generator is readable from here")
		if f then
			local src = f:read("*a")
			f:close()

			local block = src:match("ICON_ORDER%s*=%s*%[(.-)%]")
			check(block ~= nil, "and declares an ICON_ORDER")

			local fromPy = {}
			for name in (block or ""):gmatch('"([%w_]+)"') do
				fromPy[#fromPy + 1] = name
			end

			local order = A.Media.icons.order
			check(#fromPy == #order,
				"the two lists are the same length (" .. #fromPy .. " in the"
				.. " generator, " .. #order .. " in Media)")

			local bad = {}
			for i = 1, math.max(#fromPy, #order) do
				if fromPy[i] ~= order[i] then
					bad[#bad + 1] = i .. ": " .. tostring(fromPy[i]) .. " vs " .. tostring(order[i])
				end
			end
			check(#bad == 0,
				"and every position agrees - one name inserted on one side"
				.. " silently shifts every icon after it ("
				.. (#bad > 0 and table.concat(bad, "; ") or "all match") .. ")")
		end
	end

	-- Every icon resolves to its own corner of the sheet.
	do
		local seen, clash = {}, nil
		for _, name in ipairs(A.Media.icons.order) do
			local file, l, r, t, b = A.Media:Icon(name)
			local key = string.format("%.3f,%.3f,%.3f,%.3f", l, r, t, b)
			if seen[key] then clash = name .. " and " .. seen[key] end
			seen[key] = name
			if not file then clash = clash or (name .. " has no file") end
		end
		check(not clash, "each icon has its own cell (" .. tostring(clash) .. ")")

		-- AN ALIAS RESOLVES, and resolves to the SAME cell. A tank's shield is
		-- the shield already on the sheet and the party handle's figures are the
		-- pair already on it; drawing either again would be two cells that have
		-- to agree about what a shield looks like. Checked because an alias
		-- pointing at a name the sheet does not have fails the way the keybinds
		-- tile did - SetIcon returns false, the glyph hides, and nothing says so.
		for alias, real in pairs(A.Media.icons.alias) do
			local f1, l1, r1, t1, b1 = A.Media:Icon(alias)
			local f2, l2, r2, t2, b2 = A.Media:Icon(real)
			check(f2 ~= nil,
				alias .. " points at a name the sheet has (" .. real .. ")")
			check(f1 == f2 and l1 == l2 and r1 == r2 and t1 == t2 and b1 == b2,
				"and lands on the very same cell, not a copy of it")
		end
		-- EVERY key the module asks for must exist in the sheet. The settings
		-- tile keyed "keybinds" asked for an icon the atlas called "keybind",
		-- SetIcon returned false, the glyph was hidden, and the tile shipped as
		-- a bare lilac blob - no error, nothing in the log, and every other
		-- assertion about tiles still green. A name is not a contract until
		-- something checks it.
		do
			local missing = {}
			for _, t in ipairs(TBm.TILES) do
				if not A.Media:Icon(t.key) then missing[#missing + 1] = "tile:" .. t.key end
			end
			for _, m in ipairs(TBm.MICRO) do
				if not A.Media:Icon(m.key) then missing[#missing + 1] = "menu:" .. m.key end
			end
			for _, b in ipairs(TBm.BRANCHES) do
				if not A.Media:Icon(b.icon) then missing[#missing + 1] = "node:" .. b.icon end
			end
			check(#missing == 0,
				"every key the module asks the sheet for is IN the sheet ("
				.. (#missing > 0 and table.concat(missing, ", ") or "all present")
				.. ")")
		end

		check(A.Media:Icon("no_such_icon") == nil,
			"and an unknown name answers nil rather than a default - a texture"
			.. " pointed at the sheet with no TexCoord draws the WHOLE atlas,"
			.. " which is unmistakable, but only if somebody checked")
	end

	-- The module actually uses them: a real glyph, cropped to one cell.
	do
		local b = TBm.panels.menu.cells[1]
		check(b and b.glyph and b.glyph:GetTexture() == A.Media.icons.file,
			"a Menu door draws from the sheet")
		local l, r = b.glyph:GetTexCoord()
		check(r - l < 0.9,
			"cropped to ONE cell rather than the whole sheet (" ..
			string.format("%.2f..%.2f", l, r) .. ")")
		local n = A.Trunk:Get("toolbox"):Node("widgets").button
		check(n.icon:GetTexture() == A.Media.icons.file
			and select(1, n.icon:GetTexCoord()) == select(2, A.Media:Icon("widgets")),
			"and each trunk node wears its own cell")

		TBm:SetOpen(true, nil, "settings")
		local row = TBm.panels.settings.rows[1]
		check(row and row.icon:IsShown() and row.icon:GetTexture() == A.Media.icons.file,
			"and a setting's diamond carries its own mark rather than a bare node")

		-- Type: one PHYSICAL pixel of shadow, and whole-point sizes.
		do
			local host = CreateFrame("Frame", nil, UIParent)
			host:SetScale(0.71)
			local fs = A.Widgets.Text(host, "tbCardBody", "LEFT")
			local off = fs.__shadowOffset and fs.__shadowOffset[2]
			local want = A:PxIn(host)
			check(off and math.abs(math.abs(off) - want) < 0.01,
				"a text shadow is one PHYSICAL pixel, not one frame unit -"
				.. " everything here draws at profile.scale, so a flat -1 is"
				.. " 0.71 of a pixel, lands between rows and smears the glyph's"
				.. " underside across two of them. On nine-pixel body text that"
				.. " reads as an outline nobody asked for (got "
				.. string.format("%.2f", math.abs(off or 0)) .. ", want "
				.. string.format("%.2f", want) .. ")")

			local _, size = fs:GetFont()
			check(size == math.floor(size),
				"and the size is a whole point - the rasteriser rounds anyway,"
				.. " but it rounds AFTER the frame scale, so 12.5 lands on a"
				.. " different fraction in every module (got " .. tostring(size)
				.. ")")
			host:Hide()
		end
	end

	TBm:SetOpen(false)
end

print("== combat gating ==")
_G.__inCombat = true
A.db.profile.scale = 1.0
AB:OnConfigChanged()
check(AB._layoutPending, "layout changes are deferred while in combat")
AB:ApplyBindings()
check(AB._bindingsPending, "rebinding is deferred while in combat")
_G.__inCombat = false
fire("PLAYER_REGEN_ENABLED")
check(not AB._layoutPending and not AB._bindingsPending,
	"deferred work replays when combat ends")
check(_G.__overrides["1"] == "AetherUIBar1Button1", "bindings survive the replay")

print("== blizzard buttons stay silenced ==")
do
	-- The dock showed page 1 while the key fired page 6, because Blizzard's own
	-- ActionButton2 was still alive underneath and still reading the live page.
	AB:HideBlizzard()
	local b = _G.ActionButton2
	check(b ~= nil, "Blizzard's ActionButton2 exists in the mock")
	check(b:GetAttribute("statehidden") == true,
		"it is marked statehidden, so Blizzard's own visibility drivers leave it down")
	check(not b:IsShown(), "and it is hidden")
	check(next(b.__events) == nil, "and deaf")

	check(AB.hideReport["<blizzard buttons>"] ~= nil,
		"the button sweep is reported in /aether diag")
	check(_G.__clearedOverrides.MainActionBar,
		"Blizzard's bar has its override bindings cleared - the modern bar code"
		.. " re-points the ACTIONBUTTON keys at its own buttons, and last writer wins")

	check(GetBindingAction("1", true):find("AetherUI", 1, true) ~= nil,
		"and key 1 resolves to our button, not theirs (got "
		.. GetBindingAction("1", true) .. ")")
end

print("== shift-drag picks up instead of casting ==")
do
	-- RegisterForClicks("AnyDown") fires the click on mouse-down, which lands
	-- before a drag can start - so shift-dragging an action cast it. The secure
	-- handler consults `shift-type1` before `type`, and an empty string there is
	-- a click with nothing to do, which leaves the drag alone.
	local b = bar.buttons[1]
	check(b:GetAttribute("shift-type1") == "",
		"the pickup modifier's click is neutered on our buttons")
	check(b:GetAttribute("type") == "action",
		"and the unmodified click still casts")
	check(b:GetAttribute("ctrl-type1") == nil and b:GetAttribute("alt-type1") == nil,
		"only the one modifier is touched")

	-- Which modifier is the player's business, not ours.
	_G.__modifiedClick.PICKUPACTION = "CTRL"
	fire("UPDATE_BINDINGS")
	check(b:GetAttribute("ctrl-type1") == "" and b:GetAttribute("shift-type1") == nil,
		"changing PICKUPACTION in Blizzard's settings moves it, and clears the old one")

	_G.__modifiedClick.PICKUPACTION = "NONE"
	fire("UPDATE_BINDINGS")
	check(b:GetAttribute("ctrl-type1") == nil,
		"'none' leaves every modified click alone")

	_G.__modifiedClick.PICKUPACTION = "SHIFT"
	fire("UPDATE_BINDINGS")
end

print("== keybind mode ==")
do
	AB:SetBindMode(true)
	check(AB.bindMode == true, "bind mode on")
	local o = AB.bindOverlays and AB.bindOverlays[1]
	check(o ~= nil and o:IsShown(), "every button gets an overlay you can hover")
	check(o.bindingName == "ACTIONBUTTON1",
		"bar 1 binds through Blizzard's own ACTIONBUTTON names (" ..
		tostring(o.bindingName) .. ")")

	-- Bar 2 is the one action page Blizzard never named a binding for, which is
	-- why Bindings.xml declares one. Without it the bar is unreachable by key.
	local bar2
	A.Config:Module("actionbars").bars[2].enabled = true
	AB:SyncBars()
	AB:SetBindMode(true)
	for _, x in ipairs(AB.bars) do if x.id == "2" then bar2 = x end end
	local name2
	for _, ov in ipairs(AB.bindOverlays or {}) do
		if ov:IsShown() and bar2 and ov.button == bar2.buttons[1] then name2 = ov.bindingName end
	end
	check(name2 == "AETHERUI_BAR2BUTTON1",
		"bar 2 uses our own declared binding header (" .. tostring(name2) .. ")")
	A.Config:Module("actionbars").bars[2].enabled = false
	AB:SyncBars()
	AB:SetBindMode(true)

	-- A key press goes into Blizzard's account binding set, not our saved
	-- variables, so it survives the addon being turned off.
	_G.__shift = true
	o:GetScript("OnKeyDown")(o, "F")
	_G.__shift = false
	check(_G.__bindingSet.ACTIONBUTTON1 == "SHIFT-F",
		"the pressed key, with its modifiers, lands on the binding (" ..
		tostring(_G.__bindingSet.ACTIONBUTTON1) .. ")")
	check(_G.__savedBindingSet == 1, "and the binding set is saved, not left dirty")
	check(_G.__overrides["SHIFT-F"] == "AetherUIBar1Button1",
		"the override binding follows immediately, without a reload")
	check(o.text:GetText() == "SF", "the overlay shows the new key back")

	-- The bug that made bind mode look broken on bars 3-6: the press reached our
	-- handler *and* went on to the binding system, so binding ctrl-1 also fired
	-- whatever ctrl-1 already did. Propagation is reset by the client for every
	-- keyboard event, so it has to be turned off inside the handler dealing with
	-- the press - not once on OnEnter.
	-- LSHIFT on purpose: it binds nothing, so this asserts the swallow happens
	-- for *every* press rather than only the ones we act on.
	o.__propagate = true
	o:GetScript("OnKeyDown")(o, "LSHIFT")
	check(o.__propagate == false,
		"the handler itself swallows the press rather than relying on OnEnter")
	o.__propagate = true
	o:GetScript("OnKeyUp")(o)
	check(o.__propagate == false, "and the key-up half of the same press too")

	-- Modifier keys on their own are not bindings.
	o:GetScript("OnKeyDown")(o, "LSHIFT")
	check(_G.__bindingSet.ACTIONBUTTON1 == "SHIFT-F",
		"pressing shift by itself does not bind shift")

	-- Taking a key that something else owns takes it, rather than leaving two
	-- owners and letting the client choose.
	local o2 = AB.bindOverlays[2]
	o2:GetScript("OnKeyDown")(o2, "F")
	check(_G.__bindingSet.ACTIONBUTTON1 == "SHIFT-F"
		and _G.__bindingSet.ACTIONBUTTON2 == "F",
		"a plain F and a shift-F are different keys and coexist")

	o:GetScript("OnMouseWheel")(o, 1)
	check(_G.__bindingSet.ACTIONBUTTON1 == "MOUSEWHEELUP",
		"the wheel is a key too")

	o:GetScript("OnKeyDown")(o, "ESCAPE")
	check(_G.__bindingSet.ACTIONBUTTON1 == nil, "escape clears the binding")
	check(o.text:GetText() == "?", "and the overlay says so")

	-- Right-click leaves, and combat refuses.
	o:GetScript("OnMouseDown")(o, "RightButton")
	check(AB.bindMode == false, "right-click leaves bind mode")
	check(not AB.bindOverlays[1]:IsShown(), "and the overlays go away")

	_G.__inCombat = true
	AB:SetBindMode(true)
	check(AB.bindMode == false, "bind mode refuses to open in combat")
	_G.__inCombat = false

	-- Bind mode opens from a slash command or the options panel, so the cursor is
	-- wherever it already was. Over a button, no OnEnter ever fires and that
	-- overlay never takes keyboard focus - which is the "I had to hover off and
	-- back on before it would take" report.
	AB.bindOverlays[1].__mouseOver = true
	AB:SetBindMode(true)
	check(AB.bindOverlays[1].__propagate == false,
		"an overlay already under the cursor when bind mode opens is given focus"
		.. " without waiting for the mouse to move")
	AB.bindOverlays[1].__mouseOver = nil
	AB:SetBindMode(false)

	SetBinding("1", "ACTIONBUTTON1")
	AB:ApplyBindings()
end

print("== unlock grid and snapping ==")
do
	local M = A.Movers
	M:Unlock()

	local g = _G.AetherUIMoverGrid
	check(g ~= nil and g:IsShown(), "the grid appears with the handles")
	check(#g.lines > 0, "and has lines in it")

	-- OFF TAKES THE FIELD, NOT THE MODE. The dimming and the spine are what
	-- say the frames are unlocked; the dots, strands and centre line go.
	A.db.profile.movers.grid = false
	M:RefreshGrid()
	check(g:IsShown() and g.veil:IsShown() and not g.dots:IsShown()
		and not (g.lines[1] and g.lines[1]:IsShown()),
		"turning the field off takes the dots and strands without locking first,"
		.. " and leaves the dimming")
	A.db.profile.movers.grid = true
	M:RefreshGrid()
	check(g.dots:IsShown() and g.lines[1]:IsShown(), "and back on again")

	-- A controlled screen: one frame being dragged, one frame to catch on. The
	-- real registry has a dozen entries whose edges would make "did it snap to
	-- the thing I meant" unanswerable. 1080 tall, the handoff's own screen, so
	-- the field's step is exactly 24 and its dots run out from x = 500.
	UIParent:SetSize(1000, 1080)
	UIParent.__scale = 1

	local entry = _G.__testMover()
	check(entry ~= nil and entry.handle ~= nil, "a panel registered as a mover has a handle")
	local f, h = entry.frame, entry.handle
	f.__scale = 0.5                      -- so frame space is 2x UIParent's
	f:SetSize(200, 100)                  -- 100 x 50 in UIParent units

	local target = CreateFrame("Frame", "AetherUISnapTarget", UIParent)
	target.__scale = 1
	target:SetGeom({ cx = 550, cy = 275, left = 400, right = 700, bottom = 200, top = 350 })

	local saved = M.registry
	M.registry = { __testpanel = entry, __t = { name = "__t", frame = target } }
	check(math.abs(M.FieldStep() - 24) < 1e-6,
		"on a 1080 screen the field's step is the handoff's 24 (" .. M.FieldStep() .. ")")
	A.db.profile.movers.snapDistance = 12

	-- Everything below is expressed in UIParent units and converted at the
	-- boundary, exactly as the mover does. GetPoint hands back what was written,
	-- in the frame's own space, so the expected value carries the /fs.
	local function place(uiLeft, uiBottom)
		f:SetGeom({ cx = uiLeft * 2 + 100, cy = uiBottom * 2 + 50,
			left = uiLeft * 2, right = uiLeft * 2 + 200,
			bottom = uiBottom * 2, top = uiBottom * 2 + 100 })
	end
	local function droppedX()
		local _, _, _, x = f:GetPoint(1)
		return x * 0.5                    -- frame space -> UIParent units
	end

	cursorX, cursorY = 500, 500

	-- five pixels short of the target's left edge, which is as close as anyone
	-- gets with a mouse
	place(405, 100)
	h:GetScript("OnDragStart")(h)
	check(h:GetScript("OnUpdate") ~= nil, "dragging tracks the cursor by hand"
		.. " - StartMoving owns the position and cannot be nudged mid-drag")
	h:GetScript("OnUpdate")(h)
	check(math.abs(droppedX() - 400) < 0.01,
		("a near-miss lands on the other frame's edge (405 -> %.1f, wanted 400)")
			:format(droppedX()))

	-- our right edge against theirs, from the other side
	place(295, 100)                      -- right edge at 395, theirs at 400
	h:GetScript("OnDragStart")(h)
	h:GetScript("OnUpdate")(h)
	check(math.abs(droppedX() - 300) < 0.01,
		("the frame's own right edge counts too (%.1f)"):format(droppedX()))

	-- SHIFT is free placement (board 4a); Alt was, until B2.
	place(405, 100)
	h:GetScript("OnDragStart")(h)
	_G.__shift = true
	h:GetScript("OnUpdate")(h)
	_G.__shift = false
	check(math.abs(droppedX() - 405) < 0.01,
		("holding shift places it exactly where the cursor says (%.1f)"):format(droppedX()))
	place(405, 100)
	h:GetScript("OnDragStart")(h)
	_G.__alt = true
	h:GetScript("OnUpdate")(h)
	_G.__alt = false
	check(math.abs(droppedX() - 400) < 0.01,
		("and alt no longer does (%.1f)"):format(droppedX()))

	-- Far from anything, the field is what is left - its dots, counted from
	-- the centre: 500 + 13 x 24 = 812.
	place(803, 100)
	h:GetScript("OnDragStart")(h)
	h:GetScript("OnUpdate")(h)
	check(math.abs(droppedX() - 812) < 0.01,
		("with nothing near, a dot of the field catches it, counted from the"
		.. " centre (803 -> %.1f, wanted 812)"):format(droppedX()))

	-- ...but another frame always outranks it: from 405 the dot at 404 is one
	-- away and the frame's edge at 400 is five.
	place(405, 100)
	h:GetScript("OnDragStart")(h)
	h:GetScript("OnUpdate")(h)
	check(math.abs(droppedX() - 400) < 0.01,
		("a frame edge beats a nearer dot (%.1f)"):format(droppedX()))

	A.db.profile.movers.snap = false
	place(803, 100)
	h:GetScript("OnDragStart")(h)
	h:GetScript("OnUpdate")(h)
	check(math.abs(droppedX() - 803) < 0.01,
		("snapping off means nothing is caught at all (%.1f)"):format(droppedX()))
	A.db.profile.movers.snap = true

	h:GetScript("OnDragStop")(h)
	check(h:GetScript("OnUpdate") == nil, "and the tracker stops when you let go")

	M.registry = saved
	f.__geom, f.__scale = nil, 1
	M:Lock()
	M:Unregister("__testpanel")
	check(not g:IsShown(), "the grid goes away with the handles")

	-- A snap on one axis only leaves the other guide's slot nil, and `ipairs`
	-- stops at the hole - so the line that was actually drawn was the one that
	-- never got hidden, and it stayed lying across the screen after locking.
	A.Movers:Unlock()
	A.Movers.__test_resetGuides()
	A.Movers.__test_drawGuide(2, false, 400)
	check(A.Movers.__test_guideShown(2), "a horizontal snap guide is drawn")
	A.Movers:Lock()
	check(not A.Movers.__test_guideShown(2),
		"and it is cleared on lock even though no vertical guide was ever made -"
		.. " the case ipairs skipped")
	UIParent:SetSize(1024, 768)
	A:Reconfigure()
end

-- THE LATTICE UNLOCK LOOK (board 4a): the dimmed world and the field, the
-- spine across the screen, the mode pill, wire outlines with junctions, and a
-- bond from each child to its parent.
print("== lattice unlock: the look ==")
do
	local M = A.Movers
	UIParent:SetSize(1000, 1080)
	A.db.profile.anchors.__lockButton = nil
	M:Unlock()
	local g = _G.AetherUIMoverGrid

	check(g.veil:IsShown() and select(4, unpack(g.veil.__color or {})) == 0.45,
		"the world is dimmed under everything of ours")
	local u0, u1, v0 = g.dots:GetTexCoord()
	check(g.dots:GetTexture() == A.Media.texture.fieldDot and g.dots.__wrap[1] == "REPEAT"
		and math.abs(u0 - (0.5 - 500 / 24)) < 1e-6 and math.abs(u1 - u0 - 1000 / 24) < 1e-6
		and math.abs(v0 - (0.5 - 540 / 24)) < 1e-6,
		"the dots are one repeating texture, a dot every 24, one on the centre ("
		.. tostring(u0) .. ", " .. tostring(u1) .. ", " .. tostring(v0) .. ")")
	local strandAt96 = false
	for _, t in ipairs(g.lines) do
		local _, _, _, x = t:GetPoint(1)
		if t:IsShown() and x and math.abs(x - (500 + 96)) < 1e-6 then strandAt96 = true end
	end
	check(strandAt96, "a strand every fourth dot, 96 out from the centre")
	check(#g.dashes > 10 and g.dashes[1]:IsShown(), "and the centre is dashed")
	local _, rel = g.spine:GetStartPoint()
	check(g.spine:IsShown() and rel == M.nodes.spine,
		"the spine is drawn across the screen, hung from the spine itself")

	-- The mode pill, top centre, and it still locks.
	local pill = M.lockButton
	check(pill:IsShown() and pill.label:GetText() == "Lattice unlocked"
		and pill.chipText:GetText() == "LOCK" and pill:GetPoint(1) == "TOP",
		"the mode pill says Lattice unlocked with a LOCK chip, at the top centre")

	-- Wire outlines: a unit is a pill, anything else a rounded rectangle.
	local player, bar1 = M.registry.player, M.registry.bar1
	check(player.handle._kind == "pill" and bar1.handle._kind == "panel",
		"a unit's outline is a pill, a bar's a rounded rectangle")
	check(player.handle.label:GetText() == "PLAYER",
		"its name in capitals (" .. tostring(player.handle.label:GetText()) .. ")")
	-- ON A TAG IN THE TOP-LEFT, not in the middle where the junction and the
	-- bonds are (Joe, in game, 2026-10-07): a frame over the handle, so lines
	-- pass behind it, and deaf to the mouse so a drag from it still works.
	local function tagAt(handle)
		local tag = handle.tag
		if not tag then return "no tag" end
		local point, rel = tag:GetPoint(1)
		if handle.label:GetParent() ~= tag then return "label not on the tag" end
		if rel ~= handle or point ~= "TOPLEFT" then return "tag at " .. tostring(point) end
		if tag:IsMouseEnabled() then return "tag takes the mouse" end
		return "ok"
	end
	check(tagAt(player.handle) == "ok" and tagAt(bar1.handle) == "ok",
		"the name is on a tag in the top-left corner, off the junction ("
		.. tagAt(player.handle) .. ", " .. tagAt(bar1.handle) .. ")")
	local _, _, _, pillX = player.handle.tag:GetPoint(1)
	check(pillX >= player.handle:GetHeight() / 2 - 1e-6,
		"and a pill's tag starts past its rounded end (" .. tostring(pillX) .. ")")
	-- Filled or hollow by where it stands - that is B2's question, checked on a
	-- controlled screen below; here the junction only has to be there.
	local jt = player.handle.junction:GetTexture()
	check((jt == A.Media.texture.diamond or jt == A.Media.texture.diamondRim)
		and player.handle.junction:IsShown(), "and a junction diamond at its centre")

	-- Bonds: child to parent, none for the pair, none for a free node.
	local lines = {}
	for _, l in ipairs(M.__bonds().lines) do
		if l:IsShown() and l.child then lines[l.child] = l end
	end
	local function joins(child, parentFrame)
		local l = lines[child]
		if not l then return false end
		local _, a = l:GetStartPoint()
		local _, b = l:GetEndPoint()
		return a == M.registry[child].frame and b == parentFrame
	end
	check(joins("pet", player.frame), "a bond joins the pet to the player")
	check(joins("targettarget", M.registry.target.frame), "and the ToT to the target")
	check(joins("bar1", M.nodes.spine), "bar 1 is bonded to the spine")
	check(lines.target == nil, "the target has no bond - the spine joins the pair")
	check(lines.chat == nil, "and a node on the screen has none")
	local spineJunction = false
	for _, t in ipairs(M.__bonds().nodes) do
		if t:IsShown() and t.node == "spine" then spineJunction = true end
	end
	check(spineJunction, "the spine has a junction of its own")

	M:Lock()
	check(not M.__bonds():IsShown() and not g:IsShown() and not pill:IsShown(),
		"locking takes the field, the bonds and the pill away")
	UIParent:SetSize(1024, 768)
	A:Reconfigure()

	-- THE BEHAVIOUR (B2). A controlled screen again: a parent, a child being
	-- dragged (the test panel's handle, hung from it for the test), one
	-- other frame whose edge is nearer than the parent's centre, and a third
	-- node to drop onto. 1080 tall, so a field unit is one UIParent unit.
	print("== lattice unlock: the behaviour ==")
	UIParent:SetSize(1000, 1080)
	UIParent.__scale = 1
	M:Unlock()
	local entry = _G.__testMover()
	local f, h = entry.frame, entry.handle
	f.__scale = 1
	local P = CreateFrame("Frame", "AetherUILatticeParent", UIParent)
	P:SetGeom({ cx = 500, cy = 540, left = 450, right = 550, bottom = 520, top = 560 })
	local T = CreateFrame("Frame", "AetherUILatticeEdge", UIParent)
	T:SetGeom({ cx = 557.5, cy = 325, left = 457.5, right = 657.5, bottom = 300, top = 350 })
	local Q = CreateFrame("Frame", "AetherUILatticeOther", UIParent)
	Q:SetGeom({ cx = 800, cy = 300, left = 780, right = 820, bottom = 290, top = 310 })
	local savedRegistry, savedParent = M.registry, entry.parent
	local savedAnchors = A.db.profile.anchors
	A.db.profile.anchors = {}
	M.registry = {
		__testpanel = entry,
		__p = { name = "__p", frame = P, label = "Anchor" },
		__t = { name = "__t", frame = T, label = "Edge" },
		__q = { name = "__q", frame = Q, label = "Other" },
	}
	entry.parent = "__p"
	-- Unlocked again over this registry, so every node has its handle - a
	-- drop only ever lands on a junction that is on screen.
	M:Unlock()
	f:SetSize(100, 40)
	local function childAt(left, bottom)
		f:SetGeom({ cx = left + 50, cy = bottom + 20, left = left, right = left + 100,
			bottom = bottom, top = bottom + 40 })
	end
	local function dragOnce()
		h:GetScript("OnDragStart")(h)
		h:GetScript("OnUpdate")(h)
	end
	local function droppedLeft() local _, _, _, x = f:GetPoint(1) return x end
	cursorX, cursorY = 505, 728

	-- 1. The parent's centre line wins over a nearer frame edge and a dot.
	-- The bottom edge sits on a dot (540 + 7 x 24 = 708), so the other axis
	-- stays put and the distance is the child's centre, 728, less 540.
	childAt(455, 708)
	dragOnce()
	check(math.abs(droppedLeft() - 450) < 0.01,
		("the parent's centre line catches first, over a nearer frame edge"
		.. " (455 -> %.1f, wanted 450)"):format(droppedLeft()))
	local fb = M.__feedback()
	check(fb.snap:IsShown() and fb.snapText:GetText() == "SNAP · ANCHOR"
		and fb.snapDist:GetText() == "188" and fb.snapArrow:GetRotation() == math.pi,
		"and says so: SNAP · ANCHOR, a chevron pointing up, 188 ("
		.. tostring(fb.snapText:GetText()) .. " " .. tostring(fb.snapDist:GetText()) .. ")")
	check(fb.dashes[1] and fb.dashes[1]:IsShown(), "with a dashed bond to the parent")
	local insp = M.__inspector()
	check(insp:IsShown() and insp.title:GetText() == "TEST PANEL"
		and insp.rows[1].v:GetText() == "ANCHOR" and insp.rows[3].v:GetText() == "Down"
		and tostring(insp.rows[4].v:GetText()):match("^%d+%%$"),
		"the inspector shows the node's parent, how it grows and its scale ("
		.. tostring(insp.rows[1].v:GetText()) .. ", " .. tostring(insp.rows[3].v:GetText())
		.. ", " .. tostring(insp.rows[4].v:GetText()) .. ")")
	check(insp.rows[2].v:GetText() == "5, 188",
		"and its offset from the parent, up positive (" .. tostring(insp.rows[2].v:GetText()) .. ")")
	h:GetScript("OnDragStop")(h)
	check(not fb.snap:IsShown() and not insp:IsShown(), "all of it goes on drop")

	-- 2. Shift: no snapping, no SNAP, and a node off the lattice is hollow
	-- (455 to 555 across and 700 to 740 up touch no dot, edge or centre line).
	childAt(455, 700)
	h:GetScript("OnDragStart")(h)
	_G.__shift = true
	h:GetScript("OnUpdate")(h)
	_G.__shift = false
	check(math.abs(droppedLeft() - 455) < 0.01 and not fb.snap:IsShown(),
		"shift places it where it is, with no snap shown")
	check(h.junction:GetTexture() == A.Media.texture.diamondRim and h.onLattice == false,
		"and its junction turns hollow - it is off the lattice")
	h:GetScript("OnDragStop")(h)
	childAt(450, 708)
	check(M.__onLattice(entry), "lined up on its parent's centre, it is on the lattice again")

	-- 3. Dropped on another node's junction: hung from that one.
	childAt(455, 708)
	cursorX, cursorY = 800, 300
	dragOnce()
	check(fb.bond:IsShown() and fb.bondText:GetText() == "BOND · OTHER",
		"the junction under the cursor lights: BOND · OTHER ("
		.. tostring(fb.bondText:GetText()) .. ")")
	h:GetScript("OnDragStop")(h)
	check(M:ParentOf("__testpanel") == "__q", "and the drop hangs it from that node ("
		.. tostring(M:ParentOf("__testpanel")) .. ")")

	-- 4. Refused: onto one of its own children, and anything of the pair.
	M.registry.__q.parent = "__testpanel"
	entry.parent = "__p"
	dragOnce()
	check(fb.bondText:GetText() == "NO BOND · OTHER", "a node's own child lights red: NO BOND")
	h:GetScript("OnDragStop")(h)
	check(M:ParentOf("__testpanel") == "__p", "and the drop is refused - that bond would loop")
	M.registry.__q.parent = nil
	local pairTry = M.__junctionUnder({ name = "__x", pairLead = "player" }, 800, 300)
	check(pairTry and pairTry.refused == A.L.movers.bond.pair,
		"the player and target never hang from another node")

	M.registry, entry.parent = savedRegistry, savedParent
	A.db.profile.anchors = savedAnchors
	f.__geom, f.__scale = nil, 1
	M:Lock()
	M:Unregister("__testpanel")
	check(not fb.bond:IsShown() and not M.__inspector():IsShown(), "and locking clears it all")

	-- 5. Stretching the spine: the inspector reads its length.
	UF.player:SetGeom({ left = 100, right = 400, top = 300, bottom = 240 })
	UF.target:SetGeom({ left = 520, right = 820, top = 300, bottom = 240 })
	M:Unlock()
	local th = M.registry.target.handle
	_G.__ctrl = true
	cursorX, cursorY = 600, 270
	th:GetScript("OnDragStart")(th)
	cursorX = 640
	th:GetScript("OnUpdate")(th)
	_G.__ctrl = false
	insp = M.__inspector()
	check(insp:IsShown() and insp.title:GetText() == "SPINE"
		and insp.rows[1].k:GetText() == "Length" and tonumber(insp.rows[1].v:GetText()),
		"stretching the spine, the inspector reads its length ("
		.. tostring(insp.rows[1].v:GetText()) .. ")")
	th:GetScript("OnDragStop")(th)
	UF.player.__geom, UF.target.__geom = nil, nil
	M:Lock()
	UIParent:SetSize(1024, 768)
	A:Reconfigure()

	-- The spacing slider went with the fixed field, and so does its setting.
	local db = { profile = { movers = { grid = true, gridSize = 20 } } }
	A.Config.Migrate(db)
	check(db.profile.movers.gridSize == nil and db.profile.movers.grid == true,
		"an old grid spacing is dropped from the profile")
end

-- ---------------------------------------------------------------------------
-- quest log (concept 3b)
--
-- The window replaces Blizzard's rather than reskinning it, so most of what can
-- go wrong is not "does it draw" but "did we actually take the old one out of
-- circulation" - and every one of those failures is silent on screen.
-- ---------------------------------------------------------------------------

local QLog = A:GetModule("questlog")

print("== quest log: taking over from Blizzard ==")
do
	check(QLog and QLog.enabled, "quest log module enabled")
	check(QLog.win and QLog.win:GetName() == "AetherUIQuestLog", "window built")
	check(not QLog.win:IsShown(), "and starts closed")

	-- The expensive one. QuestLog_OnEvent is not gated on visibility, so a merely
	-- hidden frame still answers QUEST_LOG_UPDATE and can call
	-- SelectQuestLogEntry behind our back.
	check(not _G.QuestLogFrame:IsEventRegistered("QUEST_LOG_UPDATE"),
		"Blizzard's frame is UNREGISTERED, not just hidden - a hidden frame still"
		.. " runs QuestLog_Update and moves the selection cursor")
	check(not _G.QuestLogFrame:IsShown(), "and hidden as well")
	check(_G.QuestLogFrame:GetScript("OnShow") ~= nil,
		"with an OnShow hook, so anything calling ShowUIPanel on it bounces")

	check(_G.UIPanelWindows["QuestLogFrame"] == nil,
		"and it leaves the panel manager, or the left slot stays reserved for a"
		.. " frame that will never be shown")

	local found = false
	for _, n in pairs(_G.UISpecialFrames) do
		if n == "AetherUIQuestLog" then found = true end
	end
	check(found, "ours is registered for ESC, which Blizzard's never was")
	check(_G.ClassicQuestLog == QLog.win,
		"and answers to ClassicQuestLog, so Questie opens ours instead of popping"
		.. " Blizzard's dead frame over the top")
end

print("== quest log: the L key, the micro button, and combat ==")
do
	check(_G.ToggleQuestLog ~= nil, "ToggleQuestLog still exists")
	local before = _G.__blizzToggled

	_G.ToggleQuestLog()
	check(QLog.win:IsShown(), "the global opens ours - one hook catches the L key,"
		.. " the micro button and every other addon at once")
	check(_G.__blizzToggled == before, "and Blizzard's never runs")
	check(_G.QuestLogMicroButton.__state == "PUSHED",
		"the micro button lights up, which nothing else would do for us now")

	_G.ToggleQuestLog()
	check(not QLog.win:IsShown(), "and closes again")
	check(_G.QuestLogMicroButton.__state == "NORMAL", "micro button goes dark")

	-- Show/Hide on our own unregistered frame, never ShowUIPanel, which is
	-- combat-blocked on this client and fails silently when it is.
	_G.__inCombat = true
	QLog:Show()
	check(QLog.win:IsShown(), "opens in combat - the whole reason for not going"
		.. " through the panel manager")
	QLog:Hide()
	_G.__inCombat = false
end

print("== quest log: the list ==")
do
	QLog:Show()
	local kinds, zones, quests = {}, 0, 0
	for _, e in ipairs(QLog.entries) do
		kinds[#kinds + 1] = e.kind
		if e.kind == "zone" then zones = zones + 1 else quests = quests + 1 end
	end
	check(kinds[1] == "zone", "the list leads with a zone heading")
	check(zones == 2 and quests == 4,
		"two zones, four quests (got " .. zones .. " / " .. quests .. ")")
	check(QLog.win.head.count.text:GetText() == "4 / 20", "the count chip reads 4 / 20")

	-- A collapsed header hides its quests from GetQuestLogTitle entirely, and
	-- nothing on screen would say so - the zone would simply not be there. Set up
	-- here rather than in the shared fixture so the log's indices stay exactly as
	-- the tracker tests above expect them.
	QLog:Hide()
	CollapseQuestHeader(4)                      -- Stonetalon, as the player would
	local hiddenEntries = GetNumQuestLogEntries()
	check(hiddenEntries == 4,
		"with Stonetalon collapsed the client reports 4 entries, not 6 - its"
		.. " quests are not in the log at all")

	QLog:Show()
	local sawZone, sawQuest = false, false
	for _, e in ipairs(QLog.entries) do
		if e.kind == "zone" and e.name == "Stonetalon Mountains" then sawZone = true end
		if e.kind == "quest" and e.title == "Prowlers of the Barrens" then sawQuest = true end
	end
	check(sawZone and sawQuest,
		"but opening the window expands it first, so the zone is not silently"
		.. " missing")
	check(_G.__questLog[4].collapsed == false, "and the header is left expanded")
end

print("== quest tracker: a folded zone must not empty it silently ==")
do
	local QTf = A:GetModule("questtracker")

	-- THE REPORT. The tracker closing itself and not opening again when clicked,
	-- with the count chip reading a number over an empty body. A folded zone
	-- header does not fold its quests on screen - it removes them from
	-- GetQuestLogTitle entirely - so the scan saw a header and nothing else,
	-- drew no rows, and the body collapsed to nothing. Clicking the header then
	-- toggled a fold state over an empty list, which is why it looked dead.
	--
	-- Nothing in this suite could have caught it: every quest-log check either
	-- opened our window first, which expands, or asserted the tracker's saved
	-- sets rather than what it DREW.
	-- On the reference screen, where the trunk has room for quests at all.
	local screen = { w = UIParent:GetWidth(), h = UIParent:GetHeight(), geom = UIParent.__geom,
		anchors = A.db.profile.anchors }
	UIParent:SetSize(1920, 1080)
	UIParent:SetGeom({ cx = 960, cy = 540, left = 0, right = 1920, bottom = 0, top = 1080 })
	A.db.profile.anchors = {}
	A:Reconfigure()

	A.db.char.tracked, A.db.char.untracked = {}, {}
	ExpandQuestHeader(0)
	QTf:Refresh()
	local wasRows = TShown()
	check(wasRows > 0, "with nothing folded the trunk carries quest nodes (" .. wasRows .. ")")

	-- Fold every zone, the way a player would, and the way an earlier session
	-- can leave it.
	-- Through A.Quest like the modules do: GetQuestLogTitle does not exist on
	-- camelot, so the suite reaching for it directly would test the addon
	-- against an API the client has not got.
	for i = GetNumQuestLogEntries(), 1, -1 do
		local _, _, _, isHeader = A.Quest.Title(i)
		if isHeader then CollapseQuestHeader(i) end
	end
	QTf:Refresh()

	local rows = TShown()
	local _, numQuests = GetNumQuestLogEntries()

	-- THE CLIENT STILL ADMITS TO THE QUESTS. Only the entry count moves when a
	-- header folds, which is what makes the difference readable at all - and it
	-- is the difference the header chip was already showing while the body
	-- showed nothing.
	check(numQuests > 0,
		"the client still counts the quests (" .. numQuests .. ") even folded")
	check(QTf.behindFold ~= nil and QTf.behindFold > 0,
		"and the tracker knows how many it was not allowed to name ("
		.. tostring(QTf.behindFold) .. ")")

	-- THE POINT. Empty is fine; empty WITHOUT SAYING WHY is what looked broken.
	check(rows == 0, "folded, the trunk has no quest nodes to show (" .. rows .. ")")
	check(QTf.more and QTf.more.button:IsShown(),
		"and says so, on the node the overflow count already uses - rather than"
		.. " showing nothing and looking like it has stopped working")
	check(QTf.more and tostring(QTf.more.holder.title:GetText()):find("fold", 1, true) ~= nil,
		"and says WHAT is hiding them (" .. tostring(QTf.more and QTf.more.holder.title:GetText()) .. ")")

	-- AND IT DOES NOT UNDO THE PLAYER'S FOLD ON THE WAY PAST. The first fix
	-- expanded from the scan itself, so folding a zone anywhere was reversed in
	-- the same frame - ExpandQuestHeader fires QUEST_LOG_UPDATE and the scan
	-- runs from that. That is not a policy, it is a fight.
	local stillFolded = false
	for i = 1, #_G.__questLog do
		if _G.__questLog[i].header and _G.__questLog[i].collapsed then stillFolded = true end
	end
	check(stillFolded,
		"a fold the player just made is still there after a refresh - the sweep"
		.. " is once at login, not once per scan")

	-- AND THE SWEEP THAT CLEARS AN INHERITED ONE. The fold that caused the
	-- report came from an earlier session - before this addon, or from Questie -
	-- and could not be undone anywhere in this interface, because both of our
	-- quest windows group by zone themselves and neither has a fold to click.
	-- So the tracker clears it once on the way in.
	A:SetModuleEnabled("questtracker", false)
	A:SetModuleEnabled("questtracker", true)
	local inherited = false
	for i = 1, #_G.__questLog do
		if _G.__questLog[i].header and _G.__questLog[i].collapsed then inherited = true end
	end
	check(not inherited,
		"starting the tracker clears a fold it inherited - the one state that"
		.. " empties this window and that nothing in this interface can undo")

	ExpandQuestHeader(0)
	QTf:Refresh()
	A.db.char.tracked, A.db.char.untracked = {}, {}

	UIParent:SetSize(screen.w, screen.h)
	UIParent.__geom = screen.geom
	A.db.profile.anchors = screen.anchors
	A:Reconfigure()
end

print("== quest log: difficulty bands and the tri-state complete flag ==")
do
	local byTitle = {}
	for _, e in ipairs(QLog.entries) do
		if e.kind == "quest" then byTitle[e.title] = e end
	end

	-- player is level 16 in this harness; green range is 8.
	check(byTitle["Chen's Empty Keg"].band == "difficult",  "15 vs 16 is yellow")
	check(byTitle["Harpy Raiders"].band == "difficult",     "16 vs 16 is yellow")
	check(byTitle["Prowlers of the Barrens"].band == "difficult", "17 vs 16 is yellow")
	-- Level 20 against a green range of 8 is the one case that separates the
	-- client's answer from the deck's note, and it is a single level wide: a 12
	-- is 8 below, which GetQuestGreenRange still calls green, where the deck's
	-- floor(20/10)+5 = 7 would call it grey. A 13 comes out green either way and
	-- an 11 grey either way, so neither of those proves anything - which is
	-- exactly what the first version of this check got wrong.
	_G.__units.player.level = 20
	check(QLog.DifficultyBand(12) == "standard",
		"at level 20 a 12 is green per GetQuestGreenRange, where the deck's"
		.. " floor(P/10)+5 would have called it grey")
	check(QLog.DifficultyBand(11) == "trivial", "and an 11 is past the range either way")
	check(QLog.DifficultyBand(26) == "impossible", "+6 is red")
	check(QLog.DifficultyBand(23) == "verydifficult", "+3 is orange")
	_G.__units.player.level = 16
	QLog:Refresh()

	-- isComplete is 1 / -1 / nil, and -1 means FAILED. `if isComplete then` is
	-- true for a failed quest, which is the shape of the bug.
	local failed = byTitle["Lost in Battle"]
	check(failed.failed == true, "isComplete == -1 is read as failed")
	check(failed.complete == false,
		"and NOT as complete - `if isComplete then` would have got this wrong")

	check(byTitle["Harpy Raiders"].complete == true, "isComplete == 1 is complete")
end

print("== quest log: the tag pill and the title anchor ==")
do
	local row
	for i, e in ipairs(QLog.entries) do
		if e.kind == "quest" and e.tag == "Dungeon" then row = e.row end
	end
	check(row and row.tag:IsShown(), "the localized questTag is shown verbatim as a pill")
	check(row.tag.text:GetText() == "Dungeon", "reading 'Dungeon' straight off the tuple")

	-- An anchor to a hidden frame still resolves, so an untagged row left pinned
	-- to the pill would be clipped at whatever width it last had.
	local plain
	for i, e in ipairs(QLog.entries) do
		if e.kind == "quest" and not e.tag then plain = e.row break end
	end
	check(plain and not plain.tag:IsShown(), "an untagged quest hides its pill")
	local pt = plain.title.__points and plain.title.__points[#plain.title.__points]
	check(pt and pt[2] == plain,
		"and re-anchors its title to the row, not to the hidden pill")
end

print("== quest log: the description reads the selection exactly once ==")
do
	_G.__questTextReads = 0
	local target
	for _, e in ipairs(QLog.entries) do
		if e.kind == "quest" and e.title == "Prowlers of the Barrens" then target = e end
	end
	QLog:Select(target.questID)

	check(_G.__questSelected == target.index, "selecting a row moves the cursor to it")
	check(_G.__questTextReads == 1,
		"and reads the text exactly once - never in a loop over the log, which is"
		.. " what Blizzard's own event handler would corrupt")
	check(QLog.win.detail.desc:GetText() == "Prowlers stalk the road.",
		"description is the FIRST return, not the second")
	check(QLog.win.detail.summary:GetText() == "Thin the prowlers.",
		"and the objective summary is the second")
	check(QLog.win.detail.title:GetText() == "Prowlers of the Barrens", "title set")

	-- The list is built from the index-taking getters, so a rebuild must not
	-- need the cursor at all.
	_G.__questSelected = nil
	QLog:RefreshList()
	check(_G.__questSelected == nil,
		"rebuilding the list touches no selection - GetNumQuestLeaderBoards(i) and"
		.. " GetQuestLogLeaderBoard(j, i) both take the index")
	QLog:Select(target.questID)
end


print("== quest log: search ==")
do
	local box = QLog.win.head.search.box
	box:SetText("harpy")
	local zones, quests = 0, 0
	for _, e in ipairs(QLog.entries) do
		if e.kind == "zone" then zones = zones + 1 else quests = quests + 1 end
	end
	check(quests == 1, "search narrows to the one match")
	check(zones == 1, "and a zone with nothing left in it loses its heading too,"
		.. " rather than leaving a column of empty headings")
	check(not QLog.win.head.search.placeholder:IsShown(), "placeholder gets out of the way")

	box:SetText("")
	check(#QLog.entries > 2, "clearing it brings the list back")
	check(QLog.win.head.search.placeholder:IsShown(), "and the placeholder returns")
end

print("== quest log: rebuilds are not free ==")
do
	QLog:Hide()
	QLog.dirty = false
	local built = 0
	local realRefresh = QLog.Refresh
	QLog.Refresh = function(self) built = built + 1 return realRefresh(self) end

	-- QUEST_LOG_UPDATE fires constantly; Blizzard's own source calls it out.
	for _ = 1, 20 do fire("QUEST_LOG_UPDATE") end
	check(built == 0, "twenty QUEST_LOG_UPDATEs with the window shut rebuild nothing")
	check(QLog.dirty, "but the window is marked dirty")

	QLog:Show()
	check(built >= 1, "and opening it rebuilds once")

	built = 0
	for _ = 1, 20 do fire("QUEST_LOG_UPDATE") end
	check(built == 0, "with it open they are still coalesced onto the ticker,"
		.. " not run per event")
	QLog:Flush()
	check(built == 1, "and the ticker runs exactly one rebuild for all twenty")

	-- After a loading screen the client reports nil completion flags and zero
	-- objective counts for quests that are perfectly fine.
	built = 0
	fire("LOADING_SCREEN_ENABLED")
	for _ = 1, 5 do fire("QUEST_LOG_UPDATE") end
	QLog:Flush()
	check(built == 0, "and nothing rebuilds mid-loading-screen, when the client"
		.. " reports quests as incomplete that are not")
	fire("LOADING_SCREEN_DISABLED")
	QLog:Flush()
	check(built == 1, "the gate opens again once the world is up")

	QLog.Refresh = realRefresh
end

print("== quest log: the selection is a questID, not a log index ==")
do
	QLog:Show()
	local target
	for _, e in ipairs(QLog.entries) do
		if e.kind == "quest" and e.title == "Lost in Battle" then target = e end
	end
	QLog:Select(target.questID)
	check(QLog.win.detail.title:GetText() == "Lost in Battle", "selected it")

	-- Accepting a quest in a zone that sorts above renumbers everything below.
	-- Holding the log index across that rebuild silently swaps the detail pane to
	-- somebody else's quest with no interaction from the player.
	table.insert(_G.__questLog, 2, { id = 99, title = "A New Quest", level = 12,
		description = "New.", summary = "Do it.", objectives = {} })
	fire("QUEST_ACCEPTED", 2, 99)
	QLog:Flush()
	check(QLog.win.detail.title:GetText() == "Lost in Battle",
		"after a quest is accepted above it, the detail pane still shows the same"
		.. " quest (got '" .. tostring(QLog.win.detail.title:GetText()) .. "')")
	table.remove(_G.__questLog, 2)
	fire("QUEST_REMOVED", 99)
	QLog:Flush()
end

print("== quest log: the auto-selected row is actually highlighted ==")
do
	-- Selection is settled BEFORE the list is painted. Drawn the other way round,
	-- the right pane shows a quest in full while no row on the left is lit -
	-- every first open of a session, and every time the selected quest is turned
	-- in or filtered away.
	QLog:Hide()
	QLog.selectedID = nil
	QLog.entries = nil
	QLog:Show()
	check(QLog.selectedID ~= nil, "opening with nothing selected picks a quest")

	local row
	for _, e in ipairs(QLog.entries) do
		if e.kind == "quest" and e.questID == QLog.selectedID then row = e.row end
	end
	check(row and row._selected, "and its row is drawn selected")
	check(row and row._fillColor == A.Palette.c.rowSel,
		"carrying the selected fill, not a transparent one")
end

print("== quest log: typing in the search box does not leak frames ==")
do
	QLog:Show()
	local box = QLog.win.head.search.box
	box:SetText("harpy") box:SetText("")      -- warm the pools
	local before = _G.__frameCount()
	for _ = 1, 20 do box:SetText("harpy") box:SetText("") end
	local leaked = _G.__frameCount() - before
	check(leaked == 0,
		"twenty search toggles strand no frames (" .. leaked .. ") - zone rows come"
		.. " and go under a filter, and WoW never frees a frame or a texture")
end

print("== quest log: a window opened by somebody else is still up to date ==")
do
	-- Questie resolves ClassicQuestLog and calls ShowUIPanel on it, which with no
	-- UIPanelWindows entry degrades to a plain Show(). The refresh has to hang off
	-- the frame's OnShow, or that opens a stale window - or a blank one, if the
	-- log has not been opened this session.
	QLog:Hide()
	QLog.entries = nil
	QLog.dirty = true
	_G.ClassicQuestLog:Show()
	check(QLog.entries and #QLog.entries > 0,
		"someone else's Show() still rebuilds the list")
	check(QLog.win.detail.title:IsShown(), "and the detail pane is populated")
end

print("== quest log: a closed window never moves the client's selection ==")
do
	QLog:Hide()
	_G.__questSelected = nil

	-- Counted rather than inferred from the selection alone: descriptions are
	-- cached per questID, so a rebuild of an already-read quest would move no
	-- cursor and the side effect would hide the wasted work.
	local drawn = 0
	local realList = QLog.RefreshList
	QLog.RefreshList = function(self) drawn = drawn + 1 return realList(self) end

	A.db.profile.skin = OTHER A:Restyle()
	A.db.profile.skin = "midnight" A:Restyle()
	A:Reconfigure()

	QLog.RefreshList = realList
	check(drawn == 0,
		"a restyle and a reconfigure with the window shut draw nothing (got "
		.. drawn .. " rebuilds)")
	check(_G.__questSelected == nil,
		"and call SelectQuestLogEntry zero times - the cursor is Blizzard's, not"
		.. " ours to move for a window nobody can see")
	check(QLog.dirty, "the work is deferred, not dropped")
	check(A.lastFailure == nil, "and nothing raises")
end

print("== quest log: collapsed zones, and whose state that is ==")
do
	local QT2 = A:GetModule("questtracker")

	-- OPENING EXPANDS, AND CLOSING NO LONGER PUTS IT BACK. The restore used to
	-- be here on the grounds that the collapse is shared with Blizzard's log and
	-- with Questie and is not ours to keep. With Blizzard's log banished there
	-- is nowhere left in this interface to collapse or un-collapse a zone, so
	-- the state can only arrive from outside, can never be seen, and can never
	-- be undone - while its cost is a tracker that silently empties. One policy
	-- in both modules now: this addon keeps headers expanded.
	QLog:Hide()
	CollapseQuestHeader(4)
	QLog:Show()
	check(_G.__questLog[4].collapsed == false, "opening expands the player's zones")
	QLog:Hide()
	check(_G.__questLog[4].collapsed == false,
		"and closing leaves them expanded - a fold nothing in this interface can"
		.. " undo is a fold that only ever costs us quests")

	-- ...but re-collapsing fires QUEST_LOG_UPDATE, and a collapsed header's quests
	-- are not in the log at all. The tracker prunes its saved sets against what it
	-- can see, so without a guard every close silently deletes the tracked state
	-- for every quest in the zone being closed.
	A.db.char.tracked, A.db.char.untracked = {}, {}
	ExpandQuestHeader(0)
	QT2.SetTracked(4901, false)          -- dismiss a quest in Stonetalon
	check(A.db.char.untracked[4901] == true, "a quest is dismissed from the tracker")

	CollapseQuestHeader(4)
	QLog:Show()
	QLog:Hide()
	check(A.db.char.untracked[4901] == true,
		"and survives a quest log open/close - the tracker must not read 'hidden"
		.. " behind a collapsed header' as 'gone from the log' and drop it from"
		.. " the saved variables")

	ExpandQuestHeader(0)
	A.db.char.tracked, A.db.char.untracked = {}, {}
	QT2:Refresh()
end

print("== quest log: a zone is never silently missing ==")
do
	-- Expansion and the refresh must be driven by the same thing. With expand on
	-- QL:Show and the refresh on the frame's OnShow they stop alternating, and a
	-- window opened by anyone else draws a log that still has collapsed headers.
	QLog:Hide()
	CollapseQuestHeader(4)
	QLog.entries, QLog.dirty = nil, true
	_G.ClassicQuestLog:Show()             -- Questie's route, not ours
	local saw = false
	for _, e in ipairs(QLog.entries or {}) do
		if e.kind == "quest" and e.title == "Prowlers of the Barrens" then saw = true end
	end
	check(saw, "a window opened by somebody else still expands, so no zone is missing")
	QLog:Hide()
	ExpandQuestHeader(0)
	QLog:Show()
end

print("== quest log: a transient nil description is not cached forever ==")
do
	local target
	for _, e in ipairs(QLog.entries) do
		if e.kind == "quest" and e.title == "Harpy Raiders" then target = e end
	end

	-- For a few seconds after a loading screen the client answers with nil for
	-- quests that are perfectly fine, and the first rebuild lands in that window.
	local real = GetQuestLogQuestText
	GetQuestLogQuestText = function() return nil, nil end
	fire("QUEST_ACCEPTED", 1, 1)          -- drops the cache
	QLog:Flush()
	QLog:Select(target.key)
	check(not QLog.win.detail.desc:IsShown(), "a nil description draws nothing")

	GetQuestLogQuestText = real
	QLog:Select(target.key)
	check(QLog.win.detail.desc:IsShown()
		and QLog.win.detail.desc:GetText() == "The harpies have gone too far.",
		"and once the client is answering again the description comes back -"
		.. " the nil was never cached (got '"
		.. tostring(QLog.win.detail.desc:GetText()) .. "')")
end

print("== quest log: a missing questID does not kill selection or clicks ==")
do
	-- questID is the eighth return on 1.15 and GetQuestIDFromLogIndex backs it up,
	-- so this should never happen in the field - but the module already spends a
	-- pcall defending against it, and comparing nil to nil is worse than useless:
	-- EnsureSelection declares the selection valid, nothing is highlighted, and
	-- every row becomes unclickable.
	local realTitle, realFromIndex = GetQuestLogTitle, GetQuestIDFromLogIndex
	GetQuestLogTitle = function(i)
		local a, b, c, d, e, f, g = realTitle(i)
		return a, b, c, d, e, f, g, nil
	end
	GetQuestIDFromLogIndex = nil

	QLog.selectedID = nil
	QLog.entries = nil
	QLog.dirty = true
	QLog:Hide() QLog:Show()

	local first, firstRow
	for _, e in ipairs(QLog.entries) do
		if e.kind == "quest" then first, firstRow = e, e.row break end
	end
	check(QLog.selectedID ~= nil, "a quest is still selected with no questID")
	check(firstRow and firstRow._selected, "and its row is still highlighted")

	local other, otherRow
	for _, e in ipairs(QLog.entries) do
		if e.kind == "quest" and e ~= first then other, otherRow = e, e.row break end
	end
	otherRow:GetScript("OnMouseUp")(otherRow)
	check(QLog.win.detail.title:GetText() == other.title,
		"and clicking a row still selects that quest (wanted '" .. other.title
		.. "', got '" .. tostring(QLog.win.detail.title:GetText()) .. "')")

	GetQuestLogTitle, GetQuestIDFromLogIndex = realTitle, realFromIndex
	QLog.selectedID, QLog.entries, QLog.dirty = nil, nil, true
	QLog:Hide() QLog:Show()
end

print("== quest log: letter-spacing is UTF-8 aware ==")
do
	-- Zone headings come straight from the client and are localized. The tracked
	-- heading used to be byte-split, which tears a multi-byte character in half:
	-- an accent becomes a replacement box, and on ruRU or zhCN the whole heading
	-- is garbage.
	local tracked = A.Media:Track("D\195\188ster", 1)
	-- The two bytes of the u-umlaut must stay adjacent. Tracking separates
	-- CHARACTERS, so "D" and the umlaut are a space apart - it is the pair
	-- \195\188 being contiguous that says the character was not split.
	check(tracked:find("\195\188", 1, true) ~= nil,
		"a two-byte character survives tracking intact")
	check(select(2, tracked:gsub(" ", "")) == 5,
		"and is spaced as one character, not two (got "
		.. select(2, tracked:gsub(" ", "")) .. " gaps)")
	check(A.Media:Track("\228\184\128\228\184\137", 1) == "\228\184\128\228\184\137",
		"CJK is passed through untracked rather than pulled apart")
	check(A.Media:Track("QUESTS", 1) == "Q U E S T S", "ASCII is unchanged")

	-- ...and the zone heading must not be uppercased byte-wise on the way in.
	-- string.upper is ASCII-only in the client's locale, so "Dusterbruch" with an
	-- umlaut comes out with one lowercase letter stranded in a capital heading.
	local realName = _G.__questLog[1].title
	_G.__questLog[1].title = "D\195\188sterbruch"
	QLog.entries, QLog.dirty = nil, true
	QLog:Hide() QLog:Show()
	local heading
	for _, e in ipairs(QLog.entries) do
		if e.kind == "zone" then heading = e.row.text:GetText() break end
	end
	check(heading == A.Media:Track("D\195\188sterbruch", 1),
		"a non-ASCII zone name is left in its own case rather than half-uppercased"
		.. " (got '" .. tostring(heading) .. "')")
	_G.__questLog[1].title = realName
	QLog.entries, QLog.dirty = nil, true
	QLog:Hide() QLog:Show()
end

print("== quest log: rewards ==")
do
	QLog.entries, QLog.dirty = nil, true
	QLog:Hide() QLog:Show()
	local prowlers, keg
	for _, e in ipairs(QLog.entries) do
		if e.title == "Prowlers of the Barrens" then prowlers = e end
		if e.title == "Chen's Empty Keg" then keg = e end
	end

	QLog:Select(prowlers.key)
	local d = QLog.win.detail
	check(d.rewardLabel:IsShown() and #d.rewardCards >= 2,
		"a quest with choices draws the CHOOSE A REWARD cards")
	check(d.rewardCards[1].label:GetText() == "Grizzled Boots", "first choice named")
	check(d.giveLabel:IsShown() and d.giveCards[1].label:GetText() == "Traveller's Pack",
		"and its guaranteed reward is drawn separately - the two are different"
		.. " sets, not one list")
	check(d.giveCards[1].slot.count:GetText() == "2", "a stack shows its count")
	-- Nothing in the detail pane may sit on top of the section above it. Checked
	-- on the description -> rewards boundary specifically, because that is the one
	-- section whose trailing gap was missing: the description was the last thing
	-- on the page until the reward cards were added behind it.
	local function topOf(fs)
		local pt = fs.__points and fs.__points[#fs.__points]
		return pt and -pt[5] or nil
	end
	local descTop, lblTop = topOf(d.desc), topOf(d.rewardLabel)
	local gap = lblTop and descTop and (lblTop - descTop - d.desc:GetStringHeight())
	check(gap and gap >= 14,
		"the reward heading clears the last line of the description (gap " ..
		string.format("%.0f", gap or -1) .. ", DET_GAP is 18)")

	-- 12s 0c, not 1200c: the mock formats money in denominations now, the way
	-- the client does, and a bill nobody can read is the same as not printing
	-- one.
	check(d.money:IsShown() and d.money:GetText() == "Reward: 12s 0c",
		"reward money (" .. tostring(d.money:GetText()) .. ")")
	check(not d.required:IsShown(), "and no required-money line when none is owed")

	-- Blizzard tints an unusable reward red rather than hiding it: "you cannot
	-- use this" is information.
	local r, g = d.rewardCards[2].slot.icon.__color[1], d.rewardCards[2].slot.icon.__color[2]
	check(r > 0.8 and g < 0.5, "an unusable choice is tinted red, not hidden")

	-- A quest with no choices at all must still show what it gives, or Classic's
	-- many no-choice quests get an empty reward area that reads as a bug.
	QLog:Select(keg.key)
	check(not d.rewardLabel:IsShown(), "a quest with no choices draws no choice label")
	check(d.giveLabel:IsShown(), "but still draws what it gives")
	local sawSpell = false
	for _, card in pairs(d.giveCards) do
		if card:IsShown() and card.rewardType == "spell" then sawSpell = true end
	end
	check(sawSpell, "including the spell reward, which comes from C_QuestInfoSystem"
		.. " and takes a questID rather than a reward index")

	check(d.required:IsShown() and d.required:GetText() == "Required: 30s 0c",
		"required money is shown (" .. tostring(d.required:GetText()) .. ")")
	local col = d.required.__color
	check(col and col[1] < 0.9,
		"and is drawn normally when you can afford it")

	-- Red when you cannot. This is the one reward-area field whose absence could
	-- actually cost the player gold, so it gets the loud treatment.
	_G.__money = 100
	QLog:RefreshDetail()
	col = d.required.__color
	check(col and col[1] > 0.9 and col[2] < 0.7,
		"and red when you cannot - 3000 owed against " .. _G.__money .. " held")
	_G.__money = 5000
	QLog:RefreshDetail()
end

